-- PART 20
NAmanage.ScriptHub_DownloadImage = function(url, generation)
	const hub = NAmanage.ScriptHub
	generation = tonumber(generation) or hub.imageGeneration
	if generation ~= hub.imageGeneration or type(url) ~= "string" or url == "" then
		return nil
	end
	if Match(url, "^rbxassetid://") or Match(url, "^rbxthumb://") then
		return url
	end
	const cached = hub.imageAssets[url]
	if type(cached) == "string" and cached ~= "" then
		return cached
	end
	if generation ~= hub.imageGeneration then
		return nil
	end
	if not NAmanage.ScriptHub_EnsureImageFolder() then
		return url
	end
	const path = NAmanage.ScriptHub_GetImagePath(url, generation)
	local exists = false
	if type(NAmanage.safeIsFile) == "function" then
		exists = NAmanage.safeIsFile(path)
	elseif type(isfile) == "function" then
		local okExists, value = pcall(isfile, path)
		exists = okExists and value == true
	end
	if not exists then
		local body
		for _, targetUrl in NAmanage.ScriptHub_GetImageTargets(url) do
			if generation ~= hub.imageGeneration then
				return nil
			end
			local okGet, result = NAmanage.HttpGet(targetUrl, {
				timeout = 12;
				maxAttempts = 2;
				Headers = NAmanage.ScriptHub_GetImageHeaders(targetUrl);
			})
			if generation ~= hub.imageGeneration then
				return nil
			end
			if okGet and type(result) == "string" and result ~= "" then
				body = result
				break
			end
		end
		if generation ~= hub.imageGeneration then
			return nil
		end
		if type(body) ~= "string" or body == "" then
			return url
		end
		local okWrite
		if type(NAmanage.safeWriteFile) == "function" then
			okWrite = NAmanage.safeWriteFile(path, body)
		else
			okWrite = pcall(writefile, path, body)
		end
		if generation ~= hub.imageGeneration then
			if okWrite == true then
				if type(NAmanage.safeDeleteFile) == "function" then
					NAmanage.safeDeleteFile(path)
				elseif type(delfile) == "function" then
					pcall(delfile, path)
				end
			end
			return nil
		end
		if okWrite ~= true then
			return url
		end
	end
	if generation ~= hub.imageGeneration then
		return nil
	end
	local okAsset, asset = pcall(getcustomasset, path)
	if generation ~= hub.imageGeneration then
		return nil
	end
	if okAsset and type(asset) == "string" and asset ~= "" then
		hub.imageAssets[url] = asset
		return asset
	end
	return url
end

NAmanage.ScriptHub_ApplyImage = function(imageLabel, asset)
	if not (imageLabel and imageLabel:IsA("ImageLabel") and type(asset) == "string" and asset ~= "") then
		return
	end
	imageLabel.Image = asset
	imageLabel.ImageTransparency = math.clamp(tonumber(imageLabel:GetAttribute("NAScriptHubLoadedTransparency")) or 0, 0, 1)
end

NAmanage.ScriptHub_LoadImage = function(imageLabel, url)
	const hub = NAmanage.ScriptHub
	if not (imageLabel and imageLabel:IsA("ImageLabel") and type(url) == "string" and url ~= "") then
		return
	end
	if Match(url, "^rbxassetid://") or Match(url, "^rbxthumb://") then
		NAmanage.ScriptHub_ApplyImage(imageLabel, url)
		return
	end
	const cached = hub.imageAssets[url]
	if type(cached) == "string" and cached ~= "" then
		NAmanage.ScriptHub_ApplyImage(imageLabel, cached)
		return
	end
	const generation = hub.imageGeneration
	const pendingKey = tostring(generation).."|"..url
	if type(hub.imagePending[pendingKey]) == "table" then
		hub.imagePending[pendingKey][#hub.imagePending[pendingKey] + 1] = imageLabel
		return
	end
	hub.imagePending[pendingKey] = { imageLabel }
	SpawnCall(function()
		const asset = NAmanage.ScriptHub_DownloadImage(url, generation)
		const waiting = hub.imagePending[pendingKey] or {}
		hub.imagePending[pendingKey] = nil
		if generation ~= hub.imageGeneration or type(asset) ~= "string" or asset == "" then
			return
		end
		for _, target in waiting do
			if target and target.Parent then
				NAmanage.ScriptHub_ApplyImage(target, asset)
			end
		end
	end)
end

NAmanage.ScriptHub_SetActionText = function(button, text, iconName)
	if not button then return end
	NAmanage.SetIcon(button, iconName, {text = tostring(text or "")})
end

NAmanage.ScriptHub_CardScale = function()
	const scale = NAUIMANAGER and NAUIMANAGER.AUTOSCALER and tonumber(NAUIMANAGER.AUTOSCALER.Scale) or tonumber(NAUIScale) or 1
	return scale > 0 and scale or 1
end

NAmanage.ScriptHub_CardsWidth = function(results)
	if not results then return 0 end
	local width = results.AbsoluteSize.X / NAmanage.ScriptHub_CardScale()
	const pad = results:FindFirstChildOfClass("UIPadding")
	if pad then
		width -= pad.PaddingLeft.Offset + pad.PaddingRight.Offset + width * (pad.PaddingLeft.Scale + pad.PaddingRight.Scale)
	end
	return math.max(width, 0)
end

NAmanage.ScriptHub_Measure = function(text, size, width, font)
	const service = Services and Services.TextService
	if service and service.GetTextSize then
		local ok, result = pcall(service.GetTextSize, service, tostring(text or ""), math.max(1, tonumber(size) or 12), font or Enum.Font.Gotham, Vector2.new(math.max(1, tonumber(width) or 100), 100000))
		if ok and result then
			return result
		end
	end
	return Vector2.new(#tostring(text or "") * (tonumber(size) or 12) * 0.55, (tonumber(size) or 12) * 1.25)
end

NAmanage.ScriptHub_FormatStat = function(value)
	local number = tonumber(value)
	if not number then
		return tostring(value or "0")
	end
	number = math.floor(number)
	if number >= 1000000 then
		return Format("%.1fM", number / 1000000)
	elseif number >= 1000 then
		return Format("%.1fK", number / 1000)
	end
	return tostring(number)
end

NAmanage.ScriptHub_CreateBadge = function(parent, text, color)
	const label = InstanceNew("TextLabel", parent)
	label.Name = "Badge"
	label.BorderSizePixel = 0
	label.BackgroundColor3 = color or Color3.fromRGB(55, 57, 69)
	label.BackgroundTransparency = 0.18
	label.Text = tostring(text)
	label.TextColor3 = Color3.fromRGB(232, 232, 242)
	label.TextSize = 10
	label.Font = Enum.Font.GothamMedium
	label.TextTruncate = Enum.TextTruncate.AtEnd
	label.TextXAlignment = Enum.TextXAlignment.Center
	const width = math.ceil(NAmanage.ScriptHub_Measure(label.Text, 10, 1000, Enum.Font.GothamMedium).X) + 14
	label.Size = UDim2.new(0, width, 0, 18)
	label:SetAttribute("NABadgeWidth", width)
	const pad = InstanceNew("UIPadding", label)
	pad.PaddingLeft = UDim.new(0, 6)
	pad.PaddingRight = UDim.new(0, 6)
	const corner = InstanceNew("UICorner", label)
	corner.CornerRadius = UDim.new(0, 5)
	return label
end

NAmanage.ScriptHub_LayoutCard = function(card, width)
	if not (card and card.Parent) then
		return
	end
	width = math.max(1, tonumber(width) or 240)
	const stack = width < 520
	const phone = width < 420
	const pad = phone and 8 or 10
	const gap = 10
	const contentW = math.max(120, width - pad * 2)
	const media = card:FindFirstChild("Media")
	const content = card:FindFirstChild("Content")
	if not content then
		return
	end
	const title = content:FindFirstChild("Title")
	const subtitle = content:FindFirstChild("Subtitle")
	const badges = content:FindFirstChild("Badges")
	const stats = content:FindFirstChild("Stats")
	const desc = content:FindFirstChild("Description")
	const actions = card:FindFirstChild("Actions")
	const function setSize(obj, w, h)
		const size = UDim2.new(0, math.max(0, math.floor(w + 0.5)), 0, math.max(0, math.floor(h + 0.5)))
		if obj.Size ~= size then
			obj.Size = size
		end
	end
	const function setPos(obj, x, y)
		const pos = UDim2.new(0, math.floor(x + 0.5), 0, math.floor(y + 0.5))
		if obj.Position ~= pos then
			obj.Position = pos
		end
	end
	local mediaW = 0
	local mediaH = 0
	if media then
		if stack then
			mediaH = math.clamp(math.floor(contentW * 9 / 16), 96, 160)
			mediaW = math.min(contentW, math.floor(mediaH * 16 / 9))
			setSize(media, mediaW, mediaH)
			setPos(media, pad + math.floor((contentW - mediaW) / 2), pad)
		else
			mediaW = 160
			mediaH = 160
			setSize(media, mediaW, mediaH)
			setPos(media, pad, pad)
		end
	end
	const contentX = stack and pad or (pad + (media and mediaW + gap or 0))
	const contentY = stack and (pad + mediaH + (media and 10 or 0)) or pad
	const flowW = stack and contentW or math.max(140, width - contentX - pad)
	const titleSize = phone and 14 or 16
	const titleLineH = math.ceil(titleSize * 1.24)
	const titleMax = stack and 3 or 2
	local titleH = 0
	if title then
		if title.TextSize ~= titleSize then
			title.TextSize = titleSize
		end
		const measured = NAmanage.ScriptHub_Measure(title.Text, titleSize, flowW, Enum.Font.GothamMedium)
		const lines = math.clamp(math.ceil(measured.Y / math.max(1, titleLineH)), 1, titleMax)
		titleH = lines * titleLineH
		setSize(title, flowW, titleH)
		setPos(title, 0, 0)
	end
	local subH = 0
	if subtitle and subtitle.Text ~= "" then
		const subSize = 11
		if subtitle.TextSize ~= subSize then
			subtitle.TextSize = subSize
		end
		subH = math.clamp(math.ceil(NAmanage.ScriptHub_Measure(subtitle.Text, subSize, flowW, Enum.Font.Gotham).Y), 16, 32)
		setSize(subtitle, flowW, subH)
		setPos(subtitle, 0, titleH + 3)
	end
	local badgeH = 0
	if badges then
		local rows = 0
		local used = 0
		local count = 0
		for _, chip in badges:GetChildren() do
			if chip:IsA("TextLabel") then
				const chipW = tonumber(chip:GetAttribute("NABadgeWidth")) or math.ceil(chip.TextBounds.X) or 40
				count += 1
				if rows == 0 then
					rows = 1
					used = chipW
				elseif used + 4 + chipW > flowW then
					rows += 1
					used = chipW
				else
					used += 4 + chipW
				end
			end
		end
		badgeH = count > 0 and (rows * 18 + (rows - 1) * 4) or 0
		setSize(badges, flowW, badgeH)
		setPos(badges, 0, titleH + (subH > 0 and subH + 3 or 0) + (badgeH > 0 and 5 or 0))
	end
	local statH = 0
	if stats and stats.Text ~= "" then
		const statSize = phone and 10 or 11
		if stats.TextSize ~= statSize then
			stats.TextSize = statSize
		end
		statH = math.ceil(statSize * 1.4)
		const statY = titleH + (subH > 0 and subH + 3 or 0) + (badgeH > 0 and badgeH + 5 or 0) + 3
		setSize(stats, flowW, statH)
		setPos(stats, 0, statY)
	end
	local descH = 0
	if desc and desc.Text ~= "" then
		const descSize = phone and 10 or 11
		const descLineH = math.ceil(descSize * 1.42)
		if desc.TextSize ~= descSize then
			desc.TextSize = descSize
		end
		const measured = NAmanage.ScriptHub_Measure(desc.Text, descSize, flowW, Enum.Font.Gotham)
		descH = math.clamp(math.ceil(measured.Y), descLineH, descLineH * 2)
		const descY = titleH + (subH > 0 and subH + 3 or 0) + (badgeH > 0 and badgeH + 5 or 0) + (statH > 0 and statH + 3 or 0) + 4
		setSize(desc, flowW, descH)
		setPos(desc, 0, descY)
	end
	const flowH = titleH + (subH > 0 and subH + 3 or 0) + (badgeH > 0 and badgeH + 5 or 0) + (statH > 0 and statH + 3 or 0) + (descH > 0 and descH + 4 or 0)
	setSize(content, flowW, flowH)
	setPos(content, contentX, contentY)
	local actCount = 0
	if actions then
		for _, child in actions:GetChildren() do
			if child:IsA("GuiButton") then
				actCount += 1
			end
		end
	end
	local actH = 0
	if actions and actCount > 0 then
		const actGap = 6
		const minW = phone and 104 or 100
		const maxCols = width >= 760 and 5 or width >= 620 and 4 or 3
		const columns = math.clamp(math.floor((flowW + actGap) / (minW + actGap)), 1, math.min(maxCols, actCount))
		const rows = math.ceil(actCount / columns)
		const cellW = math.floor((flowW - (columns - 1) * actGap) / columns)
		actH = rows * 30 + (rows - 1) * actGap
		const grid = actions:FindFirstChildOfClass("UIGridLayout")
		if grid then
			const cell = UDim2.new(0, cellW, 0, 30)
			if grid.CellSize ~= cell then
				grid.CellSize = cell
			end
			if grid.FillDirectionMaxCells ~= columns then
				grid.FillDirectionMaxCells = columns
			end
		end
		const btnSize = width < 700 and 11 or 12
		for _, child in actions:GetChildren() do
			if child:IsA("GuiButton") and child.TextSize ~= btnSize then
				child.TextSize = btnSize
			end
		end
	end
	local actY = contentY + flowH + 8
	if not stack and mediaH > actH then
		actY = math.max(actY, pad + mediaH - actH)
	end
	if actions then
		if actCount > 0 then
			actions.Visible = true
			setSize(actions, flowW, actH)
			setPos(actions, contentX, actY)
		else
			actions.Visible = false
			setSize(actions, flowW, 0)
		end
	end
	const bodyBottom = math.max(contentY + flowH, pad + mediaH, actCount > 0 and actY + actH or 0)
	const cardH = math.max(80, math.ceil(bodyBottom + pad))
	const cardSize = UDim2.new(1, -4, 0, cardH)
	if card.Size ~= cardSize then
		card.Size = cardSize
	end
end

NAmanage.ScriptHub_BindCardResize = function(card)
	local last = 0
	const function update()
		if not card.Parent then return end
		const width = card.AbsoluteSize.X / NAmanage.ScriptHub_CardScale()
		if width <= 1 or math.abs(width - last) < 0.5 then return end
		last = width
		NAmanage.ScriptHub_LayoutCard(card, width)
		if not card.Visible then card.Visible = true end
	end
	NAlib.connect("NAScriptHubCards", card:GetPropertyChangedSignal("AbsoluteSize"):Connect(update))
	update()
	Defer(update)
end

NAmanage.ScriptHub_CreateActionButton = function(parent, text, width, background, iconName)
	const button = InstanceNew("TextButton", parent)
	button.Name = text
	button.BorderSizePixel = 0
	button.AutoButtonColor = false
	button.BackgroundColor3 = background
	button.BackgroundTransparency = 0.12
	button.Size = UDim2.new(0, width or 96, 0, 30)
	button.TextTruncate = Enum.TextTruncate.AtEnd
	button.TextWrapped = false
	NAmanage.ScriptHub_SetActionText(button, text, iconName)
	button.TextColor3 = Color3.fromRGB(245, 245, 250)
	button.TextSize = 11
	button.FontFace = NAmanage.uiBoldFont
	const corner = InstanceNew("UICorner", button)
	corner.CornerRadius = UDim.new(0, 6)
	const stroke = InstanceNew("UIStroke", button)
	stroke.Name = "UIStroker"
	stroke.Thickness = 1.25
	stroke.Color = NAUISTROKER or Color3.fromRGB(155, 100, 255)
	stroke.Transparency = 0.25
	return button
end

NAmanage.ScriptHub_CreateCard = function(data, order)
	const hub = NAmanage.ScriptHub
	const ui = hub.ui or NAmanage.ScriptHub_GetUI()
	const results = ui and ui.results
	if not results then
		return
	end
	const titleText = tostring(data.title or data.name or "Untitled Script")
	const requiresKey = NAmanage.ScriptHub_RequiresKey(data)
	const stats = type(data.stats) == "table" and data.stats or {}
	const flags = type(data.flags) == "table" and data.flags or {}
	const views = data.views or data.viewCount or stats.views
	const likes = data.likes or data.likeCount or stats.likes
	const creator = type(data.creator) == "table" and data.creator or nil
	const author = type(data.author) == "table" and data.author or nil
	const owner = type(data.owner) == "table" and data.owner or nil
	local verified = data.verified == true or flags.verified == true
	if not verified and creator then
		verified = creator.isVerified == true
	end
	if not verified and author then
		verified = author.verified == true or author.isVerified == true or author.isScripterVerified == true
	end
	if not verified and owner then
		verified = owner.verified == true or owner.isVerified == true
	end
	const universal = NAmanage.ScriptHub_IsUniversal(data)
	const catalogEntry = data.naCatalog == true
	const savedEntry = data.naSaved == true
	const gameName = NAmanage.ScriptHub_GetGameName(data)
	const placeId = NAmanage.ScriptHub_GetPlaceId(data)
	local imageUrl = NAmanage.ScriptHub_ResolveImageURL(data)
	if not imageUrl and placeId then
		imageUrl = NAmanage.ScriptHub_BuildPlaceThumbnail(placeId)
	end
	local status = savedEntry and "Saved" or catalogEntry and "Supported" or hub.engine == "RobloxScripts" and "Published" or (data.isPatched == true or data.patched == true or flags.patched == true) and "Patched" or "Working"
	const paid = NAmanage.ScriptHub_IsPaid(data)
	const mobile = data.isMobileReady == true or data.mobileReady == true or data.mobileSupported == true or flags.mobileSupported == true
	local authorName = ""
	for _, value in { data.authorName, data.creatorName, data.username, creator and (creator.username or creator.name or creator.displayName), author and (author.username or author.name or author.displayName), owner and (owner.username or owner.name or owner.displayName), type(data.author) == "string" and data.author or nil, type(data.creator) == "string" and data.creator or nil } do
		if type(value) == "string" and value ~= "" then
			authorName = value
			break
		end
	end
	local provider = type(data.naProvider) == "string" and data.naProvider ~= "" and data.naProvider or type(data.provider) == "string" and data.provider ~= "" and data.provider or ""
	if provider == "" then
		provider = savedEntry and tostring(data.savedEngine or "Saved") or catalogEntry and "NA Catalog" or tostring(hub.engine or "Script Hub")
	end
	if not savedEntry and not catalogEntry then
		const sites = { ScriptBlox = "scriptblox.com", RobloxScripts = "robloxscripts.com", RoScripts = "roscripts.io", RScripts = "rscripts.net", HaxHell = "haxhell.com" }
		provider = sites[provider] or provider
	end
	const width = NAmanage.ScriptHub_CardsWidth(results)
	const cardWidth = width > 1 and width or (hub.phone and 320 or 520)
	const stack = cardWidth < 520
	const phone = cardWidth < 420
	local description = type(data.description) == "string" and GSub(data.description, "%c", " ") or ""
	const descriptionLimit = phone and 120 or stack and 150 or 190
	if #description > descriptionLimit then
		description = Sub(description, 1, descriptionLimit - 3).."..."
	end
	const secondary = {}
	if gameName ~= "" then
		secondary[#secondary + 1] = gameName
	elseif universal then
		secondary[#secondary + 1] = "Universal"
	end
	if provider ~= "" then
		secondary[#secondary + 1] = provider
	end
	if authorName ~= "" then
		secondary[#secondary + 1] = "by "..authorName
	end
	if #secondary == 0 then
		secondary[#secondary + 1] = "Script Hub"
	end
	const statsText = {}
	const viewCount = tonumber(views)
	const likeCount = tonumber(likes)
	if viewCount and viewCount > 0 then
		statsText[#statsText + 1] = NAmanage.ScriptHub_FormatStat(viewCount).." views"
	end
	if likeCount and likeCount > 0 then
		statsText[#statsText + 1] = NAmanage.ScriptHub_FormatStat(likeCount).." likes"
	end
	if savedEntry and tonumber(data.savedAt) and data.savedAt > 0 then
		statsText[#statsText + 1] = "Saved "..os.date("%Y-%m-%d", data.savedAt)
	elseif catalogEntry and placeId then
		statsText[#statsText + 1] = "Place ID "..tostring(placeId)
	end

	const card = InstanceNew("Frame", results)
	card.Name = "ScriptHubCard"
	card.Visible = false
	card.LayoutOrder = order
	card.BorderSizePixel = 0
	card.BackgroundColor3 = Color3.fromRGB(42, 42, 49)
	card.BackgroundTransparency = 0.12
	card.Size = UDim2.new(1, -4, 0, 160)
	card.ClipsDescendants = true
	const corner = InstanceNew("UICorner", card)
	corner.CornerRadius = UDim.new(0, 6)
	const stroke = InstanceNew("UIStroke", card)
	stroke.Name = "UIStroker"
	stroke.Thickness = 1.25
	stroke.Color = NAUISTROKER or Color3.fromRGB(155, 100, 255)
	stroke.Transparency = 0.35

	if imageUrl then
		const media = InstanceNew("Frame", card)
		media.Name = "Media"
		media.BorderSizePixel = 0
		media.BackgroundColor3 = Color3.fromRGB(25, 25, 31)
		media.BackgroundTransparency = 0.08
		media.ClipsDescendants = true
		media.Size = UDim2.new(0, 160, 0, 160)
		const mediaCorner = InstanceNew("UICorner", media)
		mediaCorner.CornerRadius = UDim.new(0, 6)
		const cover = InstanceNew("ImageLabel", media)
		cover.Name = "Cover"
		cover.BorderSizePixel = 0
		cover.BackgroundTransparency = 1
		cover.Size = UDim2.new(1, 0, 1, 0)
		cover.Image = ""
		cover.ImageTransparency = 1
		cover.ScaleType = Enum.ScaleType.Fit
		NAmanage.ScriptHub_LoadImage(cover, imageUrl)
	end

	const content = InstanceNew("Frame", card)
	content.Name = "Content"
	content.BorderSizePixel = 0
	content.BackgroundTransparency = 1
	content.Size = UDim2.new(0, 0, 0, 0)

	const title = InstanceNew("TextLabel", content)
	title.Name = "Title"
	title.BorderSizePixel = 0
	title.BackgroundTransparency = 1
	title.TextXAlignment = Enum.TextXAlignment.Left
	title.TextYAlignment = Enum.TextYAlignment.Top
	title.TextWrapped = true
	title.TextTruncate = Enum.TextTruncate.AtEnd
	title.Text = titleText
	title.TextColor3 = Color3.fromRGB(245, 245, 250)
	title.TextSize = 16
	title.Font = Enum.Font.GothamMedium

	const subtitle = InstanceNew("TextLabel", content)
	subtitle.Name = "Subtitle"
	subtitle.BorderSizePixel = 0
	subtitle.BackgroundTransparency = 1
	subtitle.TextXAlignment = Enum.TextXAlignment.Left
	subtitle.TextTruncate = Enum.TextTruncate.AtEnd
	subtitle.Text = Concat(secondary, "  ·  ")
	subtitle.TextWrapped = true
	subtitle.TextYAlignment = Enum.TextYAlignment.Top
	subtitle.TextColor3 = Color3.fromRGB(188, 190, 205)
	subtitle.TextSize = 11
	subtitle.Font = Enum.Font.Gotham

	const badges = InstanceNew("Frame", content)
	badges.Name = "Badges"
	badges.BorderSizePixel = 0
	badges.BackgroundTransparency = 1
	badges.ClipsDescendants = true
	const badgeLayout = InstanceNew("UIListLayout", badges)
	badgeLayout.FillDirection = Enum.FillDirection.Horizontal
	badgeLayout.HorizontalAlignment = Enum.HorizontalAlignment.Left
	badgeLayout.VerticalAlignment = Enum.VerticalAlignment.Top
	badgeLayout.Wraps = true
	badgeLayout.Padding = UDim.new(0, 4)
	badgeLayout.SortOrder = Enum.SortOrder.LayoutOrder
	const statusColor = status == "Patched" and Color3.fromRGB(112, 48, 58) or status == "Saved" and Color3.fromRGB(104, 74, 38) or status == "Supported" and Color3.fromRGB(42, 100, 74) or status == "Published" and Color3.fromRGB(45, 82, 132) or Color3.fromRGB(42, 104, 78)
	local badge = NAmanage.ScriptHub_CreateBadge(badges, status, statusColor)
	badge.LayoutOrder = 1
	badge = NAmanage.ScriptHub_CreateBadge(badges, requiresKey and "Key Required" or "No Key", requiresKey and Color3.fromRGB(110, 80, 38) or Color3.fromRGB(42, 96, 72))
	badge.LayoutOrder = 2
	if verified then
		badge = NAmanage.ScriptHub_CreateBadge(badges, "Verified", Color3.fromRGB(56, 82, 132))
		badge.LayoutOrder = 3
	end
	if paid then
		badge = NAmanage.ScriptHub_CreateBadge(badges, "Paid", Color3.fromRGB(110, 62, 42))
		badge.LayoutOrder = 4
	end
	if mobile then
		badge = NAmanage.ScriptHub_CreateBadge(badges, "Mobile", Color3.fromRGB(48, 92, 104))
		badge.LayoutOrder = 5
	end

	if #statsText > 0 then
		const statsLabel = InstanceNew("TextLabel", content)
		statsLabel.Name = "Stats"
		statsLabel.BorderSizePixel = 0
		statsLabel.BackgroundTransparency = 1
		statsLabel.TextXAlignment = Enum.TextXAlignment.Left
		statsLabel.TextTruncate = Enum.TextTruncate.AtEnd
		statsLabel.Text = Concat(statsText, "  ·  ")
		statsLabel.TextColor3 = Color3.fromRGB(158, 160, 178)
		statsLabel.TextSize = 11
		statsLabel.Font = Enum.Font.Gotham
	end

	if description ~= "" then
		const descLabel = InstanceNew("TextLabel", content)
		descLabel.Name = "Description"
		descLabel.BorderSizePixel = 0
		descLabel.BackgroundTransparency = 1
		descLabel.TextXAlignment = Enum.TextXAlignment.Left
		descLabel.TextYAlignment = Enum.TextYAlignment.Top
		descLabel.TextWrapped = true
		descLabel.TextTruncate = Enum.TextTruncate.AtEnd
		descLabel.Text = description
		descLabel.TextColor3 = Color3.fromRGB(198, 199, 214)
		descLabel.TextSize = 11
		descLabel.Font = Enum.Font.Gotham
	end

	const actions = InstanceNew("Frame", card)
	actions.Name = "Actions"
	actions.BorderSizePixel = 0
	actions.BackgroundTransparency = 1
	actions.Size = UDim2.new(0, 0, 0, 0)
	const layout = InstanceNew("UIGridLayout", actions)
	layout.FillDirection = Enum.FillDirection.Horizontal
	layout.HorizontalAlignment = Enum.HorizontalAlignment.Left
	layout.VerticalAlignment = Enum.VerticalAlignment.Top
	layout.CellPadding = UDim2.new(0, 6, 0, 6)
	layout.CellSize = UDim2.new(0, 100, 0, 30)
	layout.FillDirectionMaxCells = 0
	layout.SortOrder = Enum.SortOrder.LayoutOrder

	const safeExecute = NAmanage.ScriptHub_CreateActionButton(actions, "Safe Execute", 116, Color3.fromRGB(56, 103, 154), "shield-check")
	safeExecute.LayoutOrder = 1
	NAlib.connect("NAScriptHubCards", safeExecute.MouseButton1Click:Connect(function()
		NAmanage.ScriptHub_SafeRunEntry(data)
	end))
	const execute = NAmanage.ScriptHub_CreateActionButton(actions, "Execute", 98, Color3.fromRGB(45, 125, 88), "bullet-flying")
	execute.LayoutOrder = 2
	NAlib.connect("NAScriptHubCards", execute.MouseButton1Click:Connect(function()
		NAmanage.ScriptHub_RunEntry(data)
	end))
	if not universal and placeId then
		const join = NAmanage.ScriptHub_CreateActionButton(actions, "Join", 84, Color3.fromRGB(48, 91, 158), "person-teleport")
		join.LayoutOrder = 0
		NAlib.connect("NAScriptHubCards", join.MouseButton1Click:Connect(function()
			NAmanage.ScriptHub_JoinEntry(data)
		end))
	end
	if type(setclipboard) == "function" then
		const copy = NAmanage.ScriptHub_CreateActionButton(actions, "Copy", 84, Color3.fromRGB(65, 68, 82), "chain-link")
		copy.LayoutOrder = 3
		NAlib.connect("NAScriptHubCards", copy.MouseButton1Click:Connect(function()
			NAmanage.ScriptHub_CopyEntry(data)
		end))
	end
	if hub.tabMode == "public" and not catalogEntry and not savedEntry then
		const save = NAmanage.ScriptHub_CreateActionButton(actions, "Save", 84, Color3.fromRGB(118, 82, 42), "floppy-disk")
		save.LayoutOrder = 4
		NAlib.connect("NAScriptHubCards", save.MouseButton1Click:Connect(function()
			NAmanage.ScriptHub_SaveEntry(data, save)
		end))
	end
	if savedEntry then
		const delete = NAmanage.ScriptHub_CreateActionButton(actions, "Delete", 84, Color3.fromRGB(132, 50, 57))
		delete.LayoutOrder = 5
		NAlib.connect("NAScriptHubCards", delete.MouseButton1Click:Connect(function()
			NAmanage.ScriptHub_DeleteSavedEntry(data, delete)
		end))
	end
	const discordLink = type(data.discord) == "string" and data.discord ~= "" and data.discord or data.discordUrl
	if type(discordLink) == "string" and discordLink ~= "" and type(setclipboard) == "function" then
		const discord = NAmanage.ScriptHub_CreateActionButton(actions, "Discord", 84, Color3.fromRGB(52, 90, 155), "discord")
		discord.LayoutOrder = 6
		NAlib.connect("NAScriptHubCards", discord.MouseButton1Click:Connect(function()
			local okCopy = pcall(setclipboard, discordLink)
			DoNotif(okCopy and "Discord link copied." or "Failed to copy Discord link.", 2, "Script Hub")
		end))
	end

	if type(data.pageUrl) == "string" and data.pageUrl ~= "" and type(setclipboard) == "function" then
		const page = NAmanage.ScriptHub_CreateActionButton(actions, "Page Link", 94, Color3.fromRGB(65, 68, 82), "chain-link")
		page.LayoutOrder = 7
		NAlib.connect("NAScriptHubCards", page.MouseButton1Click:Connect(function()
			const ok = pcall(setclipboard, data.pageUrl)
			DoNotif(ok and "Script page link copied." or "Failed to copy script page link.", 2, "Script Hub")
		end))
	end

	NAmanage.ScriptHub_BindCardResize(card)
end

NAmanage.ScriptHub_Render = function()
	const hub = NAmanage.ScriptHub
	if hub.searching then return end
	hub.rendering = true
	NAmanage.ScriptHub_ClearResults()
	for index, data in hub.entries do
		NAmanage.ScriptHub_CreateCard(data, index)
	end
	if #hub.entries == 0 then
		const opts = hub.searchOpts
		const filtered = opts and (hub.query ~= "" and opts.mode ~= "all" or opts.include ~= "" or opts.exclude ~= "" or hub.tabMode == "public" and opts.hidePaid)
		local text = hub.tabMode == "supported" and "No catalog scripts found" or hub.tabMode == "saved" and (hub.query ~= "" and "No saved scripts found" or "No saved scripts yet") or "No scripts found"
		if filtered then
			if hub.tabMode == "public" then
				text = hub.page < hub.totalPages and "No matches on this page. Try Next." or "No matches on this page"
			else
				text = "No matches found"
			end
		elseif hub.tabMode == "public" and hub.filterMode == "keyless" then
			text = "No keyless scripts found on this page"
		elseif hub.tabMode == "public" and hub.filterMode == "key" then
			text = "No key-required scripts found on this page"
		end
		NAmanage.ScriptHub_Message(text, Color3.fromRGB(105, 78, 42))
	end
	NAmanage.ScriptHub_UpdateControls()
	hub.rendering = false
	Defer(function()
		const ui = hub.ui or NAmanage.ScriptHub_GetUI()
		const results = ui and ui.results
		if results and results.Parent then
			pcall(updateCanvasSize, results, NAUIMANAGER and NAUIMANAGER.AUTOSCALER and NAUIMANAGER.AUTOSCALER.Scale or nil)
			if NAmanage.ScriptHubScroll and NAmanage.ScriptHubScroll.setTarget then
				pcall(NAmanage.ScriptHubScroll.setTarget, results)
			end
			if NAmanage.ScriptHubScroll and NAmanage.ScriptHubScroll.scheduleRefresh then
				pcall(NAmanage.ScriptHubScroll.scheduleRefresh)
			end
		end
	end)
end

NAmanage.ScriptHub_FetchCatalogGameIcons = function(entries)
	const placeIds = {}
	const seen = {}
	for _, entry in entries do
		if type(entry) == "table" and type(entry.placeIds) == "table" then
			for _, rawId in entry.placeIds do
				const id = tostring(rawId or "")
				if id ~= "" and not seen[id] then
					seen[id] = true
					Insert(placeIds, id)
				end
			end
		end
	end
	if #placeIds == 0 then
		return {}
	end

	const query = "placeIds="..Services.HttpService:UrlEncode(Concat(placeIds, ",")).."&returnPolicy=PlaceHolder&size=256x256&format=Png&isCircular=false"
	local decoded
	for _, host in { "thumbnails.roproxy.com", "thumbnails.rotunnel.com", "thumbnails.roblox.com" } do
		local okFetch, body = NAmanage.HttpGet("https://"..host.."/v1/places/gameicons?"..query, {
			timeout = 8;
			maxAttempts = 2;
			Headers = { Accept = "application/json" };
		})
		if okFetch and type(body) == "string" and body ~= "" then
			local okDecode, payload = pcall(Services.HttpService.JSONDecode, Services.HttpService, body)
			if okDecode and type(payload) == "table" and type(payload.data) == "table" then
				decoded = payload
				break
			end
		end
	end

	const icons = {}
	for _, item in type(decoded) == "table" and decoded.data or {} do
		const id = tostring(type(item) == "table" and item.targetId or "")
		const imageUrl = type(item) == "table" and item.imageUrl or nil
		if id ~= "" and type(imageUrl) == "string" and imageUrl ~= "" then
			icons[id] = imageUrl
		end
	end
	return icons
end

NAmanage.ScriptHub_FetchCatalogGameNames = function(entries)
	const universeIds = {}
	const seen = {}
	for _, entry in entries do
		if type(entry) == "table" and type(entry.universeIds) == "table" then
			for _, rawId in entry.universeIds do
				const id = tostring(rawId or "")
				if id ~= "" and not seen[id] then
					seen[id] = true
					Insert(universeIds, id)
				end
			end
		end
	end
	if #universeIds == 0 then
		return {}
	end

	const query = "universeIds="..Services.HttpService:UrlEncode(Concat(universeIds, ","))
	local decoded
	for _, host in { "games.roproxy.com", "games.rotunnel.com", "games.roblox.com" } do
		local okFetch, body = NAmanage.HttpGet("https://"..host.."/v1/games?"..query, {
			timeout = 8;
			maxAttempts = 2;
			Headers = { Accept = "application/json" };
		})
		if okFetch and type(body) == "string" and body ~= "" then
			local okDecode, payload = pcall(Services.HttpService.JSONDecode, Services.HttpService, body)
			if okDecode and type(payload) == "table" and type(payload.data) == "table" then
				decoded = payload
				break
			end
		end
	end

	const names = {}
	for _, item in type(decoded) == "table" and decoded.data or {} do
		const universeId = tostring(type(item) == "table" and item.id or "")
		const rootPlaceId = tostring(type(item) == "table" and item.rootPlaceId or "")
		const gameName = type(item) == "table" and item.name or nil
		if type(gameName) == "string" and gameName ~= "" then
			if universeId ~= "" then
				names[universeId] = gameName
			end
			if rootPlaceId ~= "" then
				names[rootPlaceId] = gameName
			end
		end
	end
	return names
end

NAmanage.ScriptHub_LoadSupported = function(query, page, refresh)
	const hub = NAmanage.ScriptHub
	if hub.searching or hub.tabMode ~= "supported" then
		return false
	end
	query = GSub(GSub(tostring(query or ""), "^%s+", ""), "%s+$", "")
	page = math.max(math.floor(tonumber(page) or 1), 1)
	hub.query = query
	hub.page = page
	hub.totalPages = 1
	hub.entries = {}
	hub.loaded = false
	NAmanage.ScriptHub_ClearImageCache()
	hub.searching = true
	hub.fetchToken += 1
	const token = hub.fetchToken
	const spec = NAmanage.ScriptHub_MakeSearch(query, hub.searchOpts)
	NAmanage.ScriptHub_Message("Loading my scripts...", Color3.fromRGB(65, 62, 82))
	NAmanage.ScriptHub_UpdateControls()
	SpawnCall(function()
		local okCatalog, entriesOrErr = NAmanage.FetchScriptCatalog({ refresh = refresh == true })
		if token ~= hub.fetchToken or hub.tabMode ~= "supported" then
			return
		end
		if not okCatalog then
			hub.searching = false
			NAmanage.ScriptHub_Message("Catalog request failed: "..tostring(entriesOrErr), Color3.fromRGB(120, 55, 65))
			NAmanage.ScriptHub_UpdateControls()
			return
		end

		const gameIcons = NAmanage.ScriptHub_FetchCatalogGameIcons(entriesOrErr)
		const gameNames = NAmanage.ScriptHub_FetchCatalogGameNames(entriesOrErr)
		if token ~= hub.fetchToken then return end
		const normalizedQuery = Lower(query)
		const currentGameId = tostring((game and game.GameId) or GameId or "")
		const currentPlaceId = tostring((game and game.PlaceId) or PlaceId or "")
		const matches = {}
		for _, entry in entriesOrErr do
			if type(entry) == "table" then
				const gameLinked = type(entry.placeIds) == "table" and #entry.placeIds > 0 or type(entry.universeIds) == "table" and #entry.universeIds > 0
				const categoryMatch = hub.catalogMode == "all" or hub.catalogMode == "games" and gameLinked or hub.catalogMode == "other" and not gameLinked
				const placeId = type(entry.placeIds) == "table" and entry.placeIds[1]
				const universeId = type(entry.universeIds) == "table" and entry.universeIds[1]
				const gameName = gameLinked and (gameNames[tostring(universeId or "")] or gameNames[tostring(placeId or "")] or NAmanage.ScriptHub_GetGameName(entry)) or ""
				const display = gameLinked and gameName == "" and entry.name or gameName
				local queryMatch = true
				if spec.mode == "all" and normalizedQuery ~= "" then
					local searchable = Lower(tostring(entry.name or "").." "..tostring(entry.id or "").." "..display)
					if type(entry.placeIds) == "table" then searchable ..= " "..Concat(entry.placeIds, " ") end
					if type(entry.universeIds) == "table" then searchable ..= " "..Concat(entry.universeIds, " ") end
					queryMatch = Find(searchable, normalizedQuery, 1, true) ~= nil
				end
				if categoryMatch and queryMatch then
					const currentGame = gameLinked and (NAmanage.ScriptCatalogHasId(entry.universeIds, currentGameId) or NAmanage.ScriptCatalogHasId(entry.placeIds, currentPlaceId)) or false
					const row = {
						naCatalog = true;
						catalogGameLinked = gameLinked;
						id = entry.id;
						name = entry.name;
						title = entry.name;
						gameName = gameName;
						description = entry.description;
						scriptUrl = entry.scriptUrl;
						imageUrl = entry.imageUrl or gameLinked and (gameIcons[tostring(placeId or "")] or NAmanage.ScriptHub_BuildGameIcon(universeId, placeId)) or nil;
						placeIds = entry.placeIds;
						universeIds = entry.universeIds;
						isUniversal = not gameLinked;
						featured = entry.featured == true;
						currentGame = currentGame;
					}
					if NAmanage.ScriptHub_PassesSearch(row, spec) then
						row.gameName = display
						Insert(matches, row)
					end
				end
			end
		end
		table.sort(matches, function(a, b)
			if a.currentGame ~= b.currentGame then
				return a.currentGame == true
			end
			if a.featured ~= b.featured then
				return a.featured == true
			end
			if a.catalogGameLinked ~= b.catalogGameLinked then
				return a.catalogGameLinked == true
			end
			return Lower(a.name) < Lower(b.name)
		end)

		const pageSize = math.max(math.floor(tonumber(hub.supportedPageSize) or 16), 1)
		const totalPages = math.max(math.ceil(#matches / pageSize), 1)
		page = math.clamp(page, 1, totalPages)
		const firstIndex = (page - 1) * pageSize + 1
		const pageEntries = {}
		for index = firstIndex, math.min(firstIndex + pageSize - 1, #matches) do
			Insert(pageEntries, matches[index])
		end
		hub.entries = pageEntries
		hub.totalPages = totalPages
		hub.page = page
		hub.loaded = true
		hub.searching = false
		NAmanage.ScriptHub_Render()
	end)
	return true
end

NAmanage.ScriptHub_ResolveScriptBloxPlaceId = function(data)
	const hub = NAmanage.ScriptHub
	const scriptId = tostring(type(data) == "table" and (data._id or data.id or data.slug) or "")
	if scriptId == "" then
		return nil
	end
	const cacheKey = "ScriptBlox:"..scriptId
	const cached = hub.placeIdCache[cacheKey]
	if cached ~= nil then
		return cached or nil
	end
	local placeId
	local okFetch, body = NAmanage.HttpGet("https://scriptblox.com/api/script/"..Services.HttpService:UrlEncode(scriptId), {
		timeout = 7;
		maxAttempts = 2;
		Headers = { Accept = "application/json" };
	})
	if okFetch and type(body) == "string" and body ~= "" then
		local okDecode, decoded = pcall(Services.HttpService.JSONDecode, Services.HttpService, body)
		const details = okDecode and type(decoded) == "table" and type(decoded.script) == "table" and decoded.script or nil
		placeId = details and NAmanage.ScriptHub_GetPlaceId(details) or nil
	end
	hub.placeIdCache[cacheKey] = placeId or false
	return placeId
end

NAmanage.ScriptHub_ResolveRobloxScriptsPlaceId = function(data)
	const hub = NAmanage.ScriptHub
	const gameData = type(data) == "table" and type(data.game) == "table" and data.game or nil
	const gameName = gameData and tostring(gameData.name or "") or ""
	const wantedName = NAmanage.ScriptHub_NormalizeGameName(gameName)
	const wantedSlug = NAmanage.ScriptHub_NormalizeGameName(gameData and gameData.slug or "")
	if wantedName == "" and wantedSlug == "" then
		return nil
	end
	const cacheKey = "RobloxScripts:"..(wantedSlug ~= "" and wantedSlug or wantedName)
	const cached = hub.placeIdCache[cacheKey]
	if cached ~= nil then
		return cached or nil
	end

	local placeId
	const query = Services.HttpService:UrlEncode(gameName ~= "" and gameName or tostring(gameData.slug or ""))
	for _, host in { "apis.roproxy.com", "apis.rotunnel.com", "apis.roblox.com" } do
		local okFetch, body = NAmanage.HttpGet("https://"..host.."/search-api/omni-search?searchQuery="..query.."&sessionId=na-script-hub", {
			timeout = 7;
			maxAttempts = 1;
			Headers = { Accept = "application/json" };
		})
		if okFetch and type(body) == "string" and body ~= "" then
			local okDecode, decoded = pcall(Services.HttpService.JSONDecode, Services.HttpService, body)
			if okDecode and type(decoded) == "table" and type(decoded.searchResults) == "table" then
				for _, group in decoded.searchResults do
					if type(group) == "table" and group.contentGroupType == "Game" and type(group.contents) == "table" then
						for _, item in group.contents do
							const resultName = NAmanage.ScriptHub_NormalizeGameName(type(item) == "table" and item.name or "")
							if resultName ~= "" and (resultName == wantedName or resultName == wantedSlug) then
								const candidate = tonumber(item.rootPlaceId or item.placeId)
								if candidate and candidate > 0 then
									placeId = candidate
									break
								end
							end
						end
					end
					if placeId then
						break
					end
				end
			end
		end
		if placeId then
			break
		end
	end
	hub.placeIdCache[cacheKey] = placeId or false
	return placeId
end

NAmanage.ScriptHub_HydratePlaceIds = function(entries, engine, token)
	const hub = NAmanage.ScriptHub
	const queue = {}
	for _, data in entries do
		if type(data) == "table" and not NAmanage.ScriptHub_IsUniversal(data) and not NAmanage.ScriptHub_GetPlaceId(data) then
			if engine == "ScriptBlox" or engine == "RobloxScripts" then
				Insert(queue, data)
			end
		end
	end
	if #queue == 0 then
		return true
	end

	local nextIndex = 1
	local running = math.min(#queue, 4)
	for _ = 1, running do
		Spawn(function()
			while token == hub.fetchToken do
				const index = nextIndex
				nextIndex += 1
				const data = queue[index]
				if not data then
					break
				end
				local placeId
				if engine == "ScriptBlox" then
					placeId = NAmanage.ScriptHub_ResolveScriptBloxPlaceId(data)
				else
					placeId = NAmanage.ScriptHub_ResolveRobloxScriptsPlaceId(data)
				end
				if placeId then
					data.naResolvedPlaceId = placeId
				end
			end
			running -= 1
		end)
	end
	const deadline = os.clock() + 12
	while running > 0 and token == hub.fetchToken and os.clock() < deadline do
		task.wait(0.05)
	end
	return token == hub.fetchToken
end

NAmanage.ScriptHub_CleanText = function(value)
	if type(value) ~= "string" then return "" end
	local text = value:gsub("<[^>]->", " "):gsub("&nbsp;", " "):gsub("&quot;", '"'):gsub("&#39;", "'"):gsub("&lt;", "<"):gsub("&gt;", ">"):gsub("&amp;", "&")
	return text:gsub("%c", " "):gsub("%s+", " "):match("^%s*(.-)%s*$")
end

NAmanage.ScriptHub_NormalizeEntry = function(value, engine)
	if type(value) ~= "table" then return nil end
	const data = table.clone(value)
	data.naProvider = engine
	data.title = NAmanage.ScriptHub_CleanText(data.title or data.name)
	if data.title == "" then data.title = "Untitled Script" end
	data.description = NAmanage.ScriptHub_CleanText(data.description)
	const game = type(data.game) == "table" and table.clone(data.game) or {}
	game.name = NAmanage.ScriptHub_CleanText(NAmanage.ScriptHub_GetGameName(data))
	data.game = game
	local author = data.author or data.creator or data.owner or data.user
	if type(author) == "table" then
		author = table.clone(author)
		if author.verified == nil then author.verified = author.isVerified == true or author.isScripterVerified == true end
		data.author = author
	end
	const stats = type(data.stats) == "table" and data.stats or {}
	const flags = type(data.flags) == "table" and data.flags or {}
	data.views = tonumber(data.views or data.viewCount or stats.views or data.viewsTotal) or 0
	data.likes = tonumber(data.likes or data.likeCount or stats.likes) or 0
	if data.mobileReady == nil then data.mobileReady = data.isMobileReady end
	if data.mobileReady == nil then data.mobileReady = flags.mobileSupported end
	if data.keySystem == nil then data.keySystem = data.isKeySystem end
	if data.isPatched == nil then data.isPatched = data.patched == true or flags.patched == true end
	if data.paid == nil then data.paid = NAmanage.ScriptHub_IsPaid(data) end
	data.updatedAt = data.updatedAt or data.lastUpdatedAt or data.lastUpdated or data.lastUpdate or data.lastBump
	const links = type(data.links) == "table" and data.links or {}
	data.pageUrl = data.scriptPageUrl or data.pageUrl or links.webpage
	if type(data.pageUrl) ~= "string" or data.pageUrl == "" then
		const slug = Services.HttpService:UrlEncode(tostring(data.slug or data._id or data.id or ""))
		if slug ~= "" then
			const roots = {
				ScriptBlox = "https://scriptblox.com/script/";
				RobloxScripts = "https://robloxscripts.com/script/";
				RoScripts = "https://roscripts.io/s/";
				RScripts = "https://rscripts.net/script/";
				HaxHell = "https://haxhell.com/scripts/";
			}
			data.pageUrl = roots[engine] and roots[engine]..slug or nil
		end
	end
	return data
end

NAmanage.ScriptHub_RequestHeaders = function(engine)
	const headers = { Accept = "application/json" }
	const key = NAmanage.ScriptHub.rsKey
	if engine == "RScripts" and type(key) == "string" and key ~= "" then
		headers.Authorization = "Bearer "..key
	end
	return headers
end

NAmanage.ScriptHub_BuildURL = function(query, page, engine)
	const hub = NAmanage.ScriptHub
	engine = engine or hub.engine
	query = tostring(query or "")
	page = math.max(math.floor(tonumber(page) or 1), 1)
	if engine == "RobloxScripts" or engine == "RScripts" then query = Sub(query, 1, 100) end
	const encoded = Services.HttpService:UrlEncode(query)
	const mode = hub.filterMode
	local url
	if engine == "RScripts" then
		if type(hub.rsKey) == "string" and hub.rsKey ~= "" then
			page = math.min(page, 200)
			url = Format("https://api.rscripts.net/v1/scripts?page=%d&limit=20&sort=newest", page)
			if mode == "keyless" then url ..= "&noKeySystem=true" end
		else
			url = Format("https://rscripts.net/api/v2/scripts?page=%d&orderBy=date&sort=desc", page)
		end
		if query ~= "" then url ..= "&q="..encoded end
	elseif engine == "RoScripts" then
		if query == "" then
			url = Format("https://api.roscripts.io/v1/scripts?page=%d&max=20&sortBy=updatedAt&order=desc", page)
		else
			url = Format("https://api.roscripts.io/v1/scripts/search?q=%s&page=%d&max=20&sortBy=accuracy&order=desc", encoded, page)
		end
		if mode == "keyless" then url ..= "&key=0" elseif mode == "key" then url ..= "&key=1" end
	elseif engine == "RobloxScripts" then
		page = math.min(page, 200)
		url = Format("https://robloxscripts.com/api/v1/scripts?page=%d&limit=24&sort=newest", page)
		if query ~= "" then url ..= "&q="..encoded end
		if mode == "key" then url ..= "&access=key" end
	elseif engine == "HaxHell" then
		url = query == "" and Format("https://haxhell.com/api/v1/scripts?page=%d&limit=24&sort=latest", page) or Format("https://haxhell.com/api/v1/search/scripts?q=%s&page=%d&limit=24&sort=latest", encoded, page)
		if mode == "keyless" then url ..= "&keySystem=false" elseif mode == "key" then url ..= "&keySystem=true" end
	else
		url = query == "" and Format("https://scriptblox.com/api/script/fetch?page=%d&max=20&sortBy=updatedAt&order=desc", page) or Format("https://scriptblox.com/api/script/search?q=%s&page=%d&max=20&sortBy=accuracy&order=desc", encoded, page)
		if mode == "keyless" then url ..= "&key=0" elseif mode == "key" then url ..= "&key=1" end
	end
	return url
end

NAmanage.ScriptHub_ParseResponse = function(decoded, requestedPage, engine)
	const hub = NAmanage.ScriptHub
	engine = engine or hub.engine
	requestedPage = math.max(math.floor(tonumber(requestedPage) or 1), 1)
	if type(decoded) ~= "table" then return {}, 1, requestedPage, true end
	const data = type(decoded.data) == "table" and decoded.data or {}
	const result = type(decoded.result) == "table" and decoded.result or {}
	const meta = type(decoded.meta) == "table" and decoded.meta or {}
	local entries = {}
	local pageInfo = {}
	if engine == "RScripts" then
		entries = type(decoded.scripts) == "table" and decoded.scripts or type(data.scripts) == "table" and data.scripts or data
		const pag = type(meta.pagination) == "table" and meta.pagination or {}
		pageInfo = type(pag.scripts) == "table" and pag.scripts or type(decoded.info) == "table" and decoded.info or meta
	elseif engine == "RoScripts" then
		entries = type(result.scripts) == "table" and result.scripts or type(data.scripts) == "table" and data.scripts or {}
		pageInfo = next(meta) and meta or result
	elseif engine == "RobloxScripts" or engine == "HaxHell" then
		entries = type(decoded.data) == "table" and decoded.data or type(decoded.scripts) == "table" and decoded.scripts or {}
		pageInfo = type(decoded.pagination) == "table" and decoded.pagination or meta
	else
		entries = type(result.scripts) == "table" and result.scripts or type(decoded.scripts) == "table" and decoded.scripts or {}
		pageInfo = result
	end
	local current = tonumber(pageInfo.page or pageInfo.currentPage) or requestedPage
	current = math.max(math.floor(current), 1)
	local total = tonumber(pageInfo.totalPages or pageInfo.pages or pageInfo.lastPage or pageInfo.maxPages or decoded.totalPages)
	const count = tonumber(pageInfo.total or pageInfo.totalItems)
	const limit = tonumber(pageInfo.limit or pageInfo.perPage or pageInfo.max)
	if not total and count and limit and limit > 0 then total = math.ceil(count / limit) end
	const known = total ~= nil
	const more = pageInfo.hasMore == true or pageInfo.hasNextPage == true or tonumber(pageInfo.nextPage) ~= nil and tonumber(pageInfo.nextPage) > current
	total = math.max(math.floor(total or current + (more and 1 or 0)), current, 1)
	if engine == "RobloxScripts" or engine == "RScripts" and type(hub.rsKey) == "string" and hub.rsKey ~= "" then
		total = math.min(total, 200)
		current = math.min(current, total)
	end
	const rows = {}
	for index, value in entries do
		const row = type(index) == "number" and NAmanage.ScriptHub_NormalizeEntry(value, engine)
		if row then
			local variants = 0
			if engine == "RobloxScripts" and row.hasMultipleScripts == true and type(row.variants) == "table" then
				for index, variant in row.variants do
					if type(variant) == "table" and ((type(variant.script) == "string" and variant.script ~= "") or (type(variant.rawScriptUrl) == "string" and variant.rawScriptUrl ~= "")) then
						const copy = table.clone(row)
						copy.id = tostring(row.id or row.slug or row.title)..":variant:"..tostring(index)
						copy._id = nil
						copy.naVariant = index
						copy.naListingTitle = row.title
						copy.title = row.title.." · "..NAmanage.ScriptHub_CleanText(variant.name or tostring(index))
						copy.script = variant.script
						copy.rawScriptUrl = variant.rawScriptUrl
						if type(variant.description) == "string" and variant.description ~= "" then copy.description = NAmanage.ScriptHub_CleanText(variant.description) end
						copy.variants = nil
						rows[#rows + 1] = copy
						variants += 1
					end
				end
			end
			if variants == 0 then rows[#rows + 1] = row end
		end
	end
	return rows, total, current, known
end

NAmanage.ScriptHub_Fetch = function(query, page)
	const hub = NAmanage.ScriptHub
	if hub.tabMode == "supported" then
		return NAmanage.ScriptHub_LoadSupported(query, page)
	end
	if hub.searching then
		return false
	end
	query = tostring(query or "")
	query = GSub(GSub(query, "^%s+", ""), "%s+$", "")
	page = math.max(math.floor(tonumber(page) or 1), 1)
	if hub.query ~= query or page == 1 then
		hub.totalPages = 1
		hub.pagesKnown = true
	end
	hub.query = query
	hub.page = page
	hub.entries = {}
	hub.loaded = false
	if hub.engine == "HaxHell" and query ~= "" and #query < 2 then
		NAmanage.ScriptHub_Message("HaxHell search requires at least 2 characters.", Color3.fromRGB(120, 85, 45))
		NAmanage.ScriptHub_UpdateControls()
		return false
	end
	NAmanage.ScriptHub_ClearImageCache()
	hub.searching = true
	hub.fetchToken += 1
	const token = hub.fetchToken
	const requestEngine = hub.engine
	const filterMode = hub.filterMode
	const spec = NAmanage.ScriptHub_MakeSearch(query, hub.searchOpts)
	NAmanage.ScriptHub_Message("Searching "..hub.engine.."...", Color3.fromRGB(65, 62, 82))
	NAmanage.ScriptHub_UpdateControls()
	SpawnCall(function()
		const url = NAmanage.ScriptHub_BuildURL(query, page, requestEngine)
		local okFetch, body, fetchErr = NAmanage.HttpGet(url, {
			timeout = 12;
			maxAttempts = 2;
			Headers = NAmanage.ScriptHub_RequestHeaders(requestEngine);
		})
		if token ~= hub.fetchToken then
			return
		end
		if not okFetch or type(body) ~= "string" or body == "" then
			hub.searching = false
			NAmanage.ScriptHub_Message("Request failed: "..tostring(fetchErr or "empty response"), Color3.fromRGB(120, 55, 65))
			NAmanage.ScriptHub_UpdateControls()
			return
		end
		local okDecode, decoded = pcall(Services.HttpService.JSONDecode, Services.HttpService, body)
		if not okDecode or type(decoded) ~= "table" then
			hub.searching = false
			NAmanage.ScriptHub_Message("Invalid API response", Color3.fromRGB(120, 55, 65))
			NAmanage.ScriptHub_UpdateControls()
			return
		end
		if decoded.error ~= nil or decoded.success == false or type(decoded.message) == "string" and decoded.result == nil and decoded.data == nil and decoded.scripts == nil then
			hub.searching = false
			local message = type(decoded.error) == "table" and decoded.error.message or decoded.error or decoded.message or "unknown error"
			NAmanage.ScriptHub_Message("API error: "..tostring(message), Color3.fromRGB(120, 55, 65))
			NAmanage.ScriptHub_UpdateControls()
			return
		end
		const rows, totalPages, currentPage, pagesKnown = NAmanage.ScriptHub_ParseResponse(decoded, page, requestEngine)
		const entries = {}
		for _, row in rows do
			if NAmanage.ScriptHub_PassesFilter(row, filterMode, spec.hidePaid) and NAmanage.ScriptHub_PassesSearch(row, spec) then
				Insert(entries, row)
			end
		end
		if not NAmanage.ScriptHub_HydratePlaceIds(entries, requestEngine, token) or token ~= hub.fetchToken then
			return
		end
		hub.entries = entries
		hub.totalPages = totalPages
		hub.pagesKnown = pagesKnown
		hub.page = math.clamp(currentPage, 1, totalPages)
		hub.loaded = true
		hub.searching = false
		NAmanage.ScriptHub_Render()
	end)
	return true
end

NAmanage.ScriptHub_SearchInput = function()
	const hub = NAmanage.ScriptHub
	const ui = hub.ui or NAmanage.ScriptHub_GetUI()
	const query = ui and ui.searchBox and ui.searchBox.Text or ""
	NAmanage.ScriptHub_CloseSearchOptions()
	NAmanage.ScriptHub_CloseEngineDropdown()
	if hub.tabMode == "saved" then
		return NAmanage.ScriptHub_LoadSaved(query, 1)
	end
	return NAmanage.ScriptHub_Fetch(query, 1)
end

NAmanage.ScriptHub_AddSearchOptions = function(ui)
	if ui.options or not ui.searchRow or ui.search.Parent ~= ui.searchRow or ui.searchBox.Parent ~= ui.searchRow then
		return
	end
	const width = 62
	const gap = 5
	const pos = ui.search.Position
	const button = NAmanage.ScriptHub_CreateActionButton(ui.searchRow, "Options", width, Color3.fromRGB(31, 32, 42))
	button.Name = "SearchOptions"
	button.Size = UDim2.new(0, width, ui.search.Size.Y.Scale, ui.search.Size.Y.Offset)
	button.AnchorPoint = Vector2.new(1, ui.search.AnchorPoint.Y)
	button.Position = UDim2.new(pos.X.Scale, pos.X.Offset - gap - ui.search.Size.X.Offset * ui.search.AnchorPoint.X, pos.Y.Scale, pos.Y.Offset)
	const size = ui.searchBox.Size
	ui.searchBox.Size = UDim2.new(size.X.Scale, size.X.Offset - width - gap, size.Y.Scale, size.Y.Offset)
	ui.searchBox.TextTruncate = Enum.TextTruncate.AtEnd
	ui.options = button
end

NAmanage.ScriptHub_ToggleSearchOptions = function()
	const hub = NAmanage.ScriptHub
	const ui = hub.ui or NAmanage.ScriptHub_GetUI()
	if hub.searchMenu then
		NAmanage.ScriptHub_CloseSearchOptions()
		return
	end
	if hub.searching or not (ui and ui.options and ui.frame) then return end
	NAmanage.ScriptHub_CloseEngineDropdown()
	const draft = table.clone(hub.searchOpts)
	const layer = InstanceNew("TextButton", ui.frame)
	layer.Name = "SearchOptionsDismiss"
	layer.Size = UDim2.fromScale(1, 1)
	layer.BackgroundTransparency = 1
	layer.Text = ""
	layer.AutoButtonColor = false
	layer.Selectable = false
	layer.ZIndex = 209
	layer.MouseButton1Click:Connect(NAmanage.ScriptHub_CloseSearchOptions)
	hub.searchMenu = layer
	const menu = InstanceNew("Frame", layer)
	menu.Name = "SearchOptionsMenu"
	menu.Active = true
	menu.AnchorPoint = Vector2.new(1, 0)
	menu.Position = UDim2.new(1, -14, 0, 120)
	menu.Size = UDim2.new(1, -28, 0, hub.tabMode == "public" and 170 or 138)
	menu.BorderSizePixel = 0
	menu.BackgroundColor3 = Color3.fromRGB(20, 21, 28)
	menu.ZIndex = 210
	InstanceNew("UICorner", menu).CornerRadius = UDim.new(0, 6)
	const stroke = InstanceNew("UIStroke", menu)
	stroke.Name = "UIStroker"
	stroke.Color = NAUISTROKER or Color3.fromRGB(155, 100, 255)
	stroke.Transparency = 0.22
	InstanceNew("UISizeConstraint", menu).MaxSize = Vector2.new(350, 170)
	const modes = { "all", "game", "script" }
	const picks = {}
	const function updateMode()
		for index, button in picks do
			NAmanage.ScriptHub_UpdateTabButton(button, draft.mode == modes[index])
		end
	end
	for index, label in { "Any Match", "Exact Game", "Exact Script" } do
		const button = NAmanage.ScriptHub_CreateActionButton(menu, label, nil, Color3.fromRGB(31, 32, 42))
		button.Name = "Mode_"..modes[index]
		button.Size = UDim2.new(1 / 3, -10, 0, 26)
		button.Position = UDim2.new((index - 1) / 3, 8, 0, 8)
		button.ZIndex = 211
		picks[index] = button
		button.MouseButton1Click:Connect(function()
			draft.mode = modes[index]
			updateMode()
		end)
	end
	updateMode()
	const function input(name, labelText, value, y)
		const label = InstanceNew("TextLabel", menu)
		label.Name = name.."Label"
		label.Position = UDim2.fromOffset(8, y)
		label.Size = UDim2.fromOffset(70, 26)
		label.BackgroundTransparency = 1
		label.FontFace = ui.searchBox.FontFace
		label.TextSize = 12
		label.TextColor3 = Color3.fromRGB(206, 209, 220)
		label.TextXAlignment = Enum.TextXAlignment.Left
		label.Text = labelText
		label.ZIndex = 211
		const box = InstanceNew("TextBox", menu)
		box.Name = name
		box.Position = UDim2.fromOffset(78, y)
		box.Size = UDim2.new(1, -86, 0, 26)
		box.BorderSizePixel = 0
		box.BackgroundColor3 = Color3.fromRGB(31, 32, 42)
		box.ClearTextOnFocus = false
		box.FontFace = ui.searchBox.FontFace
		box.TextSize = 12
		box.TextColor3 = Color3.fromRGB(232, 234, 242)
		box.PlaceholderColor3 = Color3.fromRGB(161, 165, 181)
		box.TextXAlignment = Enum.TextXAlignment.Left
		box.TextTruncate = Enum.TextTruncate.AtEnd
		box.PlaceholderText = "Comma-separated terms"
		box.Text = value
		box.ZIndex = 211
		const pad = InstanceNew("UIPadding", box)
		pad.PaddingLeft = UDim.new(0, 7)
		pad.PaddingRight = UDim.new(0, 7)
		InstanceNew("UICorner", box).CornerRadius = UDim.new(0, 5)
		return box
	end
	const include = input("IncludeKeywords", "Include any", draft.include, 40)
	const exclude = input("ExcludeKeywords", "Exclude any", draft.exclude, 72)
	if hub.tabMode == "public" then
		const paid = NAmanage.ScriptHub_CreateActionButton(menu, "Hide Paid", nil, Color3.fromRGB(31, 32, 42))
		paid.Name = "HidePaid"
		paid.Size = UDim2.new(1, -16, 0, 26)
		paid.Position = UDim2.fromOffset(8, 104)
		paid.ZIndex = 211
		const function updatePaid()
			paid.Text = draft.hidePaid and "Hide paid: On" or "Hide paid: Off"
			NAmanage.ScriptHub_UpdateTabButton(paid, draft.hidePaid)
		end
		paid.MouseButton1Click:Connect(function()
			draft.hidePaid = not draft.hidePaid
			updatePaid()
		end)
		updatePaid()
	end
	const reset = NAmanage.ScriptHub_CreateActionButton(menu, "Reset", 76, Color3.fromRGB(31, 32, 42))
	reset.Position = UDim2.new(0, 8, 1, -34)
	reset.Size = UDim2.fromOffset(76, 26)
	reset.ZIndex = 211
	const apply = NAmanage.ScriptHub_CreateActionButton(menu, "Apply", 76, Color3.fromRGB(72, 54, 104))
	apply.Position = UDim2.new(1, -84, 1, -34)
	apply.Size = UDim2.fromOffset(76, 26)
	apply.ZIndex = 211
	const function save(opts)
		NAmanage.ScriptHub_CloseSearchOptions()
		hub.searchOpts = NAmanage.NASettingsSet("scriptHubSearch", opts) or opts
		NAmanage.ScriptHub_UpdateHeader()
		NAmanage.ScriptHub_SearchInput()
	end
	reset.MouseButton1Click:Connect(function()
		save({ mode = "all", include = "", exclude = "", hidePaid = hub.tabMode ~= "public" and draft.hidePaid })
	end)
	apply.MouseButton1Click:Connect(function()
		draft.include = include.Text
		draft.exclude = exclude.Text
		save(draft)
	end)
end

NAmanage.ScriptHub_RequestPage = function(page)
	const hub = NAmanage.ScriptHub
	if hub.searching then
		return
	end
	page = math.clamp(math.floor(tonumber(page) or hub.page), 1, math.max(hub.totalPages, 1))
	if page ~= hub.page then
		if hub.tabMode == "supported" then
			NAmanage.ScriptHub_LoadSupported(hub.query, page)
		elseif hub.tabMode == "saved" then
			NAmanage.ScriptHub_LoadSaved(hub.query, page)
		else
			NAmanage.ScriptHub_Fetch(hub.query, page)
		end
	end
end

NAmanage.ScriptHub_Init = function()
	const hub = NAmanage.ScriptHub
	const ui = NAmanage.ScriptHub_GetUI()
	if not (ui and ui.frame and ui.container and ui.results and ui.searchBox and ui.search and ui.engine and ui.publicTab and ui.supportedTab and ui.savedTab) then
		return false
	end
	if hub.ready and hub.boundFrame == ui.frame then
		return true
	end
	hub.boundFrame = ui.frame
	hub.ready = true
	hub.searchOpts = hub.searchOpts or NAmanage.NASettingsGet("scriptHubSearch")
	NAmanage.ScriptHub_CloseSearchOptions()
	NAmanage.ScriptHub_AddSearchOptions(ui)
	NAlib.disconnect("NAScriptHub")
	if ui.options then
		NAlib.connect("NAScriptHub", ui.options.MouseButton1Click:Connect(NAmanage.ScriptHub_ToggleSearchOptions))
		NAlib.connect("NAScriptHub", ui.frame:GetPropertyChangedSignal("Visible"):Connect(function()
			if not ui.frame.Visible then NAmanage.ScriptHub_CloseSearchOptions() end
		end))
	end
	NAlib.connect("NAScriptHub", ui.publicTab.MouseButton1Click:Connect(function()
		NAmanage.ScriptHub_SetTab("public")
	end))
	NAlib.connect("NAScriptHub", ui.supportedTab.MouseButton1Click:Connect(function()
		NAmanage.ScriptHub_SetTab("supported")
	end))
	NAlib.connect("NAScriptHub", ui.savedTab.MouseButton1Click:Connect(function()
		NAmanage.ScriptHub_SetTab("saved")
	end))
	NAlib.connect("NAScriptHub", ui.engine.MouseButton1Click:Connect(function()
		NAmanage.ScriptHub_ToggleEngineDropdown()
	end))
	NAlib.connect("NAScriptHub", ui.search.MouseButton1Click:Connect(NAmanage.ScriptHub_SearchInput))
	NAlib.connect("NAScriptHub", ui.searchBox.FocusLost:Connect(function(enterPressed)
		if enterPressed then
			NAmanage.ScriptHub_SearchInput()
		end
	end))
	if ui.first then
		NAlib.connect("NAScriptHub", ui.first.MouseButton1Click:Connect(function() NAmanage.ScriptHub_RequestPage(1) end))
	end
	if ui.prev then
		NAlib.connect("NAScriptHub", ui.prev.MouseButton1Click:Connect(function() NAmanage.ScriptHub_RequestPage(hub.page - 1) end))
	end
	if ui.next then
		NAlib.connect("NAScriptHub", ui.next.MouseButton1Click:Connect(function() NAmanage.ScriptHub_RequestPage(hub.page + 1) end))
	end
	if ui.last then
		NAlib.connect("NAScriptHub", ui.last.MouseButton1Click:Connect(function() NAmanage.ScriptHub_RequestPage(hub.totalPages) end))
	end
	if ui.filter then
		NAlib.connect("NAScriptHub", ui.filter.MouseButton1Click:Connect(function()
			if hub.searching then
				return
			end
			if hub.tabMode == "supported" then
				const index = table.find(hub.catalogModes, hub.catalogMode) or 1
				hub.catalogMode = hub.catalogModes[index % #hub.catalogModes + 1]
				NAmanage.ScriptHub_UpdateHeader()
				NAmanage.ScriptHub_LoadSupported(hub.query, 1)
				return
			end
			if hub.tabMode == "saved" then
				return
			end
			const index = table.find(hub.filterModes, hub.filterMode) or 1
			hub.filterMode = hub.filterModes[index % #hub.filterModes + 1]
			NAmanage.ScriptHub_CloseEngineDropdown()
			NAmanage.ScriptHub_Fetch(hub.query, 1)
		end))
	end
	NAmanage.ScriptHub_EnsureImageFolder()
	NAmanage.ScriptHub_UpdateHeader()
	NAmanage.ScriptHub_ApplyResponsive(false)
	NAmanage.ScriptHub_SaveFrameSize = function()
		NAmanage.ExecutorWindowSizing.Save(ui.frame, "NAScriptHubSavedSizeX", "NAScriptHubSavedSizeY")
	end
	NAlib.disconnect("NAScriptHubResponsive")
	NAlib.connect("NAScriptHubResponsive", ui.frame:GetPropertyChangedSignal("Size"):Connect(NAmanage.ScriptHub_SaveFrameSize))
	NAlib.connect("NAScriptHubResponsive", ui.frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		const changed = NAmanage.ScriptHub_UpdateResponsiveLayout()
		if changed and #hub.entries > 0 and hub.rendering ~= true then
			Defer(NAmanage.ScriptHub_Render)
		end
	end))
	if Services.Workspace and Services.Workspace.CurrentCamera then
		NAlib.connect("NAScriptHubResponsive", Services.Workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
			Defer(function()
				if ui.frame and ui.frame.Parent then
					NAmanage.ScriptHub_ApplyResponsive(true)
				end
			end)
		end))
	end
	if NAStuff and NAStuff.NASCREENGUI then
		NAlib.connect("NAScriptHubResponsive", NAStuff.NASCREENGUI:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			Defer(function()
				if ui.frame and ui.frame.Parent then
					NAmanage.ScriptHub_ApplyResponsive(true)
				end
			end)
		end))
	end
	if NAUIMANAGER and NAUIMANAGER.AUTOSCALER then
		NAlib.connect("NAScriptHubResponsive", NAUIMANAGER.AUTOSCALER:GetPropertyChangedSignal("Scale"):Connect(function()
			Defer(function()
				if ui.frame and ui.frame.Parent then
					NAmanage.ScriptHub_ApplyResponsive(true)
				end
			end)
		end))
	end
	if hub.loaded then
		NAmanage.ScriptHub_Render()
	else
		NAmanage.ScriptHub_Message(hub.tabMode == "supported" and "Open this tab to load the NA script catalog." or hub.tabMode == "saved" and "Save a public-hub result to keep it here." or "Search or open the hub to load the latest scripts.", Color3.fromRGB(65, 62, 82))
	end
	return true
end

NAmanage.ScriptHub_Toggle = function()
	const frame = NAUIMANAGER and NAUIMANAGER.ScriptHubFrame
	if not frame then
		DoNotif("Script Hub UI unavailable.", 3, "Script Hub")
		return false
	end
	if not NAmanage.ScriptHub_Init() then
		DoNotif("Script Hub failed to initialize.", 3, "Script Hub")
		return false
	end
	if NAgui.isWindowOpen(frame) then
		NAmanage.ScriptHub_CloseSearchOptions()
		NAgui.closeWindow(frame)
		return true
	end
	NAgui.setWindowVisible(frame, true)
	if NAmanage.OnUIWindowShown then
		pcall(NAmanage.OnUIWindowShown, frame)
	end
	if not NAmanage.ScriptHub.loaded and not NAmanage.ScriptHub.searching then
		if NAmanage.ScriptHub.tabMode == "supported" then
			NAmanage.ScriptHub_LoadSupported(NAmanage.ScriptHub.query, 1)
		elseif NAmanage.ScriptHub.tabMode == "saved" then
			NAmanage.ScriptHub_LoadSaved(NAmanage.ScriptHub.query, 1)
		else
			NAmanage.ScriptHub_Fetch(NAmanage.ScriptHub.query, 1)
		end
	end
	return true
end

do
	const perf = NAStuff and NAStuff.StartupPerformance
	if type(perf) == "table" then
		perf.uiManagerElapsed = os.clock() - uiManagerBuildStart
	end
	pcall(function()
		const probe = NAmanage.GetExternalLagProbe and NAmanage.GetExternalLagProbe()
		if type(probe) == "table" and type(probe.mark) == "function" then
			probe.mark("ui_manager_done")
		end
	end)
end

NAmanage.EnsurePluginsWindow = NAmanage.EnsurePluginsWindow or function()
	const frame = NAUIMANAGER and NAUIMANAGER.PluginsFrame
	if not frame then
		return nil
	end
	if NAUIMANAGER then
		NAUIMANAGER.PluginsContainer = frame:FindFirstChild("Container")
		NAUIMANAGER.PluginsList = NAUIMANAGER.PluginsContainer and NAUIMANAGER.PluginsContainer:FindFirstChild("List")
		NAUIMANAGER.PluginsFilter = NAUIMANAGER.PluginsContainer and NAUIMANAGER.PluginsContainer:FindFirstChild("Filter")
		const container = NAUIMANAGER.PluginsContainer
		const list = NAUIMANAGER.PluginsList
		if list then
			list.ScrollingDirection = Enum.ScrollingDirection.XY
			if NAmanage.CreateCustomScrollbar then
				NAmanage.CreateCustomScrollbar(list)
				NAmanage.CreateCustomScrollbar(list, { axis = "X" })
			end
		end
	end
	return frame
end

