					ctrl._targetConns.layout = layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
						updateCanvasSize(target, NAUIMANAGER and NAUIMANAGER.AUTOSCALER and NAUIMANAGER.AUTOSCALER.Scale or nil);
