					end);
				end;
			end;

			local visible = ctrl.getVisibleSpace(target);
			local total = math.max(visible, ctrl.getTotalSpace(target));
			local maxPos = math.max(0, total - visible);
			local trackSize = registry.getTrackSize(ctrl.axis, track);
