				const currentY = tonumber(logicalPos.Y) or 0;
				if ctrl.axis == "X" then
					NAmanage.SetLogicalCanvasPosition(target, nextPos, currentY);
				else
					NAmanage.SetLogicalCanvasPosition(target, currentX, nextPos);
