		{"Tools", "tools toolview toolview2 equiptools unequiptools equiptool loopequiptool multitool usetools droptool droptools loopdroptools notools copytools grabtools grabtoolsfind loopgrabtools savetools loadtools preventtools gear backpack unloadbackpack deleteselectedtool removespecifictool clearremovespecifictool nocooldown waitcap notween autopatchtool patchtool ibtools f3x telekinesis gravitygun toolinvisible"};
		{"Audio", "music audiologger volume reverb forcereverb stealaudio listen vcworld joinvoice mute loopmute oofspam"};
		{"Chat", "chat privatemessage fakechat chatlogs bubblechat chattranslate uwuify autouwuify uwustutter uwuaffix mimicchat stopmimicchat errorchat clearerror antierror nachat nadisguise rename unname resetfilter"};
		{"Utility", "unload admin unadmin fpscap unfpscap"};
		{"Players", "inspectoutfit avatarpreview clearavatarpreview userpreview inspect accountage getidfromusername getuserfromid copyname copydisplay copyid rolewatch rolewatchstop rolewatchleave joingroup trackstaff stoptrackstaff antistaff friend unfriend block unblock invitefriends friendweb massfollowedinto team"};
		{"Scripting", "url loadstring gcsearch scriptlogger scriptload scripthub gamescripts serverremotespy olddex dex synapsedex decompiler saveinstance partname functionspy rc7 scriptviewer moduleeditor upvalueeditor hydroxide remotespy cobaltspy turtlespy autofireremote autofireremotefind fireremote fireremotes blockremote unblockremote httpspy console oldconsole exportconsole unctest vulnerabilitytest propertychanged"};
		{"Plugins", "pluginmaker addallplugins addplugin reloadplugin removeplugin removeallplugins"};
	}
	const lookup = {}
	const valid = {}
	for _, cat in NAmanage.CommandCategories do
		valid[Lower(cat)] = cat
	end
	for _, row in groups do
		for name in row[2]:gmatch("%S+") do
			lookup[name] = row[1]
		end
	end
	const function resolve(name)
		name = Lower(tostring(name or "")):match("[^:]+$") or ""
		for _ = 1, 4 do
			if lookup[name] then
				return lookup[name]
			end
			if Sub(name, 1, 2) == "un" then
				name = Sub(name, 3)
			elseif Sub(name, 1, 4) == "loop" or Sub(name, 1, 4) == "stop" then
				name = Sub(name, 5)
			else
				break
			end
		end
		return nil
	end
	NAmanage.Commands_GetCategory = function(name, meta)
		meta = type(meta) == "table" and meta or {}
		if meta.pluginType then
			return "Plugins"
		end
		const chosen = valid[Lower(tostring(meta.category or ""))]
		if chosen and chosen ~= "All" then
			return chosen
		end
		local cat = resolve(meta.sourceName or name)
		if not cat then
			for _, alias in meta.aliases or {} do
				cat = resolve(alias)
				if cat then break end
			end
		end
		return cat or "Utility"
	end
end

NAmanage.buildCommandDataPackage = function()
	if type(NAmanage.resetCommandWorkBudget) == "function" then
		NAmanage.resetCommandWorkBudget()
	end
	const signature = NAmanage.getCommandBuildSignature and NAmanage.getCommandBuildSignature() or nil
	const entries = {}
	const metaByName = {}
	const used = {}
	const aliasByFunc = {}
	const dataToName = {}
	const aliasOwnerMap = {}
	const savedOwnerMap = {}
	local aliasStep = 0
	local cmdMapStep = 0
	for name, data in cmds.Commands or {} do
		cmdMapStep += 1
		if name then
			dataToName[data] = tostring(name)
		end
		NAmanage.cmdYield(cmdMapStep, 220)
	end
	for alias, data in cmds.Aliases or {} do
		aliasStep += 1
		NAmanage.cmdYield(aliasStep, 180)
		const lowerAlias = Lower(tostring(alias or ""))
		if lowerAlias ~= "" then
			const owner = dataToName[data]
			if owner then
				aliasOwnerMap[lowerAlias] = owner
			end
		end
		const func = type(data) == "table" and data[1]
		if func then
			local bucket = aliasByFunc[func]
			if not bucket then
				bucket = {}
				aliasByFunc[func] = bucket
			end
			bucket[Lower(tostring(alias))] = true
		end
	end
	for alias, original in cmds.NASAVEDALIASES or {} do
		const lowerAlias = Lower(tostring(alias or ""))
		const lowerOriginal = Lower(tostring(original or ""))
		if lowerAlias ~= "" and lowerOriginal ~= "" then
			savedOwnerMap[lowerAlias] = lowerOriginal
		end
	end
	const function resolveCommandDisplay(name, data)
		const dInfo = data and data[2] and data[2][1] or ""
		const func = data and data[1]
		const aliasSet = {}
		const fromFunc = func and aliasByFunc[func]
		if fromFunc then
			for alias in fromFunc do
				aliasSet[alias] = true
			end
		end
		const main = name and Lower(name)
		local prefix, aliasBlock = dInfo:match("^(.-)%s*%((.-)%)$")
		if aliasBlock then
			for a in aliasBlock:gmatch("[^,%s]+") do
				aliasSet[Lower(a)] = true
			end
		end
		const final = {}
		for alias in aliasSet do
			if alias ~= main then
				Insert(final, alias)
			end
		end
		table.sort(final)
		local updatedText
		if prefix then
			updatedText = prefix.." ("..Concat(final, ", ")..")"
		else
			updatedText = dInfo
			if #final > 0 then
				updatedText = updatedText.." ("..Concat(final, ", ")..")"
			end
		end
		return updatedText, final
	end

	const function addNACommand(name, data)
		if not name or name == "" then return end
		local displayText, extraAliases = resolveCommandDisplay(name, data)
		if displayText and displayText ~= "" then
			if type(data[2]) == "table" then
				data[2][1] = displayText
			end
		else
			displayText = (type(data[2]) == "table" and data[2][1]) or name
		end
		const aliasList = {}
		for _, alias in extraAliases or {} do
			Insert(aliasList, alias:lower())
		end
		const commandMeta = (type(data[4]) == "table") and data[4] or {}
		const isPatched = commandMeta.patched == true
		local isPluginCmd, pluginType = NAmanage.IsPluginCommand and NAmanage.IsPluginCommand(name)
		local pluginTag = nil
		if isPluginCmd then
			pluginTag = pluginType or true -- keep a marker even if type is unknown so coloring works
		end
		local finalText = displayText
		if isPluginCmd then
			finalText = finalText.." ["..(pluginType and (pluginType.." plugin") or "plugin").."]"
		end
		if isPatched then
			finalText = NAgui.addPatchedLabel(finalText)
		end
		if isAprilFools() then
			finalText = maybeMock(finalText)
		end
		local desc = ""
		if type(data[2]) == "table" then
			desc = data[2][2] or ""
		end
		if isPatched then
			if desc == "" then
				desc = "Patched / may not work; might work again later or be removed if it stays patched"
			elseif not Lower(desc):find("patched", 1, true) then
				desc = desc.." (patched; might work again later or be removed if it stays patched)"
			end
		end
		used[Lower(name)] = true
		local searchable = NAmanage.stripMarkup(Lower(finalText or displayText or name))
		if #aliasList > 0 then
			searchable = searchable.." "..Concat(aliasList, " ")
		end
		if desc ~= "" then
			searchable = searchable.." "..NAmanage.stripMarkup(Lower(desc))
		end
		if isPatched then
			searchable = searchable.." patched"
		end
		metaByName[name] = {
			origin = "na";
			displayText = finalText;
			usage = displayText;
			argumentHint = type(commandMeta.argumentHint) == "string" and commandMeta.argumentHint or nil;
			searchable = searchable;
			aliases = aliasList;
			pluginType = pluginTag;
			category = commandMeta.category;
			desc = desc;
			requiresArguments = type(data) == "table" and data[3] == true or false;
			patched = isPatched;
		}
		entries[#entries + 1] = {
			name = name;
			display = finalText;
			meta = metaByName[name];
			sortKey = Lower(tostring(finalText or name));
		}
	end

	local cmdStep = 0
	for name, data in cmds.Commands do
		cmdStep += 1
		addNACommand(name, data)
		NAmanage.cmdYield(cmdStep, 120)
	end

	const cmdList = NAStuff.CmdIntegrationCommands
	if type(cmdList) == "table" then
		for cmdInfoIndex, info in cmdList do
			NAmanage.cmdYield(cmdInfoIndex, 120)
			local baseName = info and info.name
			if baseName then
				baseName = tostring(baseName)
			end
			if baseName and baseName ~= "" then
				const canonicalName = "cmd:"..baseName
				const aliases = { Lower(baseName), Lower(canonicalName) }
				const displayAliases = {}
				const seenAliases = {
					[Lower(baseName)] = true;
					[Lower(canonicalName)] = true;
				}
				if type(info.aliases) == "table" then
					for _, alias in info.aliases do
						const rawAlias = tostring(alias or "")
						const lowerAlias = Lower(rawAlias)
						if rawAlias ~= "" and lowerAlias ~= Lower(baseName) then
							if not seenAliases[lowerAlias] then
								seenAliases[lowerAlias] = true
								Insert(aliases, lowerAlias)
							end
							const explicitAlias = "cmd:"..rawAlias
							const lowerExplicitAlias = Lower(explicitAlias)
							if not seenAliases[lowerExplicitAlias] then
								seenAliases[lowerExplicitAlias] = true
								Insert(aliases, lowerExplicitAlias)
								Insert(displayAliases, explicitAlias)
							end
						end
					end
				end
				local usage = canonicalName
				const argumentHints = {}
				if type(info.arguments) == "table" then
					for index, argument in info.arguments do
						local argumentName = type(argument) == "table" and tostring(argument.name or argument.type or "arg"..tostring(index)) or "arg"..tostring(index)
						if argumentName == "" then
							argumentName = "arg"..tostring(index)
						end
						Insert(argumentHints, "<"..argumentName..">")
					end
				end
				if #argumentHints > 0 then
					usage = usage.." "..Concat(argumentHints, " ")
				end
				const sourceDesc = type(info.desc) == "string" and info.desc or ""
				const descParts = { "Run: "..usage }
				if #displayAliases > 0 then
					Insert(descParts, "Aliases: "..Concat(displayAliases, ", "))
				end
				if sourceDesc ~= "" then
					Insert(descParts, sourceDesc)
				end
				const desc = Concat(descParts, "\n")
				local finalText = "[Cmd] "..canonicalName
				if #displayAliases > 0 then
					finalText = finalText.." ("..Concat(displayAliases, ", ")..")"
				end
				local searchable = NAmanage.stripMarkup(Lower(finalText.." "..baseName))
				if #aliases > 0 then
					searchable = searchable.." "..Concat(aliases, " ")
				end
				if sourceDesc ~= "" then
					searchable = searchable.." "..NAmanage.stripMarkup(Lower(sourceDesc))
				end
				used[Lower(canonicalName)] = true
				metaByName[canonicalName] = {
					origin = "cmd";
					displayText = finalText;
					searchable = searchable;
					aliases = aliases;
					sourceName = baseName;
					duplicate = used[Lower(baseName)] == true;
					usage = usage;
					requiresArguments = #argumentHints > 0 or info.requiresArguments == true or info.RequiresArguments == true;
					desc = desc;
				}
				entries[#entries + 1] = {
					name = canonicalName;
					display = finalText;
					meta = metaByName[canonicalName];
					sortKey = Lower(tostring(finalText));
				}
			end
		end
	end

	const iyList = NAStuff.IYIntegrationCommands
	if type(iyList) == "table" then
		for iyInfoIndex, info in iyList do
			NAmanage.cmdYield(iyInfoIndex, 120)
			local baseName = info and info.name
			if baseName then baseName = tostring(baseName) end
			if baseName and baseName ~= "" then
				const canonicalName = "iy:"..baseName
				const aliases = { Lower(baseName), Lower(canonicalName) }
				const displayAliases = {}
				const seenAliases = { [Lower(baseName)] = true; [Lower(canonicalName)] = true; }
				if type(info.aliases) == "table" then
					for _, alias in info.aliases do
						const rawAlias = tostring(alias or "")
						const lowerAlias = Lower(rawAlias)
						if rawAlias ~= "" and lowerAlias ~= Lower(baseName) then
							if not seenAliases[lowerAlias] then seenAliases[lowerAlias] = true; Insert(aliases, lowerAlias) end
							const explicitAlias = "iy:"..rawAlias
							const lowerExplicitAlias = Lower(explicitAlias)
							if not seenAliases[lowerExplicitAlias] then
								seenAliases[lowerExplicitAlias] = true
								Insert(aliases, lowerExplicitAlias)
								Insert(displayAliases, explicitAlias)
							end
						end
					end
				end
				local usage = canonicalName
				const argumentHints = {}
				if type(info.arguments) == "table" then
					for index, argument in info.arguments do
						local argumentName = type(argument) == "table" and tostring(argument.name or argument.type or "arg"..tostring(index)) or "arg"..tostring(index)
						if argumentName == "" then argumentName = "arg"..tostring(index) end
						Insert(argumentHints, "<"..argumentName..">")
					end
				end
				if #argumentHints > 0 then usage = usage.." "..Concat(argumentHints, " ") end
				const sourceDesc = type(info.desc) == "string" and info.desc or ""
				const descParts = { "Run: "..usage }
				if #displayAliases > 0 then Insert(descParts, "Aliases: "..Concat(displayAliases, ", ")) end
				if sourceDesc ~= "" then Insert(descParts, sourceDesc) end
				const desc = Concat(descParts, "\n")
				local finalText = "[IY] "..canonicalName
				if #displayAliases > 0 then finalText = finalText.." ("..Concat(displayAliases, ", ")..")" end
				local searchable = NAmanage.stripMarkup(Lower(finalText.." "..baseName))
				if #aliases > 0 then searchable = searchable.." "..Concat(aliases, " ") end
				if sourceDesc ~= "" then searchable = searchable.." "..NAmanage.stripMarkup(Lower(sourceDesc)) end
				used[Lower(canonicalName)] = true
				metaByName[canonicalName] = {
					origin = "iy";
					displayText = finalText;
					searchable = searchable;
					aliases = aliases;
					sourceName = baseName;
					duplicate = used[Lower(baseName)] == true;
					usage = usage;
					requiresArguments = #argumentHints > 0 or info.requiresArguments == true or info.RequiresArguments == true;
					desc = desc;
				}
				entries[#entries + 1] = { name = canonicalName; display = finalText; meta = metaByName[canonicalName]; sortKey = Lower(tostring(finalText)); }
			end
		end
	end

	if type(NAmanage.sortCommandEntries) == "function" then
		NAmanage.sortCommandEntries(entries)
	else
		table.sort(entries, function(a, b)
			return tostring(a.sortKey or a.display or a.name) < tostring(b.sortKey or b.display or b.name)
		end)
	end

	const searchEntries = {}
	const defaultEntryMap = {}
	const defaultTargets = {}
	for _, cmdName in defaultBarCommands or {} do
		const lowerCmd = Lower(tostring(cmdName or ""))
		if lowerCmd ~= "" then
			defaultTargets[lowerCmd] = true
		end
	end
	for i = 1, #entries do
		NAmanage.cmdYield(i, 180)
		const entry = entries[i]
		const cmdName = entry and entry.name
		if cmdName then
			const meta = entry.meta or metaByName[cmdName] or {}
			meta.category = NAmanage.Commands_GetCategory(cmdName, meta)
			const lowerName = Lower(tostring(cmdName))
			const extraAliases = {}
			if type(meta.aliases) == "table" then
				for j = 1, #meta.aliases do
					const aliasText = Lower(tostring(meta.aliases[j] or ""))
					if aliasText ~= "" then
						extraAliases[#extraAliases + 1] = aliasText
						if defaultTargets[aliasText] and not defaultEntryMap[aliasText] then
							defaultEntryMap[aliasText] = entry
						end
					end
				end
			end
			if defaultTargets[lowerName] and not defaultEntryMap[lowerName] then
				defaultEntryMap[lowerName] = entry
			end
			searchEntries[#searchEntries + 1] = {
				name = cmdName,
				lowerName = lowerName,
				searchable = meta.searchable or NAmanage.stripMarkup(Lower(tostring(entry.display or cmdName))),
				extraAliases = extraAliases,
				display = entry.display,
				meta = meta,
			}
		end
	end

	return {
		signature = signature;
		totalCount = NAmanage.totalCommandCount and NAmanage.totalCommandCount() or #entries;
		entries = entries;
		metaByName = metaByName;
		searchEntries = searchEntries;
		aliasOwnerMap = aliasOwnerMap;
		savedOwnerMap = savedOwnerMap;
		defaultEntryMap = defaultEntryMap;
	}
end

NAmanage.buildCommandEntries=function()
	const package = NAmanage.buildCommandDataPackage()
	NAStuff.AutofillMetaByName = package and package.metaByName or {}
	return package and package.entries or {}, package and package.metaByName or {}
end

NAmanage.totalCommandCount=function()
	local count = countDictNA(cmds.Commands)
	if type(NAStuff.CmdIntegrationCommands) == "table" then
		count = count + #NAStuff.CmdIntegrationCommands
	end
	if type(NAStuff.IYIntegrationCommands) == "table" then
		count = count + #NAStuff.IYIntegrationCommands
	end
	return count
end
COMMAND_LIST_TOP_PADDING = 5
COMMAND_OVERSCAN_ROWS = 8
COMMAND_MIN_VISIBLE_ROWS = 18

NAmanage.cmdStatic = function()
	return false
end

NAmanage.vpSize = function()
	const sg = NAStuff and NAStuff.NASCREENGUI
	local vp = nil
	if sg and sg.AbsoluteSize then
		vp = sg.AbsoluteSize
	end
	if (not vp or vp.X <= 0 or vp.Y <= 0) and Services.Workspace.CurrentCamera then
		vp = Services.Workspace.CurrentCamera.ViewportSize
	end
	vp = vp or Vector2.new(1280, 720)

	local scale = 1
	const scaler = NAUIMANAGER and NAUIMANAGER.AUTOSCALER
	if scaler then
		scale = tonumber(scaler.Scale) or 1
	end
	if not scale or scale <= 0 then
		scale = 1
	end

	return Vector2.new(math.max(1, vp.X / scale), math.max(1, vp.Y / scale))
end

NAmanage.virtView = function(sf, viewH, totalH, minH)
	const floorH = math.max(1, tonumber(minH) or 1)
	local winH = 0
	if sf and NAmanage.GetLogicalWindowSize then
		local ok, logicalWindow = pcall(NAmanage.GetLogicalWindowSize, sf)
		if ok and logicalWindow then
			winH = tonumber(logicalWindow.Y) or 0
		end
	end

	if winH > 0 then
		viewH = winH
	elseif (tonumber(viewH) or 0) <= 0 then
		const vp = NAmanage.vpSize and NAmanage.vpSize() or Vector2.new(1280, 720)
		viewH = math.max(floorH, vp.Y * 0.25)
	else
		viewH = tonumber(viewH)
	end

	totalH = math.max(0, tonumber(totalH) or 0)
	local y = 0
	local x = 0
	if sf then
		const pos = NAmanage.GetLogicalCanvasPosition and NAmanage.GetLogicalCanvasPosition(sf) or sf.CanvasPosition
		x = tonumber(pos.X) or 0
		y = tonumber(pos.Y) or 0
	end

	const maxY = math.max(0, totalH - viewH)
	y = math.clamp(y, 0, maxY)

	return viewH, y
end

NAmanage.virtRange = function(tops, heights, firstY, lastY)
	const count = #tops
	local lo, hi, first = 1, count, count + 1
	while lo <= hi do
		const mid = math.floor((lo + hi) / 2)
		if tops[mid] + heights[mid] >= firstY then first = mid; hi = mid - 1 else lo = mid + 1 end
	end
	local last = first - 1
	lo, hi = first, count
	while lo <= hi do
		const mid = math.floor((lo + hi) / 2)
		if tops[mid] <= lastY then last = mid; lo = mid + 1 else hi = mid - 1 end
	end
	return first, last
end

NAmanage.cmdResp = function(center)
	const frame = NAUIMANAGER and NAUIMANAGER.commandsFrame
	if not (frame and frame:IsA("GuiObject")) then
		return
	end

	if frame.GetAttribute and NAmanage.GetAttr(frame, "NAMenuMinimized") == true then
		const container = frame:FindFirstChild("Container")
		if container and container:IsA("GuiObject") then
			container.Visible = false
		end
		return
	end

	const vp = NAmanage.vpSize()
	const margin = (vp.X < 420 or vp.Y < 260) and 8 or 16
	const maxW = math.max(180, vp.X - margin)
	const maxH = math.max(118, vp.Y - margin)
	const minW = math.min(260, math.max(180, maxW))
	const minH = math.min(180, math.max(118, maxH))
	const curW = tonumber(frame.Size.X.Offset) or 300
	const curH = tonumber(frame.Size.Y.Offset) or 320
	const nextW = math.clamp(curW, minW, maxW)
	const nextH = math.clamp(curH, minH, maxH)

	if nextW ~= curW or nextH ~= curH then
		frame.Size = UDim2.new(0, math.floor(nextW + 0.5), 0, math.floor(nextH + 0.5))
	end

	const compact = nextH <= 190 or nextW <= 235
	const container = frame:FindFirstChild("Container")
	if container and container:IsA("GuiObject") then
		container.Visible = true
		container.Size = compact and UDim2.new(1, -10, 1, -42) or UDim2.new(1, -15, 1, -50)
		container.Position = compact and UDim2.new(0.5, 0, 1, -6) or UDim2.new(0.5, 0, 1, -10)

		const filter = container:FindFirstChild("Filter")
		if filter and filter:IsA("GuiObject") then
			filter.Size = compact and UDim2.new(1, -8, 0, 20) or UDim2.new(1, -10, 0, 24)
			filter.Position = compact and UDim2.new(0.5, 0, 0, 4) or UDim2.new(0.5, 0, 0, 5)
			if NAlib and NAlib.isProperty and NAlib.isProperty(filter, "TextSize") then
				filter.TextSize = compact and 14 or 16
			end
		end

		const button = container:FindFirstChild("CategoryFilter")
		const menu = container:FindFirstChild("CategoryMenu")
		const empty = container:FindFirstChild("NoCommands")
		const hasCats = button and menu and empty
		const listTop = hasCats and (compact and 55 or 62) or (compact and 27 or 30)
		const list = NAUIMANAGER.commandsList or container:FindFirstChild("List")
		if list and list:IsA("GuiObject") then
			list.Position = UDim2.new(0, compact and 4 or 5, 0, listTop)
			list.Size = UDim2.new(1, compact and -8 or -10, 1, -(listTop + (compact and 4 or 5)))
		end
		if hasCats then
			button.Position = UDim2.new(0, compact and 4 or 5, 0, compact and 28 or 33)
			button.Size = UDim2.new(1, compact and -8 or -10, 0, compact and 22 or 24)
			button.TextSize = compact and 12 or 14
			menu.Position = UDim2.new(0, compact and 4 or 5, 0, listTop)
			const avail = nextH + container.Size.Y.Offset - listTop - 4
			menu.Size = UDim2.new(1, compact and -8 or -10, 0, math.max(0, math.min(#NAmanage.CommandCategories * 28, avail)))
			if list then
				empty.Position = list.Position
				empty.Size = list.Size
			end
		end


	end

	if center and NAmanage.centerFrame then
		NAmanage.centerFrame(frame)
	end
end

NAmanage.Commands_ParseInlineArguments = function(raw)
	const out = {}
	raw = tostring(raw or "")
	if raw == "" then
		return out
	end
	if type(ParseArguments) == "function" then
		local okParse, parsed = pcall(ParseArguments, raw)
		if okParse and type(parsed) == "table" then
			for _, value in parsed do
				out[#out + 1] = value
			end
			return out
		end
	end
	for value in raw:gmatch("%S+") do
		out[#out + 1] = value
	end
	return out
end

NAmanage.Commands_RunInline = function(name, rawArguments)
	name = tostring(name or "")
	if name == "" or type(cmd) ~= "table" or type(cmd.run) ~= "function" then
		return
	end
	const runArgs = { name }
	for _, value in NAmanage.Commands_ParseInlineArguments(rawArguments) do
		runArgs[#runArgs + 1] = value
	end
	SpawnCall(function()
		cmd.run(runArgs)
	end)
end

-- PART 21
NAmanage.Commands_UpdateExpandedMetrics = function(state)
	if type(state) ~= "table" then
		return
	end
	const prev = state.expandedIndex
	state.expandedIndex = nil
	state.expandedExtra = 0
	const expandedName = tostring(state.expandedName or "")
	if expandedName == "" then
		state.expandedName = nil
		return
	end
	const entry = prev and (state.filteredEntries or {})[prev]
	if entry and tostring(entry.name or "") == expandedName then
		state.expandedIndex = prev
		state.expandedExtra = 44
		return
	end
	for index, entry in state.filteredEntries or {} do
		if entry and tostring(entry.name or "") == expandedName then
			state.expandedIndex = index
			state.expandedExtra = 44
			return
		end
	end
	state.expandedName = nil
end

NAStuff.CommandInlineTweens = type(NAStuff.CommandInlineTweens) == "table" and NAStuff.CommandInlineTweens or setmetatable({}, { __mode = "k" })

NAmanage.Commands_StopInlineTween = function(object)
	if not object then
		return
	end
	const tween = NAStuff.CommandInlineTweens and NAStuff.CommandInlineTweens[object]
	if tween then
		pcall(function()
			tween:Cancel()
		end)
		NAStuff.CommandInlineTweens[object] = nil
	end
end

NAmanage.Commands_TweenInline = function(object, goals, duration)
	if not (object and type(goals) == "table") then
		return false
	end
	NAmanage.Commands_StopInlineTween(object)
	if not Services.TweenService then
		for property, value in goals do
			pcall(function()
				object[property] = value
			end)
		end
		return false
	end
	local ok, tween = pcall(function()
		return Services.TweenService:Create(
			object,
			TweenInfo.new(tonumber(duration) or 0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
			goals
		)
	end)
	if not (ok and tween) then
		for property, value in goals do
			pcall(function()
				object[property] = value
			end)
		end
		return false
	end
	NAStuff.CommandInlineTweens[object] = tween
	tween:Play()
	return true
end

NAmanage.Commands_SetInlineExpanded = function(state, commandName, expanded)
	if type(state) ~= "table" then
		return false
	end
	commandName = tostring(commandName or "")
	if commandName == "" then
		return false
	end
	const previousName = state.expandedName
	local nextName = previousName
	if expanded == true then
		nextName = commandName
	elseif expanded == false then
		if tostring(previousName or "") == commandName then
			nextName = nil
		end
	else
		if tostring(previousName or "") == commandName then
			nextName = nil
		else
			nextName = commandName
		end
	end
	if previousName == nextName then
		return false
	end
	state.expandedName = nextName
	state.applied = setmetatable({}, { __mode = "k" })
	state.commandExpansionAnimation = {
		openingName = nextName and tostring(nextName) ~= tostring(previousName or "") and tostring(nextName) or nil;
		closingName = previousName and tostring(previousName) ~= tostring(nextName or "") and tostring(previousName) or nil;
		duration = 0.25;
		started = false;
	}
	NAmanage.Commands_UpdateExpandedMetrics(state)
	if NAUIMANAGER.description then
		NAUIMANAGER.description.Visible = false
		NAUIMANAGER.description.Text = ""
	end
	if type(NAmanage.syncVisibleCommandRows) == "function" then
		NAmanage.syncVisibleCommandRows(state)
	end
	return true
end

function createCommandListLabel(state)
	const tmpl = NAUIMANAGER.commandExample
	const label = InstanceNew("Frame")
	label.Name = "CommandRow"
	label.Visible = false
	label.BackgroundColor3 = tmpl.BackgroundColor3
	label.BackgroundTransparency = tmpl.BackgroundTransparency
	label.BorderSizePixel = tmpl.BorderSizePixel
	label.Size = UDim2.new(tmpl.Size.X.Scale, tmpl.Size.X.Offset, 0, state.templateHeight or 32)
	label.AnchorPoint = Vector2.new(0, 0)
	label.ClipsDescendants = true
	label.ZIndex = tmpl.ZIndex
	for _, child in tmpl:GetChildren() do
		if child:IsA("UICorner") or child:IsA("UIStroke") or child:IsA("UIGradient") then
			child:Clone().Parent = label
		end
	end

	const title = InstanceNew("TextLabel", label)
	title.Name = "CommandTitle"
	title.BackgroundTransparency = 1
	title.BorderSizePixel = 0
	title.Position = UDim2.fromOffset(8, 0)
	title.Size = UDim2.new(1, -16, 0, state.templateHeight or 32)
	title.FontFace = tmpl.FontFace
	title.TextSize = tmpl.TextSize
	title.Text = ""
	title.TextScaled = false
	title.TextWrapped = false
	title.TextXAlignment = Enum.TextXAlignment.Left
	title.TextYAlignment = Enum.TextYAlignment.Center
	title.TextTruncate = Enum.TextTruncate.AtEnd
	title.RichText = tmpl.RichText
	title.AutoLocalize = false
	title.TextColor3 = tmpl.TextColor3
	title.TextStrokeTransparency = 1
	title.ZIndex = label.ZIndex + 1

	const clickTarget = InstanceNew("TextButton", label)
	clickTarget.Name = "CommandClickTarget"
	clickTarget.BackgroundTransparency = 1
	clickTarget.BorderSizePixel = 0
	clickTarget.AutoButtonColor = false
	clickTarget.Active = true
	clickTarget.Text = ""
	clickTarget.Position = UDim2.fromOffset(0, 0)
	clickTarget.Size = UDim2.new(1, 0, 0, state.templateHeight or 32)
	clickTarget.ZIndex = label.ZIndex + 3

	const expansion = InstanceNew("Frame", label)
	expansion.Name = "CommandExpansion"
	expansion.BackgroundTransparency = 1
	expansion.BorderSizePixel = 0
	expansion.ClipsDescendants = true
	expansion.Position = UDim2.new(0, 8, 0, (state.templateHeight or 32) + 4)
	expansion.Size = UDim2.new(1, -16, 0, 36)
	expansion.Visible = false
	expansion.ZIndex = label.ZIndex + 2

	const divider = InstanceNew("Frame", expansion)
	divider.Name = "Divider"
	divider.BorderSizePixel = 0
	divider.BackgroundColor3 = NAUISTROKER or Color3.fromRGB(155, 100, 255)
	divider.BackgroundTransparency = 0.45
	divider.Position = UDim2.new(0, 0, 0, 0)
	divider.Size = UDim2.new(1, 0, 0, 1)
	divider.ZIndex = expansion.ZIndex

	const argsBox = InstanceNew("TextBox", expansion)
	argsBox.Name = "Arguments"
	argsBox.BorderSizePixel = 0
	argsBox.BackgroundColor3 = Color3.fromRGB(24, 25, 33)
	argsBox.BackgroundTransparency = 0.08
	argsBox.ClearTextOnFocus = false
	argsBox.PlaceholderText = "Enter arguments..."
	argsBox.PlaceholderColor3 = Color3.fromRGB(145, 148, 162)
	argsBox.Text = ""
	argsBox.TextColor3 = Color3.fromRGB(235, 237, 244)
	argsBox.TextSize = 14
	argsBox.TextXAlignment = Enum.TextXAlignment.Left
	argsBox.FontFace = Font.new("rbxasset://fonts/families/Roboto.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal)
	argsBox.Position = UDim2.new(0, 0, 0, 7)
	argsBox.Size = UDim2.new(1, -78, 0, 28)
	argsBox.ZIndex = expansion.ZIndex + 1
	InstanceNew("UICorner", argsBox).CornerRadius = UDim.new(0, 5)
	const argsStroke = InstanceNew("UIStroke", argsBox)
	argsStroke.Name = "UIStroker"
	argsStroke.Thickness = 1
	argsStroke.Color = NAUISTROKER or Color3.fromRGB(155, 100, 255)
	argsStroke.Transparency = 0.38
	argsStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	const argsPadding = InstanceNew("UIPadding", argsBox)
	argsPadding.PaddingLeft = UDim.new(0, 8)
	argsPadding.PaddingRight = UDim.new(0, 8)

	const runButton = InstanceNew("TextButton", expansion)
	runButton.Name = "Run"
	runButton.BorderSizePixel = 0
	runButton.BackgroundColor3 = Color3.fromRGB(48, 42, 68)
	runButton.BackgroundTransparency = 0.08
	runButton.AutoButtonColor = false
	runButton.Active = true
	runButton.Text = "Run"
	runButton.TextColor3 = Color3.fromRGB(242, 243, 248)
	runButton.TextSize = 14
	runButton.FontFace = NAmanage.uiMedFont
	runButton.AnchorPoint = Vector2.new(1, 0)
	runButton.Position = UDim2.new(1, 0, 0, 7)
	runButton.Size = UDim2.new(0, 70, 0, 28)
	runButton.ZIndex = expansion.ZIndex + 1
	InstanceNew("UICorner", runButton).CornerRadius = UDim.new(0, 5)
	const runStroke = InstanceNew("UIStroke", runButton)
	runStroke.Name = "UIStroker"
	runStroke.Thickness = 1
	runStroke.Color = NAUISTROKER or Color3.fromRGB(155, 100, 255)
	runStroke.Transparency = 0.28
	runStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

	argsBox:GetPropertyChangedSignal("Text"):Connect(function()
		state.inlineArguments = state.inlineArguments or {}
		const commandName = tostring(NAmanage.GetAttr(label, "CmdName") or "")
		if commandName ~= "" then
			state.inlineArguments[commandName] = argsBox.Text
		end
	end)

	runButton.Activated:Connect(function()
		const commandName = tostring(NAmanage.GetAttr(label, "CmdName") or label.Name or "")
		const requiresArguments = NAmanage.GetAttr(label, "CmdRequiresArguments") == true
		if commandName ~= "" and tostring(state.expandedName or "") == commandName then
			NAmanage.Commands_SetInlineExpanded(state, commandName, false)
		end
		NAmanage.Commands_RunInline(commandName, requiresArguments and argsBox.Text or "")
	end)

	clickTarget.Activated:Connect(function()
		if NAmanage.Commands_SyncHiddenState and not NAmanage.Commands_SyncHiddenState({ responsive = false; syncRows = false }) then
			return
		end
		const commandName = tostring(NAmanage.GetAttr(label, "CmdName") or label.Name or "")
		if commandName == "" then
			return
		end
		NAmanage.Commands_SetInlineExpanded(state, commandName, tostring(state.expandedName or "") ~= commandName)
	end)

	clickTarget.MouseEnter:Connect(function()
		if NAmanage.Commands_SyncHiddenState and not NAmanage.Commands_SyncHiddenState({ responsive = false; syncRows = false }) then
			return
		end
		const desc = NAmanage.GetAttr(label, "CmdDesc")
		if type(desc) == "string" and desc ~= "" then
			NAUIMANAGER.description.Visible = true
			NAUIMANAGER.description.Text = desc
		else
			NAUIMANAGER.description.Visible = false
			NAUIMANAGER.description.Text = ""
		end
	end)
	clickTarget.MouseLeave:Connect(function()
		NAUIMANAGER.description.Visible = false
		NAUIMANAGER.description.Text = ""
	end)
	return label
end

function releaseCommandListLabel(state, label)
	if not label or table.find(state.pooledLabels, label) then
		return
	end
	NAmanage.Commands_StopInlineTween(label)
	const expansion = label:FindFirstChild("CommandExpansion")
	if expansion then
		NAmanage.Commands_StopInlineTween(expansion)
	end
	label.Visible = false
	if state.applied then state.applied[label] = nil end
	const args = expansion and expansion:FindFirstChild("Arguments")
	if args and args:IsFocused() then
		args:ReleaseFocus(false)
	end
	label.Parent = nil
	Insert(state.pooledLabels, label)
end

function acquireCommandListLabel(state)
	local label = table.remove(state.pooledLabels)
	while label do
		if typeof(label) == "Instance" and label.Parent ~= state.virtualCanvas then
			const ok = pcall(function()
				label.Parent = state.virtualCanvas
			end)
			if ok then
				return label
			end
		end
		label = table.remove(state.pooledLabels)
	end

	label = createCommandListLabel(state)
	if NAStuff.CommandListState ~= state or state.virtualCanvas.Parent ~= state.list then
		label:Destroy()
		return nil
	end
	label.Parent = state.virtualCanvas
	return label
end

function pruneCommandListRows(state, wanted)
	const active, keep = {}, {}
	for entry, label in state.activeRows or {} do
		if wanted[entry] and label.Parent == state.virtualCanvas and not keep[label] then
			active[entry] = label
			keep[label] = true
		else
			releaseCommandListLabel(state, label)
		end
	end
	state.activeRows = active
	table.clear(state.visibleLabels)
	for _, label in state.virtualCanvas:GetChildren() do
		if label:IsA("GuiObject") and not keep[label] then
			if state.applied then state.applied[label] = nil end
			label:Destroy()
		end
	end
end

function applyCommandListEntry(state, label, entry, index, animation)
	const meta = entry.meta or {}
	const cmdName = entry.name
	const finalText = meta.displayText or entry.display or cmdName
	const isPatched = meta.patched == true
	const isCmdIntegration = meta.origin == "cmd"
	const isIYIntegration = meta.origin == "iy"
	const isPluginCmd = meta.pluginType ~= nil
	const isExpanded = state.expandedName ~= nil and tostring(state.expandedName) == tostring(cmdName or "")
	const previousCmdName = tostring(NAmanage.GetAttr(label, "CmdName") or "")
	const sameEntryBefore = previousCmdName ~= "" and previousCmdName == tostring(cmdName or "")
	const animationRunning = type(animation) == "table"
	const animationFirstPass = animationRunning and animation.started ~= true
	const animationOngoing = animationRunning and animation.started == true
	const animationDuration = animationRunning and (tonumber(animation.duration) or 0.25) or 0.25
	const openingThis = animationRunning and tostring(animation.openingName or "") == tostring(cmdName or "")
	const closingThis = animationRunning and tostring(animation.closingName or "") == tostring(cmdName or "")

	local ink = state.defaultCmdColor
	if isPatched then
		ink = patchedCommandColor
	elseif isCmdIntegration then
		ink = cmdIntegrationColor
	elseif isIYIntegration then
		ink = iyIntegrationColor
	elseif isPluginCmd then
		ink = pluginCommandColor
	end

	const saved = state.applied and state.applied[label]
	if saved and saved.entry == entry and saved.index == index
		and saved.height == state.templateHeight and saved.expanded == isExpanded
		and saved.before == state.expandedIndex and saved.text == finalText and saved.ink == ink
		and saved.desc == meta.desc and saved.usage == meta.usage
		and saved.hint == meta.argumentHint and saved.needs == meta.requiresArguments
		and not saved.animated and not animationRunning then
		return
	end

	local desc = meta.desc
	if desc ~= nil then
		desc = tostring(desc)
	end
	desc = desc or ""
	if desc ~= "" and isAprilFools() then
		desc = maybeMock(desc)
	end

	if label.SetAttribute then
		NAmanage.SetAttr(label, "CmdName", tostring(cmdName or ""))
		NAmanage.SetAttr(label, "CmdUsage", tostring(meta.usage or meta.displayText or entry.display or cmdName or ""))
		NAmanage.SetAttr(label, "CmdDesc", desc)
		NAmanage.SetAttr(label, "CmdRequiresArguments", meta.requiresArguments == true)
		NAmanage.SetAttr(label, "IsPluginCommand", isPluginCmd)
		NAmanage.SetAttr(label, "IsPatchedCommand", isPatched)
		NAmanage.SetAttr(label, "IsCmdIntegration", isCmdIntegration)
	end

	label.Name = cmdName
	const baseSize = state.templateSize or label.Size
	const targetSize = UDim2.new(baseSize.X.Scale, baseSize.X.Offset, 0, (state.templateHeight or 32) + (isExpanded and 44 or 0))
	local targetPosition
	if state.staticMode then
		label.LayoutOrder = index
		targetPosition = UDim2.new(0, 0, 0, 0)
	else
		const rowStep = state.rowStep or 20
		const extraBefore = state.expandedIndex and index > state.expandedIndex and (state.expandedExtra or 0) or 0
		targetPosition = UDim2.new(0, 0, 0, COMMAND_LIST_TOP_PADDING + ((index - 1) * rowStep) + extraBefore)
	end

	if animationOngoing and sameEntryBefore then
	elseif animationFirstPass and sameEntryBefore then
		NAmanage.Commands_TweenInline(label, {
			Size = targetSize;
			Position = targetPosition;
		}, animationDuration)
	else
		NAmanage.Commands_StopInlineTween(label)
		label.Size = targetSize
		label.Position = targetPosition
	end

	const title = label:FindFirstChild("CommandTitle")
	if title and title:IsA("TextLabel") then
		title.Text = finalText
		title.TextColor3 = ink
		title.Size = UDim2.new(1, -16, 0, state.templateHeight or 32)
	end
	const clickTarget = label:FindFirstChild("CommandClickTarget")
	if clickTarget and clickTarget:IsA("GuiObject") then
		clickTarget.Size = UDim2.new(1, 0, 0, state.templateHeight or 32)
	end
	const expansion = label:FindFirstChild("CommandExpansion")
	if expansion and expansion:IsA("Frame") then
		expansion.Position = UDim2.new(0, 8, 0, (state.templateHeight or 32) + 4)
		const argsBox = expansion:FindFirstChild("Arguments")
		const runButton = expansion:FindFirstChild("Run")
		if argsBox and argsBox:IsA("TextBox") then
			const requiresArguments = meta.requiresArguments == true
			argsBox.Visible = requiresArguments
			if requiresArguments then
				local hint = tostring(meta.argumentHint or "")
				if hint == "" then
					const usage = tostring(meta.usage or "")
					const usageLower = Lower(usage)
					hint = usage:match("^%S+%s+(.+)$") or "Enter arguments..."
					hint = hint:gsub("%s+%([^)]*%)$", "")
					if usageLower:find("npc:", 1, true) then
						hint = hint:gsub("<player|npc:filter>", "player / me / others / nearest / npc:name / npcs")
						hint = hint:gsub("<target|npc:filter>", "player / me / others / nearest / npc:name / npcs")
					elseif usageLower:find("<player>", 1, true) then
						hint = hint:gsub("<[Pp][Ll][Aa][Yy][Ee][Rr]>", "player / me / others / nearest")
					end
				end
				argsBox.PlaceholderText = hint ~= "" and hint or "Enter arguments..."
				state.inlineArguments = state.inlineArguments or {}
				const savedText = tostring(state.inlineArguments[tostring(cmdName or "")] or "")
				if argsBox.Text ~= savedText then
					argsBox.Text = savedText
				end
			end
		end
		if runButton and runButton:IsA("TextButton") then
			if meta.requiresArguments == true then
				runButton.Size = UDim2.new(0, 70, 0, 28)
			else
				runButton.Size = UDim2.new(1, 0, 0, 28)
			end
		end

		if animationOngoing and sameEntryBefore and (openingThis or closingThis) then
		elseif animationFirstPass and sameEntryBefore and openingThis then
			NAmanage.Commands_StopInlineTween(expansion)
			expansion.Visible = true
			expansion.Size = UDim2.new(1, -16, 0, 0)
			NAmanage.Commands_TweenInline(expansion, { Size = UDim2.new(1, -16, 0, 36) }, animationDuration)
		elseif animationFirstPass and sameEntryBefore and closingThis then
			expansion.Visible = true
			NAmanage.Commands_TweenInline(expansion, { Size = UDim2.new(1, -16, 0, 0) }, animationDuration)
			const closingName = tostring(cmdName or "")
			Delay(animationDuration, function()
				if expansion.Parent == label and tostring(NAmanage.GetAttr(label, "CmdName") or "") == closingName and tostring(state.expandedName or "") ~= closingName then
					expansion.Visible = false
				end
			end)
		else
			NAmanage.Commands_StopInlineTween(expansion)
			expansion.Size = UDim2.new(1, -16, 0, 36)
			expansion.Visible = isExpanded
		end
	end
	label.Visible = true
	state.applied = state.applied or setmetatable({}, { __mode = "k" })
	state.applied[label] = {
		entry = entry; index = index; height = state.templateHeight;
		expanded = isExpanded; before = state.expandedIndex; animated = animationRunning;
		text = finalText; ink = ink; desc = meta.desc; usage = meta.usage;
		hint = meta.argumentHint; needs = meta.requiresArguments;
	}
end

function clearStaticCommandLabels(state)
	if type(state.staticLabels) ~= "table" then
		state.staticLabels = {}
		return
	end
	for i = 1, #state.staticLabels do
		const label = state.staticLabels[i]
		if typeof(label) == "Instance" then
			pcall(function()
				label:Destroy()
			end)
		end
	end
	state.staticLabels = {}
end

function rebuildStaticCommandLabels(state)
	if not state then
		return
	end
	const cList = state.list
	if not cList then
		return
	end

	if state.virtualCanvas and state.virtualCanvas.Parent == cList then
		state.virtualCanvas.Parent = nil
	end
	while #state.visibleLabels > 0 do
		releaseCommandListLabel(state, table.remove(state.visibleLabels))
	end
	clearStaticCommandLabels(state)

	const entries = state.entries or {}
	state.staticLabels = state.staticLabels or {}
	for i = 1, #entries do
		const entry = entries[i]
		const label = createCommandListLabel(state)
		label.Parent = cList
		applyCommandListEntry(state, label, entry, i)
		state.staticLabels[i] = label
	end

	updateCanvasSize(cList, NAUIMANAGER and NAUIMANAGER.AUTOSCALER and NAUIMANAGER.AUTOSCALER.Scale or nil)
	if NAmanage.CustomScroll and NAmanage.CustomScroll.refreshByTarget then
		NAmanage.CustomScroll.refreshByTarget(cList)
	end
end

function requestCommandListSync(state)
	if not state or NAStuff.CommandListState ~= state or state.syncQueued == true then
		return
	end
	state.syncQueued = true
	Defer(function()
		if NAStuff.CommandListState ~= state then
			return
		end
		state.syncQueued = false
		if type(NAmanage.syncVisibleCommandRows) == "function" then
			NAmanage.syncVisibleCommandRows(state)
		end
	end)
end

function getCommandTemplateHeight()
	const template = NAUIMANAGER and NAUIMANAGER.commandExample
	if not template then
		return 18
	end

	const minH = math.max(18, math.ceil((tonumber(template.TextSize) or 16) + 8))
	const size = template.Size
	if size and size.Y then
		local height = tonumber(size.Y.Offset) or 0
		if size.Y.Scale ~= 0 and NAUIMANAGER.commandsList then
			const view = NAmanage.GetLogicalWindowSize(NAUIMANAGER.commandsList)
			height += size.Y.Scale * view.Y
		end
		if height > 0 then return math.max(minH, math.ceil(height)) end
	end

	const logicalSize = NAmanage.GetLogicalAbsoluteSize and NAmanage.GetLogicalAbsoluteSize(template) or nil
	const absY = logicalSize and logicalSize.Y or (template.AbsoluteSize and template.AbsoluteSize.Y or 0)
	if absY and absY > 0 then
		return math.floor(absY + 0.5)
	end

	return 18
end

NAmanage.ensureCommandListState=function()
	const cList = NAUIMANAGER and NAUIMANAGER.commandsList
	if not (cList and NAUIMANAGER and NAUIMANAGER.commandExample) then
		return nil
	end
	const staticMode = NAmanage.cmdStatic and NAmanage.cmdStatic() or false
	pcall(function()
		NAmanage.SetAttr(cList, "NAManualCanvasSize", staticMode ~= true)
		cList.AutomaticCanvasSize = Enum.AutomaticSize.None
	end)
	local state = NAStuff.CommandListState
	const listLayout = cList:FindFirstChildOfClass("UIListLayout")
		or (type(state) == "table" and state.list == cList and state.listLayout)
	if listLayout then
		const parent = staticMode and cList or nil
		if listLayout.Parent ~= parent then
			listLayout.Parent = parent
		end
	end

	if type(state) == "table" and state.list == cList and state.staticMode == staticMode then
		if staticMode then
			return state
		end
		if state.virtualCanvas and state.virtualCanvas.Parent == cList then
			return state
		end
	end

	if type(state) == "table" then
		clearStaticCommandLabels(state)
		while #state.visibleLabels > 0 do
			releaseCommandListLabel(state, table.remove(state.visibleLabels))
		end
		for _, label in state.pooledLabels or {} do
			pcall(function() label:Destroy() end)
		end
		table.clear(state.pooledLabels)
		if state.virtualCanvas then
			pcall(function()
				state.virtualCanvas:Destroy()
			end)
		end
		NAStuff.CommandListState = nil
		state = nil
	end

	for _, child in cList:GetChildren() do
		if child == NAUIMANAGER.commandExample then
			child.Parent = nil
		elseif child:IsA("TextLabel") or child:IsA("TextButton") or NAmanage.GetAttr(child, "CmdName") ~= nil then
			child:Destroy()
		end
	end
	local virtualCanvas = nil
	if not staticMode then
		virtualCanvas = cList:FindFirstChild("VirtualCanvas")
		if not virtualCanvas then
			virtualCanvas = Instance.new("Frame")
			virtualCanvas.Name = "VirtualCanvas"
			virtualCanvas.BackgroundTransparency = 1
			virtualCanvas.BorderSizePixel = 0
			virtualCanvas.Size = UDim2.new(1, 0, 0, 0)
			virtualCanvas.Position = UDim2.new(0, 0, 0, 0)
			virtualCanvas.AnchorPoint = Vector2.new(0, 0)
			virtualCanvas.Parent = cList
		else
			virtualCanvas.AnchorPoint = Vector2.new(0, 0)
			virtualCanvas.Position = UDim2.new(0, 0, 0, 0)
		end
		virtualCanvas.ClipsDescendants = true
		for _, label in virtualCanvas:GetChildren() do
			if label:IsA("GuiObject") then
				label:Destroy()
			end
		end
	else
		virtualCanvas = cList:FindFirstChild("VirtualCanvas")
		if virtualCanvas then
			virtualCanvas.Parent = nil
		end
	end

	if type(state) == "table" and state.list == cList and state.staticMode == staticMode then
		return state
	end

	const pooled = {}
	for _, label in NAStuff.CommandLabelPool or {} do
		if typeof(label) == "Instance" then label:Destroy() end
	end
	NAStuff.CommandLabelPool = nil

	const templateHeight = getCommandTemplateHeight()
	const rowGap = math.max(2, math.floor(templateHeight * 0.15 + 0.5))
	const rowStep = templateHeight + rowGap

	state = {
		list = cList;
		virtualCanvas = virtualCanvas;
		entries = {};
		filteredEntries = {};
		visibleLabels = {};
		activeRows = {};
		applied = setmetatable({}, { __mode = "k" });
		pooledLabels = pooled;
		defaultCmdColor = NAUIMANAGER.commandExample.TextColor3;
		templateSize = NAUIMANAGER.commandExample.Size;
		templateHeight = templateHeight;
		rowGap = rowGap;
		rowStep = rowStep;
		syncQueued = false;
		staticMode = staticMode;
		staticLabels = {};
		listLayout = listLayout;
		expandedName = nil;
		expandedIndex = nil;
		expandedExtra = 0;
		inlineArguments = {};
		commandExpansionAnimation = nil;
	}
	NAStuff.CommandListState = state

	if NAUIMANAGER.description then
		NAUIMANAGER.description.Visible = false
		NAUIMANAGER.description.Text = ""
	end

	NAlib.disconnect("NA_CommandListCanvasPos")
	NAlib.disconnect("NA_CommandListAbsSize")
	if not staticMode then
		NAlib.connect("NA_CommandListCanvasPos", cList:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
			requestCommandListSync(state)
		end))
		NAlib.connect("NA_CommandListAbsSize", cList:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			requestCommandListSync(state)
		end))
	end

	return state
end

function syncCommandListRows(state)
	if not state or NAStuff.CommandListState ~= state then
		return
	end

	const cList = state.list
	const virtualCanvas = state.virtualCanvas
	const filteredEntries = state.filteredEntries or {}
	const count = #filteredEntries
	NAmanage.Commands_UpdateExpandedMetrics(state)
	local expansionAnimation = state.commandExpansionAnimation
	if type(expansionAnimation) == "table" and expansionAnimation.started == true then
		const expiresAt = tonumber(expansionAnimation.expiresAt) or 0
		if expiresAt > 0 and os.clock() >= expiresAt then
			state.commandExpansionAnimation = nil
			expansionAnimation = nil
		end
	end

	if state.staticMode then
		if type(state.staticLabels) == "table" then
			for i = 1, #state.staticLabels do
				const label = state.staticLabels[i]
				const entry = filteredEntries[i] or state.entries[i]
				if label and entry then
					applyCommandListEntry(state, label, entry, i, expansionAnimation)
				end
			end
		end
		updateCanvasSize(cList, NAUIMANAGER and NAUIMANAGER.AUTOSCALER and NAUIMANAGER.AUTOSCALER.Scale or nil)
		if NAmanage.CustomScroll and NAmanage.CustomScroll.refreshByTarget then
			NAmanage.CustomScroll.refreshByTarget(cList)
		end
		if type(expansionAnimation) == "table" and expansionAnimation.started ~= true then
			expansionAnimation.started = true
			const duration = tonumber(expansionAnimation.duration) or 0.25
			expansionAnimation.expiresAt = os.clock() + duration + 0.04
			Delay(duration + 0.04, function()
				if state.commandExpansionAnimation == expansionAnimation then
					state.commandExpansionAnimation = nil
					NAmanage.syncVisibleCommandRows(state)
				end
			end)
		end
		return
	end

	if NAUIMANAGER.description then
		NAUIMANAGER.description.Visible = false
		NAUIMANAGER.description.Text = ""
	end

	if count <= 0 then
		state.commandExpansionAnimation = nil
		pruneCommandListRows(state, {})
		if virtualCanvas then
			virtualCanvas.Size = UDim2.new(1, 0, 0, 0)
		end
		cList.CanvasSize = UDim2.new(0, 0, 0, 0)
		if NAmanage.CustomScroll and NAmanage.CustomScroll.refreshByTarget then
			NAmanage.CustomScroll.refreshByTarget(cList)
		end
		return
	end

	const height = getCommandTemplateHeight()
	if state.templateHeight ~= height then
		state.templateHeight = height
		state.rowGap = math.max(2, math.floor(height * 0.15 + 0.5))
		state.rowStep = height + state.rowGap
	end
	const rowStep = state.rowStep or 20
	const totalHeight = COMMAND_LIST_TOP_PADDING + (count * rowStep) + (state.expandedExtra or 0)
	const canvas = UDim2.new(0, 0, 0, totalHeight)
	if virtualCanvas.Size.Y.Offset ~= totalHeight then
		virtualCanvas.Size = UDim2.new(1, 0, 0, totalHeight)
	end
	if cList.CanvasSize ~= canvas then
		cList.CanvasSize = canvas
	end

	local logicalListSize = nil
	if NAmanage.GetLogicalWindowSize then
		logicalListSize = NAmanage.GetLogicalWindowSize(cList)
	elseif NAmanage.GetLogicalAbsoluteSize then
		logicalListSize = NAmanage.GetLogicalAbsoluteSize(cList)
	end
	local viewHeight = logicalListSize and logicalListSize.Y or cList.AbsoluteSize.Y
	const scrollPos = NAmanage.GetLogicalCanvasPosition and NAmanage.GetLogicalCanvasPosition(cList) or cList.CanvasPosition
	local scrollY = scrollPos.Y
	if NAmanage.virtView then
		viewHeight, scrollY = NAmanage.virtView(cList, viewHeight, totalHeight, rowStep * 3)
	end
	if NAmanage.CustomScroll and NAmanage.CustomScroll.refreshByTarget then
		NAmanage.CustomScroll.refreshByTarget(cList)
	end
	const viewRows = math.max(COMMAND_MIN_VISIBLE_ROWS, math.ceil(math.max(viewHeight, rowStep) / rowStep) + 2)
	const overscanPx = math.max(COMMAND_OVERSCAN_ROWS * rowStep, viewHeight, rowStep * 10)
	const firstY = math.max(0, scrollY - COMMAND_LIST_TOP_PADDING - overscanPx)
	const lastY = math.max(firstY + rowStep, scrollY + viewHeight - COMMAND_LIST_TOP_PADDING + overscanPx)
	const function rowAt(y)
		const exp = state.expandedIndex
		if exp then
			const top = (exp - 1) * rowStep
			if y >= top + rowStep + state.expandedExtra then
				y -= state.expandedExtra
			elseif y >= top then
				return exp
			end
		end
		return math.clamp(math.floor(y / rowStep) + 1, 1, count)
	end
	local firstIndex = rowAt(firstY)
	local lastIndex = math.max(firstIndex, rowAt(lastY))
	const minNeeded = math.min(count, viewRows)
	if (lastIndex - firstIndex + 1) < minNeeded then
		lastIndex = math.min(count, firstIndex + minNeeded - 1)
		firstIndex = math.max(1, math.min(firstIndex, lastIndex - minNeeded + 1))
	end

	const wanted = {}
	for i = firstIndex, lastIndex do
		wanted[filteredEntries[i]] = true
	end
	pruneCommandListRows(state, wanted)
	for i = firstIndex, lastIndex do
		const entry = filteredEntries[i]
		local label = state.activeRows[entry]
		if not label then
			label = acquireCommandListLabel(state)
			if not label then return end
			if state.filteredEntries ~= filteredEntries then
				releaseCommandListLabel(state, label)
				state.syncAgain = true
				return
			end
			state.activeRows[entry] = label
		end
		state.visibleLabels[#state.visibleLabels + 1] = label
		applyCommandListEntry(state, label, entry, i, expansionAnimation)
	end

	if type(expansionAnimation) == "table" and expansionAnimation.started ~= true then
		expansionAnimation.started = true
		const duration = tonumber(expansionAnimation.duration) or 0.25
		expansionAnimation.expiresAt = os.clock() + duration + 0.04
		Delay(duration + 0.04, function()
			if state.commandExpansionAnimation == expansionAnimation then
				state.commandExpansionAnimation = nil
				NAmanage.syncVisibleCommandRows(state)
			end
		end)
	end
end

NAmanage.syncVisibleCommandRows=function(state)
	state = state or NAmanage.ensureCommandListState()
	if not state or NAStuff.CommandListState ~= state then return end
	if state.syncing == true then
		state.syncAgain = true
		return
	end
	state.syncing = true
	const ok, err = pcall(syncCommandListRows, state)
	state.syncing = false
	if state.syncAgain == true then
		state.syncAgain = false
		requestCommandListSync(state)
	end
	if not ok then error(err, 0) end
end

NAgui.commands = function(opts)
	opts = type(opts) == "table" and opts or {}
	const cFrame, cList = NAUIMANAGER.commandsFrame, NAUIMANAGER.commandsList
	if not (cFrame and cList and NAUIMANAGER.commandExample) then
		return
	end

	if opts.toggle == true and NAgui.isWindowOpen(cFrame) then
		if NAmanage.Commands_SetVisible then
			NAmanage.Commands_SetVisible(false, { refresh = false })
		else
			cFrame.Visible = false
		end
		return
	end

	if not cFrame.Visible then
		cFrame.Visible = true
		cList.CanvasSize = UDim2.new(0, 0, 0, 0)
	end

	local expanded = true
	if NAmanage.Commands_SyncHiddenState then
		expanded = NAmanage.Commands_SyncHiddenState({
			center = opts.center ~= false;
			responsive = true;
			syncRows = false;
		})
	else
		if NAmanage.cmdResp then
			NAmanage.cmdResp(false)
		end
		NAmanage.centerFrame(cFrame)
	end

	const state = NAmanage.ensureCommandListState()
	if not state then
		return
	end

	local entries = NAStuff.AutofillEntries
	if type(entries) ~= "table" then
		entries = {}
	end
	if type(NAmanage.isCommandDataStale) == "function" and NAmanage.isCommandDataStale() then
		if type(NAmanage.queueCommandDataBuild) == "function" then
			pcall(NAmanage.queueCommandDataBuild, { force = (#entries <= 0) })
		elseif type(NAgui.loadCMDS) == "function" then
			pcall(NAgui.loadCMDS, { force = (#entries <= 0) })
		end
		if type(NAStuff.AutofillEntries) == "table" then
			entries = NAStuff.AutofillEntries
		end
	end
	state.entries = entries
	state.filteredEntries = entries
	NAStuff.CommandFilterEntries = nil

	if not expanded then
		return
	end

	if NAgui.filterCommandList then
		NAgui.filterCommandList(NAUIMANAGER.commandsFilter and NAUIMANAGER.commandsFilter.Text or "")
	else
		NAmanage.syncVisibleCommandRows(state)
	end
end
NAgui.chatlogs = function()
	if NAUIMANAGER.chatLogsFrame then
		if not NAUIMANAGER.chatLogsFrame.Visible then
			NAUIMANAGER.chatLogsFrame.Visible = true
		end
		--NAUIMANAGER.chatLogsFrame.Position = UDim2.new(0.43, 0, 0.4, 0)
		NAmanage.centerFrame(NAUIMANAGER.chatLogsFrame)
	end
end
NAgui.doModal = function(v)
