end

NAmanage.MusicWindowLayout = function(frame)
	const c = frame and frame:FindFirstChild("Container")
	if not c then return end
	const ctrls = c:FindFirstChild("Controls")
	const grid = ctrls and ctrls:FindFirstChildWhichIsA("UIGridLayout")
	const mix = c:FindFirstChild("Mix")
	const range = c:FindFirstChild("LoopRange")
	const files = c:FindFirstChild("FileTools")
	const library = c:FindFirstChild("LibraryTools")
	const function place(obj,x,y,w,h)
		if not obj then return end
		obj.Position = UDim2.fromOffset(x,y)
		obj.Size = UDim2.fromOffset(math.max(1,w),h)
	end
	const function lay()
		if not c.Parent or c.AbsoluteSize.X <= 0 or c.AbsoluteSize.Y < 80 then return end
		const scale = NAmanage.GetUIScaleFactor and NAmanage.GetUIScaleFactor(c) or 1
		const w,h = c.AbsoluteSize.X/math.max(scale,0.01),c.AbsoluteSize.Y/math.max(scale,0.01)
		const small = w < 460
		const compact = h < 460
		const rowH = compact and 26 or 30
		const gap = compact and 6 or 8
		const right = small and 78 or 96
		place(c:FindFirstChild("TrackInput"),8,8,w-right-24,30)
		place(c:FindFirstChild("Load"),w-right-8,8,right,30)
		place(c:FindFirstChild("NowPlaying"),10,44,w-right-26,22)
		place(c:FindFirstChild("Status"),w-right-8,44,right,22)
		place(c:FindFirstChild("Progress"),10,compact and 72 or 76,w-right-26,compact and 10 or 12)
		place(c:FindFirstChild("Time"),w-right-8,compact and 68 or 72,right,18)
		local count = 0
		if ctrls then for _,item in ctrls:GetChildren() do if item:IsA("TextButton") then count += 1 end end end
		local cols = math.clamp(math.floor((w-10)/70),2,9)
		if small then cols = math.min(cols,4) end
		const rows = math.ceil(math.max(1,count)/cols)
		const height = rows*rowH+(rows-1)*6
		if grid then
			grid.FillDirectionMaxCells = cols
			grid.CellPadding = UDim2.fromOffset(6,6)
			grid.CellSize = UDim2.fromOffset(math.floor((w-20-(cols-1)*6)/cols),rowH)
		end
		local y = compact and 92 or 102
		place(ctrls,10,y,w-20,height)
		y += height+gap
		place(mix,10,y,w-20,rowH)
		if mix then
			place(mix:FindFirstChild("VolumeLabel"),0,0,48,rowH)
			place(mix:FindFirstChild("VolumeBox"),50,0,54,rowH)
			place(mix:FindFirstChild("SpeedLabel"),116,0,42,rowH)
			place(mix:FindFirstChild("SpeedBox"),160,0,54,rowH)
			const folder = mix:FindFirstChild("FolderHint")
			if folder then folder.Visible = w >= 550; place(folder,226,0,w-246,rowH) end
		end
		y += rowH+gap
		const two = small and not compact
		const rangeH = two and rowH*2+4 or rowH
		place(range,10,y,w-20,rangeH)
		if range then
			place(range:FindFirstChild("StartLabel"),0,0,64,rowH)
			place(range:FindFirstChild("StartBox"),66,0,66,rowH)
			place(range:FindFirstChild("EndLabel"),140,0,26,rowH)
			place(range:FindFirstChild("EndBox"),168,0,66,rowH)
			const x = two and 0 or 244
			const by = two and rowH+4 or 0
			for _,name in {"SetStart","SetEnd","Clear"} do
				const b = range:FindFirstChild(name)
				if b then b.Visible = not (small and compact) end
			end
			place(range:FindFirstChild("SetStart"),x,by,72,rowH)
			place(range:FindFirstChild("SetEnd"),x+78,by,72,rowH)
			place(range:FindFirstChild("Clear"),x+156,by,60,rowH)
		end
		y += rangeH+gap
		place(files,10,y,w-20,rowH)
		if files then
			place(files:FindFirstChild("NameBox"),0,0,w-104,rowH)
			place(files:FindFirstChild("Rename"),w-96,0,76,rowH)
		end
		y += rowH+gap
		place(library,10,y,w-20,rowH)
		if library then
			place(library:FindFirstChild("SearchBox"),0,0,w-160,rowH)
			place(library:FindFirstChild("SeekBox"),w-152,0,72,rowH)
			place(library:FindFirstChild("Seek"),w-72,0,52,rowH)
		end
		y += rowH+gap
		place(c:FindFirstChild("LocalList"),8,y,w-16,math.max(24,h-y-8))
	end
	NAlib.connect("NA_MusicPlayer",c:GetPropertyChangedSignal("AbsoluteSize"):Connect(lay))
	lay()
	Defer(lay)
end

NAmanage.MusicWindowInit = NAmanage.MusicWindowInit or function()
	const frame = NAUIMANAGER and NAUIMANAGER.MusicFrame
	if not frame then return false end
	local st = NAStuff.MusicPlayer
	if type(st) ~= "table" then
		st = {}
		NAStuff.MusicPlayer = st
	end
	if st.ready == true and st.frame == frame and st.rev == 2 then return true end
	NAlib.disconnect("NA_MusicPlayer")
	NAlib.disconnect("NA_MusicPlayerSound")
	NAlib.disconnect("NA_MusicRows")
	st.ready = true
	st.rev = 2
	st.closed = false
	st.frame = frame
	st.seq = (tonumber(st.seq) or 0) + 1
	st.assets = st.assets or {}
	st.clips = st.clips or {}
	st.hist = st.hist or {}
	st.filter = st.filter or ""
	st.root = st.root or "Nameless-Admin/Music"
	st.cfgPath = st.root.."/_config.json"
	st.exts = {mp3=true,ogg=true,flac=true,wav=true}
	st.mode = st.mode or "off"
	st.loop = st.loop == true
	st.vol = math.clamp(tonumber(st.vol) or 1, 0, 10)
	st.spd = math.clamp(tonumber(st.spd) or 1, 0.25, 4)
	const c = frame:FindFirstChild("Container")
	if not c then return false end
	const inp = c:FindFirstChild("TrackInput")
	const load = c:FindFirstChild("Load")
	const now = c:FindFirstChild("NowPlaying")
	const stat = c:FindFirstChild("Status")
	const time = c:FindFirstChild("Time")
	const prog = c:FindFirstChild("Progress")
	const fill = prog and prog:FindFirstChild("Fill")
	const list = c:FindFirstChild("LocalList")
	const mix = c:FindFirstChild("Mix")
	const volBox = mix and mix:FindFirstChild("VolumeBox")
	const spdBox = mix and mix:FindFirstChild("SpeedBox")
	const range = c:FindFirstChild("LoopRange")
	const startBox = range and range:FindFirstChild("StartBox")
	const endBox = range and range:FindFirstChild("EndBox")
	const files = c:FindFirstChild("FileTools")
	const nameBox = files and files:FindFirstChild("NameBox")
	const library = c:FindFirstChild("LibraryTools")
	const search = library and library:FindFirstChild("SearchBox")
	const seekBox = library and library:FindFirstChild("SeekBox")
	const region = prog and prog:FindFirstChild("LoopRegion")
	const markA = prog and prog:FindFirstChild("StartMark")
	const markB = prog and prog:FindFirstChild("EndMark")
	const ctrls = c:FindFirstChild("Controls")
	const btns = {}
	if ctrls then
		for _, ch in ctrls:GetChildren() do
			if ch:IsA("TextButton") then btns[ch.Name] = ch end
		end
	end
	const function trim(v)
		return tostring(v or ""):gsub("^%s*(.-)%s*$", "%1")
	end
	const function bn(p)
		return tostring(p or ""):match("[^/\\]+$") or tostring(p or "")
	end
	const function noext(p)
		return tostring(p or ""):gsub("%.[^%.]+$", "")
	end
	const function ext(p)
		const clean = tostring(p or ""):match("([^?#]+)") or tostring(p or "")
		local e = clean:match("%.([%w]+)$")
		e = e and e:lower() or nil
		return e and st.exts[e] and e or nil
	end
	const function key(v)
		return trim(v):gsub("\\", "/"):lower()
	end
	const function parse(v)
		if type(v) == "number" then
			return v == v and v >= 0 and v < math.huge and v or nil
		end
		v = trim(v)
		if v == "" or v:find("[^%d%.:]") or v:find("::", 1, true) or v:match("^:") or v:match(":$") then return nil end
		for part in v:gmatch("([^:]+):") do if part:find("%.") then return nil end end
		local n, count = 0, 0
		for part in v:gmatch("[^:]+") do
			const val = tonumber(part)
			if not val or val < 0 or val >= math.huge or (count > 0 and val >= 60) then return nil end
			n = n * 60 + val
			count += 1
		end
		return count > 0 and count <= 3 and n < math.huge and n or nil
	end
	const function clipKey()
		return key(st.file and st.file.name or st.raw or st.last or "")
	end
	const function bounds(len)
		const clip = st.clips[clipKey()] or {}
		len = math.max(0, tonumber(len) or 0)
		if len <= 0 then return 0, 0, false end
		const a = math.clamp(tonumber(clip.a) or 0, 0, math.max(0, len - 0.05))
		const b = math.clamp(tonumber(clip.b) or len, math.min(len, a + 0.05), len)
		return a, b, a > 0 or b < len
	end
	const function assetFor(item)
		if not item then return nil end
		const k = key(item.path)
		local asset = st.assets[k]
		if not asset and type(getcustomasset) == "function" then
			const ok, value = pcall(getcustomasset, item.path)
			if ok and type(value) == "string" and value ~= "" then
				asset = value
				st.assets[k] = asset
			end
		end
		item.asset = asset
		return asset
	end
	const function hsh(s)
		local h = 0
		for i = 1, #s do h = (h * 31 + (string.byte(s, i) or 0)) % 4294967296 end
		return Format("%08x", h)
	end
	const function safeFolder()
		if type(isfolder) ~= "function" or type(makefolder) ~= "function" then return false end
		local ok, ex = pcall(isfolder, st.root)
		if ok and ex then return true end
		return pcall(makefolder, st.root) == true
	end
	const function saveCfg()
		if not (Services.HttpService and type(writefile) == "function" and safeFolder()) then return false end
		local ok, data = pcall(Services.HttpService.JSONEncode, Services.HttpService, {
			last = st.last or "",
			vol = st.vol,
			spd = st.spd,
			loop = st.loop == true,
			mode = st.mode or "off",
			clips = st.clips
		})
		if ok and type(data) == "string" then return pcall(writefile, st.cfgPath, data) == true end
		return false
	end
	const function loadCfg()
		if not (Services.HttpService and type(isfile) == "function" and type(readfile) == "function") then return end
		local okFile, has = pcall(isfile, st.cfgPath)
		if not (okFile and has) then return end
		local okRead, raw = pcall(readfile, st.cfgPath)
		if not (okRead and type(raw) == "string" and raw ~= "") then return end
		local okDec, cfg = pcall(Services.HttpService.JSONDecode, Services.HttpService, raw)
		if not (okDec and type(cfg) == "table") then return end
		st.last = tostring(cfg.last or st.last or "")
		st.vol = math.clamp(tonumber(cfg.vol) or st.vol or 1, 0, 10)
		st.spd = math.clamp(tonumber(cfg.spd) or st.spd or 1, 0.25, 4)
		st.loop = cfg.loop == true
		st.mode = (cfg.mode == "order" or cfg.mode == "random") and cfg.mode or "off"
		if type(cfg.clips) == "table" then
			st.clips = {}
			for name, clip in cfg.clips do
				if type(name) == "string" and type(clip) == "table" then
					const a = parse(clip.a) or 0
					const b = parse(clip.b)
					if not b or b > a then st.clips[key(name)] = {a=a,b=b} end
				end
			end
		end
	end
	const function fmt(sec)
		sec = math.max(0, math.floor(tonumber(sec) or 0))
		return Format("%02d:%02d", math.floor(sec / 60), sec % 60)
	end
	const function stamp(sec)
		sec = math.max(0, math.floor((tonumber(sec) or 0)*100+0.5)/100)
		if sec % 1 < 0.005 then return fmt(sec) end
		return Format("%02d:%05.2f",math.floor(sec/60),sec%60)
	end
	const function setStat(txt, col)
		if stat then
			stat.Text = tostring(txt or "Stopped")
			if col then stat.BackgroundColor3 = col end
		end
	end
	const function setNow(txt)
		if now then now.Text = tostring(txt or "No track loaded") end
	end
	const function setProg(pos, len)
		pos = tonumber(pos) or 0
		len = tonumber(len) or 0
		const a = len > 0 and math.clamp(pos / len, 0, 1) or 0
		if fill then fill.Size = UDim2.new(a, 0, 1, 0) end
		if time then time.Text = fmt(pos).." / "..fmt(len) end
		const a, b, custom = bounds(len)
		const show = st.loop and custom and len > 0
		if region then
			region.Visible = show
			if show then region.Position = UDim2.fromScale(a / len, 0); region.Size = UDim2.fromScale((b - a) / len, 1) end
		end
		if markA then markA.Visible = show; if show then markA.Position = UDim2.fromScale(a / len, 0) end end
		if markB then markB.Visible = show; if show then markB.Position = UDim2.fromScale(b / len, 0) end end
	end
	const function syncMix()
		if volBox then volBox.Text = tostring(math.floor((st.vol or 1) * 100 + 0.5) / 100) end
		if spdBox then spdBox.Text = tostring(math.floor((st.spd or 1) * 100 + 0.5) / 100) end
		if btns.Loop then btns.Loop.Text = st.loop and "Loop On" or "Loop" end
		if btns.Mode then btns.Mode.Text = st.mode == "order" and "Order" or st.mode == "random" and "Random" or "Mode" end
		if st.snd then
			pcall(function()
				st.snd.Volume = st.vol
				st.snd.PlaybackSpeed = st.spd
				const _, _, custom = bounds(st.snd.TimeLength)
				st.snd.Looped = st.loop == true and not custom
			end)
		end
	end
	const function syncRange()
		const clip = st.clips[clipKey()] or {}
		if startBox then startBox.Text = stamp(clip.a or 0) end
		if endBox then endBox.Text = clip.b and stamp(clip.b) or "" end
	end
	const function fail(text)
		DoNotif(text, 3, "Music")
		return false, text
	end
	const function seekTo(value)
		const pos = parse(value)
		if not pos then return fail("Use seconds, mm:ss, or hh:mm:ss.") end
		const snd = st.snd
		if not snd or snd.TimeLength <= 0 then return fail("Load an audio track first.") end
		local dest = math.clamp(pos, 0, snd.TimeLength)
		if st.loop then
			const a, b, custom = bounds(snd.TimeLength)
			if custom then dest = math.clamp(dest, a, math.max(a, b - 0.01)) end
		end
		const ok = pcall(function() snd.TimePosition = dest end)
		if not ok then return fail("Could not seek in this track.") end
		st.repairPos = dest
		setProg(dest, snd.TimeLength)
		return true, dest
	end
	const function setRange(a, b)
		const name = clipKey()
		if name == "" then return fail("Load a track before setting loop points.") end
		a = trim(a) == "" and 0 or parse(a)
		if b == nil or trim(b) == "" or key(b) == "end" then
			b = nil
		else
			b = parse(b)
			if b == nil then syncRange(); return fail("Loop end must be a timestamp, or blank for the track end.") end
		end
		if a == nil then syncRange(); return fail("Loop start must be seconds or a timestamp.") end
		if b and b <= a then syncRange(); return fail("Loop end must be after loop start.") end
		const len = st.snd and tonumber(st.snd.TimeLength) or 0
		if len > 0 and (a >= len or (b and b > len)) then syncRange(); return fail("Loop points must be within this track.") end
		st.clips[name] = (a > 0 or b ~= nil) and {a=a,b=b} or nil
		syncRange()
		syncMix()
		if st.loop and st.snd and len > 0 then
			const pos = st.snd.TimePosition
			const start, finish = bounds(len)
			if pos < start or pos >= finish then st.snd.TimePosition = start end
		end
		if st.snd then setProg(st.snd.TimePosition, len) end
		saveCfg()
		return true
	end
	const function scan()
		const out = {}
		const seen = {}
		if type(listfiles) == "function" and safeFolder() then
			const ok, paths = pcall(listfiles, st.root)
			if ok and type(paths) == "table" then
				for _, path in paths do
					if type(path) == "string" and ext(path) and not seen[key(path)] then
						local has = true
						if type(isfile) == "function" then
							const good, exists = pcall(isfile, path)
							has = good and exists
						end
						if has then
							seen[key(path)] = true
							out[#out + 1] = {path=path,name=bn(path),asset=st.assets[key(path)]}
						end
					end
				end
			end
		end
		for path in st.assets do if not seen[path] then st.assets[path] = nil end end
		table.sort(out, function(a,b) return a.name:lower() < b.name:lower() end)
		st.tracks = out
		return out
	end
	const function rowButton(txt)
		const b = InstanceNew("TextButton")
		b.Name = "Track"
		b.BorderSizePixel = 0
		b.BackgroundColor3 = Color3.fromRGB(50, 50, 58)
		b.BackgroundTransparency = 0.15
		b.TextColor3 = Color3.fromRGB(235, 235, 245)
		b.FontFace = Font.new("rbxasset://fonts/families/Roboto.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal)
		b.TextSize = 13
		b.TextXAlignment = Enum.TextXAlignment.Left
		b.TextTruncate = Enum.TextTruncate.AtEnd
		b.Text = "  "..tostring(txt or "")
		b.Size = UDim2.new(1, -4, 0, 28)
		const cr = InstanceNew("UICorner", b)
		cr.CornerRadius = UDim.new(0, 6)
		const stt = InstanceNew("UIStroke", b)
		stt.Thickness = 1
		stt.Color = Color3.fromRGB(155, 100, 255)
		stt.Transparency = 0.45
		stt.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		stt.Name = "UIStroker"
		return b
	end
	local loadTrack
	const function rebuildList(rescan)
		NAlib.disconnect("NA_MusicRows")
		if not list then return end
		for _, ch in list:GetChildren() do
			if not ch:IsA("UIListLayout") and not ch:IsA("UIPadding") then ch:Destroy() end
		end
		const items = {}
		const query = trim(st.filter):lower()
		for _, item in rescan == false and (st.tracks or {}) or scan() do
			if query == "" or item.name:lower():find(query, 1, true) then items[#items + 1] = item end
		end
		if #items == 0 then
			const empty = InstanceNew("TextLabel")
			empty.Name = "Empty"
			empty.BackgroundTransparency = 1
			empty.TextXAlignment = Enum.TextXAlignment.Left
			empty.TextSize = 13
			empty.TextColor3 = Color3.fromRGB(170, 170, 185)
			empty.FontFace = Font.new("rbxasset://fonts/families/Roboto.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal)
			empty.TextWrapped = true
			empty.TextYAlignment = Enum.TextYAlignment.Top
			empty.Text = query ~= "" and "No matching audio files." or "Add mp3, ogg, flac, or wav files here, or paste a direct audio link above."
			empty.Size = UDim2.new(1, -4, 0, 52)
			empty.Parent = list
			return
		end
		for _, item in items do
			const b = rowButton(item.name)
			if st.file and key(st.file.path) == key(item.path) then b.BackgroundColor3 = Color3.fromRGB(72, 49, 108) end
			b.Parent = list
			NAlib.connect("NA_MusicRows", MouseButtonFix(b, function()
				if inp then inp.Text = item.name end
				if loadTrack then loadTrack(item.name, true) end
			end))
		end
	end
	const function findLocal(q)
		q = trim(q):lower()
		if q == "" then return nil end
		local best
		for _, item in st.tracks or scan() do
			const nm = tostring(item.name or ""):lower()
			const base = noext(nm)
			if q == nm or q == base then return item end
			if not best and nm:find(q, 1, true) then best = item end
		end
		return best
	end
	const function normUrl(u)
		u = trim(u)
		if u:match("^www%.") then u = "https://"..u end
		u = u:gsub(" ", "%%20")
		u = u:gsub("^https://github%.com/([^/]+)/([^/]+)/blob/([^/]+)/(.+)$", "https://raw.githubusercontent.com/%1/%2/%3/%4")
		return u
	end
	const function fileNameFor(u, e)
		local n = bn((u:match("([^?#]+)") or u)):gsub("%.[^%.]+$", "")
		n = n:gsub("[^%w%._%-]", "_")
		if n == "" then n = "track" end
		return n.."_"..hsh(u).."."..e
	end
	const function reqBody(u)
		local body
		const rq = opt and opt.NAREQUEST
		if type(rq) == "function" then
			local ok, res = pcall(rq, {Url = u, Method = "GET", Headers = { ["Accept"] = "*/*" }})
			if ok and type(res) == "table" then
				const code = tonumber(res.StatusCode or res.status_code or res.Status)
				if res.Success ~= false and (not code or (code >= 200 and code < 300)) then body = res.Body or res.body end
			end
		end
		if type(body) ~= "string" or body == "" then
			local ok, res = NAmanage.HttpGet(u, { timeout = 10, Headers = { ["Accept"] = "*/*" } })
			if ok and type(res) == "string" and res ~= "" then body = res end
		end
		return body
	end
	const function dl(u)
		if type(writefile) ~= "function" or type(getcustomasset) ~= "function" or not safeFolder() then
			return nil, "File support and getcustomasset are required for URL audio."
		end
		u = normUrl(u)
		const e = ext(u)
		if not e then return nil, "URL must end in mp3, ogg, flac, or wav." end
		const dst = st.root.."/"..fileNameFor(u, e)
		if type(isfile) == "function" then
			local okFile, has = pcall(isfile, dst)
			if okFile and has then
				local okAsset, asset = pcall(getcustomasset, dst)
				if okAsset and asset then return {path = dst, name = bn(dst), asset = asset} end
			end
		end
		const body = reqBody(u)
		if type(body) ~= "string" or body == "" then return nil, "Failed to download audio." end
		if body:match("^%s*<") then return nil, "That link returned a web page instead of audio." end
		const okWrite = pcall(writefile, dst, body)
		if not okWrite then return nil, "Failed to save audio." end
		local okAsset, asset = pcall(getcustomasset, dst)
		if not (okAsset and type(asset) == "string" and asset ~= "") then return nil, "Failed to load local audio asset." end
		return {path = dst, name = bn(dst), asset = asset}
	end
	const function idOf(q)
		q = trim(q)
		const n = q:match("^rbxassetid://(%d+)$") or q:match("[?&]id=(%d+)") or q:match("^(%d+)$") or q:match("/library/(%d+)") or q:match("/catalog/(%d+)")
		if n then return "rbxassetid://"..n, n end
		return nil
	end
	const function resolve(q)
		q = trim(q)
		if q == "" then return nil, nil, "Enter an asset id, URL, or local filename." end
		const loc = findLocal(q)
		if loc then
			const asset = assetFor(loc)
			if asset then return asset, loc.name, nil, loc end
			return nil, nil, "This executor could not load the local audio file."
		end
		local sid, raw = idOf(q)
		if sid then return sid, raw end
		if q:match("^https?://") or q:match("^www%.") then
			local item, err = dl(q)
			if item and item.asset then
				st.assets[key(item.path)] = item.asset
				if not st.closed and st.frame == frame then rebuildList() end
				return item.asset, item.name, nil, item
			end
			return nil, nil, err or "Failed to load URL."
		end
		if ext(q) then return nil, nil, "Local audio file not found in Nameless-Admin/Music." end
		return nil, nil, "Enter a valid asset id, URL, or local filename."
	end
	const function nextTrack(dir)
		dir = dir == -1 and -1 or 1
		const tracks = scan()
		if #tracks == 0 then return nil end
		const cur = trim(st.raw or st.last or ""):lower()
		local idx
		for i, it in tracks do
			const nm = tostring(it.name or ""):lower()
			if cur == nm or cur == noext(nm) then idx = i break end
		end
		if st.mode == "random" and dir > 0 then
			if #tracks == 1 then return tracks[1] end
			local n = math.random(1, #tracks)
			if n == idx then n = (n % #tracks) + 1 end
			return tracks[n]
		end
		return tracks[(((idx or (dir > 0 and 0 or 1)) - 1 + dir) % #tracks) + 1]
	end
	local cmp = type(compareinstances) == "function" and compareinstances or nil
	if not cmp and __NAUIProtector and type(__NAUIProtector.getFunction) == "function" then
		const ok, fn = pcall(__NAUIProtector.getFunction, "compareinstances")
		if ok and type(fn) == "function" then cmp = fn end
	end
	const function sameInst(a, b)
		if a == b then return true end
		if typeof(a) ~= "Instance" or typeof(b) ~= "Instance" or not cmp then return false end
		const ok, res = pcall(cmp, a, b)
		return ok and res == true
	end
	const function protRoot()
		local root
		if __NAUIProtector and type(__NAUIProtector.parent) == "function" then
			local ok, res = pcall(__NAUIProtector.parent)
			if ok and typeof(res) == "Instance" then root = res end
		end
		if not root and NAlib and type(NAlib.huiGrabber) == "function" then
			local ok, res = pcall(NAlib.huiGrabber)
			if ok and typeof(res) == "Instance" then root = res end
		end
		if not root and NAStuff and typeof(NAStuff.NASCREENGUI) == "Instance" then root = NAStuff.NASCREENGUI end
		if not root and typeof(frame) == "Instance" then root = frame end
		return root
	end
	const function safeParent(obj)
		if typeof(obj) ~= "Instance" then return nil end
		local ok, par = pcall(function() return obj.Parent end)
		if ok then return par end
		return nil
	end
	const function lockHost(host, root, rename)
		if NAmanage and type(NAmanage.ProtectInstance) == "function" then
			pcall(NAmanage.ProtectInstance, host, {
				register = true,
				enforceParent = true,
				parent = root,
				renameRoot = rename,
				nameKey = "MusicHost",
			})
		end
	end
	const function ensureHost()
		const root = protRoot()
		if not root then return frame end
		local host = st.host
		if typeof(host) == "Instance" then
			local par = safeParent(host)
			if not sameInst(par, root) then
				const ok = pcall(function() host.Parent = root end)
				par = safeParent(host)
				if ok and par then
					lockHost(host, root, false)
					par = safeParent(host)
				end
				if not ok or not sameInst(par, root) then
					if par then return host end
					host = nil
				end
			end
		else
			host = nil
		end
		if not host then
			host = InstanceNew("Folder")
			host.Name = NAmanage.GetSessionInstanceName and NAmanage.GetSessionInstanceName("MusicHost") or "NA_MusicHost"
			host.Parent = root
			st.host = host
			lockHost(host, root, true)
		end
		return host
	end
	const function clearSound()
		NAlib.disconnect("NA_MusicPlayerSound")
		if st.snd then
			pcall(function() st.snd:Destroy() end)
			st.snd = nil
		end
	end
	const function mkSound(id, raw, auto, seek, repair)
		clearSound()
		const par = ensureHost() or frame
		const s = InstanceNew("Sound")
		s.Name = NAmanage.GetSessionInstanceName and NAmanage.GetSessionInstanceName("MusicPlayerSound") or "NA_MusicPlayerSound"
		s.SoundId = id
		s.Volume = st.vol
		s.PlaybackSpeed = st.spd
		s.Looped = false
		s.Parent = par
		st.snd = s
		st.sid = id
		st.raw = tostring(raw or "")
		st.last = st.raw
		st.wasPlaying = auto == true
		st.repairing = false
		st.needsRepair = false
		if NAmanage and type(NAmanage.ProtectInstance) == "function" then
			pcall(NAmanage.ProtectInstance, s, {
				register = true,
				enforceParent = true,
				parent = par,
				renameRoot = true,
				nameKey = "MusicPlayerSound",
			})
		end
		if nameBox then nameBox.Text = st.file and noext(st.file.name) or "" end
		syncRange()
		if not repair then setNow("Loaded: "..st.raw) end
		setStat(repair and "Restored" or "Loaded", Color3.fromRGB(55, 55, 75))
		setProg(tonumber(seek) or 0, s.TimeLength or 0)
		syncMix()
		saveCfg()
		const function clearGroup()
			if st.snd == s and safeParent(s) then pcall(function() if s.SoundGroup ~= nil then s.SoundGroup = nil end end) end
		end
		const function markRepair()
			if st.snd ~= s then return end
			local pos = 0
			pcall(function() pos = s.TimePosition or 0 end)
			st.repairPos = pos
			st.needsRepair = true
		end
		clearGroup()
		NAlib.connect("NA_MusicPlayerSound", s:GetPropertyChangedSignal("SoundGroup"):Connect(function() Defer(clearGroup) end))
		NAlib.connect("NA_MusicPlayerSound", s.AncestryChanged:Connect(function(_, parent)
			if st.snd == s and parent == nil then markRepair() end
		end))
		pcall(function()
			NAlib.connect("NA_MusicPlayerSound", s.Destroying:Connect(markRepair))
		end)
		local prepared = false
		const function onLoaded()
			if st.snd ~= s or prepared then return end
			prepared = true
			syncMix()
			local pos = tonumber(seek)
			if pos == nil then pos = st.loop and select(1, bounds(s.TimeLength)) or 0 end
			pos = math.clamp(pos, 0, math.max(0, s.TimeLength))
			if pos > 0 then pcall(function() s.TimePosition = pos end) end
			setStat(s.IsPlaying and "Playing" or "Loaded", s.IsPlaying and Color3.fromRGB(35,90,70) or Color3.fromRGB(55,55,75))
			setProg(s.TimePosition, s.TimeLength)
		end
		NAlib.connect("NA_MusicPlayerSound", s.Loaded:Connect(onLoaded))
		if s.IsLoaded then Defer(onLoaded) end
		NAlib.connect("NA_MusicPlayerSound", s.Played:Connect(function()
			if st.snd ~= s then return end
			st.wasPlaying = true
			setStat("Playing", Color3.fromRGB(35, 90, 70))
		end))
		NAlib.connect("NA_MusicPlayerSound", s.Paused:Connect(function()
			if st.snd ~= s then return end
			st.wasPlaying = false
			setStat("Paused", Color3.fromRGB(65, 65, 82))
		end))
		NAlib.connect("NA_MusicPlayerSound", s.Stopped:Connect(function()
			if st.snd ~= s then return end
			st.wasPlaying = false
			setStat("Stopped", Color3.fromRGB(55, 55, 65))
			setProg(0, s.TimeLength or 0)
		end))
		NAlib.connect("NA_MusicPlayerSound", s.Ended:Connect(function()
			if st.snd ~= s then return end
			st.wasPlaying = false
			setStat("Ended", Color3.fromRGB(86, 62, 45))
			if st.loop then
				const a = select(1, bounds(s.TimeLength))
				s:Play()
				s.TimePosition = a
				return
			end
			if st.mode == "order" or st.mode == "random" then
				const nxt = nextTrack()
				if nxt then loadTrack(nxt.name, true, true) end
			end
		end))
		if auto then
			Defer(function()
				if st.snd ~= s then return end
				pcall(function() s:Play() end)
				local pos = tonumber(seek)
				if pos == nil then pos = st.loop and select(1, bounds(s.TimeLength)) or 0 end
				if pos > 0 then pcall(function() s.TimePosition = pos end) end
			end)
		elseif tonumber(seek) and seek > 0 then
			pcall(function() s.TimePosition = seek end)
		end
		return true
	end
	const function repairSound(force)
		if not st.sid or st.repairing then return false end
		const nowTick = tick()
		if not force and nowTick - (tonumber(st.lastRepair) or 0) < 0.75 then return false end
		st.lastRepair = nowTick
		st.repairing = true
		local pos = tonumber(st.repairPos) or 0
		local play = st.wasPlaying == true
		if st.snd then
			pcall(function() pos = st.snd.TimePosition or pos end)
			pcall(function() play = st.snd.IsPlaying == true or st.snd.Playing == true or play end)
		end
		return mkSound(st.sid, st.raw or st.last or "", play, pos, true)
	end
	function loadTrack(raw, auto, quiet, back)
		raw = raw or (inp and inp.Text) or st.last or ""
		st.seq += 1
		const seq = st.seq
		if tostring(raw):match("^https?://") or tostring(raw):match("^www%.") then setStat("Downloading", Color3.fromRGB(65,65,82)) end
		local id, display, err, item = resolve(raw)
		if st.closed or st.frame ~= frame or st.seq ~= seq then return false end
		if not id then
			if not quiet then DoNotif(err or "Failed to load track.", 3, "Music") end
			setStat("Error", Color3.fromRGB(95,45,55))
			return false
		end
		const name = tostring(display or raw or "")
		if not back and st.raw and st.raw ~= "" and st.raw ~= name then
			st.hist[#st.hist + 1] = st.raw
			if #st.hist > 64 then table.remove(st.hist,1) end
		end
		st.file = item
		if inp then inp.Text = name end
		const good = mkSound(id, name, auto)
		rebuildList(false)
		return good
	end
	const function renameImpl(value)
		const item = st.file
		if not item then return fail("Load a local file or downloaded track before renaming it.") end
		if type(readfile) ~= "function" or type(writefile) ~= "function" or type(delfile) ~= "function" or type(isfile) ~= "function" then
			return fail("This executor does not support renaming local files.")
		end
		st.seq += 1
		local name = trim(value or (nameBox and nameBox.Text) or "")
		const suffix = ext(item.path)
		if name:lower():sub(-#suffix - 1) == "."..suffix then name = name:sub(1,-#suffix - 2) end
		if name == "" or name == "." or name == ".." or name:find('[/\\:*?"<>|%c]') or name:match("[%. ]$") then
			return fail("Use a filename without slashes, special characters, or a trailing dot.")
		end
		const base = (name:match("^[^%.]+") or name):upper()
		if base == "CON" or base == "PRN" or base == "AUX" or base == "NUL" or base:match("^COM[1-9]$") or base:match("^LPT[1-9]$") then
			return fail("That filename is reserved. Choose another name.")
		end
		if #name > 160 then return fail("Keep the filename under 160 characters.") end
		const other = ext(name)
		if other and other ~= suffix then return fail("Renaming cannot change the audio format.") end
		name ..= "."..suffix
		const dst = st.root.."/"..name
		if key(dst) == key(item.path) then return fail("This file already has that name.") end
		const okDst, exists = pcall(isfile,dst)
		if not okDst or exists then return fail("A file with that name already exists.") end
		const okRead, data = pcall(readfile,item.path)
		if not okRead or type(data) ~= "string" then return fail("Could not read the original audio file.") end
		const okWrite = pcall(writefile,dst,data)
		const okCheck, copy = pcall(readfile,dst)
		if not okWrite or not okCheck or copy ~= data then
			pcall(delfile,dst)
			return fail("Could not verify the new file. The original was kept.")
		end
		const changed = {path=dst,name=name}
		const asset = assetFor(changed)
		if not asset then pcall(delfile,dst); return fail("Could not load the renamed audio. The original was kept.") end
		const okDelete = pcall(delfile,item.path)
		const okOld, remains = pcall(isfile,item.path)
		if not okDelete or not okOld or remains then
			if okOld and remains then pcall(delfile,dst) end
			st.assets[key(dst)] = nil
			return fail("Could not remove the old filename. Your audio was kept.")
		end
		const clip = st.clips[key(item.name)]
		st.clips[key(item.name)] = nil
		st.clips[key(name)] = clip
		for i, prev in st.hist do if key(prev) == key(item.name) then st.hist[i] = name end end
		st.assets[key(item.path)] = nil
		local pos, play = 0, false
		if st.snd then pos = st.snd.TimePosition; play = st.snd.IsPlaying end
		st.file = changed
		if inp then inp.Text = name end
		mkSound(asset,name,play,pos,true)
		setNow("Loaded: "..name)
		rebuildList()
		saveCfg()
		return true, name
	end
	const function renameTrack(value)
		if st.renaming then return false end
		st.renaming = true
		const ok, good, info = pcall(renameImpl,value)
		st.renaming = false
		if not ok then return fail("The file could not be renamed.") end
		return good,info
	end
	loadCfg()
	if inp and trim(inp.Text) == "" then inp.Text = st.last or "" end
	syncMix()
	syncRange()
	if search then search.Text = st.filter end
	rebuildList()
	if st.last and st.last ~= "" then setNow("Last: "..st.last) end
	if load then NAlib.connect("NA_MusicPlayer", MouseButtonFix(load, function() loadTrack(nil, false) end)) end
	if inp then NAlib.connect("NA_MusicPlayer", inp.FocusLost:Connect(function(ok) if ok then loadTrack(nil, false) end end)) end
	if btns.Refresh then NAlib.connect("NA_MusicPlayer", MouseButtonFix(btns.Refresh, rebuildList)) end
	if btns.Play then NAlib.connect("NA_MusicPlayer", MouseButtonFix(btns.Play, function()
		if not st.snd then loadTrack(nil,true); return end
		pcall(function()
			st.snd:Play()
			if st.loop then
				const a,b,custom = bounds(st.snd.TimeLength)
				if custom and (st.snd.TimePosition < a or st.snd.TimePosition >= b) then st.snd.TimePosition = a end
			end
		end)
	end)) end
	if btns.Pause then NAlib.connect("NA_MusicPlayer", MouseButtonFix(btns.Pause, function() if st.snd then pcall(function() st.snd:Pause() end) end end)) end
	if btns.Resume then NAlib.connect("NA_MusicPlayer", MouseButtonFix(btns.Resume, function()
		if st.snd then
			const pos = st.snd.TimePosition
			pcall(function()
				st.snd:Resume()
				if not st.snd.IsPlaying then st.snd:Play(); st.snd.TimePosition = pos end
			end)
		end
	end)) end
	if btns.Stop then NAlib.connect("NA_MusicPlayer", MouseButtonFix(btns.Stop, function() if st.snd then pcall(function() st.snd:Stop() end) end end)) end
	if btns.Loop then NAlib.connect("NA_MusicPlayer", MouseButtonFix(btns.Loop, function()
		st.loop = not st.loop
		syncMix()
		if st.loop and st.snd and st.snd.TimeLength > 0 then
			const a,b,custom = bounds(st.snd.TimeLength)
			if custom and (st.snd.TimePosition < a or st.snd.TimePosition >= b) then st.snd.TimePosition = a end
		end
		saveCfg()
	end)) end
	if btns.Mode then NAlib.connect("NA_MusicPlayer", MouseButtonFix(btns.Mode, function()
		st.mode = st.mode == "off" and "order" or st.mode == "order" and "random" or "off"
		syncMix()
		saveCfg()
	end)) end
	const function prevTrack()
		const prev = table.remove(st.hist)
		if prev then return loadTrack(prev,true,false,true) end
		const item = nextTrack(-1)
		if item then return loadTrack(item.name,true,false,true) end
		return fail("No local music files found.")
	end
	if btns.Previous then NAlib.connect("NA_MusicPlayer",MouseButtonFix(btns.Previous,prevTrack)) end
	if btns.Next then NAlib.connect("NA_MusicPlayer", MouseButtonFix(btns.Next, function()
		const nxt = nextTrack()
		if not nxt then DoNotif("No local music files found.", 3, "Music") return end
		loadTrack(nxt.name, true)
	end)) end
	if volBox then NAlib.connect("NA_MusicPlayer", volBox.FocusLost:Connect(function()
		st.vol = math.clamp(tonumber(volBox.Text) or st.vol or 1, 0, 10)
		syncMix()
		saveCfg()
	end)) end
	if spdBox then NAlib.connect("NA_MusicPlayer", spdBox.FocusLost:Connect(function()
		st.spd = math.clamp(tonumber(spdBox.Text) or st.spd or 1, 0.25, 4)
		syncMix()
		saveCfg()
	end)) end
	if search then NAlib.connect("NA_MusicPlayer", search:GetPropertyChangedSignal("Text"):Connect(function()
		st.filter = search.Text
		rebuildList(false)
	end)) end
	if files and files:FindFirstChild("Rename") then NAlib.connect("NA_MusicPlayer", MouseButtonFix(files.Rename,function() renameTrack() end)) end
	if nameBox then NAlib.connect("NA_MusicPlayer",nameBox.FocusLost:Connect(function(enter) if enter then renameTrack() end end)) end
	const function applyRange()
		setRange(startBox and startBox.Text or "0",endBox and endBox.Text or "")
	end
	if startBox then NAlib.connect("NA_MusicPlayer",startBox.FocusLost:Connect(applyRange)) end
	if endBox then NAlib.connect("NA_MusicPlayer",endBox.FocusLost:Connect(applyRange)) end
	if range then
		if range:FindFirstChild("SetStart") then NAlib.connect("NA_MusicPlayer",MouseButtonFix(range.SetStart,function()
			if st.snd then setRange(st.snd.TimePosition,endBox and endBox.Text or "") end
		end)) end
		if range:FindFirstChild("SetEnd") then NAlib.connect("NA_MusicPlayer",MouseButtonFix(range.SetEnd,function()
			if st.snd then setRange(startBox and startBox.Text or "0",st.snd.TimePosition) end
		end)) end
		if range:FindFirstChild("Clear") then NAlib.connect("NA_MusicPlayer",MouseButtonFix(range.Clear,function() setRange(0,nil) end)) end
	end
	if seekBox then NAlib.connect("NA_MusicPlayer",seekBox.FocusLost:Connect(function(enter) if enter then seekTo(seekBox.Text) end end)) end
	if library and library:FindFirstChild("Seek") then NAlib.connect("NA_MusicPlayer",MouseButtonFix(library.Seek,function() seekTo(seekBox and seekBox.Text or "") end)) end
	if prog then
		local drag
		const function move(x)
			if not st.snd or st.snd.TimeLength <= 0 then return end
			const a = math.clamp((x-prog.AbsolutePosition.X)/math.max(prog.AbsoluteSize.X,1),0,1)
			seekTo(st.snd.TimeLength*a)
		end
		NAlib.connect("NA_MusicPlayer",prog.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				drag = input
				move(input.Position.X)
			end
		end))
		NAlib.connect("NA_MusicPlayer",Services.UserInputService.InputChanged:Connect(function(input)
			if drag and (input == drag or input.UserInputType == Enum.UserInputType.MouseMovement) then move(input.Position.X) end
		end))
		NAlib.connect("NA_MusicPlayer",Services.UserInputService.InputEnded:Connect(function(input)
			if input == drag or input.UserInputType == Enum.UserInputType.MouseButton1 then drag = nil end
		end))
	end
	NAlib.connect("NA_MusicPlayer", Services.RunService.Heartbeat:Connect(function(dt)
		if st.closed or st.frame ~= frame then return end
		if st.snd and st.loop and st.snd.IsPlaying and st.snd.TimeLength > 0 then
			const a,b,custom = bounds(st.snd.TimeLength)
			const pos = st.snd.TimePosition
			if custom and pos >= b then st.snd.TimePosition = a + ((pos-b) % math.max(b-a,0.05)) end
		end
		st.tick = (tonumber(st.tick) or 0) + (tonumber(dt) or 0)
		if st.tick < 0.18 then return end
		st.tick = 0
		if st.snd then
			const par = safeParent(st.snd)
			const want = ensureHost()
			if st.needsRepair or par == nil then
				st.needsRepair = false
				repairSound(false)
				return
			elseif want and not sameInst(par, want) then
				const ok = pcall(function() st.snd.Parent = want end)
				if not ok or not sameInst(safeParent(st.snd), want) then
					repairSound(false)
					return
				end
			end
			pcall(function()
				st.repairPos = st.snd.TimePosition or st.repairPos or 0
				st.wasPlaying = st.snd.IsPlaying == true or st.snd.Playing == true
			end)
		end
		if not (frame and frame.Parent and frame.Visible and st.snd) then return end
		setProg(st.snd.TimePosition or 0, st.snd.TimeLength or 0)
	end))
	if st.snd and st.sid then
		local pos, play = 0, false
		pcall(function() pos = st.snd.TimePosition; play = st.snd.IsPlaying end)
		mkSound(st.sid,st.raw or st.last or "",play,pos,true)
	end
	if NAmanage.MusicWindowLayout then NAmanage.MusicWindowLayout(frame) end
	st.actions = {load=loadTrack,refresh=rebuildList,rename=renameTrack,seek=seekTo,range=setRange,parse=parse,bounds=bounds,previous=prevTrack}
	NAlib.connect("NA_MusicPlayer",frame.Destroying:Connect(function()
		if st.frame ~= frame then return end
		st.closed = true
		st.ready = false
		st.seq += 1
		NAlib.disconnect("NA_MusicRows")
		NAlib.disconnect("NA_MusicPlayer")
		clearSound()
		st.actions = nil
	end))
	return true
end

NAmanage.MusicWindow_Open = NAmanage.MusicWindow_Open or function()
	if not NAmanage.MusicWindowInit() then
		DoNotif("Music player UI unavailable.", 3, "Music")
		return false
	end
	const frame = NAUIMANAGER and NAUIMANAGER.MusicFrame
	if frame then
		NAgui.setWindowVisible(frame, true)
		if NAmanage.OnUIWindowShown then pcall(NAmanage.OnUIWindowShown, frame) end
		return true
	end
	return false
end

NAmanage.MusicWindow_Toggle = NAmanage.MusicWindow_Toggle or function()
	const frame = NAUIMANAGER and NAUIMANAGER.MusicFrame
	if NAgui.isWindowOpen(frame) then
		NAgui.closeWindow(frame)
		return true
	end
	return NAmanage.MusicWindow_Open()
end

NAgui.musicplayer = NAgui.musicplayer or function()
	return NAmanage.MusicWindow_Open()
end

NAgui.settingss = function()
	if NAUIMANAGER.SettingsFrame then
		const settingsFrame = NAUIMANAGER.SettingsFrame
		if NAmanage.InstallUIVisibilityOptimizer then pcall(NAmanage.InstallUIVisibilityOptimizer) end
		if not settingsFrame.Visible then
			settingsFrame.Visible = true
		end
		if NAmanage.OnUIWindowShown then pcall(NAmanage.OnUIWindowShown, settingsFrame) end
		NAmanage.centerFrame(settingsFrame)
		Defer(function()
			if not (settingsFrame and settingsFrame.Parent and settingsFrame.Visible) then
				return
			end
			if NAmanage.SettingsTabLayout then
				if type(NAmanage.SettingsTabLayout.FitFrameToViewport) == "function" then
					NAmanage.SettingsTabLayout.FitFrameToViewport()
				end
				if type(NAmanage.SettingsTabLayout.Apply) == "function" then
					NAmanage.SettingsTabLayout.Apply()
				end
			end
			NAmanage.centerFrame(settingsFrame)
		end)
	end
end
NAgui.commandkeybinds = function()
	const frame = NAUIMANAGER and NAUIMANAGER.CommandKeybindsFrame
	if not frame then
		return
	end
	if not NAmanage.CanUseCommandKeybinds(true) then
		frame.Visible = false
		return
	end
	if type(NAmanage.CommandKeybindsUIInit) == "function" then
		NAmanage.CommandKeybindsUIInit()
	end
	if type(NAmanage.CommandKeybindsUIWire) == "function" then
		NAmanage.CommandKeybindsUIWire()
	end
	if not frame.Visible then
		frame.Visible = true
	end
	NAmanage.centerFrame(frame)
	if type(NAmanage.CommandKeybindsUIRefresh) == "function" then
		NAmanage.CommandKeybindsUIRefresh()
	end
end
NAgui.waypointers = function()
	if NAUIMANAGER.WaypointFrame then
		if not NAUIMANAGER.WaypointFrame.Visible then
			NAUIMANAGER.WaypointFrame.Visible = true
		end
		--NAUIMANAGER.WaypointFrame.Position = UDim2.new(0.43, 0, 0.4, 0)
		NAmanage.centerFrame(NAUIMANAGER.WaypointFrame)
	end
end
NAgui.eventbinders = function()
	if NAUIMANAGER.BindersFrame then
		if not NAUIMANAGER.BindersFrame.Visible then
			NAUIMANAGER.BindersFrame.Visible = true
		end
		--NAUIMANAGER.BindersFrame.Position = UDim2.new(0.43, 0, 0.4, 0)
		NAmanage.centerFrame(NAUIMANAGER.BindersFrame)
	end
end
do
	const active = NAmanage.ensureWeakKeyTable()
	const windows = NAmanage.ensureWeakKeyTable()
	NAgui.UIMotion = { active = active; windows = windows }
	const gui = SafeGetService("GuiService")
	const function reduced()
		local enabled = false
		pcall(function() enabled = gui.ReducedMotionEnabled end)
		return enabled == true
	end
	NAgui.UIMotion.isReduced = reduced

	NAgui.motion = function(obj, info, goal)
		local slots = active[obj]
		if not slots then slots = {} active[obj] = slots end
		const previous = {}
		for key in goal do
			const old = slots[key]
			if old then previous[old] = true end
		end
		for old in previous do old:Cancel() end
		active[obj] = slots
		if NAgui.UIMotion.isReduced() then info = TweenInfo.new(0) end
		const tween = __lt.cm("TweenService", "Create", obj, info, goal)
		for key in goal do slots[key] = tween end
		local conn
		conn = tween.Completed:Connect(function()
			conn:Disconnect()
			for key in goal do if slots[key] == tween then slots[key] = nil end end
			if not next(slots) and active[obj] == slots then active[obj] = nil end
		end)
		return tween
	end

	NAgui.tween = function(obj, style, direction, duration, goal, callback)
		const info = TweenInfo.new(math.max(0, tonumber(duration) or 0.24), Enum.EasingStyle[style or "Quint"], Enum.EasingDirection[direction or "Out"])
		const tween = NAgui.motion(obj, info, goal)
		if callback then
			local conn
			conn = tween.Completed:Connect(function(state)
				conn:Disconnect()
				if state == Enum.PlaybackState.Completed then callback(state) end
			end)
		end
		tween:Play()
		return tween
	end

	local function openWindow(menu, rec, position, reset)
		rec.pos = position
		if reset then
			menu.Position = position + UDim2.new(0, 0, 0.15, 0)
		end
		const epoch = rec.epoch
		const tween = NAgui.motion(menu, TweenInfo.new(0.2, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out), {
			Position = position
		})
		tween.Completed:Once(function()
			if rec.epoch == epoch and rec.opening then
				rec.opening = false
				rec.pos = nil
			end
		end)
		tween:Play()
	end

	NAgui.stopWindowMotion = function(menu, finish)
		const rec = windows[menu]
		if not rec then return end
		rec.closePending = false
		if not (rec.opening or rec.closing) then return end
		const position = rec.pos
		rec.epoch += 1
		rec.opening = false
		rec.closing = false
		rec.pos = nil
		const slots = active[menu]
		if slots and slots.Position then slots.Position:Cancel() end
		if finish and position then menu.Position = position end
	end

	NAgui.retargetWindowMotion = function(menu, position)
		const rec = windows[menu]
		if not (rec and rec.opening) then return false end
		if rec.pos ~= position then
			rec.epoch += 1
			openWindow(menu, rec, position, true)
		end
		return true
	end

	NAgui.bindWindowMotion = function(menu, key)
		key = key.."_motion"
		NAlib.disconnect(key)
		local rec = windows[menu]
		const scale = rec and rec.scale or InstanceNew("UIScale")
		scale.Name = "NAWindowMotion"
		scale.Parent = menu
		rec = rec or { scale = scale; epoch = 0; closing = false }
		rec.epoch += 1
		rec.closing = false
		rec.opening = false
		rec.closePending = false
		rec.shown = nil
		rec.pos = nil
		rec.restoringBubble = nil
		windows[menu] = rec
		NAgui.tween(scale, "Quint", "Out", 0, { Scale = 1 })
		NAlib.connect(key, menu.Destroying:Connect(function()
			rec.epoch += 1
			rec.closePending = false
			windows[menu] = nil
			NAlib.disconnect(key)
		end))
		const header = menu:FindFirstChild("Topbar")
		if header then
			const hidden, watched = rec.headerHidden or {}, {}
			rec.headerHidden = hidden
			local fitHeader
			fitHeader = function()
				const width = NAmanage.GetLogicalAbsoluteSize(menu).X
				const scale = math.max(0.01, NAmanage.GetUIScaleFactor(header))
				local left = math.huge
				for _, name in { "Translate", "TranslateInput" } do
					const obj = header:FindFirstChild(name)
					if obj and obj:IsA("GuiObject") then left = math.min(left, (obj.AbsolutePosition.X - header.AbsolutePosition.X) / scale) end
				end
				const title = header:FindFirstChild("Title") or header
				local right = 0
				if title:IsA("TextLabel") then
					const x = title.AbsolutePosition.X - header.AbsolutePosition.X
					const w = title.AbsoluteSize.X
					const text = title.TextBounds.X
					right = (x + (title.TextXAlignment == Enum.TextXAlignment.Left and text or title.TextXAlignment == Enum.TextXAlignment.Right and w or (w + text) * 0.5)) / scale
					if not watched[title] then
						watched[title] = true
						NAlib.connect(key, title:GetPropertyChangedSignal("TextBounds"):Connect(fitHeader))
					end
				end
				const compact = width > 0 and (width < 420 or right + 10 > left)
				for _, name in { "Translate", "TranslateInput" } do
					const obj = header:FindFirstChild(name)
					if obj and obj:IsA("GuiObject") then
						if not watched[obj] then
							watched[obj] = true
							NAlib.connect(key, obj:GetPropertyChangedSignal("Visible"):Connect(fitHeader))
						end
						if compact then
							if hidden[obj] == nil then hidden[obj] = obj.Visible end
							if obj.Visible ~= false then obj.Visible = false end
						elseif hidden[obj] ~= nil then
							if obj.Visible ~= hidden[obj] then obj.Visible = hidden[obj] end
							hidden[obj] = nil
						end
					end
				end
			end
			NAlib.connect(key, menu:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitHeader))
			NAlib.connect(key, header.ChildAdded:Connect(function() fitHeader() Defer(fitHeader) end))
			if header:IsA("TextLabel") then NAlib.connect(key, header:GetPropertyChangedSignal("TextBounds"):Connect(fitHeader)) end
			fitHeader()
		end
		NAlib.connect(key, menu:GetPropertyChangedSignal("Visible"):Connect(function()
			const shown = menu.Visible
			const restore = shown and rec.restoringBubble
			if shown then rec.restoringBubble = nil end
			if rec.shown == shown then return end
			rec.shown = shown
			rec.epoch += 1
			rec.closePending = false
			rec.closing = false
			if not menu.Visible then
				rec.opening = false
				if rec.pos then
					const slots = active[menu]
					if slots and slots.Position then slots.Position:Cancel() end
					menu.Position = rec.pos
					rec.pos = nil
				end
				return
			end
			const slots = active[menu]
			if slots and slots.Size then
				rec.opening = false
				rec.pos = nil
				return
			end
			rec.opening = false
			rec.pos = nil
			if not restore then NAmanage.centerFrame(menu) end
			if NAgui.UIMotion.isReduced() then return end
			rec.opening = true
			openWindow(menu, rec, menu.Position, true)
		end))
		for _, name in { "Minimize", "Maximize", "Exit" } do
			const button = menu:FindFirstChild(name, true)
			if button and button:IsA("GuiButton") then
				const old = button:FindFirstChild("NAButtonMotion")
				if old then old:Destroy() end
				if not button:FindFirstChildOfClass("UIScale") then
					local holder = button.Parent
					if not (holder and holder.Name == "NAButtonMotionHolder") then
						holder = InstanceNew("Frame")
						holder.Name = "NAButtonMotionHolder"
						holder.BackgroundTransparency = 1
						holder.BorderSizePixel = 0
						holder.AnchorPoint = button.AnchorPoint
						holder.Position = button.Position
						holder.Size = button.Size
						holder.LayoutOrder = button.LayoutOrder
						holder.ZIndex = button.ZIndex
						holder.Parent = button.Parent
						button.AnchorPoint = Vector2.new(0.5, 0.5)
						button.Position = UDim2.fromScale(0.5, 0.5)
						button.Size = UDim2.fromScale(1, 1)
						button.Parent = holder
					end
					const slots = active[button]
					if slots and slots.Size then slots.Size:Cancel() end
					const base = UDim2.fromScale(1, 1)
					if button.Size ~= base then button.Size = base end
					const pressOffset = UDim2.new(-0.04, -3, -0.04, -3)
					const selectOffset = UDim2.new(0.04, 3, 0.04, 3)
					const pressInfo = TweenInfo.new(0.06666666666666667, Enum.EasingStyle.Linear, Enum.EasingDirection.In)
					const releaseInfo = TweenInfo.new(0.06666666666666667, Enum.EasingStyle.Linear, Enum.EasingDirection.In)
					const selectInfo = TweenInfo.new(0.13333333333333333, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out)
					const deselectInfo = TweenInfo.new(0.13333333333333333, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out)
					local selected = false
					local pressed
					const function selectButton()
						if selected then return end
						selected = true
						NAgui.motion(button, selectInfo, { Size = base + selectOffset }):Play()
					end
					const function deselectButton()
						if not selected then return end
						selected = false
						NAgui.motion(button, deselectInfo, { Size = base }):Play()
					end
					const function releaseButton()
						pressed = nil
						NAgui.motion(button, releaseInfo, { Size = selected and base + selectOffset or base }):Play()
					end
					NAlib.connect(key, button.MouseEnter:Connect(selectButton))
					NAlib.connect(key, button.MouseLeave:Connect(deselectButton))
					NAlib.connect(key, button.SelectionGained:Connect(selectButton))
					NAlib.connect(key, button.SelectionLost:Connect(deselectButton))
					NAlib.connect(key, button.InputBegan:Connect(function(input)
						if not button.Active or input.UserInputState ~= Enum.UserInputState.Begin then return end
						if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch or input.KeyCode == Enum.KeyCode.ButtonA then
							pressed = input
							NAgui.motion(button, pressInfo, { Size = base + pressOffset }):Play()
						end
					end))
					NAlib.connect(key, Services.UserInputService.InputEnded:Connect(function(input)
						if input == pressed then releaseButton() end
					end))
					NAlib.connect(key, button:GetPropertyChangedSignal("Active"):Connect(function()
						if not button.Active then
							deselectButton()
							if pressed then releaseButton() end
						end
					end))
				end
			end
		end
		return rec
	end

	NAgui.closeWindow = function(menu)
		if not (menu and menu.Parent) then return end
		const rec = windows[menu]
		if rec and rec.clearBubble then rec.clearBubble() end
		if not menu.Visible then return end
		if not rec or NAgui.UIMotion.isReduced() then menu.Visible = false return end
		if rec.closing or rec.closePending then return end
		const slots = active[menu]
		const resize = slots and slots.Size
		if resize and resize.PlaybackState == Enum.PlaybackState.Playing then
			rec.closePending = true
			resize.Completed:Once(function()
				if not rec.closePending then return end
				rec.closePending = false
				if menu.Parent and menu.Visible then NAgui.closeWindow(menu) end
			end)
			return
		end
		const position = rec.opening and rec.pos or menu.Position
		rec.pos = position
		rec.opening = false
		rec.closing = true
		rec.epoch += 1
		const epoch = rec.epoch
		NAgui.tween(menu, "Cubic", "In", 0.15, {
			Position = position + UDim2.new(0, 0, 0.15, 0)
		}, function()
			if rec.epoch == epoch and rec.closing then menu.Visible = false end
		end)
	end

	NAgui.cancelWindowClose = function(menu)
		const rec = windows[menu]
		if rec then rec.closePending = false end
		if rec and rec.closing then
			rec.epoch += 1
			rec.closing = false
			rec.opening = true
			openWindow(menu, rec, rec.pos or menu.Position, false)
		end
	end

	NAgui.isWindowOpen = function(menu)
		if not (menu and menu.Visible) then return false end
		const rec = windows[menu]
		return not (rec and (rec.closing or rec.closePending))
	end

	NAgui.setWindowVisible = function(menu, visible)
		if not (menu and menu.Parent) then return false end
		if visible then
			const rec = windows[menu]
			if rec and rec.clearBubble and rec.setMinimized and NAmanage.GetAttr(menu, "NAMenuMinimized") == true then
				return rec.setMinimized(false)
			end
			NAgui.cancelWindowClose(menu)
			NAmanage.centerFrame(menu)
			if not menu.Visible then menu.Visible = true end
		else
			NAgui.closeWindow(menu)
		end
		return true
	end

	NAgui.toggleWindow = function(menu)
		return NAgui.setWindowVisible(menu, not NAgui.isWindowOpen(menu))
	end

	NAmanage.RegisterUnloadCleanup("ui_motion", function()
		const tweens = {}
		for _, slots in active do for _, tween in slots do tweens[tween] = true end end
		for tween in tweens do tween:Cancel() end
		table.clear(active)
		table.clear(windows)
	end)
end

NAmanage.PluginsWindow_Clear = NAmanage.PluginsWindow_Clear or function()
	const list = NAUIMANAGER and NAUIMANAGER.PluginsList
	if not list then
		return
	end
	for _, child in list:GetChildren() do
		if child:IsA("GuiObject") then
			child:Destroy()
		end
	end
	if not list:FindFirstChildWhichIsA("UIListLayout") then
		const layout = InstanceNew("UIListLayout", list)
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		layout.Padding = UDim.new(0, 6)
	end
end

