NAmanage.PluginsWindow_Filter = NAmanage.PluginsWindow_Filter or function()
	const list = NAUIMANAGER and NAUIMANAGER.PluginsList
	const filter = NAUIMANAGER and NAUIMANAGER.PluginsFilter
	if not list then return end
	const query = Lower(tostring(filter and filter.Text or ""))
	for _, child in list:GetChildren() do
		if child:IsA("GuiObject") then
			if query == "" then
				child.Visible = true
			else
				const hay = tostring(NAmanage.GetAttr(child, "NAPluginSearch") or child.Name or ""):lower()
				child.Visible = hay:find(query, 1, true) ~= nil
			end
		end
	end
	if NAmanage.CustomScroll and NAmanage.CustomScroll.refreshByTarget then
		NAmanage.CustomScroll.refreshByTarget(list)
	end
end

NAmanage.PluginsWindow_Rebuild = NAmanage.PluginsWindow_Rebuild or function(opts)
	opts = opts or {}
	const frame = NAmanage.EnsurePluginsWindow()
	NAmanage.PluginsWindow_Clear()
	const entries = NAmanage.PluginListFiles and NAmanage.PluginListFiles() or {}
	local builtRows = 0
	const function pulse()
		builtRows += 1
		if builtRows % 8 == 0 then
			Wait()
		end
	end
	NAmanage.PluginsWindow_AddSection("Manager")
	NAmanage.PluginsWindow_AddToggle("Load plugins on startup", NAStuff.PluginAutoLoad ~= false, function(on)
		NAStuff.PluginAutoLoad = on == true
		pcall(NAmanage.NASettingsSet, "pluginAutoLoad", NAStuff.PluginAutoLoad)
		DoNotif("Plugin startup loading "..(on and "enabled" or "disabled"), 2)
	end)
	NAmanage.PluginsWindow_AddToggle("Allow plugin UI controls", NAStuff.PluginSettingsUIEnabled ~= false, function(on)
		NAStuff.PluginSettingsUIEnabled = on == true
		pcall(NAmanage.NASettingsSet, "pluginAllowSettingsUI", NAStuff.PluginSettingsUIEnabled)
		DoNotif("Plugin UI controls "..(on and "enabled" or "disabled"), 2)
	end)
	NAmanage.PluginsWindow_AddButton("Create plugin with Plugin Maker", function()
		if type(NAmanage.PluginMaker_Open) == "function" then
			NAmanage.PluginMaker_Open()
		elseif cmd and cmd.run then
			cmd.run({"pluginmaker"})
		end
	end)
	NAmanage.PluginsWindow_AddButton("Reload enabled plugins", function()
		if NAmanage.LoadPlugins then
			NAmanage.LoadPlugins({ forceNotify = true })
		end
		NAmanage.PluginsWindow_RequestRebuild()
	end)
	NAmanage.PluginsWindow_AddInput("Install plugin from URL", "https://.../plugin.na", "", function(text)
		const url = tostring(text or ""):match("^%s*(.-)%s*$") or ""
		if url == "" then return end
		local ok, msg = NAmanage.PluginInstallFromUrl(url)
		DoNotif(ok and ("Installed "..NAmanage.PluginBaseName(msg)) or ("Install failed: "..tostring(msg)), 3)
		if ok and NAmanage.LoadPlugins then
			NAmanage.LoadPlugins({ silent = true })
		end
		NAmanage.PluginsWindow_RequestRebuild()
	end)
	NAmanage.PluginsWindow_AddButton("Move all workspace plugins into plugin folders", function()
		if cmd and cmd.run then
			cmd.run({"addallplugins"})
		end
		if NAmanage.LoadPlugins then
			NAmanage.LoadPlugins({ silent = true })
		end
		NAmanage.PluginsWindow_RequestRebuild()
	end)
	NAmanage.PluginsWindow_AddButton("Enable all installed plugins", function()
		for _, entry in entries do
			NAmanage.PluginSetEnabled(entry.path, true)
		end
		if NAmanage.LoadPlugins then
			NAmanage.LoadPlugins({ silent = true })
		end
		DoNotif("Enabled all installed plugins", 2)
		NAmanage.PluginsWindow_RequestRebuild()
	end)
	NAmanage.PluginsWindow_AddButton("Disable all installed plugins", function()
		for _, entry in entries do
			NAmanage.PluginSetEnabled(entry.path, false)
		end
		if NAmanage.LoadPlugins then
			NAmanage.LoadPlugins({ silent = true })
		end
		DoNotif("Disabled all installed plugins", 2)
		NAmanage.PluginsWindow_RequestRebuild()
	end)
	NAmanage.PluginsWindow_AddSection("Installed Plugins")
	if #entries == 0 then
		NAmanage.PluginsWindow_AddButton("No plugins found in Plugins or PluginsIY", function()
			if cmd and cmd.run then
				cmd.run({"addplugin"})
			end
		end)
	else
		for _, entry in entries do
			NAmanage.PluginsWindow_AddPlugin(entry)
			pulse()
		end
	end
	local available = type(opts.availableEntries) == "table" and opts.availableEntries or nil
	local availablePending = false
	if not available then
		const cachedAvailable = NAmanage.PluginAvailableCacheGet and NAmanage.PluginAvailableCacheGet(30) or nil
		available = cachedAvailable or {}
		availablePending = cachedAvailable == nil
		if availablePending and opts.scanAvailable ~= false and NAmanage.PluginScanAvailableAsync then
			const token = NAStuff.PluginsWindowRebuildRequestToken
			NAmanage.PluginScanAvailableAsync(opts.forceScan == true, function(fresh)
				if frame and frame.Visible == true and token == NAStuff.PluginsWindowRebuildRequestToken and NAmanage.PluginsWindow_RequestRebuild then
					NAmanage.PluginsWindow_RequestRebuild({
						availableEntries = fresh,
						scanAvailable = false,
						placeholder = false,
					})
				end
			end)
		end
	end
	NAmanage.PluginsWindow_AddSection("Available Plugins")
	if #available == 0 then
		NAmanage.PluginsWindow_AddButton(availablePending and "Scanning workspace plugins..." or "No workspace plugins outside Plugins or PluginsIY", function()
			if cmd and cmd.run then
				cmd.run({"addplugin"})
			end
		end)
	else
		for _, entry in available do
			NAmanage.PluginsWindow_AddAvailablePlugin(entry)
			pulse()
		end
	end
	if NAStuff.PluginSettingsUIEnabled ~= false and type(NAmanage._pluginControlSpecs) == "table" then
		const controlGroups = {}
		for _, group in NAmanage._pluginControlSpecs do
			if type(group) == "table" and type(group.items) == "table" and #group.items > 0 then
				Insert(controlGroups, group)
			end
		end
		table.sort(controlGroups, function(a, b)
			return tostring(a.name or "") < tostring(b.name or "")
		end)
		if #controlGroups > 0 then
			NAmanage.PluginsWindow_AddSection("Plugin UI")
			for _, group in controlGroups do
				local lastTab
				for _, item in group.items do
					const tabName = tostring(item.tabName or "Controls")
					if tabName ~= lastTab then
						lastTab = tabName
						NAmanage.PluginsWindow_AddSection(tostring(group.name or "Plugin").." / "..tabName)
					end
					if item.kind == "section" then
						NAmanage.PluginsWindow_AddSection(item.label)
					elseif item.kind == "button" then
						NAmanage.PluginsWindow_AddButton(item.label, item.callback)
					elseif item.kind == "input" then
						NAmanage.PluginsWindow_AddInput(item.label, item.placeholder, item.defaultText, item.callback)
					elseif item.kind == "toggle" then
						NAmanage.PluginsWindow_AddToggle(item.label, item.defaultValue == true, item.callback)
					end
					pulse()
				end
			end
		end
	end
	NAmanage.PluginsWindow_Filter()
	const filter = NAUIMANAGER and NAUIMANAGER.PluginsFilter
	if filter and not NAStuff.PluginsFilterConnected then
		NAStuff.PluginsFilterConnected = true
		filter:GetPropertyChangedSignal("Text"):Connect(NAmanage.PluginsWindow_Filter)
	end
	NAStuff.PluginsWindowHasContent = true
	if NAmanage.CustomScroll and NAmanage.CustomScroll.refreshByTarget then
		NAmanage.CustomScroll.refreshByTarget(NAUIMANAGER and NAUIMANAGER.PluginsList)
	end
end

NAmanage.PluginsWindow_RequestRebuild = NAmanage.PluginsWindow_RequestRebuild or function(opts)
	opts = opts or {}
	const frame = NAmanage.EnsurePluginsWindow and NAmanage.EnsurePluginsWindow()
	if not frame then
		return false
	end
	NAStuff.PluginsWindowRebuildRequestToken = (tonumber(NAStuff.PluginsWindowRebuildRequestToken) or 0) + 1
	const token = NAStuff.PluginsWindowRebuildRequestToken
	if opts.placeholder ~= false and not NAStuff.PluginsWindowHasContent then
		NAmanage.PluginsWindow_Clear()
		NAmanage.PluginsWindow_AddSection("Loading plugins...")
	end
	SpawnCall(function()
		Wait()
		if token ~= NAStuff.PluginsWindowRebuildRequestToken or frame.Visible ~= true then
			return
		end
		if NAmanage.PluginsWindow_Rebuild then
			NAmanage.PluginsWindow_Rebuild(opts)
		end
	end)
	return true
end

NAgui.plugins = function()
	if NAmanage.PluginsWindow_Toggle then
		return NAmanage.PluginsWindow_Toggle()
	end
	const frame = NAmanage.EnsurePluginsWindow and NAmanage.EnsurePluginsWindow()
	if not frame then
		DoNotif("Plugins UI unavailable.", 3)
		return false
	end
	frame.Visible = not frame.Visible
	return true
end

NAmanage.PluginsWindow_Bind = NAmanage.PluginsWindow_Bind or function()
	const frame = NAmanage.EnsurePluginsWindow and NAmanage.EnsurePluginsWindow()
	if not frame then
		return false
	end
	const wasVisible = frame.Visible == true
	if NAgui and type(NAgui.menu) == "function" and NAStuff.PluginsWindowMenuBound ~= frame then
		NAgui.menu(frame)
		NAStuff.PluginsWindowMenuBound = frame
		frame.Visible = wasVisible
	end
	if NAgui and type(NAgui.resizeable) == "function" and NAStuff.PluginsWindowResizeBound ~= frame then
		NAgui.resizeable(frame, Vector2.new(340, 260), Vector2.new(5000, 5000))
		NAStuff.PluginsWindowResizeBound = frame
	end
	if NAmanage.PluginsScroll and NAmanage.PluginsScroll.install then
		NAmanage.PluginsScroll.install()
	end
	if NAmanage.PluginsHorizontalScroll and NAmanage.PluginsHorizontalScroll.install then
		NAmanage.PluginsHorizontalScroll.install()
	end
	return true
end

NAmanage.PluginsWindow_SetVisible = NAmanage.PluginsWindow_SetVisible or function(visible, opts)
	opts = opts or {}
	const frame = NAmanage.EnsurePluginsWindow and NAmanage.EnsurePluginsWindow()
	if not frame then
		DoNotif("Plugins UI unavailable.", 3)
		return false
	end
	if NAmanage.PluginsWindow_Bind then
		NAmanage.PluginsWindow_Bind()
	end
	visible = visible == true
	NAgui.setWindowVisible(frame, visible)
	if visible then
		if NAmanage.PluginsScroll and NAmanage.PluginsScroll.scheduleRefresh then
			NAmanage.PluginsScroll.scheduleRefresh()
		end
		if NAmanage.PluginsHorizontalScroll and NAmanage.PluginsHorizontalScroll.scheduleRefresh then
			NAmanage.PluginsHorizontalScroll.scheduleRefresh()
		end
		if opts.refresh ~= false and NAmanage.PluginsWindow_RequestRebuild then
			NAmanage.PluginsWindow_RequestRebuild(opts)
		end
		if opts.center ~= false and NAmanage.centerFrame then
			NAmanage.centerFrame(frame)
		end
	end
	return true
end

NAmanage.PluginsWindow_Toggle = NAmanage.PluginsWindow_Toggle or function(forceState, opts)
	const frame = NAmanage.EnsurePluginsWindow and NAmanage.EnsurePluginsWindow()
	if not frame then
		DoNotif("Plugins UI unavailable.", 3)
		return false
	end
	local nextState = forceState
	if type(nextState) ~= "boolean" then
		nextState = not NAgui.isWindowOpen(frame)
	end
	return NAmanage.PluginsWindow_SetVisible(nextState, opts)
end

NAgui._resizeCleanup = NAmanage.ensureWeakTable(NAgui._resizeCleanup, "k")
NAgui.isSettingsLayoutSuspended = NAgui.isSettingsLayoutSuspended or function()
	return NAUIMANAGER
		and NAUIMANAGER.SettingsFrame
		and NAmanage.GetAttr
		and NAmanage.GetAttr(NAUIMANAGER.SettingsFrame, "NAHeavyResizeSuspended") == true
end

NAgui._setHeavyResizeSuspended = NAgui._setHeavyResizeSuspended or function(ui, suspended)
	if not (ui and NAUIMANAGER and ui == NAUIMANAGER.SettingsFrame) then
		return
	end
	const body = ui:FindFirstChild("Container")
	if not (body and body:IsA("GuiObject")) then
		return
	end
	if suspended then
		if NAmanage.GetAttr and NAmanage.GetAttr(ui, "NAResizeBodyWasVisible") == nil then
			NAmanage.SetAttr(ui, "NAResizeBodyWasVisible", body.Visible == true)
		end
		NAmanage.SetAttr(ui, "NAHeavyResizeSuspended", true)
		body.Visible = false
		return
	end
	local wasVisible = true
	if NAmanage.GetAttr then
		const stored = NAmanage.GetAttr(ui, "NAResizeBodyWasVisible")
		if stored ~= nil then
			wasVisible = stored == true
		end
	end
	NAmanage.SetAttr(ui, "NAResizeBodyWasVisible", nil)
	NAmanage.SetAttr(ui, "NAHeavyResizeSuspended", nil)
	if NAmanage.GetAttr and NAmanage.GetAttr(ui, "NAMenuMinimized") == true then
		body.Visible = false
	else
		body.Visible = wasVisible
	end
	if wasVisible and NAUIMANAGER.SettingsList then
		Defer(function()
			if NAUIMANAGER and NAUIMANAGER.SettingsList then
				updateCanvasSize(NAUIMANAGER.SettingsList, NAUIMANAGER.AUTOSCALER and NAUIMANAGER.AUTOSCALER.Scale or nil)
			end
		end)
	end
end

NAgui.resizeable = function(ui, min, max)
	if not ui or not ui:IsA("GuiObject") then return function() end end
	const prevCleanup = NAgui._resizeCleanup[ui]
	if prevCleanup then
		pcall(prevCleanup)
		NAgui._resizeCleanup[ui] = nil
	end
	pcall(function()
		NAmanage.SetAttr(ui, "NAResizeActive", nil)
	end)
	const function getUiScale()
		local s = (NAUIMANAGER and NAUIMANAGER.AUTOSCALER and tonumber(NAUIMANAGER.AUTOSCALER.Scale)) or 1
		if not s or s <= 0 then
			s = 1
		end
		return s
	end
	const function getLogicalSize()
		const size = ui.Size
		local lx = tonumber(size.X.Offset) or 0
		local ly = tonumber(size.Y.Offset) or 0
		if size.X.Scale ~= 0 or size.Y.Scale ~= 0 then
			const s = getUiScale()
			const abs = ui.AbsoluteSize
			if size.X.Scale ~= 0 then
				lx = (abs.X or 0) / s
			end
			if size.Y.Scale ~= 0 then
				ly = (abs.Y or 0) / s
			end
		end
		return Vector2.new(lx, ly)
	end

	if not min then
		const baseMin = getLogicalSize()
		min = Vector2.new(
			math.max(1, math.floor(baseMin.X * 0.5 + 0.5)),
			math.max(1, math.floor(baseMin.Y * 0.5 + 0.5))
		)
	end
	max = max or Vector2.new(5000, 5000)

	const screenGui = ui:FindFirstAncestorWhichIsA("ScreenGui") or ui:FindFirstAncestorWhichIsA("LayerCollector") or ui.Parent
	local mouse
	pcall(function()
		if Services.Players and Services.Players.LocalPlayer then
			mouse = NAmanage.GetMouse(Services.Players.LocalPlayer)
		end
	end)

	const rgui = NAUIMANAGER.resizeFrame and NAUIMANAGER.resizeFrame:Clone()
	if not rgui then return function() end end
	NAmanage.TrackOwnedInstance(rgui)
	rgui.Parent = screenGui
	rgui.BackgroundTransparency = 1
	rgui.ClipsDescendants = false
	NAgui.NAProtection(rgui)

	if NAStuff.ResizeHandleIconsEnabled == true then
		const function resizeIconSpec(name)
			if name == "Left" then return "arrow-medium-left", 0 end
			if name == "Right" then return "arrow-medium-right", 0 end
			if name == "Top" then return "arrow-medium-up", 0 end
			if name == "Bottom" then return "arrow-medium-down", 0 end
			if name == "TopRight" then return "arrow-medium-up", 45 end
			if name == "TopLeft" then return "arrow-medium-up", -45 end
			if name == "BottomLeft" then return "arrow-medium-up", -135 end
			if name == "BottomRight" then return "arrow-medium-up", 135 end
			return nil, 0
		end
		for _, handle in rgui:GetChildren() do
			if handle:IsA("GuiObject") then
				local iconText, rotation = resizeIconSpec(handle.Name)
				if iconText then
					handle.Active = true
					handle.Visible = true
					handle.ClipsDescendants = false
					handle.BackgroundTransparency = 1
					local icon = handle:FindFirstChild("NAResizeHandleIcon")
					if not (icon and icon:IsA("TextLabel")) then
						if icon then
							icon:Destroy()
						end
						icon = InstanceNew("TextLabel", handle)
						icon.Name = "NAResizeHandleIcon"
						icon.BackgroundTransparency = 1
						icon.BorderSizePixel = 0
						icon.Active = false
					end
					icon.AnchorPoint = Vector2.new(0.5, 0.5)
					icon.Position = UDim2.fromScale(0.5, 0.5)
					icon.Size = UDim2.new(0, 28, 0, 28)
					icon.ZIndex = math.max(handle.ZIndex + 1, 121)
					NAmanage.SetIcon(icon, iconText)
					icon.TextColor3 = NAUISTROKER or Color3.fromRGB(148, 93, 255)
					icon.TextTransparency = 0
					icon.TextStrokeTransparency = 0.35
					icon.TextStrokeColor3 = Color3.fromRGB(8, 8, 10)
					icon.TextScaled = false
					icon.TextSize = 22
					icon.Rotation = rotation or 0
					icon.Visible = true
				end
			end
		end
	end

	const function updateOverlay()
		const ok = pcall(function()
			if not ui or not ui.Parent or not rgui or not rgui.Parent or not screenGui then
				return
			end
			const s = getUiScale()
			const absPos = ui.AbsolutePosition
			const absSize = ui.AbsoluteSize
			const rootPos = screenGui.AbsolutePosition or Vector2.new(0, 0)
			const relPos = absPos - rootPos
			rgui.Position = UDim2.new(0, math.floor((relPos.X / s) + 0.5), 0, math.floor((relPos.Y / s) + 0.5))
			rgui.Size = UDim2.new(0, math.floor((absSize.X / s) + 0.5), 0, math.floor((absSize.Y / s) + 0.5))
		end)
		if not ok then end
	end

	const function updateVisibility()
		const ok = pcall(function()
			if not ui or not ui.Parent or not rgui or not rgui.Parent then
				return
			end
			const visible = ui.Visible and NAmanage.GetAttr(ui, "NAMenuMinimized") ~= true
				and NAmanage.GetAttr(ui, "NAMenuTransition") ~= true and NAmanage.GetAttr(ui, "NAMenuMaximized") ~= true
			if rgui.Visible ~= visible then rgui.Visible = visible end
		end)
		if not ok then end
	end

	updateOverlay()
	updateVisibility()

	const overlayConns = {}
	pcall(function()
		Insert(overlayConns, ui:GetPropertyChangedSignal("AbsoluteSize"):Connect(updateOverlay))
	end)
	pcall(function()
		Insert(overlayConns, ui:GetPropertyChangedSignal("AbsolutePosition"):Connect(updateOverlay))
	end)
	pcall(function()
		Insert(overlayConns, ui:GetPropertyChangedSignal("Visible"):Connect(updateVisibility))
		for _, attr in {"NAMenuMinimized", "NAMenuTransition", "NAMenuMaximized"} do
			Insert(overlayConns, ui:GetAttributeChangedSignal(NAmanage.GetSessionAttrKey(attr)):Connect(updateVisibility))
		end
	end)
	pcall(function()
		if NAUIMANAGER and NAUIMANAGER.AUTOSCALER and NAUIMANAGER.AUTOSCALER.GetPropertyChangedSignal then
			Insert(overlayConns, NAUIMANAGER.AUTOSCALER:GetPropertyChangedSignal("Scale"):Connect(updateOverlay))
		end
	end)

	local dragging = false
	local mode
	local UIPos
	local lastSize
	local lastPos = Vector2.new()
	local dragInput
	local dragEndedConn
	local cursorSaved
	local cursorActive = false
	local touchGestureLocked = false
	local lastResizeUpdate = 0
	local updateResize

	const function resizeBlocked()
		return NAmanage.GetAttr(ui, "NAMenuMinimized") == true or NAmanage.GetAttr(ui, "NAMenuTransition") == true
			or NAmanage.GetAttr(ui, "NAMenuMaximized") == true
	end

	const function ensureMouse()
		if mouse then return mouse end
		pcall(function()
			if Services.Players and Services.Players.LocalPlayer then
				mouse = NAmanage.GetMouse(Services.Players.LocalPlayer)
			end
		end)
		return mouse
	end

	const function setCursor(icon)
		if not ensureMouse() then return end
		if not mouse then return end
		if not cursorActive then
			cursorSaved = mouse.Icon
			cursorActive = true
		end
		mouse.Icon = icon or ""
	end

	const function restoreCursor()
		if not mouse then return end
		if cursorActive then
			mouse.Icon = cursorSaved or ""
			cursorSaved = nil
			cursorActive = false
		elseif mouse.Icon ~= "" then
			mouse.Icon = ""
		end
	end

	const function endDrag()
		if dragging and dragInput and dragInput.Position then
			const p = dragInput.Position
			updateResize(Vector2.new(p.X, p.Y), true)
		end
		if touchGestureLocked then
			NAgui.releaseTouchGesture(ui, "resize", dragInput)
			touchGestureLocked = false
		end
		pcall(function()
			if ui then
				NAmanage.SetAttr(ui, "NAResizeActive", nil)
			end
		end)
		dragging = false
		mode = nil
		dragInput = nil
		if dragEndedConn then dragEndedConn:Disconnect() dragEndedConn = nil end
		restoreCursor()
		if NAgui._setHeavyResizeSuspended then
			NAgui._setHeavyResizeSuspended(ui, false)
		end
	end

	updateResize = function(currentPos, force)
		if ui == (NAUIMANAGER and NAUIMANAGER.SettingsFrame) then
			const now = os.clock()
			if force ~= true and now - lastResizeUpdate < 0.033 then
				return
			end
			lastResizeUpdate = now
		end
		local ok, err = pcall(function()
			if resizeBlocked() then return end
			if not dragging or not mode or not screenGui or not screenGui.AbsoluteSize then return end
			const map = resizeXY and resizeXY[mode.Name]
			if not map then return end

			const s = getUiScale()
			const delta = (currentPos - lastPos) / s

			const resizeDelta = Vector2.new(delta.X * map[1].X, delta.Y * map[1].Y)
			local low, high = min, max
			if type(min) == "function" then low, high = min() end
			const newSize = Vector2.new(
				math.clamp(lastSize.X + resizeDelta.X, low.X, high.X),
				math.clamp(lastSize.Y + resizeDelta.Y, low.Y, high.Y)
			)

			ui.Size = UDim2.new(0, newSize.X, 0, newSize.Y)

			local ox = UIPos.X.Offset
			local oy = UIPos.Y.Offset
			if map[1].X < 0 then
				ox = ox + (lastSize.X - newSize.X)
			end
			if map[1].Y < 0 then
				oy = oy + (lastSize.Y - newSize.Y)
			end

			ui.Position = UDim2.new(UIPos.X.Scale, ox, UIPos.Y.Scale, oy)
		end)
		if not ok then warn("Resize update failed:", err) end
	end

	local uisChangedConn, uisEndedConn
	pcall(function()
		uisChangedConn = Services.UserInputService.InputChanged:Connect(function(input)
			pcall(function()
				if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
					if input.UserInputType == Enum.UserInputType.Touch and input ~= dragInput then
						return
					end
					updateResize(Vector2.new(input.Position.X, input.Position.Y))
				end
			end)
		end)
	end)

	pcall(function()
		uisEndedConn = Services.UserInputService.InputEnded:Connect(function(input)
			pcall(function()
				if not dragging then return end
				if input.UserInputType == Enum.UserInputType.MouseButton1 then
					endDrag()
				elseif input.UserInputType == Enum.UserInputType.Touch and input == dragInput then
					endDrag()
				end
			end)
		end)
	end)

	for _, button in rgui:GetChildren() do
		if button:IsA("GuiObject") then
			button.Active = true
			pcall(function()
				Insert(overlayConns, button.InputBegan:Connect(function(input)
					pcall(function()
						if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
							if resizeBlocked() then return end
							if input.UserInputType == Enum.UserInputType.Touch then
								if not (NAgui.tryLockTouchGesture and NAgui.tryLockTouchGesture(ui, "resize", input)) then
									return
								end
								touchGestureLocked = true
							end
							mode = button
							dragging = true
							pcall(function()
								if ui then
									NAmanage.SetAttr(ui, "NAResizeActive", true)
								end
							end)
							if NAgui._setHeavyResizeSuspended then
								NAgui._setHeavyResizeSuspended(ui, true)
							end
							const p = input.Position
							lastPos = Vector2.new(p.X, p.Y)
							lastSize = getLogicalSize()
							UIPos = ui.Position
							dragInput = input
							if dragEndedConn then dragEndedConn:Disconnect() end
							dragEndedConn = input.Changed:Connect(function()
								if input.UserInputState == Enum.UserInputState.End then
									endDrag()
								end
							end)
						end
					end)
				end))
			end)

			pcall(function()
				Insert(overlayConns, button.InputEnded:Connect(function(input)
					pcall(function()
						if not dragging or mode ~= button or input.UserInputState ~= Enum.UserInputState.End then return end
						if input.UserInputType == Enum.UserInputType.MouseButton1 then
							endDrag()
						elseif input.UserInputType == Enum.UserInputType.Touch and input == dragInput then
							endDrag()
						end
					end)
				end))
			end)

			pcall(function()
				Insert(overlayConns, button.MouseEnter:Connect(function()
					pcall(function()
						const map = resizeXY and resizeXY[button.Name]
						if map then setCursor(originalIO.resizeCursors(map[3])) end
					end)
				end))
			end)

			pcall(function()
				Insert(overlayConns, button.MouseLeave:Connect(function()
					pcall(function()
						if not dragging then restoreCursor() end
					end)
				end))
			end)
		end
	end

	local cleaned = false
	local ancestryConn
	pcall(function()
		ancestryConn = ui.AncestryChanged:Connect(function(_, parent)
			if not parent then
				pcall(function()
					if NAgui._resizeCleanup[ui] then
						NAgui._resizeCleanup[ui]()
					end
				end)
			end
		end)
	end)

	const function cleanup()
		if cleaned then return end
		cleaned = true
		NAgui._resizeCleanup[ui] = nil
		pcall(endDrag)
		for _, conn in overlayConns do
			pcall(function() conn:Disconnect() end)
		end
		pcall(function() if ancestryConn then ancestryConn:Disconnect() end end)
		pcall(function() if uisChangedConn then uisChangedConn:Disconnect() end end)
		pcall(function() if uisEndedConn then uisEndedConn:Disconnect() end end)
		pcall(function() if dragEndedConn then dragEndedConn:Disconnect() end end)
		pcall(restoreCursor)
		pcall(function() rgui:Destroy() end)
	end
	NAgui._resizeCleanup[ui] = cleanup
	return cleanup
end
NAmanage.RefreshResizeHandles=function()
	if not (NAgui and type(NAgui.resizeable) == "function" and NAUIMANAGER) then
		return
	end
	local ok, err = pcall(function()
		if NAUIMANAGER.chatLogsFrame then
			NAgui.resizeable(NAUIMANAGER.chatLogsFrame)
		end
		if NAUIMANAGER.NAconsoleFrame then
			NAgui.resizeable(NAUIMANAGER.NAconsoleFrame)
		end
		if NAUIMANAGER.commandsFrame then
			NAgui.resizeable(NAUIMANAGER.commandsFrame, Vector2.new(180, 118), Vector2.new(5000, 5000))
		end
		if NAUIMANAGER.CommandKeybindsFrame then
			NAgui.resizeable(NAUIMANAGER.CommandKeybindsFrame, Vector2.new(460, 320), Vector2.new(1400, 920))
		end
		if NAUIMANAGER.SettingsFrame then
			NAgui.resizeable(NAUIMANAGER.SettingsFrame, NAmanage.GetSettingsResizeMin and NAmanage.GetSettingsResizeMin() or nil, Vector2.new(5000, 5000))
		end
		if NAUIMANAGER.WaypointFrame then
			NAgui.resizeable(NAUIMANAGER.WaypointFrame)
		end
		if NAUIMANAGER.BindersFrame then
			NAgui.resizeable(NAUIMANAGER.BindersFrame)
		end
		if NAUIMANAGER.MusicFrame then
			NAgui.resizeable(NAUIMANAGER.MusicFrame, Vector2.new(380, 280), Vector2.new(1100, 820))
		end
		if NAUIMANAGER.PurchaseFrame then
			const metrics = NAmanage.ExecutorWindowSizing.GetSize(750, 580, { minWidth = 460; minHeight = 360; mobileMinWidth = 280; mobileMinHeight = 280; })
			NAgui.resizeable(NAUIMANAGER.PurchaseFrame, Vector2.new(metrics.minWidth, metrics.minHeight), Vector2.new(1400, 1000))
		end
		if NAUIMANAGER.ScriptHubFrame then
			NAgui.resizeable(NAUIMANAGER.ScriptHubFrame, IsOnMobile and Vector2.new(340, 280) or Vector2.new(560, 360), Vector2.new(5000, 5000))
		end
		if NAUIMANAGER.SubplaceViewerFrame then
			NAgui.resizeable(NAUIMANAGER.SubplaceViewerFrame, IsOnMobile and Vector2.new(340, 280) or Vector2.new(560, 360), Vector2.new(5000, 5000))
		end
		if NAUIMANAGER.ServerListFrame then
			NAgui.resizeable(NAUIMANAGER.ServerListFrame, IsOnMobile and Vector2.new(340, 300) or Vector2.new(620, 420), Vector2.new(5000, 5000))
		end
		if NAUIMANAGER.ExecutorFrame then
			const exMin = IsOnMobile and Vector2.new(340, 280) or Vector2.new(680, 420)
			NAgui.resizeable(NAUIMANAGER.ExecutorFrame, exMin, Vector2.new(5000, 5000))
		end
		if NAUIMANAGER.NotepadFrame then
			const npVp = Services.Workspace.CurrentCamera and Services.Workspace.CurrentCamera.ViewportSize or Vector2.new(1280, 720)
			const npSmall = IsOnMobile or npVp.X < 720 or npVp.Y < 520
			const npMin = npSmall and Vector2.new(280, 230) or Vector2.new(460, 340)
			NAgui.resizeable(NAUIMANAGER.NotepadFrame, npMin, Vector2.new(5000, 5000))
		end
		if NAmanage.PluginsWindow_Bind then
			NAmanage.PluginsWindow_Bind()
		end
	end)
	if not ok then
		warn("RefreshResizeHandles failed:", err)
	end
end
NAmanage.UpdateWaypointList=function()
	const list = NAUIMANAGER.WaypointList
	if not list then
		return
	end
	const rawFilter = NAUIMANAGER.filterBox and NAUIMANAGER.filterBox.Text or ""
	const filterText = rawFilter:lower()
	NAmanage._waypointBuildGen = (tonumber(NAmanage._waypointBuildGen) or 0) + 1
	const buildGen = NAmanage._waypointBuildGen
	local built = 0
	for _, child in list:GetChildren() do
		if not child:IsA("UIListLayout") then
			child:Destroy()
		end
	end
	for name, entry in Waypoints do
		if filterText == "" or name:lower():find(filterText, 1, true) then
			const row = NAUIMANAGER.WPFrame:Clone()
			row.Name = name
			row.Parent = list
			const nameBtn = row:FindFirstChildWhichIsA("TextButton")
			if nameBtn then
				nameBtn.Text = name
			end
			const actionFrame = row:FindFirstChildWhichIsA("Frame")
			if actionFrame then
				const copyBtn = actionFrame:FindFirstChild("CopyBtn")
				const delBtn = actionFrame:FindFirstChild("DelBtn")
				const tpBtn = actionFrame:FindFirstChild("TPBtn")
				const editBtn = actionFrame:FindFirstChild("EditBtn")
				const renameBtn = actionFrame:FindFirstChild("RenameBtn")
				const pathBtn = actionFrame:FindFirstChild("PathBtn")
				if renameBtn then
					MouseButtonFix(renameBtn, function()
						Window({
							Title = "Rename Waypoint",
							Description = "Enter a new name for '"..name.."'.",
							InputField = true,
							Buttons = {
								{
									Text = "Rename",
									Callback = function(input)
										const newName = NAmanage.waypointNameFromArgs(input)
										if not newName or newName == "" then
											return DoNotif("Waypoint name cannot be empty.", 3)
										end
										if newName == name then
											return DebugNotif("Waypoint name unchanged.", 2)
										end
										if Waypoints[newName] then
											return DoNotif(("Waypoint '%s' already exists."):format(newName), 3)
										end
										if not Waypoints[name] then
											return DoNotif(("Waypoint '%s' no longer exists."):format(name), 3)
										end
										Waypoints[newName] = Waypoints[name]
										Waypoints[name] = nil
										const pathState = NAmanage.WaypointPathGetState and NAmanage.WaypointPathGetState()
										local restartLoopPath = false
										if pathState then
											restartLoopPath = pathState.looping == true and pathState.loopTarget == name
											if restartLoopPath and type(NAmanage.WaypointPathStop) == "function" then
												NAmanage.WaypointPathStop(true)
											elseif pathState.followTarget == name then
												pathState.followTarget = newName
											end
											if pathState.lastName == name then
												pathState.lastName = newName
											end
										end
										NAmanage.SaveWaypoints()
										NAmanage.UpdateWaypointList()
										if restartLoopPath and type(NAmanage.WaypointPathLoopStart) == "function" then
											Delay(0, function()
												NAmanage.WaypointPathLoopStart(newName)
											end)
										end
										DebugNotif(("Renamed waypoint '%s' to '%s'."):format(name, newName))
									end
								}
							}
						})
					end)
				end
				if editBtn then
					MouseButtonFix(editBtn, function()
						NAmanage.WaypointOpenCoordinateEditor(name)
					end)
				end
				if pathBtn then
					const pathState = NAmanage.WaypointPathGetState and NAmanage.WaypointPathGetState()
					const followingThis = pathState and pathState.following == true and pathState.followTarget == name
					const loopingThis = pathState and pathState.looping == true and pathState.loopTarget == name
					pathBtn.Text = (followingThis or loopingThis) and "Stop" or "Path"
					pathBtn.BackgroundColor3 = (followingThis or loopingThis) and Color3.fromRGB(185, 55, 55) or Color3.fromRGB(55, 125, 215)
					MouseButtonFix(pathBtn, function()
						if type(NAmanage.WaypointPathToggle) == "function" then
							NAmanage.WaypointPathToggle(name)
						elseif type(NAmanage.WaypointPathFollow) == "function" then
							NAmanage.WaypointPathFollow(name)
						end
					end)
				end
				if copyBtn then
					MouseButtonFix(copyBtn, function()
						const cf = NAmanage.WaypointEntryToCFrame(entry)
						if typeof(cf) ~= "CFrame" then
							return DebugNotif("Waypoint position is invalid", 3)
						end
						const copyText = NAmanage.WaypointFormatCFramePosition(cf)
						if setclipboard then
							pcall(setclipboard, copyText)
							DebugNotif("Copied "..name)
						else
							DebugNotif("Copy not supported")
						end
					end)
				end
				if delBtn then
					MouseButtonFix(delBtn, function()
						const pathState = NAmanage.WaypointPathGetState and NAmanage.WaypointPathGetState()
						if pathState and (pathState.followTarget == name or pathState.loopTarget == name or pathState.lastName == name) and type(NAmanage.WaypointPathStop) == "function" then
							NAmanage.WaypointPathStop(true)
						end
						Waypoints[name] = nil
						NAmanage.SaveWaypoints()
						NAmanage.UpdateWaypointList()
						DebugNotif("Removed '"..name.."'")
					end)
				end
				if tpBtn then
					MouseButtonFix(tpBtn, function()
						const cf = NAmanage.WaypointEntryToCFrame(entry)
						if typeof(cf) ~= "CFrame" then
							return DoNotif(("Waypoint '%s' is invalid."):format(name), 3)
						end
						const char = getChar()
						if char then
							NAmanage.UG_pivotModel(char, cf)
						end
					end)
				end
			end
		end
		built += 1
		if built % 12 == 0 then
			Wait()
			if buildGen ~= NAmanage._waypointBuildGen then
				return
			end
		end
	end
	updateCanvasSize(list, NAUIMANAGER and NAUIMANAGER.AUTOSCALER and NAUIMANAGER.AUTOSCALER.Scale or nil)
end

NAgui.atchSettings = function(row, hoverKey, strength)
	if not (row and row:IsA("GuiObject")) then
		return
	end
	if not (Services.TweenService and NAlib and NAlib.connect and NAlib.disconnect) then
		return
	end

	const key = "NAgui_row_hover:"..tostring(hoverKey or row.Name or "row")
	const baseRowColor = row.BackgroundColor3
	const hoverRowColor = baseRowColor:Lerp(Color3.new(1, 1, 1), strength or 0.08)

	const function tw(color)
		pcall(function()
			NAgui.motion(row, TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				BackgroundColor3 = color
			}):Play()
		end)
	end

	NAlib.disconnect(key)
	NAlib.connect(key, row.MouseEnter:Connect(function()
		tw(hoverRowColor)
	end))
	NAlib.connect(key, row.MouseLeave:Connect(function()
		tw(baseRowColor)
	end))
	NAlib.connect(key, row:GetPropertyChangedSignal("Parent"):Connect(function()
		if not row.Parent then
			Defer(function()
				NAlib.disconnect(key)
			end)
		end
	end))
end

NAgui.SettingsBuildState = NAgui.SettingsBuildState or {
	count = 0;
	lastYield = 0;
	batch = 12;
	budget = 0.004;
	building = false;
	background = false;
	userInteracted = false;
	userSelectedTab = nil;
}

NAgui.SettingsBuildStep = NAgui.SettingsBuildStep or function()
	const settingsTarget = NAgui.getSettingsTarget and select(1, NAgui.getSettingsTarget()) or (NAUIMANAGER and NAUIMANAGER.SettingsList)
	if not settingsTarget then return end
	NAgui.SettingsBuildState = NAgui.SettingsBuildState or {}
	const state = NAgui.SettingsBuildState
	state.count = (tonumber(state.count) or 0) + 1
	state.building = true
	while NAmanage and type(NAmanage.IsSettingsBuildTeleportPaused) == "function" and NAmanage.IsSettingsBuildTeleportPaused() do
		Wait(0.1)
	end

	const now = os.clock()
	local lastYield = tonumber(state.lastYield) or 0
	if lastYield <= 0 then
		state.lastYield = now
		lastYield = now
	end
	if type(NAmanage.StartupWorkStep) == "function" then
		if NAmanage.StartupWorkStep() then
			state.lastYield = os.clock()
			const perf = NAStuff and NAStuff.StartupPerformance
			if type(perf) == "table" and perf.finished ~= true then
				perf.settingsYields = (tonumber(perf.settingsYields) or 0) + 1
			end
		end
		return
	end
	const userActive = state.userInteracted == true
	const lowEnd = IsOnMobile == true or (NAmanage.IsLowEndUI and NAmanage.IsLowEndUI() == true)
	const batch = math.max(2, math.min(math.floor(tonumber(state.batch) or 12), lowEnd and 3 or 6))
	const budget = math.max(0.0005, math.min(tonumber(state.budget) or 0.004, lowEnd and 0.0015 or 0.0025))
	const activeBatch = userActive and math.max(2, math.floor(batch * 0.5)) or batch
	const activeBudget = userActive and math.min(budget, 0.0025) or budget
	if state.count % activeBatch == 0 or (now - lastYield) >= activeBudget then
		Wait()
		state.lastYield = os.clock()
	end
end

NAgui.SettingsBuildDone = NAgui.SettingsBuildDone or function()
	if type(NAgui.SettingsBuildState) ~= "table" then
		return
	end
	if NAgui.setSettingsTabContext then
		NAgui.setSettingsTabContext(nil)
	end
	NAgui.SettingsBuildState.building = false
	NAgui.SettingsBuildState.background = false
	NAgui.SettingsBuildState.lastYield = 0
end

NAmanage.SettingsBuildTeleportPause = NAmanage.SettingsBuildTeleportPause or {
	active = false;
	token = nil;
	started = 0;
	timeout = 30;
	reason = nil;
}

NAmanage.PauseSettingsBuildForTeleport = function(reason)
	const token = tostring(os.clock())..":"..tostring(math.random(1, 1000000))
	const st = NAmanage.SettingsBuildTeleportPause or {}
	st.active = true
	st.token = token
	st.started = tick()
	st.timeout = 30
	st.reason = tostring(reason or "teleport")
	NAmanage.SettingsBuildTeleportPause = st
	NAStuff.SettingsBuildPausedForTeleport = true
	NAStuff.SettingsBuildPauseToken = token
	if NAAssetsLoading and type(NAAssetsLoading.setStatus) == "function" then
		pcall(NAAssetsLoading.setStatus, "rejoining")
	end
	return token
end

NAmanage.ResumeSettingsBuildAfterTeleport = function(token, reason)
	const st = NAmanage.SettingsBuildTeleportPause
	if type(st) ~= "table" then
		return false
	end
	if token and st.token and token ~= st.token then
		return false
	end
	st.active = false
	st.token = nil
	st.started = 0
	st.reason = nil
	NAStuff.SettingsBuildPausedForTeleport = false
	NAStuff.SettingsBuildPauseToken = nil
	if NAStuff.SettingsBuildRunning == true and NAAssetsLoading and type(NAAssetsLoading.setStatus) == "function" then
		pcall(NAAssetsLoading.setStatus, "building settings")
	end
	return true
end

NAmanage.IsSettingsBuildTeleportPaused = function()
	const st = NAmanage.SettingsBuildTeleportPause
	if type(st) ~= "table" or st.active ~= true then
		return false
	end
	const started = tonumber(st.started) or 0
	const timeout = tonumber(st.timeout) or 30
	if started > 0 and timeout > 0 and tick() - started > timeout then
		NAmanage.ResumeSettingsBuildAfterTeleport(st.token, "timeout")
		return false
	end
	return true
end

NAgui.addButton = function(label, callback, opts)
	local settingsList, settingsTabName = NAgui.getSettingsTarget()
	if not settingsList then return end
	if NAgui.SettingsBuildStep then NAgui.SettingsBuildStep("button") end
	const button = templates.Button:Clone()
	const title = button.Title
	const indicator = button:FindFirstChild("ElementIndicator")
	button.Size = UDim2.new(button.Size.X.Scale, button.Size.X.Offset, 0, 42)
	title.Size = UDim2.new(1, indicator and -58 or -30, 1, -4)
	title.TextScaled = false
	title.TextSize = 16
	title.TextTruncate = Enum.TextTruncate.AtEnd
	title.Text = label
	if indicator then
		indicator.Size = UDim2.fromOffset(20, 20)
		indicator.TextScaled = false
		indicator.TextWrapped = false
		indicator.TextSize = 20
		indicator.TextTransparency = 0.2
		indicator.TextXAlignment = Enum.TextXAlignment.Center
		const icon = type(opts) == "table" and type(opts.icon) == "string" and opts.icon
		NAmanage.SetIcon(indicator, icon or "chevron-right", {fallback = icon and opts.fallback or nil})
	end
	if button.Interact:IsA("TextButton") then button.Interact.Text = "" end
	NAmanage.SetSearch.tag(button, label)
	button.Parent = settingsList
	button.LayoutOrder = NAgui._nextLayoutOrder(settingsTabName)
	NAmanage.registerElementForCurrentTab(button, settingsTabName)
	if NAgui.RegisterStrokesFrom then
		NAgui.RegisterStrokesFromAsync(button)
	end
	NAgui.atchSettings(button, "button:"..tostring(label)..":"..tostring(button.LayoutOrder), 0.08)

	MouseButtonFix(button.Interact,function()
		pcall(callback)
	end)
	return button
end

NAgui.addSection = function(titleText)
	local settingsList, settingsTabName = NAgui.getSettingsTarget()
	if not settingsList then return end
	if type(NAgui.SettingsBuildState) == "table" and NAgui.SettingsBuildState.background == true then
		NAmanage.MarkExternalLagProbe("settings_section:"..tostring(settingsTabName or "?")..":"..tostring(titleText or ""))
	end
	if NAgui.SettingsBuildStep then NAgui.SettingsBuildStep("section") end
	const section = templates.SectionTitle:Clone()
	const tab = TabManager.tabs[settingsTabName]
	local icon = tab and tab.textIcon
	if type(icon) == "table" then icon = icon.icon or icon.name or icon[1] end
	NAmanage.SetIcon(section.Title, icon or "layers", {text = titleText})
	pcall(function()
		NAmanage.SetAttr(section, "NASettingsSection", true)
	end)
	NAmanage.SetSearch.tag(section, titleText)
	section.Parent = settingsList
	section.LayoutOrder = NAgui._nextLayoutOrder(settingsTabName)
	NAmanage.registerElementForCurrentTab(section, settingsTabName)
	if NAgui.RegisterStrokesFrom then
		NAgui.RegisterStrokesFromAsync(section)
	end
end

NAgui.getInputMinWidth=function(frame, fallback)
	fallback = fallback or 32
	if not (frame and frame.GetAttribute) then
		return fallback
	end
	local ok, attr = pcall(function()
		return NAmanage.GetAttr(frame, "NAMinWidth")
	end)
	const minAttr = tonumber(ok and attr or nil)
	if not minAttr then
		return fallback
	end
	return math.max(fallback, minAttr)
end

NAgui.getInputMeasureText=function(box)
	if not box then
		return ""
	end

	local text = tostring(box.Text or "")
	local okContent, contentText = pcall(function()
		return box.ContentText
	end)
	if okContent and type(contentText) == "string" and contentText ~= "" then
		local focused = false
		local okFocused, isFocused = pcall(function()
			return box:IsFocused()
		end)
		if okFocused and isFocused == true then
			focused = true
		end
		if focused or text == "" then
			text = contentText
		end
	end

	return text
end

NAgui.getInputTextWidth=function(box, padding)
	padding = padding or 24
	if not box then
		return padding
	end
	const measureText = NAgui.getInputMeasureText(box)

	if (box.TextScaled or box.TextWrapped) and Services.TextService then
		local okScaled, sizeScaled = pcall(function()
			const fontSize = tonumber(box.TextSize) or 14
			local font = box.Font
			if font == nil or font == Enum.Font.Unknown then font = Enum.Font.SourceSans end
			return __lt.cm("TextService", "GetTextSize", measureText, fontSize, font, Vector2.new(1e6, 1e6))
		end)
		if okScaled and sizeScaled and type(sizeScaled.X) == "number" then
			return sizeScaled.X + padding
		end
	end

	local okBounds, bounds = pcall(function()
		return box.TextBounds
	end)
	if okBounds and bounds and type(bounds.X) == "number" then
		return bounds.X + padding
	end

	if Services.TextService then
		local okSize, size = pcall(function()
			return __lt.cm("TextService", "GetTextSize", measureText, box.TextSize or 14, box.Font or Enum.Font.SourceSans, Vector2.new(1e4, 1e3))
		end)
		if okSize and size and type(size.X) == "number" then
			return size.X + padding
		end
	end

	return 56
end

NAgui.addInfo = function(label, value, opts)
	local settingsList, settingsTabName = NAgui.getSettingsTarget()
	if not settingsList then return nil end
	if NAgui.SettingsBuildStep then NAgui.SettingsBuildStep("info") end
	opts = type(opts) == "table" and opts or {}
	NAgui._infoConnCounter = (NAgui._infoConnCounter or 0) + 1
	const connKey = "NAgui_info:"..tostring(NAgui._infoConnCounter)

	const info = templates.Input:Clone()
	info.Name = "Info"
	info.Title.Text = label
	NAmanage.SetSearch.tag(info, label)

	info.LayoutOrder = NAgui._nextLayoutOrder(settingsTabName)
	info.Parent = settingsList
	NAmanage.registerElementForCurrentTab(info, settingsTabName)
	if NAgui.RegisterStrokesFrom then
		NAgui.RegisterStrokesFromAsync(info)
	end
	NAgui.atchSettings(info, "info:"..tostring(label)..":"..tostring(info.LayoutOrder), 0.06)

	const frame = info.InputFrame
	if not frame then
		return nil
	end

	const box = frame.InputBox
	if not box then
		return nil
	end

	box.Text = value or ""
	box.PlaceholderText = ""
	box.ClearTextOnFocus = false
	pcall(function()
		box.TextEditable = false
	end)
	pcall(function()
		box.Interactable = false
	end)
	box.Active = false
	box.Selectable = false

	local sideChip, sideBtn
	local sideChipWidth = 0
	if opts.sideChip then
		const tgl = templates.Toggle:Clone()
		const sw = tgl:FindFirstChild("Switch")
		if sw then
			sideChip = sw:Clone()
			sideChip.Name = "SideButton"
			sideChip.Parent = info
			tgl:Destroy()

			sideChipWidth = sideChip.Size.X.Offset
			if sideChipWidth <= 0 then
				sideChipWidth = 45
			end

			local sideChipHeight = sideChip.Size.Y.Offset
			if sideChipHeight <= 0 then
				sideChipHeight = 22
			end

			sideChip.AnchorPoint = Vector2.new(1, 0.5)
			sideChip.Position = UDim2.new(1, -15, 0.5, 0)
			sideChip.Size = UDim2.new(0, sideChipWidth, 0, sideChipHeight)

			frame.AnchorPoint = Vector2.new(1, 0.5)
			frame.Position = UDim2.new(1, -15 - sideChipWidth - 6, 0.5, 0)

			const chipInd = sideChip:FindFirstChild("Indicator")
			if chipInd then
				chipInd.Visible = false
			end

			sideBtn = InstanceNew("TextButton")
			sideBtn.Name = "ChipInteract"
			sideBtn.BackgroundTransparency = 1
			sideBtn.Text = tostring(opts.sideText or "Copy")
			sideBtn.TextColor3 = Color3.new(1, 1, 1)
			sideBtn.TextSize = 12
			sideBtn.Font = Enum.Font.GothamSemibold
			sideBtn.AutoButtonColor = false
			sideBtn.Size = UDim2.new(1, 0, 1, 0)
			sideBtn.ZIndex = (sideChip.ZIndex or 1) + 1
			sideBtn.Parent = sideChip

			NAgui.deferSettingsWork(function()
				if not sideChip.Parent then
					return
				end
				for _, d in NAmanage.QueryDescendants(sideChip, "GuiObject") do
					d.ZIndex = math.max(d.ZIndex or 1, sideBtn.ZIndex or 1)
				end
			end)

			local sideBusy = false
			MouseButtonFix(sideBtn, function()
				if sideBusy then
					return
				end
				sideBusy = true

				const oldText = sideBtn.Text
				local ok, result = true, true

				if type(opts.sideClick) == "function" then
					ok, result = pcall(opts.sideClick, box, info, sideBtn)
				elseif type(opts.sideSet) == "function" then
					ok, result = pcall(opts.sideSet, box.Text, box, info, sideBtn)
				end

				if ok and result ~= false then
					sideBtn.Text = tostring(opts.sideDoneText or "Copied")
					Delay(0.7, function()
						if sideBtn and sideBtn.Parent then
							sideBtn.Text = oldText
						end
						sideBusy = false
					end)
				else
					sideBusy = false
				end
			end)
		else
			tgl:Destroy()
		end
	end

	box.TextXAlignment = Enum.TextXAlignment.Center
	box.TextWrapped = opts.textWrapped ~= false
	box.MultiLine = box.TextWrapped
	if box.TextWrapped then
		box.Size = UDim2.new(box.Size.X.Scale, box.Size.X.Offset, 1, -8)
	end
	box.TextYAlignment = opts.textYAlignment == "Top" and Enum.TextYAlignment.Top or Enum.TextYAlignment.Center
	box.TextTruncate = Enum.TextTruncate.None
	const textScaledEnabled = opts.textScaled == true
	box.TextScaled = textScaledEnabled
	box.ClipsDescendants = true
	frame.ClipsDescendants = true
	const inputHeight = math.max(24, math.floor(tonumber(opts.inputHeight) or frame.Size.Y.Offset))
	const rowHeight = math.max(32, math.floor(tonumber(opts.rowHeight) or info.Size.Y.Offset))
	const fillWidth = opts.fillWidth == true
	const autoHeight = opts.autoHeight ~= false
	const minInputHeight = math.max(24, math.floor(tonumber(opts.minInputHeight) or inputHeight))
	const maxInputHeight = math.max(minInputHeight, math.floor(tonumber(opts.maxInputHeight) or math.huge))
	if autoHeight then
		frame.Size = UDim2.new(frame.Size.X.Scale, frame.Size.X.Offset, 0, inputHeight)
		info.Size = UDim2.new(info.Size.X.Scale, info.Size.X.Offset, 0, math.max(rowHeight, inputHeight + 8))
	elseif opts.rowHeight ~= nil then
		info.Size = UDim2.new(info.Size.X.Scale, info.Size.X.Offset, 0, rowHeight)
	end
	const baseTextSize = tonumber(opts.textSize) or tonumber(box.TextSize) or 14
	local minTextSize = tonumber(opts.minTextSize) or 10
	if minTextSize > baseTextSize then
		minTextSize = baseTextSize
	end
	const clampAlignLeft = opts.clampAlignLeft ~= false
	const autoShrink = opts.autoShrink ~= false

	local lastW
	local lastH
	local resizeBusy = false
	local resizeQueued = false
	local resizePending = false
	local resize
	local requestResize
	opts._naResizeRunToken = NAmanage and NAmanage._runToken

	requestResize = function()
		if type(NAmanage) == "table" and type(NAmanage.IsActiveRun) == "function" and not NAmanage.IsActiveRun(opts._naResizeRunToken) then
			return
		end
		if resizeBusy then
			resizePending = true
			return
		end
		if resizeQueued then
			return
		end
		resizeQueued = true
		Delay(0.03, function()
			resizeQueued = false
			if type(NAmanage) == "table" and type(NAmanage.IsActiveRun) == "function" and not NAmanage.IsActiveRun(opts._naResizeRunToken) then
				return
			end
			if resize and info and info.Parent then
				resize()
			end
		end)
	end

	const function finishResize()
		resizeBusy = false
		if resizePending then
			resizePending = false
			requestResize()
		end
	end

	resize = function()
		if type(NAmanage) == "table" and type(NAmanage.IsActiveRun) == "function" and not NAmanage.IsActiveRun(opts._naResizeRunToken) then
			return
		end
		if resizeBusy then
			resizePending = true
			return
		end
		if type(NAgui.isSettingsLayoutSuspended) == "function" and NAgui.isSettingsLayoutSuspended() then
			resizePending = true
			Delay(0.08, function()
				if info and info.Parent then
					requestResize()
				end
			end)
			return
		end
		if not (info and info.Parent and frame and frame.Parent and box and box.Parent) then
			return
		end

		resizeBusy = true

		const textW = type(NAgui.getInputTextWidth) == "function" and NAgui.getInputTextWidth(box) or 56
		const minW = type(NAgui.getInputMinWidth) == "function" and NAgui.getInputMinWidth(frame) or 56
		local maxW

		local cw = NAmanage.GetLogicalAbsoluteSize(info).X
		if (not cw or cw <= 0) and info.Parent then
			cw = NAmanage.GetLogicalAbsoluteSize(info.Parent).X
		end
		if (not cw or cw <= 0) and settingsList then
			cw = NAmanage.GetLogicalAbsoluteSize(settingsList).X
		end

		if cw and cw > 0 then
			const scale = info.AbsoluteSize.X > 0 and cw / info.AbsoluteSize.X or 1
			const tw = (info.Title and info.Title.TextBounds.X or 0) * scale
			local gap = 32
			if sideChip then
				local extra = sideChipWidth
				if extra <= 0 then
					extra = 45
				end
				gap = gap + extra + 6
			end
			maxW = cw - tw - gap
		end

		local w = math.max(textW, minW)
		local hit = false
		if maxW then
			if fillWidth then
				w = math.max(minW, maxW)
				hit = true
			else
				const clamped = math.max(minW, math.min(w, maxW))
				hit = clamped >= (maxW - 0.5)
				w = clamped
			end
		end

		const targetAlignment = ((fillWidth or hit) and clampAlignLeft) and Enum.TextXAlignment.Left or Enum.TextXAlignment.Center
		if box.TextXAlignment ~= targetAlignment then
			box.TextXAlignment = targetAlignment
		end

		if not textScaledEnabled then
			local targetTextSize = baseTextSize
			if hit and autoShrink and not box.TextWrapped then
				const avail = math.max(1, w - 14)
				const rawWidth = math.max(1, NAgui.getInputTextWidth(box, 0))
				if rawWidth > avail then
					targetTextSize = math.max(minTextSize, math.floor(baseTextSize * (avail / rawWidth)))
				end
			end
			if box.TextSize ~= targetTextSize then
				box.TextSize = targetTextSize
			end
		end

		if type(w) ~= "number" then
			finishResize()
			return
		end

		local targetInputHeight = inputHeight
		if autoHeight and box.TextWrapped then
			local measuredHeight = baseTextSize
			const textService = Services.TextService
			if textService then
				local font = box.Font
				if font == nil or font == Enum.Font.Unknown then
					font = Enum.Font.SourceSans
				end
				local okMeasure, measured = pcall(textService.GetTextSize, textService, tostring(box.Text or ""), tonumber(box.TextSize) or baseTextSize, font, Vector2.new(math.max(1, w - 16), 10000))
				if okMeasure and measured then
					measuredHeight = measured.Y
				end
			end
			targetInputHeight = math.clamp(math.ceil(measuredHeight + 8), minInputHeight, maxInputHeight)
			const targetRowHeight = math.max(rowHeight, targetInputHeight + 8)
			const targetInfoSize = UDim2.new(info.Size.X.Scale, info.Size.X.Offset, 0, targetRowHeight)
			if info.Size ~= targetInfoSize then
				info.Size = targetInfoSize
			end
		end

		if not lastW or not lastH or math.abs(lastW - w) > 0.5 or math.abs(lastH - targetInputHeight) > 0.5 then
			lastW = w
			lastH = targetInputHeight
			const targetSize = UDim2.new(0, w, 0, targetInputHeight)
			if frame.Size ~= targetSize then
				frame.Size = targetSize
			end
			if sideChip then
				const targetChipPosition = UDim2.new(1, -15, 0.5, 0)
				const targetFramePosition = UDim2.new(1, -15 - sideChipWidth - 6, 0.5, 0)
				if sideChip.Position ~= targetChipPosition then
					sideChip.Position = targetChipPosition
				end
				if frame.Position ~= targetFramePosition then
					frame.Position = targetFramePosition
				end
			end
		end

		finishResize()
	end

	NAlib.connect(connKey, box:GetPropertyChangedSignal("TextBounds"):Connect(requestResize))
	NAlib.connect(connKey, box:GetPropertyChangedSignal("Text"):Connect(requestResize))
	NAlib.connect(connKey, info:GetPropertyChangedSignal("AbsoluteSize"):Connect(requestResize))
	NAlib.connect(connKey, frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(requestResize))
	if settingsList and settingsList:IsA("GuiObject") then
		NAlib.connect(connKey, settingsList:GetPropertyChangedSignal("AbsoluteSize"):Connect(requestResize))
		NAlib.connect(connKey, settingsList:GetPropertyChangedSignal("Visible"):Connect(requestResize))
	end
	NAlib.connect(connKey, info.Destroying:Connect(function()
		NAlib.disconnect(connKey)
	end))
	resize()
	Defer(function() requestResize() end)
	Delay(0.12, function() requestResize() end)
	Delay(0.35, function() requestResize() end)

	const interact = frame:FindFirstChild("Interact")
	if interact then
		interact.Visible = false
	end

	return box, info
end

NAgui._toggleRegistry = NAgui._toggleRegistry or {}
NAgui._colorPickerRegistry = NAgui._colorPickerRegistry or {}
NAgui._sliderRegistry = NAgui._sliderRegistry or {}
NAgui._inputRegistry = NAgui._inputRegistry or {}
NAgui._dropdownRegistry = NAgui._dropdownRegistry or {}
NAgui._keybindRegistry = NAgui._keybindRegistry or {}

NAgui.addToggle = function(lbl, def, cb, opt)
	local settingsList, settingsTabName = NAgui.getSettingsTarget()
	if not settingsList then return end
	if NAgui.SettingsBuildStep then NAgui.SettingsBuildStep("toggle") end
	opt = opt or {}
	cb = type(cb) == "function" and cb or function() end

	const tgl = templates.Toggle:Clone()
	const sw = tgl:FindFirstChild("Switch")
	const ind = sw and sw:FindFirstChild("Indicator")
	const st = ind and ind:FindFirstChildWhichIsA("UIStroke")
	const swStroke = sw and sw:FindFirstChildWhichIsA("UIStroke")
	const rowStroke = tgl:FindFirstChild("UIStroke")
	const title = tgl:FindFirstChild("Title")

	if sw then
		pcall(function() sw.Active = false end)
		pcall(function() sw.Selectable = false end)
	end

	local it = tgl:FindFirstChild("Interact")
	if it then
		it:Destroy()
	end

	it = InstanceNew("ImageButton")
	it.Name = "Interact"
	it.BackgroundTransparency = 1
	it.ImageTransparency = 1
	it.AutoButtonColor = false
	it.Active = true
	it.Selectable = false
	it.ZIndex = 999999
	it.AnchorPoint = Vector2.new(1, 0.5)
	it.Position = UDim2.new(1, -15, 0.5, 0)
	it.Size = UDim2.new(0, 45, 0, 22)
	it.Parent = tgl

	local cbtn
	if opt.sideChip and sw then
		const chip = sw:Clone()
		chip.Name = "SideSwitch"
		chip.Parent = tgl

		local w = sw.Size.X.Offset
		if w <= 0 then w = 45 end

		sw.AnchorPoint = Vector2.new(1, 0.5)
		sw.Position = UDim2.new(1, -15, 0.5, 0)

		chip.AnchorPoint = Vector2.new(1, 0.5)
		chip.Position = UDim2.new(1, -15 - w - 6, 0.5, 0)
		chip.Size = UDim2.new(0, w, 0, sw.Size.Y.Offset)

		it.AnchorPoint = Vector2.new(1, 0.5)
		it.Position = UDim2.new(1, -15, 0.5, 0)
		it.Size = UDim2.new(0, 45, 0, 22)

		const cind = chip:FindFirstChild("Indicator")
		const cst = chip:FindFirstChildWhichIsA("UIStroke", true)
		local con = false

		const function cupd()
			if cind then
				const onx = chip.AbsoluteSize.X - cind.AbsoluteSize.X - 4
				const offx = 2
				const toPos = UDim2.new(0, con and onx or offx, 0.5, 0)
				pcall(function()
					NAgui.motion(cind, TweenInfo.new(0.35, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
						Position = toPos
					}):Play()
				end)
				cind.Visible = false
			end
			if cst then
				pcall(function()
					NAgui.motion(cst, TweenInfo.new(0.24, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
						Color = con and Color3.fromRGB(155, 100, 255) or Color3.fromRGB(72, 72, 72)
					}):Play()
				end)
			end
		end

		if type(opt.sideGet) == "function" then
			local ok, v = pcall(opt.sideGet)
			if ok then con = v and true or false end
		end
		cupd()

		cbtn = InstanceNew("TextButton")
		cbtn.Name = "ChipInteract"
		cbtn.BackgroundTransparency = 1
		cbtn.Text = "Use"
		cbtn.TextColor3 = Color3.new(1, 1, 1)
		cbtn.AutoButtonColor = false
		cbtn.Size = UDim2.new(1, 0, 1, 0)
		cbtn.Parent = chip

		chip.ZIndex = it.ZIndex + 1
		NAgui.deferSettingsWork(function()
			if not chip.Parent then
				return
			end
			for _, d in NAmanage.QueryDescendants(chip, "GuiObject") do
				d.ZIndex = it.ZIndex + 2
			end
		end)
		cbtn.ZIndex = it.ZIndex + 3

		MouseButtonFix(cbtn, function()
			con = not con
			cupd()
			if type(opt.sideSet) == "function" then
				pcall(opt.sideSet, con)
			end
		end)
	end

	tgl.Title.Text = lbl
	NAmanage.SetSearch.tag(tgl, lbl)
	tgl.Parent = settingsList
	tgl.ZIndex = 1
	NAgui.deferSettingsWork(function()
		if not tgl.Parent then
			return
		end
		for _, d in NAmanage.QueryDescendants(tgl, "GuiObject") do
			d.ZIndex = d == it and 999999 or d.ZIndex
		end
	end)
	tgl.LayoutOrder = NAgui._nextLayoutOrder(settingsTabName)
	NAmanage.registerElementForCurrentTab(tgl, settingsTabName)

	const baseRowColor = tgl.BackgroundColor3
	const hoverRowColor = baseRowColor:Lerp(Color3.new(1, 1, 1), 0.08)
	local on = def and true or false
	local busy = false

	const function tw(obj, info, goal)
		if not obj then return nil end
		local ok, tween = pcall(function()
			return NAgui.motion(obj, info, goal)
		end)
		if ok and tween then
			tween:Play()
			return tween
		end
		return nil
	end

	const function animateRowHover(show)
		const rowColor = show and hoverRowColor or baseRowColor
		tw(tgl, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
			BackgroundColor3 = rowColor
		})
	end

	const function applyToggleVisual(state, opts2)
		opts2 = opts2 or {}
		const animate = opts2.animate ~= false
		const pulse = opts2.pulse == true

		if not ind then
			return
		end

		const onPos = UDim2.new(1, -20, 0.5, 0)
		const offPos = UDim2.new(1, -40, 0.5, 0)
		const toPos = state and onPos or offPos
		const toColor = state and Color3.fromRGB(60, 200, 80) or Color3.fromRGB(111, 111, 121)
		const toStroke = state and Color3.fromRGB(50, 255, 80) or Color3.fromRGB(80, 80, 80)
		const toOuterStroke = state and Color3.fromRGB(84, 208, 102) or Color3.fromRGB(72, 72, 72)

		if animate then
			animateRowHover(true)
			if rowStroke then
				tw(rowStroke, TweenInfo.new(0.24, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
					Transparency = 1
				})
			end
			tw(ind, TweenInfo.new(state and 0.24 or 0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				Position = toPos
			})
			tw(ind, TweenInfo.new(0.26, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				BackgroundColor3 = toColor
			})
			if st then
				tw(st, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
					Color = toStroke
				})
			end
			if swStroke then
				tw(swStroke, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
					Color = toOuterStroke
				})
			end
			if pulse then
				const mini = UDim2.new(0, 12, 0, 12)
				const resetSize = UDim2.new(0, 17, 0, 17)
				const down = tw(ind, TweenInfo.new(0.15, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Size = mini })
				if down then
					pcall(function()
						down.Completed:Once(function(state)
							if state ~= Enum.PlaybackState.Completed then return end
							tw(ind, TweenInfo.new(0.22, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Size = resetSize })
						end)
					end)
				else
					ind.Size = resetSize
				end
			end
			Delay(0.05, function()
				animateRowHover(false)
				if rowStroke then
					tw(rowStroke, TweenInfo.new(0.24, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
						Transparency = 0
					})
				end
			end)
		else
			ind.Position = toPos
			ind.BackgroundColor3 = toColor
			if st then st.Color = toStroke end
			if swStroke then swStroke.Color = toOuterStroke end
		end
	end

	const function flashToggleError(message)
		tw(tgl, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
			BackgroundColor3 = Color3.fromRGB(85, 0, 0)
		})
		if rowStroke then
			tw(rowStroke, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				Transparency = 1
			})
		end
		const prevTitle = title and title.Text or nil
		if title then
			title.Text = "Callback Error"
		end
		warn("[NA] Toggle callback error ("..tostring(lbl).."): "..tostring(message))
		Delay(0.5, function()
			if not tgl.Parent then
				return
			end
			if title and prevTitle ~= nil then
				title.Text = prevTitle
			end
			tw(tgl, TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				BackgroundColor3 = baseRowColor
			})
			if rowStroke then
				tw(rowStroke, TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
					Transparency = 0
				})
			end
		end)
	end

	const function set(v, o)
		o = o or {}
		const want = v and true or false
		if not o.force and on == want then
			if o.fire then
				local ok, err = pcall(cb, on)
				if not ok then
					flashToggleError(err)
				end
			end
			return
		end
		on = want
		applyToggleVisual(on, {
			animate = o.animate ~= false,
			pulse = o.pulse == true
		})
		if o.fire ~= false then
			local ok, err = pcall(cb, on)
			if not ok then
				flashToggleError(err)
			end
		end
	end

	if rowStroke then
		rowStroke.Transparency = 1
		tw(rowStroke, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Transparency = 0 })
	end
	if title then
		title.TextTransparency = 1
		tw(title, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { TextTransparency = 0 })
	end
	tgl.BackgroundTransparency = 1
	tw(tgl, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { BackgroundTransparency = 0 })

	set(on, { force = true, fire = false, animate = false, pulse = false })

	NAlib.connect("NAgui_toggle_hover:"..tostring(lbl)..":"..tostring(tgl.LayoutOrder), tgl.MouseEnter:Connect(function()
		animateRowHover(true)
	end))
	NAlib.connect("NAgui_toggle_hover:"..tostring(lbl)..":"..tostring(tgl.LayoutOrder), tgl.MouseLeave:Connect(function()
		animateRowHover(false)
	end))

	const function clk()
		if busy then return end
		busy = true
		set(not on, { force = true, fire = true, animate = true, pulse = true })
		Defer(function()
			busy = false
		end)
	end

	MouseButtonFix(it, clk)

	const ent = {
		button = tgl;
		get = function() return on end;
		set = function(v, o)
			o = o or {}
			if o.force == nil then o.force = true end
			if o.animate == nil then o.animate = true end
			set(v, o)
		end;
	}
	NAgui._toggleRegistry[lbl] = ent

	tgl:GetPropertyChangedSignal("Parent"):Connect(function()
		if not tgl.Parent and NAgui._toggleRegistry[lbl] == ent then
			NAgui._toggleRegistry[lbl] = nil
		end
	end)

	return tgl
end

NAgui.setToggleState = function(label, value, opts)
	const entry = NAgui._toggleRegistry and NAgui._toggleRegistry[label]
	if not entry then return end
	entry.set(value, opts)
end

NAgui.addColorPicker = function(label, defaultColor, callback, opts)
	local settingsList, settingsTabName = NAgui.getSettingsTarget()
	if not settingsList then return end
	if NAgui.SettingsBuildStep then NAgui.SettingsBuildStep("color") end
	callback = type(callback) == "function" and callback or function() end

	const cfg = opts or {}

	const picker = templates.ColorPicker:Clone()
	picker.Title.Text = label
	NAmanage.SetSearch.tag(picker, label)
	picker.Parent = settingsList
	picker.LayoutOrder = NAgui._nextLayoutOrder(settingsTabName)
	NAmanage.registerElementForCurrentTab(picker, settingsTabName)

	const bg = picker.CPBackground
	const disp = bg.Display
	const main = bg.MainCP
	const valueShade = main:FindFirstChild("ValueShade")
	const sl = picker.ColorSlider
	const rgb = picker.RGB
	const hex = picker.HexInput
	const rowStroke = picker:FindFirstChild("UIStroke")
	const title = picker:FindFirstChild("Title")
	local interact = picker:FindFirstChild("Interact")
	const baseRowColor = picker.BackgroundColor3
	const hoverRowColor = baseRowColor:Lerp(Color3.new(1, 1, 1), 0.08)
	local opened = false

	local rgbTog = picker:FindFirstChild("RGBToggle")
	local rgbBtn, rgbSw, rgbDot, rgbTit

	if rgbTog and rgbTog:IsA("GuiObject") then
		rgbBtn = rgbTog:FindFirstChild("Interact")
		rgbSw = rgbTog:FindFirstChild("Switch")
		if rgbSw then
			rgbDot = rgbSw:FindFirstChild("Indicator")
		end
		rgbTit = rgbTog:FindFirstChild("Title")
	end

	if not (rgbTog and rgbBtn and rgbSw and rgbDot and rgbTit) then
		rgbTog, rgbBtn, rgbSw, rgbDot, rgbTit = NAgui.MakeSwitchRow(picker, "RGBToggle", "RGB Cycle")
	end

	if not (interact and interact:IsA("GuiButton")) then
		interact = InstanceNew("TextButton")
		interact.Name = "Interact"
		interact.BackgroundTransparency = 1
		interact.BorderSizePixel = 0
		interact.Text = ""
		interact.AutoButtonColor = false
		interact.AnchorPoint = Vector2.new(0.5, 0.5)
		interact.Position = UDim2.new(0.5, 0, 0.5, 0)
		interact.Size = UDim2.new(1, 0, 1, 0)
		interact.Parent = picker
	end

	const function tw(obj, info, goal)
		if not obj then return nil end
		local ok, tween = pcall(function()
			return NAgui.motion(obj, info, goal)
		end)
		if ok and tween then
			tween:Play()
			return tween
		end
		return nil
	end

	const function flashColorPickerError(message)
		tw(picker, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
			BackgroundColor3 = Color3.fromRGB(85, 0, 0)
		})
		if rowStroke then
			tw(rowStroke, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				Transparency = 1
			})
		end
		const prevTitle = title and title.Text or nil
		if title then
			title.Text = "Callback Error"
		end
		warn("[NA] ColorPicker callback error ("..tostring(label).."): "..tostring(message))
		Delay(0.5, function()
			if not picker.Parent then
				return
			end
			if title and prevTitle ~= nil then
				title.Text = prevTitle
			end
			tw(picker, TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				BackgroundColor3 = baseRowColor
			})
			if rowStroke then
				tw(rowStroke, TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
					Transparency = 0
				})
			end
		end)
	end

	const function runColorCallback(col, optPack)
		local ok, err = pcall(callback, col, optPack)
		if not ok then
			flashColorPickerError(err)
		end
	end

	const function getSaved()
		if type(label) ~= "string" then return nil end
		if not (NAmanage and type(NAmanage.NASettingsGet) == "function") then return nil end
		const st = NAmanage.NASettingsGet("colorPickerAutoRGB")
		if type(st) ~= "table" then return nil end
		const v = st[label]
		if type(v) == "boolean" then return v end
		return nil
	end

	const function saveState(sta)
		if type(label) ~= "string" then return end
		if not (NAmanage and type(NAmanage.NASettingsGet) == "function" and type(NAmanage.NASettingsSet) == "function") then return end
		local st = NAmanage.NASettingsGet("colorPickerAutoRGB")
		if type(st) ~= "table" then st = {} end
		const nxt = {}
		for k,v in st do nxt[k] = v end
		nxt[label] = sta and true or false
		NAmanage.NASettingsSet("colorPickerAutoRGB", nxt)
	end

	rgbTit = rgbTog:FindFirstChild("Title")

	rgbBtn = rgbTog:FindFirstChild("Interact")
	if not (rgbBtn and rgbBtn:IsA("GuiButton")) then
		rgbBtn = InstanceNew("TextButton")
		rgbBtn.Name = "Interact"
		rgbBtn.BackgroundTransparency = 1
		rgbBtn.AutoButtonColor = false
		rgbBtn.BorderSizePixel = 0
		rgbBtn.Text = ""
		rgbBtn.Size = UDim2.new(1, 0, 1, 0)
		rgbBtn.ZIndex = (rgbTog.ZIndex or 1) + 1
		rgbBtn.Parent = rgbTog
	end

	rgbSw = rgbTog:FindFirstChild("Switch")
	if not (rgbSw and rgbSw:IsA("GuiObject")) then
		rgbSw = InstanceNew("Frame")
		rgbSw.Name = "Switch"
		rgbSw.BorderSizePixel = 0
		rgbSw.AnchorPoint = Vector2.new(1, 0.5)
		rgbSw.Position = UDim2.new(1, -12, 0.5, 0)
		rgbSw.Size = UDim2.new(0, 45, 0, 22)
		rgbSw.BackgroundColor3 = Color3.fromRGB(49, 49, 54)
		rgbSw.Parent = rgbTog

		const c = InstanceNew("UICorner")
		c.CornerRadius = UDim.new(0, 6)
		c.Parent = rgbSw

		const st = InstanceNew("UIStroke")
		st.Color = Color3.fromRGB(71, 71, 71)
		st.Parent = rgbSw
	end

	rgbDot = rgbSw:FindFirstChild("Indicator")
	if not (rgbDot and rgbDot:IsA("GuiObject")) then
		rgbDot = InstanceNew("Frame")
		rgbDot.Name = "Indicator"
		rgbDot.BorderSizePixel = 0
		rgbDot.AnchorPoint = Vector2.new(0, 0.5)
		rgbDot.Position = UDim2.new(0, 2, 0.5, 0)
		rgbDot.Size = UDim2.new(0, 18, 0, 18)
		rgbDot.BackgroundColor3 = Color3.fromRGB(114, 114, 124)
		rgbDot.Parent = rgbSw

		const c = InstanceNew("UICorner")
		c.CornerRadius = UDim.new(0, 6)
		c.Parent = rgbDot

		const st = InstanceNew("UIStroke")
		st.Color = Color3.fromRGB(83, 83, 83)
		st.Parent = rgbDot
	end

	const pickerConns = {}
	local pickerDestroyed = false
	local rgbLoopConn = nil
	local startRgbLoop = nil
	local dM, dS = false, false
	local inM, inS
	local dragChangedConn, dragEndedConn = nil, nil

	const function trackPickerConn(conn)
		if conn then
			Insert(pickerConns, conn)
		end
		return conn
	end

	const function stopRgbLoop()
		if rgbLoopConn then
			rgbLoopConn:Disconnect()
			rgbLoopConn = nil
		end
	end

	const function stopDragListeners()
		if dragChangedConn then
			dragChangedConn:Disconnect()
			dragChangedConn = nil
		end
		if dragEndedConn then
			dragEndedConn:Disconnect()
			dragEndedConn = nil
		end
	end

	const function cleanupPickerConnections()
		if pickerDestroyed then
			return
		end
		pickerDestroyed = true
		stopRgbLoop()
		stopDragListeners()
		for i = 1, #pickerConns do
			const conn = pickerConns[i]
			if conn then
				pcall(function()
					conn:Disconnect()
				end)
			end
		end
		for i = #pickerConns, 1, -1 do
			pickerConns[i] = nil
		end
		dM, dS = false, false
		inM, inS = nil, nil
	end

	const pickerOpenSize = picker.Size
	const bgOpenSize = bg.Size
	const bgOpenTr = bg.BackgroundTransparency
	const dispOpenTr = 1
	const interactOpenSize = interact.Size
	const interactOpenPos = interact.Position
	const bgOpenPos = UDim2.new(1, -15, bg.Position.Y.Scale, bg.Position.Y.Offset)
	const slOpenPos = UDim2.new(1, -15, sl.Position.Y.Scale, sl.Position.Y.Offset)
	const rgbOpenPos = rgb.Position
	const hexOpenPos = hex.Position
	const mainOpenTr = main.ImageTransparency
	const pointOpenTr = main.MainPoint.ImageTransparency
	const sliderPointOpenTr = sl.SliderPoint.ImageTransparency

	const pickerClosedSize = UDim2.new(pickerOpenSize.X.Scale, pickerOpenSize.X.Offset, 0, 32)
	const bgClosedSize = UDim2.new(0, 39, 0, 22)
	const bgClosedPos = UDim2.new(1, -15, 0, 5)
	const bgClosedTr = 1
	const dispClosedTr = disp.BackgroundTransparency
	const interactClosedSize = UDim2.new(1, 0, 1, 0)
	const interactClosedPos = UDim2.new(0.5, 0, 0.5, 0)
	const rgbClosedPos = UDim2.new(rgbOpenPos.X.Scale, rgbOpenPos.X.Offset, rgbOpenPos.Y.Scale, rgbOpenPos.Y.Offset + 30)
	const hexClosedPos = UDim2.new(hexOpenPos.X.Scale, hexOpenPos.X.Offset, hexOpenPos.Y.Scale, hexOpenPos.Y.Offset + 17)
	const mainClosedTr = 1
	const pointClosedTr = 1
	const sliderPointClosedTr = 1

	bg.Position = bgOpenPos
	sl.Position = slOpenPos

	const function animateRowHover(show)
		tw(picker, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
			BackgroundColor3 = show and hoverRowColor or baseRowColor
		})
	end

	const function setPickerOpen(state, animate)
		opened = state == true
		const fast = TweenInfo.new(0.16, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
		const mid = TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
		const bgInfo = TweenInfo.new(0.24, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
		const useAnim = animate ~= false

		const pickerSize = opened and pickerOpenSize or pickerClosedSize
		const bgSize = opened and bgOpenSize or bgClosedSize
		const displayTr = opened and dispOpenTr or dispClosedTr
		const interactSize = opened and interactOpenSize or interactClosedSize
		const interactPos = opened and interactOpenPos or interactClosedPos
		const rgbPos = opened and rgbOpenPos or rgbClosedPos
		const hexPos = opened and hexOpenPos or hexClosedPos
		const mainTr = opened and mainOpenTr or mainClosedTr
		const pointTr = opened and pointOpenTr or pointClosedTr
		const sliderPointTr = opened and sliderPointOpenTr or sliderPointClosedTr
		const bgTr = opened and bgOpenTr or bgClosedTr
		const bgPos = opened and bgOpenPos or bgClosedPos

		pcall(function() sl.Visible = opened end)
		pcall(function() main.MainPoint.Visible = opened end)
		pcall(function() sl.SliderPoint.Visible = opened end)

		if useAnim then
			tw(picker, mid, { Size = pickerSize })
			tw(bg, bgInfo, { Size = bgSize, BackgroundTransparency = bgTr, Position = bgPos })
			tw(disp, mid, { BackgroundTransparency = displayTr })
			tw(interact, mid, { Size = interactSize, Position = interactPos })
			tw(rgb, mid, { Position = rgbPos })
			tw(hex, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Position = hexPos })
			pcall(function()
				tw(main.MainPoint, fast, { ImageTransparency = pointTr })
			end)
			pcall(function()
				tw(sl.SliderPoint, fast, { ImageTransparency = sliderPointTr })
			end)
			pcall(function()
				tw(main, fast, { ImageTransparency = mainTr })
				if valueShade then tw(valueShade, fast, { ImageTransparency = mainTr }) end
			end)
		else
			picker.Size = pickerSize
			bg.Size = bgSize
			bg.BackgroundTransparency = bgTr
			bg.Position = bgPos
			disp.BackgroundTransparency = displayTr
			interact.Size = interactSize
			interact.Position = interactPos
			sl.Position = slOpenPos
			rgb.Position = rgbPos
			hex.Position = hexPos
			pcall(function() main.MainPoint.ImageTransparency = pointTr end)
			pcall(function() sl.SliderPoint.ImageTransparency = sliderPointTr end)
			pcall(function()
				main.ImageTransparency = mainTr
				if valueShade then valueShade.ImageTransparency = mainTr end
			end)
		end
	end

	picker.ClipsDescendants = true
	if rowStroke then
		rowStroke.Transparency = 1
		tw(rowStroke, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Transparency = 0 })
	end
	if title then
		title.TextTransparency = 1
		tw(title, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { TextTransparency = 0 })
	end
	picker.BackgroundTransparency = 1
	tw(picker, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { BackgroundTransparency = 0 })

	trackPickerConn(picker.MouseEnter:Connect(function()
		animateRowHover(true)
	end))
	trackPickerConn(picker.MouseLeave:Connect(function()
		animateRowHover(false)
	end))
	trackPickerConn(interact.MouseButton1Click:Connect(function()
		animateRowHover(true)
		if rowStroke then
			tw(rowStroke, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Transparency = 1 })
		end
		Delay(0.2, function()
			if picker.Parent then
				animateRowHover(false)
				if rowStroke then
					tw(rowStroke, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Transparency = 0 })
				end
			end
		end)
		setPickerOpen(not opened, true)
	end))

	setPickerOpen(false, false)

	local rgbOn = false
	const rgbSpd = 0.1

	const function updTog()
		if rgbSw then
			rgbSw.BackgroundColor3 = rgbOn and Color3.fromRGB(70, 49, 104) or Color3.fromRGB(49, 49, 54)
		end
		if rgbDot then
			local w = rgbDot.Size.X.Offset
			if w == 0 then w = math.max(rgbDot.AbsoluteSize.X, 18) end
			const pad = 2
			rgbDot.Position = rgbOn and UDim2.new(1, -w - pad, 0.5, 0) or UDim2.new(0, pad, 0.5, 0)
			rgbDot.BackgroundColor3 = rgbOn and Color3.fromRGB(154, 99, 255) or Color3.fromRGB(114, 114, 124)
		end
		if rgbTit and rgbTit:IsA("TextLabel") then
			rgbTit.Text = rgbOn and "RGB Cycle (ON)" or "RGB Cycle"
			rgbTit.TextColor3 = rgbOn and Color3.fromRGB(194, 194, 255) or Color3.fromRGB(244, 244, 249)
		end
	end

	const function setRGB(sta, opt)
		opt = opt or {}
		const ns = sta and true or false
		if rgbOn == ns then
			if not opt.skipVis then updTog() end
			return
		end
		rgbOn = ns
		if not opt.skipSave then
			saveState(rgbOn)
		end
		updTog()
		if rgbOn then
			if startRgbLoop then
				startRgbLoop()
			end
		else
			stopRgbLoop()
		end
	end

	const sv = getSaved()
	if type(sv) == "boolean" then
		setRGB(sv, { skipVis = true, skipSave = true })
	end
	updTog()

	if rgbBtn then
		MouseButtonFix(rgbBtn, function()
			setRGB(not rgbOn)
		end)
	end

	if typeof(defaultColor) ~= "Color3" then
		defaultColor = Color3.fromRGB(255, 255, 255)
	end

	local h, s, v = defaultColor:ToHSV()

	const function updUI(push, opt)
		opt = opt or {}
		const col = Color3.fromHSV(h, s, v)
		disp.BackgroundColor3 = col
		bg.BackgroundColor3 = Color3.fromHSV(h, 1, 1)
		main.MainPoint.Position = UDim2.new(s, 0, 1 - v, 0)
		sl.SliderPoint.Position = UDim2.new(h, 0, 0.5, 0)

		const r = math.floor(col.R * 255 + 0.5)
		const g = math.floor(col.G * 255 + 0.5)
		const b = math.floor(col.B * 255 + 0.5)

		if push then
			rgb.RInput.InputBox.Text = tostring(r)
			rgb.GInput.InputBox.Text = tostring(g)
			rgb.BInput.InputBox.Text = tostring(b)
			hex.InputBox.Text = Format("#%02X%02X%02X", r, g, b)
		end

		if opt.fire ~= false then
			runColorCallback(col, opt)
		end
	end

	const function parseRGB()
		setRGB(false)
		local r = tonumber(rgb.RInput.InputBox.Text) or 0
		local g = tonumber(rgb.GInput.InputBox.Text) or 0
		local b = tonumber(rgb.BInput.InputBox.Text) or 0
		r = math.clamp(r, 0, 255)
		g = math.clamp(g, 0, 255)
		b = math.clamp(b, 0, 255)
		h, s, v = Color3.fromRGB(r, g, b):ToHSV()
		updUI(false)
	end

	trackPickerConn(rgb.RInput.InputBox.FocusLost:Connect(parseRGB))
	trackPickerConn(rgb.GInput.InputBox.FocusLost:Connect(parseRGB))
	trackPickerConn(rgb.BInput.InputBox.FocusLost:Connect(parseRGB))

	trackPickerConn(hex.InputBox.FocusLost:Connect(function()
		setRGB(false)
		const txt = (hex.InputBox.Text or ""):gsub("#", ""):upper()
		if txt:match("^[0-9A-F]+$") and #txt == 6 then
			const r = tonumber(txt:sub(1, 2), 16)
			const g = tonumber(txt:sub(3, 4), 16)
			const b = tonumber(txt:sub(5, 6), 16)
			if r and g and b then
				h, s, v = Color3.fromRGB(r, g, b):ToHSV()
				updUI(true)
				return
			end
		end
		const col = Color3.fromHSV(h, s, v)
		hex.InputBox.Text = Format("#%02X%02X%02X",
			math.floor(col.R * 255 + 0.5),
			math.floor(col.G * 255 + 0.5),
			math.floor(col.B * 255 + 0.5)
		)
	end))

	pcall(function() main.MainPoint.AnchorPoint = Vector2.new(0.5, 0.5) end)
	pcall(function() sl.SliderPoint.AnchorPoint = Vector2.new(0.5, 0.5) end)

	const UIS = SafeGetService("UserInputService")
	const RS = SafeGetService("RunService")

	startRgbLoop = function()
		if pickerDestroyed or rgbLoopConn or not RS then
			return
		end
		rgbLoopConn = trackPickerConn(RS.RenderStepped:Connect(function(dt)
			if pickerDestroyed then
				return
			end
			local visible = opened
			if visible and NAmanage and NAmanage.IsUIWindowVisible then visible = NAmanage.IsUIWindowVisible("SettingsFrame") end
			if visible and picker and NAmanage and NAmanage.IsGuiActuallyVisible then visible = NAmanage.IsGuiActuallyVisible(picker) end
			if rgbOn and visible and not dM and not dS then
				const step = math.clamp(dt or 0.016, 0.001, 0.1)
				h = (h + step * rgbSpd) % 1
				updUI(true)
			end
		end))
	end
	if rgbOn then
		startRgbLoop()
	end

	const function v2(p)
		if typeof(p) == "Vector2" then return p end
		if typeof(p) == "Vector3" then return Vector2.new(p.X, p.Y) end
		return UIS and __lt.cm("UserInputService", "GetMouseLocation") or Vector2.new(0, 0)
	end

	const function updMain(pos)
		const sz = main.AbsoluteSize
		if sz.X <= 0 or sz.Y <= 0 then return end
		const ap = main.AbsolutePosition
		const rx = math.clamp(pos.X - ap.X, 0, sz.X)
		const ry = math.clamp(pos.Y - ap.Y, 0, sz.Y)
		s = rx / sz.X
		v = 1 - (ry / sz.Y)
		updUI(true)
	end

	const function updSl(pos)
		const sz = sl.AbsoluteSize
		if sz.X <= 0 then return end
		const ap = sl.AbsolutePosition
		const rx = math.clamp(pos.X - ap.X, 0, sz.X)
		h = rx / sz.X
		updUI(true)
	end

	const function startDragListeners()
		if not UIS or pickerDestroyed then
			return
		end
		if dragChangedConn or dragEndedConn then
			return
		end

		dragChangedConn = UIS.InputChanged:Connect(function(input)
			if not dM and not dS then
				return
			end
			if dM then
				if inM and inM.UserInputType == Enum.UserInputType.Touch then
					if input == inM then
						updMain(v2(input.Position))
					end
				elseif input.UserInputType == Enum.UserInputType.MouseMovement then
					updMain(v2(input.Position))
				end
			end
			if dS then
				if inS and inS.UserInputType == Enum.UserInputType.Touch then
					if input == inS then
						updSl(v2(input.Position))
					end
				elseif input.UserInputType == Enum.UserInputType.MouseMovement then
					updSl(v2(input.Position))
				end
			end
		end)

		dragEndedConn = UIS.InputEnded:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 then
				dM, dS = false, false
				inM, inS = nil, nil
				stopDragListeners()
				return
			end
			if input.UserInputType == Enum.UserInputType.Touch then
				if inM == input then dM, inM = false, nil end
				if inS == input then dS, inS = false, nil end
				if not dM and not dS then
					stopDragListeners()
				end
			end
		end)
	end

	const function hit(obj)
		if obj:IsA("GuiButton") then
			pcall(function() obj.Active = true end)
			return obj
		end
		pcall(function() obj.Active = true end)
		local b = obj:FindFirstChild("__Hit")
		if not (b and b:IsA("TextButton")) then
			b = InstanceNew("TextButton")
			b.Name = "__Hit"
			b.BackgroundTransparency = 1
			b.AutoButtonColor = false
			b.BorderSizePixel = 0
			b.Text = ""
			b.Size = UDim2.new(1, 0, 1, 0)
			b.ZIndex = (obj.ZIndex or 1) + 20
			b.Parent = obj
		end
		return b
	end

	const mHit = hit(main)
	const sHit = hit(sl)
	pcall(function() main.MainPoint.Interactable = false end)
	pcall(function() sl.SliderPoint.Interactable = false end)
	pcall(function() interact.Interactable = true end)

	const function beg(t, input)
		if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then
			return
		end
		if not opened then
			return
		end
		setRGB(false)
		if t == "m" then
			dM = true
			inM = input
			updMain(v2(input.Position))
		else
			dS = true
			inS = input
			updSl(v2(input.Position))
		end
		startDragListeners()
	end

	trackPickerConn(mHit.InputBegan:Connect(function(i) beg("m", i) end))
	trackPickerConn(sHit.InputBegan:Connect(function(i) beg("s", i) end))

	const entry = {
		get = function()
			return Color3.fromHSV(h, s, v)
		end,
		set = function(col, opt)
			if typeof(col) ~= "Color3" then return end
			h, s, v = col:ToHSV()
			updUI(true, opt or {})
		end,
		getAutoRGB = function()
			return rgbOn
		end,
		setAutoRGB = function(sta)
			setRGB(sta)
		end,
	}

	NAgui._colorPickerRegistry[label] = entry

	trackPickerConn(picker:GetPropertyChangedSignal("Parent"):Connect(function()
		if not picker.Parent then
			if NAgui._colorPickerRegistry[label] == entry then
				NAgui._colorPickerRegistry[label] = nil
			end
			cleanupPickerConnections()
		end
	end))

	const initOpts = {
		fire = cfg.fireOnInit ~= false;
		context = "init";
	}
	updUI(true, initOpts)

	return picker
end

NAgui.setColorPickerValue = function(label, color, opts)
	const entry = NAgui._colorPickerRegistry and NAgui._colorPickerRegistry[label]
	if not entry then return end
	entry.set(color, opts or { fire = false })
end

NAgui.setColorPickerAutoRGB = function(label, enabled)
	const entry = NAgui._colorPickerRegistry and NAgui._colorPickerRegistry[label]
	if not entry or not entry.setAutoRGB then return end
	entry.setAutoRGB(enabled)
end

NAgui.getColorPickerAutoRGB = function(label)
	const entry = NAgui._colorPickerRegistry and NAgui._colorPickerRegistry[label]
	if not entry or not entry.getAutoRGB then return nil end
	return entry.getAutoRGB()
end

NAgui.addInput = function(label, placeholder, defaultText, callback, opts)
	local settingsList, settingsTabName = NAgui.getSettingsTarget()
	if not settingsList then return end
	if NAgui.SettingsBuildStep then NAgui.SettingsBuildStep("input") end
	opts = opts or {}

	const input = templates.Input:Clone()
	const frame = input.InputFrame
	const box = frame.InputBox
	local chipRow
	if opts.sideChip then
		const tgl = templates.Toggle:Clone()
		const sw = tgl:FindFirstChild("Switch")
		if sw then
			const chip = sw:Clone()
			chip.Name = "SideSwitch"
			chip.Parent = input
			tgl:Destroy()

			local swW = chip.Size.X.Offset
			if swW <= 0 then
				swW = 45
			end

			chip.AnchorPoint = Vector2.new(1, 0.5)
			chip.Position = UDim2.new(1, -15, 0.5, 0)
			chip.Size = UDim2.new(0, swW, 0, chip.Size.Y.Offset)

			chipRow = chip

			frame.AnchorPoint = Vector2.new(1, 0.5)
			frame.Position = UDim2.new(1, -15, 0.5, 0)

			const chipInd = chip:FindFirstChild("Indicator")
			const chipStroke = chip:FindFirstChildWhichIsA("UIStroke", true)
			local chipOn = false

			const function updChip2()
				if chipInd then
					const onX = chip.AbsoluteSize.X - chipInd.AbsoluteSize.X - 4
					const offX = 2
					chipInd.Position = UDim2.new(0, chipOn and onX or offX, 0.5, 0)
					chipInd.Visible = false
				end
				if chipStroke then
					chipStroke.Color = chipOn and Color3.fromRGB(155, 100, 255) or Color3.fromRGB(72, 72, 72)
				end
			end

			if type(opts.sideGet) == "function" then
				local ok, v = pcall(opts.sideGet)
				if ok then
					chipOn = v and true or false
				end
			end

			updChip2()

			const btn = InstanceNew("TextButton")
			btn.Name = "ChipInteract"
			btn.BackgroundTransparency = 1
			btn.Text = tostring(opts.sideText or "Use")
			btn.TextColor3 = Color3.new(1, 1, 1)
			btn.Size = UDim2.new(1, 0, 1, 0)
			btn.ZIndex = (chip.ZIndex or 1) + 1
			btn.Parent = chip

			MouseButtonFix(btn, function()
				if type(opts.sideSet) == "function" or type(opts.sideGet) == "function" then
					const nextState = not chipOn
					local ok, result = true, nil
					if type(opts.sideSet) == "function" then
						ok, result = pcall(opts.sideSet, nextState)
					end
					if not ok or result == false then
						return
					end

					chipOn = nextState
					if type(opts.sideGet) == "function" then
						local getOk, currentState = pcall(opts.sideGet)
						if getOk then
							chipOn = currentState and true or false
						end
					end
					updChip2()
				else
					box:CaptureFocus()
				end
			end)
		else
			tgl:Destroy()
		end
	end

	input.Title.Text = label
	NAmanage.SetSearch.tag(input, label)
	box.Text = defaultText or ""
	box.PlaceholderText = placeholder or ""
	box.TextXAlignment = Enum.TextXAlignment.Center
	box.TextTruncate = Enum.TextTruncate.None

	input.LayoutOrder = NAgui._nextLayoutOrder(settingsTabName)
	input.Parent = settingsList
	NAmanage.registerElementForCurrentTab(input, settingsTabName)
	NAgui.atchSettings(input, "input:"..tostring(label)..":"..tostring(input.LayoutOrder), 0.08)

	local lastW
	local mobileInputPollConn
	local resizeBusy = false
	local resizeQueued = false
	local resizePending = false
	local resize
	local requestResize

	requestResize = function()
		if resizeBusy then
			resizePending = true
			return
		end
		if resizeQueued then
			return
		end
		resizeQueued = true
		Delay(0.03, function()
			resizeQueued = false
			if resize and input and input.Parent then
				resize()
			end
		end)
	end

	const function finishResize()
		resizeBusy = false
		if resizePending then
			resizePending = false
			requestResize()
		end
	end

	const function stopMobileInputPoll()
		NAlib.disconnect("NAgui_input_mobile_poll:"..tostring(label)..":"..tostring(input.LayoutOrder))
		if mobileInputPollConn then
			mobileInputPollConn:Disconnect()
			mobileInputPollConn = nil
		end
	end

	const function startMobileInputPoll()
		stopMobileInputPoll()
		if not (Services.RunService and Services.UserInputService and Services.UserInputService.TouchEnabled) then
			return
		end

		local accum = 0
		mobileInputPollConn = NAlib.reconnect("NAgui_input_mobile_poll:"..tostring(label)..":"..tostring(input.LayoutOrder), Services.RunService.Heartbeat:Connect(function(dt)
			if not (input and input.Parent and box and box.Parent) then
				stopMobileInputPoll()
				return
			end
			local okFocused, isFocused = pcall(function()
				return box:IsFocused()
			end)
			if not (okFocused and isFocused == true) then
				stopMobileInputPoll()
				return
			end
			accum += tonumber(dt) or 0
			if accum < 0.05 then
				return
			end
			accum = 0
			resize()
		end))
	end

	resize = function()
		if resizeBusy then
			resizePending = true
			return
		end
		if NAgui.isSettingsLayoutSuspended and NAgui.isSettingsLayoutSuspended() then
			return
		end
		if not (input and input.Parent and frame and frame.Parent and box and box.Parent) then
			return
		end

		resizeBusy = true

		const textW = NAgui.getInputTextWidth(box)
		const minW = NAgui.getInputMinWidth(frame)
		local maxW

		local cw = input.AbsoluteSize.X
		if (not cw or cw <= 0) and input.Parent then
			cw = input.Parent.AbsoluteSize.X
		end
		if (not cw or cw <= 0) and settingsList then
			cw = settingsList.AbsoluteSize.X
		end

		if cw and cw > 0 then
			const tw = (input.Title and input.Title.TextBounds.X or 0)
			local gap = 32
			if chipRow then
				local extra = chipRow.Size.X.Offset
				if extra <= 0 then
					extra = 45
				end
				gap = gap + extra
			end
			maxW = cw - tw - gap
		end

		local w = math.max(textW, minW)
		local hit = false
		if maxW then
			const clamped = math.max(minW, math.min(w, maxW))
			hit = clamped >= (maxW - 0.5)
			w = clamped
		end

		const targetAlignment = hit and Enum.TextXAlignment.Left or Enum.TextXAlignment.Center
		if box.TextXAlignment ~= targetAlignment then
			box.TextXAlignment = targetAlignment
		end

		if type(w) ~= "number" then
			finishResize()
			return
		end

		if not lastW or math.abs(lastW - w) > 0.5 then
			lastW = w
			const targetSize = UDim2.new(0, w, frame.Size.Y.Scale, frame.Size.Y.Offset)
			if frame.Size ~= targetSize then
				frame.Size = targetSize
			end
			if chipRow then
				local fw = frame.Size.X.Offset
				if fw <= 0 then fw = w end
				const targetChipPosition = UDim2.new(1, -15 - fw - 6, 0.5, 0)
				const targetFramePosition = UDim2.new(1, -15, 0.5, 0)
				if chipRow.Position ~= targetChipPosition then
					chipRow.Position = targetChipPosition
				end
				if frame.Position ~= targetFramePosition then
					frame.Position = targetFramePosition
				end
			end
		end

		finishResize()
	end

	box.Focused:Connect(function()
		startMobileInputPoll()
		resize()
	end)

	box.FocusLost:Connect(function()
		stopMobileInputPoll()
		local commitText = tostring(box.Text or "")
		const measureText = NAgui.getInputMeasureText(box)
		if commitText == "" and measureText ~= "" then
			commitText = measureText
			box.Text = commitText
		end
		resize()
		pcall(callback, commitText)
	end)

	box:GetPropertyChangedSignal("TextBounds"):Connect(requestResize)
	box:GetPropertyChangedSignal("Text"):Connect(requestResize)
	pcall(function()
		box:GetPropertyChangedSignal("ContentText"):Connect(requestResize)
	end)
	input:GetPropertyChangedSignal("AbsoluteSize"):Connect(requestResize)
	input:GetPropertyChangedSignal("Parent"):Connect(function()
		if not input.Parent then
			stopMobileInputPoll()
		end
	end)
	const function setText(newValue, opts)
		opts = opts or {}
		const text = tostring(newValue or "")
		if not opts.force and box.Text == text then
			if opts.fire then
				pcall(callback, text)
			end
			return
		end
		box.Text = text
		resize()
		if opts.fire then
			pcall(callback, text)
		end
	end

	const entry = {
		input = input;
		get = function()
			return box.Text
		end;
		set = function(v, opts)
			setText(v, opts)
		end;
	}

	NAgui._inputRegistry[label] = entry

	input:GetPropertyChangedSignal("Parent"):Connect(function()
		if not input.Parent and NAgui._inputRegistry[label] == entry then
			NAgui._inputRegistry[label] = nil
		end
	end)

	resize()

	return input
end

NAgui.setInputValue = function(label, value, opts)
	const entry = NAgui._inputRegistry and NAgui._inputRegistry[label]
	if not entry then return end
	entry.set(value, opts or { fire = false })
end

NAmanage.SyncPrefixUI = function(opts)
	if not NAgui then return end
	local prefixValue = opt and tostring(opt.prefix or "") or ""
	if prefixValue == "" then
		prefixValue = ";"
	end
	opts = opts or {}
	const setterOpts = {
		force = opts.force == true,
		fire = opts.fire == true,
	}
	if NAgui.setKeybindValue then
		NAgui.setKeybindValue("Prefix", prefixValue, setterOpts)
		return
	end
	if NAgui.setInputValue then
		NAgui.setInputValue("Prefix", prefixValue, setterOpts)
	end
end

NAmanage.SyncUIScaleUI = function(opts)
	if not (NAgui and NAgui.setInputValue) then return end
	opts = opts or {}
	local value = opts.value
	if value == nil then
		value = NAUIScale
	end
	const clamped = NAmanage.ClampUIScale(value, 1)
	const setterOpts = {
		force = opts.force ~= false,
		fire = opts.fire == true,
	}
	NAgui.setInputValue("UI Scale", Format("%.2f", clamped), setterOpts)
end

NAmanage._uiAutoSync = NAmanage._uiAutoSync or { toggles = {} }

NAmanage.RegisterToggleAutoSync = function(label, getter, opts)
	if type(label) ~= "string" or type(getter) ~= "function" then return end
	const store = NAmanage._uiAutoSync
	local entry = store.toggles[label]
	if not entry then
		entry = { getter = getter, last = nil, opts = opts }
		store.toggles[label] = entry
	else
		entry.getter = getter
		entry.opts = opts or entry.opts
	end
end

NAmanage.RunUIAutoSync = function()
	const store = NAmanage._uiAutoSync
	if not store then return end
	const buildState = NAgui and NAgui.SettingsBuildState
	if type(buildState) == "table" and (buildState.background == true or buildState.building == true) then
		return
	end
	const settingsFrame = NAUIMANAGER and NAUIMANAGER.SettingsFrame
	if typeof(settingsFrame) == "Instance" and settingsFrame.Visible ~= true then return end
	const toggleStore = store.toggles
	if toggleStore and NAgui and NAgui.setToggleState then
		const mobile = IsOnMobile == true
		const lowEnd = NAmanage.IsLowEndUI and NAmanage.IsLowEndUI() or false
		local processed = 0
		for label, watcher in toggleStore do
			processed += 1
			local success, rawValue = pcall(watcher.getter)
			if success then
				local normalized = nil
				if watcher.opts and type(watcher.opts.normalize) == "function" then
					local ok, result = pcall(watcher.opts.normalize, rawValue)
					if ok then
						normalized = result
					end
				end
				if normalized == nil then
					normalized = rawValue and true or false
				end
				const registry = NAgui._toggleRegistry
				if registry and registry[label] then
					if watcher.last == nil or watcher.last ~= normalized then
						watcher.last = normalized
						const fireCallback = watcher.opts and watcher.opts.fire == true
						NAgui.setToggleState(label, normalized, {
							force = true,
							fire = fireCallback and true or false,
						})
					end
				else
					watcher.last = nil
				end
			end
			if (mobile or lowEnd) and processed % (mobile and 6 or 12) == 0 then
				Wait(mobile and 0.02 or nil)
			end
		end
	end
end

NAmanage.StartUIAutoSyncLoop = function()
	if NAmanage._uiAutoSyncLoopStarted then return end
	NAmanage._uiAutoSyncLoopStarted = true
	NAmanage._uiAutoSyncLoopAlive = true
	Spawn(function()
		local idleStreak = 0
		while NAmanage._uiAutoSyncLoopAlive do
			const store = NAmanage._uiAutoSync
			const hasToggles = store and store.toggles and next(store.toggles) ~= nil
			if hasToggles then
				local ok, err = pcall(NAmanage.RunUIAutoSync)
				if ok then
					idleStreak = 0
				else
					idleStreak = math.min(idleStreak + 1, 10)
					warn("[NA] UI auto-sync failed:", err)
				end
			else
				idleStreak = math.min(idleStreak + 1, 12)
			end

			const settingsFrame = NAUIMANAGER and NAUIMANAGER.SettingsFrame
			const settingsVisible = not (typeof(settingsFrame) == "Instance") or settingsFrame.Visible == true
			const buildState = NAgui and NAgui.SettingsBuildState
			const settingsBuilding = type(buildState) == "table" and (buildState.background == true or buildState.building == true)
			const lowEnd = NAmanage.IsLowEndUI and NAmanage.IsLowEndUI() or false
			local sleepTime = hasToggles and 1.25 or math.min(8, 2.5 + idleStreak * 0.5)
			if hasToggles then
				if settingsBuilding then sleepTime = lowEnd and 6 or 4
				elseif not settingsVisible then sleepTime = lowEnd and 10 or 6
				elseif NAmanage.isLoad and NAmanage.isLoad() then sleepTime = lowEnd and 2.75 or 1.75
				elseif idleStreak > 0 then sleepTime = math.min(lowEnd and 8 or 5, 1.25 + idleStreak * 0.35)
				elseif lowEnd then sleepTime = 2.5 end
			end
			Wait(sleepTime)
		end
	end)
end

NAmanage.StartUIAutoSyncLoop()
if NAmanage.InstallUIVisibilityOptimizer then pcall(NAmanage.InstallUIVisibilityOptimizer) end

NAgui.addKeybind = function(label, defaultKey, callback)
	local settingsList, settingsTabName = NAgui.getSettingsTarget()
	if not settingsList then return end
	if NAgui.SettingsBuildStep then NAgui.SettingsBuildStep("keybind") end
	callback = type(callback) == "function" and callback or function() end
	const connKey = "NAgui_keybind:"..tostring(label)
	NAlib.disconnect(connKey)
	const keybind = templates.Keybind:Clone()
	keybind.Title.Text = label
	NAmanage.SetSearch.tag(keybind, label)
	const frame = keybind.KeybindFrame
	const box = frame and frame.KeybindBox
	const rowStroke = keybind:FindFirstChild("UIStroke")
	const frameStroke = frame and frame:FindFirstChildWhichIsA("UIStroke")
	const title = keybind:FindFirstChild("Title")
	local defaultKeyText = tostring(defaultKey or "Unknown")
	if defaultKeyText == "" then
		defaultKeyText = "Unknown"
	end

	const keybindSymbolAliases = {
		["!"] = "One",
		["\""] = "Quote",
		["#"] = "Three",
		["$"] = "Four",
		["%"] = "Five",
		["&"] = "Seven",
		["'"] = "Quote",
		["("] = "Nine",
		[")"] = "Zero",
		["*"] = "Eight",
		["+"] = "Equals",
		[";"] = "Semicolon",
		[":"] = "Semicolon",
		[","] = "Comma",
		["<"] = "Comma",
		["."] = "Period",
		[">"] = "Period",
		["/"] = "Slash",
		["?"] = "Slash",
		["\\"] = "BackSlash",
		["|"] = "BackSlash",
		["`"] = "Backquote",
		["~"] = "Backquote",
		["-"] = "Minus",
		["_"] = "Minus",
		["="] = "Equals",
		["["] = "LeftBracket",
		["{"] = "LeftBracket",
		["]"] = "RightBracket",
		["}"] = "RightBracket",
		["@"] = "Two",
		["^"] = "Six",
	}
	const keybindDigitAliases = {
		["0"] = "Zero",
		["1"] = "One",
		["2"] = "Two",
		["3"] = "Three",
		["4"] = "Four",
		["5"] = "Five",
		["6"] = "Six",
		["7"] = "Seven",
		["8"] = "Eight",
		["9"] = "Nine",
	}

	const function safeKeyCodeLookup(name)
		if type(name) ~= "string" or name == "" then
			return nil
		end
		local ok, code = pcall(function()
			return Enum.KeyCode[name]
		end)
		if ok and code and code ~= Enum.KeyCode.Unknown then
			return code
		end
		return nil
	end

	const function resolveKeyCode(text)
		if type(text) ~= "string" then
			return Enum.KeyCode.Unknown, nil
		end
		local clean = text:match("^%s*(.-)%s*$")
		if not clean or clean == "" then
			return Enum.KeyCode.Unknown, nil
		end
		if #clean == 1 then
			const alias = keybindSymbolAliases[clean] or keybindDigitAliases[clean]
			if alias then
				const aliasCode = safeKeyCodeLookup(alias)
				if aliasCode then
					return aliasCode, aliasCode.Name
				end
			end
		end
		clean = clean:gsub("^Enum%.KeyCode%.", "")
		const direct = safeKeyCodeLookup(clean)
		if direct then
			return direct, direct.Name
		end
		const lower = Lower(clean)
		for _, enumKey in Enum.KeyCode:GetEnumItems() do
			if Lower(enumKey.Name) == lower then
				return enumKey, enumKey.Name
			end
		end
		return Enum.KeyCode.Unknown, clean
	end

	local defaultKeyCode, defaultDisplay = resolveKeyCode(defaultKeyText)
	if defaultDisplay and defaultDisplay ~= "" then
		defaultKeyText = defaultDisplay
	end
	local boundKeyCode = defaultKeyCode
	box.Text = defaultKeyText
	local runCallback
	local tweenFrameWidth

	const function setKeyText(newValue, opts)
		opts = opts or {}
		local text = tostring(newValue or "")
		if text == "" then
			text = defaultKeyText
		end
		local code, normalized = resolveKeyCode(text)
		if normalized and normalized ~= "" then
			text = normalized
		end
		if not opts.force and box.Text == text then
			if opts.fire then
				runCallback(text)
			end
			return
		end
		box.Text = text
		boundKeyCode = code
		tweenFrameWidth()
		if opts.fire then
			runCallback(text)
		end
	end

	keybind.LayoutOrder = NAgui._nextLayoutOrder(settingsTabName)
	keybind.Parent = settingsList
	NAmanage.registerElementForCurrentTab(keybind, settingsTabName)

	local capturing = false
	const baseRowColor = keybind.BackgroundColor3
	const hoverRowColor = baseRowColor:Lerp(Color3.new(1, 1, 1), 0.08)
	const baseFrameColor = frame and frame.BackgroundColor3 or Color3.fromRGB(45, 45, 50)
	const focusFrameColor = baseFrameColor:Lerp(Color3.new(1, 1, 1), 0.1)
	const baseFrameStrokeColor = frameStroke and frameStroke.Color or Color3.fromRGB(72, 72, 72)
	const focusFrameStrokeColor = Color3.fromRGB(155, 100, 255)
	local frameFocused = false
	local lastPulseAt = 0
	const pulseCooldown = 0.09
	const pulseHold = 0.08
	local pulseResetAt = 0
	local pulseResetRunning = false

	const function tw(obj, info, goal)
		if not obj then return nil end
		local same = true
		for prop, target in goal do
			local ok, current = pcall(function()
				return obj[prop]
			end)
			if not ok or current ~= target then
				same = false
				break
			end
		end
		if same then
			return nil
		end
		local ok, tween = pcall(function()
			return NAgui.motion(obj, info, goal)
		end)
		if ok and tween then
			tween:Play()
			return tween
		end
		return nil
	end

	const function flashKeybindError(message)
		tw(keybind, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
			BackgroundColor3 = Color3.fromRGB(85, 0, 0)
		})
		if rowStroke then
			tw(rowStroke, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				Transparency = 1
			})
		end
		const prevTitle = title and title.Text or nil
		if title then
			title.Text = "Callback Error"
		end
		warn("[NA] Keybind callback error ("..tostring(label).."): "..tostring(message))
		Delay(0.5, function()
			if not keybind.Parent then
				return
			end
			if title and prevTitle ~= nil then
				title.Text = prevTitle
			end
			tw(keybind, TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				BackgroundColor3 = baseRowColor
			})
			if rowStroke then
				tw(rowStroke, TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
					Transparency = 0
				})
			end
		end)
	end

	runCallback = function(...)
		local ok, err = pcall(callback, ...)
		if not ok then
			flashKeybindError(err)
		end
	end

	const function setFrameFocused(focused, force)
		focused = focused == true
		if not force and frameFocused == focused then
			return
		end
		frameFocused = focused
		if frame then
			tw(frame, TweenInfo.new(0.16, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				BackgroundColor3 = frameFocused and focusFrameColor or baseFrameColor
			})
		end
		if frameStroke then
			tw(frameStroke, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				Color = frameFocused and focusFrameStrokeColor or baseFrameStrokeColor
			})
		end
	end

	const function schedulePulseReset()
		pulseResetAt = os.clock() + pulseHold
		if pulseResetRunning then
			return
		end
		pulseResetRunning = true
		Spawn(function()
			while keybind and keybind.Parent do
				const remaining = pulseResetAt - os.clock()
				if remaining > 0 then
					Wait(math.min(remaining, 0.05))
				else
					if not capturing then
						setFrameFocused(false, false)
					end
					break
				end
			end
			pulseResetRunning = false
			pulseResetAt = 0
		end)
	end

	tweenFrameWidth = function()
		if not (frame and box) then
			return
		end
		local width = box.TextBounds.X + 24
		if width < 24 then
			width = 24
		end
		tw(frame, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
			Size = UDim2.new(0, width, frame.Size.Y.Scale, frame.Size.Y.Offset)
		})
	end

	if rowStroke then
		rowStroke.Transparency = 1
		tw(rowStroke, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Transparency = 0 })
	end
	if title then
		title.TextTransparency = 1
		tw(title, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { TextTransparency = 0 })
	end
	keybind.BackgroundTransparency = 1
	tw(keybind, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { BackgroundTransparency = 0 })
	tweenFrameWidth()

	NAlib.connect(connKey, keybind.MouseEnter:Connect(function()
		tw(keybind, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
			BackgroundColor3 = hoverRowColor
		})
	end))
	NAlib.connect(connKey, keybind.MouseLeave:Connect(function()
		tw(keybind, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
			BackgroundColor3 = baseRowColor
		})
	end))

	NAlib.connect(connKey, box.Focused:Connect(function()
		capturing = true
		pulseResetAt = 0
		box.Text = ""
		setFrameFocused(true, true)
	end))

	NAlib.connect(connKey, box.FocusLost:Connect(function()
		capturing = false
		pulseResetAt = 0
		const typed = box.Text
		if typed == nil or typed == "" then
			box.Text = defaultKeyText
		end
		local code, normalized = resolveKeyCode(box.Text)
		if normalized and normalized ~= "" then
			box.Text = normalized
		end
		boundKeyCode = code
		setFrameFocused(false, true)
		tweenFrameWidth()
	end))

	NAlib.connect(connKey, Services.UserInputService.InputBegan:Connect(function(input, processed)
		if not input or input.UserInputType ~= Enum.UserInputType.Keyboard then
			return
		end
		const keyCode = input.KeyCode
		if keyCode == Enum.KeyCode.Unknown then
			return
		end
		if capturing and input.KeyCode ~= Enum.KeyCode.Unknown then
			const keyName = keyCode.Name
			box:ReleaseFocus()
			box.Text = keyName
			boundKeyCode = keyCode
			capturing = false
			pulseResetAt = 0
			setFrameFocused(false, true)
			runCallback(keyName)
		elseif not capturing and boundKeyCode ~= Enum.KeyCode.Unknown and not processed and keyCode == boundKeyCode then
			const now = os.clock()
			if now - lastPulseAt >= pulseCooldown then
				lastPulseAt = now
				setFrameFocused(true, false)
				schedulePulseReset()
			end
			runCallback()
		end
	end))

	NAlib.connect(connKey, box:GetPropertyChangedSignal("Text"):Connect(function()
		const code = resolveKeyCode(box.Text)
		boundKeyCode = code
		tweenFrameWidth()
	end))

	const entry = {
		keybind = keybind;
		get = function()
			return box.Text
		end;
		set = function(v, opts)
			setKeyText(v, opts)
		end;
		getKeyCode = function()
			return boundKeyCode
		end;
	}

	NAgui._keybindRegistry[label] = entry
	NAlib.connect(connKey, keybind:GetPropertyChangedSignal("Parent"):Connect(function()
		if keybind.Parent then
			return
		end
		if NAgui._keybindRegistry[label] == entry then
			NAgui._keybindRegistry[label] = nil
		end
		NAlib.disconnect(connKey)
	end))

	return keybind
end

NAgui.setKeybindValue = function(label, value, opts)
	const entry = NAgui._keybindRegistry and NAgui._keybindRegistry[label]
	if not entry then return end
	if not (entry.keybind and entry.keybind.Parent) then
		NAgui._keybindRegistry[label] = nil
		return
	end
	entry.set(value, opts or { fire = false })
end

NAgui.addSlider = function(label, min, max, defaultValue, increment, suffix, callback, opts)
	local settingsList, settingsTabName = NAgui.getSettingsTarget()
	if not settingsList then return end
	if NAgui.SettingsBuildStep then NAgui.SettingsBuildStep("slider") end
	if type(callback) == "table" and opts == nil then
		opts = callback
		callback = nil
	end
	opts = type(opts) == "table" and opts or {}
	callback = type(callback) == "function" and callback or function() end
	NAgui._sliderConnCounter = (NAgui._sliderConnCounter or 0) + 1
	const connKey = "NAgui_slider:"..tostring(label)..":"..tostring(NAgui._sliderConnCounter)
	const slider = templates.Slider:Clone()
	slider.Title.Text = label
	NAmanage.SetSearch.tag(slider, label)

	slider.LayoutOrder = NAgui._nextLayoutOrder(settingsTabName)
	slider.Parent = settingsList
	NAmanage.registerElementForCurrentTab(slider, settingsTabName)

	const function toCg(o)
		if not o or o:IsA("CanvasGroup") or not o:IsA("GuiObject") then
			if o then pcall(function() o.ClipsDescendants = true end) end
			return o
		end
		const p = o.Parent
		const n = InstanceNew("CanvasGroup")
		n.Name = o.Name
		n.Active = o.Active
		n.AnchorPoint = o.AnchorPoint
		n.AutomaticSize = o.AutomaticSize
		n.BackgroundColor3 = o.BackgroundColor3
		n.BackgroundTransparency = o.BackgroundTransparency
		n.BorderColor3 = o.BorderColor3
		n.BorderSizePixel = o.BorderSizePixel
		n.LayoutOrder = o.LayoutOrder
		n.Position = o.Position
		n.Rotation = o.Rotation
		n.Size = o.Size
		n.Visible = o.Visible
		n.ZIndex = o.ZIndex
		n.ClipsDescendants = true
		for _, v in o:GetChildren() do
			v.Parent = n
		end
		n.Parent = p
		o:Destroy()
		return n
	end

	const main = toCg(slider:FindFirstChild("Main"))
	const interact = main.Interact
	const progress = toCg(main.Progress)
	const infoText = main.Information
	const rowStroke = slider:FindFirstChild("UIStroke")
	const title = slider:FindFirstChild("Title")
	const mainStroke = main and main:FindFirstChildWhichIsA("UIStroke")
	const progressStroke = progress and progress:FindFirstChildWhichIsA("UIStroke")

	local dragging = false
	local dragDirty = false
	local currentValue = defaultValue
	const step = tonumber(increment) or 0
	const range = max - min
	local dragInputChangedConn
	local dragInputEndedConn
	local dragInputStateConn
	local dragStepConn
	local activeDragInput
	local activeDragType
	local pendingPointerX
	const baseRowColor = slider.BackgroundColor3
	const hoverRowColor = baseRowColor:Lerp(Color3.new(1, 1, 1), 0.08)
	const mainStrokeIdleTransparency = (mainStroke and typeof(mainStroke.Transparency) == "number") and mainStroke.Transparency or 0.4
	const progressStrokeIdleTransparency = (progressStroke and typeof(progressStroke.Transparency) == "number") and progressStroke.Transparency or 0.3
	const fireOnRelease = opts.fireOnRelease == true or opts.live == false

	const function tw(obj, info, goal)
		if not obj then return nil end
		local ok, tween = pcall(function()
			return NAgui.motion(obj, info, goal)
		end)
		if ok and tween then
			tween:Play()
			return tween
		end
		return nil
	end

	const function flashSliderError(message)
		tw(slider, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
			BackgroundColor3 = Color3.fromRGB(85, 0, 0)
		})
		if rowStroke then
			tw(rowStroke, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				Transparency = 1
			})
		end
		const prevTitle = title and title.Text or nil
		if title then
			title.Text = "Callback Error"
		end
		warn("[NA] Slider callback error ("..tostring(label).."): "..tostring(message))
		Delay(0.5, function()
			if not slider.Parent then
				return
			end
			if title and prevTitle ~= nil then
				title.Text = prevTitle
			end
			tw(slider, TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				BackgroundColor3 = baseRowColor
			})
			if rowStroke then
				tw(rowStroke, TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
					Transparency = 0
				})
			end
		end)
	end

	const function runCallback(value)
		local ok, err = pcall(callback, value)
		if not ok then
			flashSliderError(err)
		end
	end

	const function quantize(value)
		if step == 0 then
			return math.clamp(value, min, max)
		end
		const scaled = (value - min) / step
		const rounded = math.floor(scaled + 0.5)
		local quantized = min + rounded * step
		if quantized < min then quantized = min end
		if quantized > max then quantized = max end
		return quantized
	end

	const function progressGoalForPercent(percent)
		percent = math.clamp(percent or 0, 0, 1)
		const width = interact and interact.AbsoluteSize.X or 0
		if width > 0 then
			const pixel = math.clamp(width * percent, 0, width)
			return UDim2.new(0, pixel, 1, 0)
		end
		return UDim2.new(percent, 0, 1, 0)
	end

	const function applyValue(value, opts)
		opts = opts or {}
		const quantized = quantize(value)
		const changed = currentValue ~= quantized
		currentValue = quantized
		const percent = (range ~= 0) and ((quantized - min) / range) or 0
		const goalSize = progressGoalForPercent(percent)
		if opts.animate == false then
			progress.Size = goalSize
		else
			tw(progress, TweenInfo.new(0.24, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				Size = goalSize
			})
		end
		infoText.Text = Format("%.14g", quantized)..(suffix or "")
		if opts.fire ~= false and (changed or opts.forceFire == true) then
			runCallback(quantized)
		end
		return quantized, changed
	end

	const function updateSliderValueFromPos(x)
		const relX = math.clamp(x - interact.AbsolutePosition.X, 0, interact.AbsoluteSize.X)
		const width = math.max(interact.AbsoluteSize.X, 1)
		const percent = relX / width
		const value = min + range * percent
		local _, changed = applyValue(value, { fire = not (fireOnRelease and dragging) })
		if fireOnRelease and dragging and changed then
			dragDirty = true
		end
	end

	const function disconnectDragListeners()
		if dragInputChangedConn then
			dragInputChangedConn:Disconnect()
			dragInputChangedConn = nil
		end
		if dragInputEndedConn then
			dragInputEndedConn:Disconnect()
			dragInputEndedConn = nil
		end
		if dragInputStateConn then
			dragInputStateConn:Disconnect()
			dragInputStateConn = nil
		end
		if dragStepConn then
			NAlib.disconnect(connKey..":drag_step")
			dragStepConn = nil
		end
		pendingPointerX = nil
	end

	const function stopDrag()
		const shouldFire = dragging and fireOnRelease and dragDirty
		const commitValue = currentValue
		dragging = false
		dragDirty = false
		disconnectDragListeners()
		activeDragInput = nil
		activeDragType = nil
		if mainStroke then
			tw(mainStroke, TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				Transparency = mainStrokeIdleTransparency
			})
		end
		if progressStroke then
			tw(progressStroke, TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				Transparency = progressStrokeIdleTransparency
			})
		end
		if shouldFire then
			runCallback(commitValue)
		end
	end

	const function queuePointerX(input)
		if not dragging or not input then
			return
		end
		local ok, position = pcall(function()
			return input.Position
		end)
		if ok and typeof(position) == "Vector3" then
			pendingPointerX = position.X
		end
	end

	const function isActiveDragInput(input)
		if not dragging or not input then
			return false
		end
		if activeDragType == Enum.UserInputType.Touch then
			return input == activeDragInput
		end
		return activeDragType == Enum.UserInputType.MouseButton1
			and input.UserInputType == Enum.UserInputType.MouseButton1
	end

	const function ensureDragListeners()
		disconnectDragListeners()
		dragInputChangedConn = Services.UserInputService.InputChanged:Connect(function(input)
			if not dragging then
				return
			end
			if activeDragType == Enum.UserInputType.Touch then
				if input == activeDragInput then
					queuePointerX(input)
				end
			elseif activeDragType == Enum.UserInputType.MouseButton1
				and input.UserInputType == Enum.UserInputType.MouseMovement then
				queuePointerX(input)
			end
		end)
		dragInputEndedConn = Services.UserInputService.InputEnded:Connect(function(input)
			if isActiveDragInput(input) then
				stopDrag()
			end
		end)
		if activeDragInput then
			dragInputStateConn = activeDragInput.Changed:Connect(function()
				if not dragging or activeDragInput == nil then
					return
				end
				if activeDragType == Enum.UserInputType.Touch then
					queuePointerX(activeDragInput)
				end
				const state = activeDragInput.UserInputState
				if state == Enum.UserInputState.End or state == Enum.UserInputState.Cancel then
					stopDrag()
				end
			end)
		end
		dragStepConn = NAlib.reconnect(connKey..":drag_step", Services.RunService.RenderStepped:Connect(function()
			const pointerX = pendingPointerX
			if not dragging or pointerX == nil then
				return
			end
			pendingPointerX = nil
			pcall(function()
				updateSliderValueFromPos(pointerX)
			end)
		end))
	end

	NAlib.connect(connKey, interact.InputBegan:Connect(function(input)
		const inputType = input.UserInputType
		if inputType ~= Enum.UserInputType.MouseButton1 and inputType ~= Enum.UserInputType.Touch then
			return
		end
		if dragging then
			return
		end

		dragging = true
		activeDragInput = input
		activeDragType = inputType
		if mainStroke then
			tw(mainStroke, TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				Transparency = 1
			})
		end
		if progressStroke then
			tw(progressStroke, TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				Transparency = 1
			})
		end
		ensureDragListeners()
		queuePointerX(input)
		pcall(function()
			updateSliderValueFromPos(input.Position.X)
		end)
	end))

	NAlib.connect(connKey, slider.MouseEnter:Connect(function()
		tw(slider, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
			BackgroundColor3 = hoverRowColor
		})
	end))
	NAlib.connect(connKey, slider.MouseLeave:Connect(function()
		tw(slider, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
			BackgroundColor3 = baseRowColor
		})
	end))

	if rowStroke then
		rowStroke.Transparency = 1
		tw(rowStroke, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Transparency = 0 })
	end
	if title then
		title.TextTransparency = 1
		tw(title, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { TextTransparency = 0 })
	end
	slider.BackgroundTransparency = 1
	tw(slider, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { BackgroundTransparency = 0 })

	applyValue(defaultValue, { fire = false, animate = false })

	const entry = {
		get = function()
			return currentValue
		end;
		set = function(value, opts)
			opts = opts or {}
			if opts.animate == nil then
				opts.animate = true
			end
			applyValue(value, opts)
		end;
	}
	NAgui._sliderRegistry[label] = entry

	NAlib.connect(connKey, slider:GetPropertyChangedSignal("Parent"):Connect(function()
		if not slider.Parent and NAgui._sliderRegistry[label] == entry then
			stopDrag()
			NAgui._sliderRegistry[label] = nil
			Defer(function()
				NAlib.disconnect(connKey)
			end)
		end
	end))

	return slider
end

NAgui.setSliderValue = function(label, value, opts)
	const entry = NAgui._sliderRegistry and NAgui._sliderRegistry[label]
	if not entry then return end
	entry.set(value, opts or { fire = false })
end

-- PART 22
NAgui.addDropdown = function(label, values, defaultValue, callback, opts)
	local settingsList, settingsTabName = NAgui.getSettingsTarget()
	if not settingsList then return end
	if NAgui.SettingsBuildStep then NAgui.SettingsBuildStep("dropdown") end
	if not (templates and templates.Dropdown) then return end

	local DropdownSettings
	if type(label) == "table" and values == nil then
		DropdownSettings = label
	else
		opts = opts or {}
		if type(defaultValue) == "function" and callback == nil then
			callback = defaultValue
			defaultValue = nil
		end
		DropdownSettings = {
			Name = tostring(label or "Dropdown"),
			Options = values,
			CurrentOption = defaultValue,
			MultipleOptions = opts.MultipleOptions == true or opts.multipleOptions == true,
			Callback = callback,
			Ext = opts.Ext,
			Flag = opts.Flag,
		}
	end

	DropdownSettings = DropdownSettings or {}
	DropdownSettings.Name = tostring(DropdownSettings.Name or label or "Dropdown")
	DropdownSettings.Options = DropdownSettings.Options or {}
	DropdownSettings.Callback = type(DropdownSettings.Callback) == "function" and DropdownSettings.Callback or function() end
	DropdownSettings.MultipleOptions = DropdownSettings.MultipleOptions == true
	NAgui._dropdownConnCounter = (NAgui._dropdownConnCounter or 0) + 1
	const connKey = "NAgui_dropdown:"..DropdownSettings.Name..":"..tostring(NAgui._dropdownConnCounter)

	const function normalizeOption(option)
		if type(option) == "table" then
			local rawValue = option.value
			if rawValue == nil then
				rawValue = option.id or option.key or option.name or option[1]
			end
			const value = tostring(rawValue or "")
			local rawDisplay = option.display
			if rawDisplay == nil then
				rawDisplay = option.text or option.label or rawValue or value
			end
			return {
				value = value,
				display = tostring(rawDisplay or value),
				selectedDisplay = tostring(option.selectedDisplay or option.SelectedDisplay or rawDisplay or value),
				richText = option.richText == true or option.RichText == true,
			}
		end
		const text = tostring(option)
		return {
			value = text,
			display = text,
			selectedDisplay = text,
			richText = false,
		}
	end

	const function normalizeOptions(raw)
		const out = {}
		if type(raw) ~= "table" then
			return out
		end
		const n = #raw
		if n > 0 then
			for i = 1, n do
				out[#out + 1] = normalizeOption(raw[i])
			end
		else
			for _, v in raw do
				out[#out + 1] = normalizeOption(v)
			end
		end
		return out
	end

	DropdownSettings.Options = normalizeOptions(DropdownSettings.Options)

	const function getOptionRecordByValue(value)
		const wanted = tostring(value or "")
		for _, option in DropdownSettings.Options do
			if option.value == wanted then
				return option
			end
		end
		return nil
	end

	const function getOptionDisplay(value)
		const option = getOptionRecordByValue(value)
		if option then
			return option.display
		end
		return tostring(value or "")
	end

	const function getOptionSelectedDisplay(value)
		const option = getOptionRecordByValue(value)
		if option then
			return option.selectedDisplay or option.display
		end
		return tostring(value or "")
	end

	const function hasOptionValue(value)
		return getOptionRecordByValue(value) ~= nil
	end

	const function dropdownUsesRichText()
		if opts and (opts.RichText == true or opts.richText == true) then
			return true
		end
		for _, option in DropdownSettings.Options do
			if option.richText == true then
				return true
			end
		end
		return false
	end

	local dropdown, title, selected, toggle
	local collapsedHeight, openHeight

	const function resizeSelectedLabel()
		if NAgui.isSettingsLayoutSuspended and NAgui.isSettingsLayoutSuspended() then
			return
		end
		if not (dropdown and selected and selected:IsA("TextLabel")) then
			return
		end
		const rowWidth = dropdown.AbsoluteSize.X
		if not rowWidth or rowWidth <= 0 then
			return
		end

		local titleWidth = 0
		if title and title:IsA("TextLabel") then
			titleWidth = title.TextBounds.X
		end

		local toggleWidth = 26
		if toggle and toggle:IsA("GuiObject") then
			const abs = toggle.AbsoluteSize.X
			if abs and abs > 0 then
				toggleWidth = abs
			end
		end

		const leftInset = 12
		const gap = 10
		const rightInset = 10
		local selectedLeft = leftInset
		if title and title:IsA("TextLabel") then
			local titleStart = title.AbsolutePosition.X - dropdown.AbsolutePosition.X
			if not titleStart or titleStart < 0 then
				titleStart = leftInset
			end
			selectedLeft = math.max(selectedLeft, math.floor(titleStart + titleWidth + gap + 0.5))
		end
		const rightLimit = rowWidth - toggleWidth - rightInset
		const available = math.max(72, rightLimit - selectedLeft)
		const selectedHeight = math.max(16, selected.TextBounds.Y > 0 and selected.TextBounds.Y or selected.AbsoluteSize.Y > 0 and selected.AbsoluteSize.Y or 18)
		const headerYOffset = math.max(0, math.floor((collapsedHeight - selectedHeight) * 0.5))

		selected.AnchorPoint = Vector2.new(1, 0)
		selected.Position = UDim2.new(0, rightLimit, 0, headerYOffset)
		selected.Size = UDim2.new(0, available, 0, selectedHeight)
		selected.TextScaled = false
		selected.TextWrapped = false
		selected.TextTruncate = Enum.TextTruncate.AtEnd
		selected.TextXAlignment = Enum.TextXAlignment.Right
	end

	dropdown = templates.Dropdown:Clone()
	if Find(DropdownSettings.Name, "closed") then
		dropdown.Name = "Dropdown"
	else
		dropdown.Name = DropdownSettings.Name
	end
	dropdown.Visible = true
	dropdown.ClipsDescendants = true
	dropdown.Parent = settingsList
	dropdown.LayoutOrder = NAgui._nextLayoutOrder(settingsTabName)
	NAmanage.registerElementForCurrentTab(dropdown, settingsTabName)
	NAmanage.SetSearch.tag(dropdown, DropdownSettings.Name)
	if NAgui.RegisterStrokesFrom then
		NAgui.RegisterStrokesFromAsync(dropdown)
	end

	title = dropdown:FindFirstChild("Title")
	selected = dropdown:FindFirstChild("Selected")
	toggle = dropdown:FindFirstChild("Toggle")
	if toggle and toggle:IsA("ImageButton") then NAmanage.SetImageIcon(toggle, "chevron-down") end
	local interact = dropdown:FindFirstChild("Interact")
	local list = dropdown:FindFirstChild("List")
	local listLayout = list and list:FindFirstChildWhichIsA("UIListLayout")
	const optionTemplate = list and list:FindFirstChild("Template")
	const uiStroke = dropdown:FindFirstChild("UIStroke")

	if title and title:IsA("TextLabel") then
		title.Text = DropdownSettings.Name
	end

	if not (interact and interact:IsA("GuiButton")) then
		interact = InstanceNew("TextButton")
		interact.Name = "Interact"
		interact.BackgroundTransparency = 1
		interact.Text = ""
		interact.AutoButtonColor = false
		interact.Parent = dropdown
	end

	if not (list and list:IsA("ScrollingFrame")) then
		list = InstanceNew("ScrollingFrame")
		list.Name = "List"
		list.BackgroundTransparency = 1
		list.BorderSizePixel = 0
		list.AutomaticCanvasSize = Enum.AutomaticSize.Y
		list.ScrollBarThickness = 3
		list.Parent = dropdown
	end

	if not listLayout then
		listLayout = InstanceNew("UIListLayout")
		listLayout.SortOrder = Enum.SortOrder.LayoutOrder
		listLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
		listLayout.Padding = UDim.new(0, 3)
		listLayout.Parent = list
	end

	collapsedHeight = tonumber((opts and opts.CollapsedHeight) or (opts and opts.collapsedHeight)) or dropdown.Size.Y.Offset
	openHeight = tonumber((opts and opts.OpenHeight) or (opts and opts.openHeight)) or 180
	collapsedHeight = math.max(28, math.floor(collapsedHeight + 0.5))
	openHeight = math.max(collapsedHeight + 20, math.floor(openHeight + 0.5))

	list.Visible = false
	list.Position = UDim2.new(0, 5, 0, collapsedHeight + 2)
	list.Size = UDim2.new(1, -10, 1, -collapsedHeight - 6)
	if title then
		title.Position = UDim2.new(title.Position.X.Scale, title.Position.X.Offset, 0, collapsedHeight * 0.5)
	end
	if toggle then
		toggle.Position = UDim2.new(toggle.Position.X.Scale, toggle.Position.X.Offset, 0, collapsedHeight * 0.5)
	end
	list.ScrollBarImageTransparency = 1
	dropdown.Size = UDim2.new(1, -10, 0, collapsedHeight)
	interact.AnchorPoint = Vector2.new(0, 0)
	interact.Position = UDim2.new(0, 0, 0, 0)
	interact.Size = UDim2.new(1, 0, 0, collapsedHeight)

	const selectedColor = (opts and (opts.DropdownSelected or opts.selectedColor)) or Color3.fromRGB(40, 40, 40)
	const unselectedColor = (opts and (opts.DropdownUnselected or opts.unselectedColor)) or Color3.fromRGB(30, 30, 30)
	const hoverColor = (opts and (opts.HoverColor or opts.hoverColor)) or Color3.fromRGB(55, 55, 60)
	const baseColor = dropdown.BackgroundColor3
	local busy = false

	if DropdownSettings.CurrentOption then
		if type(DropdownSettings.CurrentOption) == "string" then
			DropdownSettings.CurrentOption = {DropdownSettings.CurrentOption}
		end
		if not DropdownSettings.MultipleOptions and type(DropdownSettings.CurrentOption) == "table" then
			DropdownSettings.CurrentOption = {DropdownSettings.CurrentOption[1]}
		end
	else
		DropdownSettings.CurrentOption = {}
	end

	const function updateSelectedText()
		if not (selected and selected:IsA("TextLabel")) then
			return
		end
		selected.RichText = dropdownUsesRichText()
		if DropdownSettings.MultipleOptions then
			if #DropdownSettings.CurrentOption == 1 then
				selected.Text = getOptionSelectedDisplay(DropdownSettings.CurrentOption[1])
			elseif #DropdownSettings.CurrentOption == 0 then
				selected.Text = "None"
			else
				selected.Text = "Various"
			end
		else
			selected.Text = getOptionSelectedDisplay(DropdownSettings.CurrentOption[1] or "None")
		end
		resizeSelectedLabel()
	end

	const function eachOptionRow(fn)
		for _, child in list:GetChildren() do
			if child:IsA("Frame") and child.Name ~= "Placeholder" and child.Name ~= "Template" then
				fn(child)
			end
		end
	end

	const function applySelectionColors()
		eachOptionRow(function(row)
			const optionValue = row:GetAttribute("DropdownValue") or row.Name
			const on = Discover(DropdownSettings.CurrentOption, optionValue) ~= nil
			row.BackgroundColor3 = on and selectedColor or unselectedColor
			const rowStroke = row:FindFirstChild("UIStroke")
			if rowStroke and rowStroke:IsA("UIStroke") then
				rowStroke.Transparency = on and 1 or 0
			end
		end)
	end

	const function syncOptionRowVisualState(isOpen)
		eachOptionRow(function(row)
			const rowStroke = row:FindFirstChild("UIStroke")
			const rowTitle = row:FindFirstChild("Title")
			const optionValue = row:GetAttribute("DropdownValue") or row.Name
			const isSelected = Discover(DropdownSettings.CurrentOption, optionValue) ~= nil
			row.BackgroundTransparency = isOpen and 0 or 1
			if rowTitle and rowTitle:IsA("TextLabel") then
				rowTitle.TextTransparency = isOpen and 0 or 1
			end
			if rowStroke and rowStroke:IsA("UIStroke") then
				if isOpen then
					rowStroke.Transparency = isSelected and 1 or 0
				else
					rowStroke.Transparency = 1
				end
			end
		end)
	end

	const function openDropdown()
		if busy then return end
		busy = true
		list.Visible = true
		NAgui.motion(dropdown, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Size = UDim2.new(1, -10, 0, openHeight)}):Play()
		NAgui.motion(list, TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {ScrollBarImageTransparency = 0.7}):Play()
		if toggle then
			NAgui.motion(toggle, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Rotation = 0}):Play()
		end
		eachOptionRow(function(row)
			const rowStroke = row:FindFirstChild("UIStroke")
			const rowTitle = row:FindFirstChild("Title")
			const optionValue = row:GetAttribute("DropdownValue") or row.Name
			if rowStroke and rowStroke:IsA("UIStroke") then
				if not Discover(DropdownSettings.CurrentOption, optionValue) then
					NAgui.motion(rowStroke, TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Transparency = 0}):Play()
				end
			end
			NAgui.motion(row, TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {BackgroundTransparency = 0}):Play()
			if rowTitle and rowTitle:IsA("TextLabel") then
				NAgui.motion(rowTitle, TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {TextTransparency = 0}):Play()
			end
		end)
		Wait(0.05)
		busy = false
	end

	const function closeDropdown()
		if busy then return end
		busy = true
		NAgui.motion(dropdown, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Size = UDim2.new(1, -10, 0, collapsedHeight)}):Play()
		eachOptionRow(function(row)
			const rowStroke = row:FindFirstChild("UIStroke")
			const rowTitle = row:FindFirstChild("Title")
			NAgui.motion(row, TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {BackgroundTransparency = 1}):Play()
			if rowStroke and rowStroke:IsA("UIStroke") then
				NAgui.motion(rowStroke, TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Transparency = 1}):Play()
			end
			if rowTitle and rowTitle:IsA("TextLabel") then
				NAgui.motion(rowTitle, TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {TextTransparency = 1}):Play()
			end
		end)
		NAgui.motion(list, TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {ScrollBarImageTransparency = 1}):Play()
		if toggle then
			NAgui.motion(toggle, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Rotation = 180}):Play()
		end
		Wait(0.22)
		list.Visible = false
		busy = false
	end

	const function toggleDropdown()
		NAgui.motion(dropdown, TweenInfo.new(0.16, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {BackgroundColor3 = hoverColor}):Play()
		if uiStroke and uiStroke:IsA("UIStroke") then
			NAgui.motion(uiStroke, TweenInfo.new(0.16, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Transparency = 1}):Play()
		end
		Wait(0.08)
		NAgui.motion(dropdown, TweenInfo.new(0.16, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {BackgroundColor3 = baseColor}):Play()
		if uiStroke and uiStroke:IsA("UIStroke") then
			NAgui.motion(uiStroke, TweenInfo.new(0.16, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Transparency = 0}):Play()
		end
		if list.Visible then
			closeDropdown()
		else
			openDropdown()
		end
	end

	const function clearOptionRows()
		eachOptionRow(function(row)
			row:Destroy()
		end)
	end

	const function makeFallbackTemplate()
		const row = InstanceNew("Frame")
		row.Size = UDim2.new(1, -8, 0, 28)
		row.BackgroundColor3 = unselectedColor
		row.BorderSizePixel = 0
		const c = InstanceNew("UICorner")
		c.CornerRadius = UDim.new(0, 6)
		c.Parent = row
		const st = InstanceNew("UIStroke")
		st.Color = Color3.fromRGB(70, 70, 70)
		st.Parent = row
		const txt = InstanceNew("TextLabel")
		txt.Name = "Title"
		txt.AnchorPoint = Vector2.new(0, 0.5)
		txt.Position = UDim2.new(0, 10, 0.5, 0)
		txt.Size = UDim2.new(1, -20, 0, 14)
		txt.BackgroundTransparency = 1
		txt.TextXAlignment = Enum.TextXAlignment.Left
		txt.FontFace = Font.new("rbxasset://fonts/families/Roboto.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal)
		txt.TextColor3 = Color3.fromRGB(245, 245, 250)
		txt.Parent = row
		const btn = InstanceNew("TextButton")
		btn.Name = "Interact"
		btn.BackgroundTransparency = 1
		btn.Text = ""
		btn.Size = UDim2.new(1, 0, 1, 0)
		btn.ZIndex = 50
		btn.Parent = row
		return row
	end

	const function fireCallback(payload)
		local ok, err = pcall(function()
			DropdownSettings.Callback(payload)
		end)
		if not ok then
			NAgui.motion(dropdown, TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {BackgroundColor3 = Color3.fromRGB(85, 0, 0)}):Play()
			if uiStroke and uiStroke:IsA("UIStroke") then
				NAgui.motion(uiStroke, TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Transparency = 1}):Play()
			end
			if title and title:IsA("TextLabel") then
				title.Text = "Callback Error"
			end
			warn("[NA] Dropdown callback error:", err)
			Wait(0.4)
			if title and title:IsA("TextLabel") then
				title.Text = DropdownSettings.Name
			end
			NAgui.motion(dropdown, TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {BackgroundColor3 = baseColor}):Play()
			if uiStroke and uiStroke:IsA("UIStroke") then
				NAgui.motion(uiStroke, TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Transparency = 0}):Play()
			end
		end
	end

	const function setDropdownOptions()
		clearOptionRows()
		const templateRow = optionTemplate
		if templateRow and templateRow:IsA("GuiObject") then
			templateRow.Visible = false
		end
		for index, option in DropdownSettings.Options do
			if NAgui.SettingsBuildStep and index % 16 == 0 then NAgui.SettingsBuildStep("dropdownOption") end
			const optionValue = tostring(option.value or "")
			const optionDisplay = tostring(option.display or optionValue)
			const optionRichText = option.richText == true or (opts and (opts.RichText == true or opts.richText == true))
			const row = (templateRow and templateRow:Clone()) or makeFallbackTemplate()
			row.Name = "Option_"..tostring(index)
			row:SetAttribute("DropdownValue", optionValue)
			row.Visible = true
			row.Parent = list
			const rowTitle = row:FindFirstChild("Title")
			local rowInteract = row:FindFirstChild("Interact")
			const rowStroke = row:FindFirstChild("UIStroke")
			if rowTitle and rowTitle:IsA("TextLabel") then
				rowTitle.Text = optionDisplay
				rowTitle.RichText = optionRichText
				rowTitle.TextTransparency = 1
			end
			if rowStroke and rowStroke:IsA("UIStroke") then
				rowStroke.Transparency = 1
			end
			row.BackgroundTransparency = 1

			if not (rowInteract and rowInteract:IsA("GuiButton")) then
				rowInteract = InstanceNew("TextButton")
				rowInteract.Name = "Interact"
				rowInteract.BackgroundTransparency = 1
				rowInteract.Text = ""
				rowInteract.Size = UDim2.new(1, 0, 1, 0)
				rowInteract.Parent = row
			end
			rowInteract.ZIndex = 50

			MouseButtonFix(rowInteract, function()
				const idx = Discover(DropdownSettings.CurrentOption, optionValue)
				if not DropdownSettings.MultipleOptions and idx then
					updateSelectedText()
					applySelectionColors()
					fireCallback(DropdownSettings.CurrentOption)
					if list.Visible then
						Wait(0.1)
						closeDropdown()
					end
					return
				end

				if idx then
					table.remove(DropdownSettings.CurrentOption, idx)
				else
					if not DropdownSettings.MultipleOptions then
						table.clear(DropdownSettings.CurrentOption)
					end
					Insert(DropdownSettings.CurrentOption, optionValue)
				end

				updateSelectedText()
				applySelectionColors()
				fireCallback(DropdownSettings.CurrentOption)

				if not DropdownSettings.MultipleOptions and list.Visible then
					Wait(0.1)
					closeDropdown()
				end
			end)
		end
		applySelectionColors()
		syncOptionRowVisualState(list.Visible == true)
	end

	updateSelectedText()
	setDropdownOptions()
	if toggle and toggle:IsA("GuiObject") then
		toggle.Rotation = 180
	end

	pcall(function()
		NAlib.connect(connKey, dropdown:GetPropertyChangedSignal("AbsoluteSize"):Connect(resizeSelectedLabel))
	end)
	if title and title:IsA("TextLabel") then
		pcall(function()
			NAlib.connect(connKey, title:GetPropertyChangedSignal("TextBounds"):Connect(resizeSelectedLabel))
		end)
	end
	if selected and selected:IsA("TextLabel") then
		pcall(function()
			NAlib.connect(connKey, selected:GetPropertyChangedSignal("TextBounds"):Connect(resizeSelectedLabel))
		end)
	end
	resizeSelectedLabel()

	MouseButtonFix(interact, toggleDropdown)
	if toggle and toggle:IsA("GuiButton") then
		MouseButtonFix(toggle, toggleDropdown)
	end

	NAlib.connect(connKey, dropdown.MouseEnter:Connect(function()
		if not list.Visible then
			NAgui.motion(dropdown, TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {BackgroundColor3 = hoverColor}):Play()
		end
	end))
	NAlib.connect(connKey, dropdown.MouseLeave:Connect(function()
		NAgui.motion(dropdown, TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {BackgroundColor3 = baseColor}):Play()
	end))

	function DropdownSettings:Set(NewOption)
		DropdownSettings.CurrentOption = NewOption
		if typeof(DropdownSettings.CurrentOption) == "string" then
			DropdownSettings.CurrentOption = {DropdownSettings.CurrentOption}
		end
		if type(DropdownSettings.CurrentOption) ~= "table" then
			DropdownSettings.CurrentOption = {}
		end
		if not DropdownSettings.MultipleOptions then
			DropdownSettings.CurrentOption = {DropdownSettings.CurrentOption[1]}
		end
		updateSelectedText()
		applySelectionColors()
		fireCallback(NewOption)
	end

	function DropdownSettings:Refresh(optionsTable)
		DropdownSettings.Options = normalizeOptions(optionsTable)
		for i = #DropdownSettings.CurrentOption, 1, -1 do
			const val = DropdownSettings.CurrentOption[i]
			if not hasOptionValue(val) then
				table.remove(DropdownSettings.CurrentOption, i)
			end
		end
		updateSelectedText()
		setDropdownOptions()
	end

	DropdownSettings.Instance = dropdown

	const regKey = DropdownSettings.Name
	const entry = {
		get = function()
			return DropdownSettings.CurrentOption
		end;
		set = function(value, setOpts)
			setOpts = setOpts or {}
			if setOpts.fire == false then
				const prev = DropdownSettings.Callback
				DropdownSettings.Callback = function() end
				DropdownSettings:Set(value)
				DropdownSettings.Callback = prev
				return
			end
			DropdownSettings:Set(value)
		end;
		setOptions = function(newOptions)
			DropdownSettings:Refresh(newOptions)
		end;
		api = DropdownSettings;
	}
	NAgui._dropdownRegistry[regKey] = entry

	NAlib.connect(connKey, dropdown:GetPropertyChangedSignal("Parent"):Connect(function()
		if not dropdown.Parent and NAgui._dropdownRegistry[regKey] == entry then
			NAgui._dropdownRegistry[regKey] = nil
			Defer(function()
				NAlib.disconnect(connKey)
			end)
		end
	end))

	return DropdownSettings
end

NAgui.setDropdownValue = function(label, value, opts)
	const entry = NAgui._dropdownRegistry and NAgui._dropdownRegistry[label]
	if not entry then return end
	entry.set(value, opts or { fire = false, context = "set" })
end

NAgui.setDropdownOptions = function(label, options, opts)
	const entry = NAgui._dropdownRegistry and NAgui._dropdownRegistry[label]
	if not entry then return end
	entry.setOptions(options, opts or {})
end

NAmanage.Topbar_SanitizeButtonShape=function(shape)
	const raw = Lower(tostring(shape or ""))
	if raw == "square" then
		return "Square"
	elseif raw == "rounded" or raw == "round" then
		return "Rounded"
	elseif raw == "squircle" then
		return "Squircle"
	elseif raw == "circle" then
		return "Circle"
	end
	return "Circle"
end

NAmanage.Topbar_GetButtonShapeOptions=function()
	return { "Square", "Rounded", "Squircle", "Circle" }
end

NAmanage.Topbar_GetButtonCornerRadius=function(shape)
	const normalized = NAmanage.Topbar_SanitizeButtonShape(shape)
	if normalized == "Square" then
		return UDim.new(0, 0)
	elseif normalized == "Rounded" then
		return UDim.new(0.18, 0)
	elseif normalized == "Squircle" then
		return UDim.new(0.3, 0)
	end
	return UDim.new(1, 0)
end

NAmanage.Topbar_ApplyButtonShape=function(shape, opts)
	opts = opts or {}
	const normalized = NAmanage.Topbar_SanitizeButtonShape(shape)
	NAStuff.TopbarButtonShape = normalized
	const glass = TopBarApp and TopBarApp.tGlass
	if glass then
		local corner = glass:FindFirstChildOfClass("UICorner")
		if not corner then
			corner = InstanceNew("UICorner", glass)
		end
		corner.CornerRadius = NAmanage.Topbar_GetButtonCornerRadius(normalized)
	end
	if opts.save ~= false and NAmanage.NASettingsSet then
		NAmanage.NASettingsSet("topbarButtonShape", normalized)
	end
	return normalized
end

NAStuff.TopbarButtonShape = NAmanage.Topbar_SanitizeButtonShape(NAStuff.TopbarButtonShape)

NAmanage.Topbar_PlayTween=function(key,instance,info,props)
	NAmanage._tweens=NAmanage._tweens or {}
	if NAmanage._tweens[key] then NAmanage._tweens[key]:Cancel() end
	const t=NAgui.motion(instance,info,props)
	NAmanage._tweens[key]=t
	t:Play()
	return t
end

NAmanage.Topbar_ButtonCount=function()
	local n=0
	for _ in TopBarApp.buttonDefs do n+=1 end
	return n
end

NAmanage.Menu_GetView=function(root)
	const cam = Services.Workspace.CurrentCamera
	const gui = root and (root:IsA("ScreenGui") and root or root:FindFirstAncestorWhichIsA("ScreenGui"))
	const size = gui and gui.AbsoluteSize
	const vp = size and size.X > 0 and size.Y > 0 and size or (cam and cam.ViewportSize or Vector2.new(1280, 720))
	const scale = math.max(0.01, NAmanage.GetUIScaleFactor(root))
	const origin = root and root.AbsolutePosition or Vector2.new()
	const viewPos = gui and gui.AbsolutePosition or Vector2.new()
	return vp / scale, scale, origin / scale, viewPos / scale
end

NAmanage.Menu_WatchScale=function(root, key, refresh)
	NAlib.disconnect(key)
	if not root then return end
	NAlib.connect(key, root:GetPropertyChangedSignal("AbsoluteSize"):Connect(refresh))
	NAlib.connect(key, root:GetPropertyChangedSignal("AbsolutePosition"):Connect(refresh))
	local node = root
	while node do
		const scaler = node:FindFirstChildOfClass("UIScale")
		if scaler then
			NAlib.connect(key, scaler:GetPropertyChangedSignal("Scale"):Connect(function()
				Defer(refresh)
			end))
		end
		node = node.Parent
	end
end

NAmanage.MenuScroll_Size=function(count, limit, tile, gap, inset, maxH, hints)
	local shown = math.max(1, math.min(limit, count))
	shown = math.min(shown, math.max(1, math.floor((maxH - inset + gap) / (tile + gap))))
	const footer = hints and count > shown and maxH >= tile + inset + 24 and 24 or 0
	if footer > 0 then
		shown = math.min(shown, math.max(1, math.floor((maxH - inset - footer + gap) / (tile + gap))))
	end
	const height = math.min(maxH, shown * tile + (shown - 1) * gap + inset + footer)
	return height, footer, shown
end

NAmanage.MenuScroll_UpdateHint=function(app)
	const scroll, hint = app.scroll, app.hint
	if not (scroll and hint) then return end
	const horiz = app.scrollAxis == "X"
	const extent = horiz and scroll.CanvasSize.X.Offset or scroll.CanvasSize.Y.Offset
	const maxPos = math.max(0, extent - (app.scrollView or 0))
	const point = NAmanage.GetLogicalCanvasPosition(scroll)
	const pos = horiz and point.X or point.Y
	const visible = (app.hintH or 0) > 0 and maxPos > 1
	if hint.Visible ~= visible then hint.Visible = visible end
	if not visible then return end
	local arrow
	if pos >= maxPos - 1 then
		arrow = horiz and "arrow-left" or "arrow-up"
	elseif pos > 1 then
		arrow = horiz and "move-horizontal" or "move-vertical"
	else
		arrow = horiz and "arrow-right" or "arrow-down"
	end
	if app.hintIcon ~= arrow then
		app.hintIcon = arrow
		NAmanage.SetIcon(hint, arrow, {text = "Scroll"})
	end
end

NAmanage.MenuScroll_BuildHint=function(app, key, parent, z)
	NAlib.disconnect(key)
	if app.hint then app.hint:Destroy() end
	const hint = InstanceNew("TextButton", parent)
	app.hint = hint
	app.hintIcon = nil
	hint.Name = "ScrollHint"
	hint.AnchorPoint = Vector2.new(0.5, 1)
	hint.Position = UDim2.new(0.5, 0, 1, 0)
	hint.Size = UDim2.new(1, -8, 0, 24)
	hint.BackgroundTransparency = 1
	hint.BorderSizePixel = 0
	hint.AutoButtonColor = false
	hint.Font = Enum.Font.GothamMedium
	hint.TextSize = 11
	hint.TextColor3 = Color3.fromRGB(230, 230, 240)
	hint.Text = "Scroll"
	hint.Visible = false
	hint.ZIndex = z
	MouseButtonFix(hint, function()
		const scroll = app.scroll
		if not (scroll and hint.Visible) then return end
		const horiz = app.scrollAxis == "X"
		const extent = horiz and scroll.CanvasSize.X.Offset or scroll.CanvasSize.Y.Offset
		const maxPos = math.max(0, extent - (app.scrollView or 0))
		const point = NAmanage.GetLogicalCanvasPosition(scroll)
		const pos = horiz and point.X or point.Y
		const step = math.max(1, app.scrollStep or app.scrollView or 1)
		const nextPos = math.clamp(pos + (pos >= maxPos - 1 and -step or step), 0, maxPos)
		NAmanage.SetLogicalCanvasPosition(scroll, horiz and nextPos or 0, horiz and 0 or nextPos)
		NAmanage.MenuScroll_UpdateHint(app)
	end)
	NAlib.connect(key, app.scroll:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
		NAmanage.MenuScroll_UpdateHint(app)
	end))
end

NAmanage.Topbar_ComputedSize=function()
	const count = NAmanage.Topbar_ButtonCount()
	const vp, scale, _, viewPos = NAmanage.Menu_GetView(TopBarApp.top)
	const maxW = math.max(56, vp.X - 16 / scale)
	if TopBarApp.mode == "bottom" then
		const wanted = math.clamp(math.floor((tonumber(NAStuff.TopbarColumns) or 5) + 0.5), 1, 8)
		const fit = math.max(1, math.floor((maxW - 12 + 8) / 52))
		const cols = math.max(1, math.min(wanted, count, fit))
		const rows = math.clamp(math.floor((tonumber(NAStuff.TopbarVisibleRows) or 2) + 0.5), 1, 5)
		local maxH = vp.Y - 80 / scale
		local openDown = (TopBarApp.dock or NATopbarDock or "top") ~= "bottom"
		const toggle = TopBarApp.toggle
		if toggle and toggle.AbsoluteSize.Y > 0 then
			const top = toggle.AbsolutePosition.Y / scale - viewPos.Y
			const down = vp.Y - top - toggle.AbsoluteSize.Y / scale - 10 - 8 / scale
			const up = top - 10 - 8 / scale
			maxH = openDown and down or up
			const other = openDown and up or down
			if maxH < 80 and other > maxH then
				openDown = not openDown
				maxH = other
			end
		end
		const h, footer, shown = NAmanage.MenuScroll_Size(math.ceil(count / cols), rows, 44, 8, 12, math.max(56, maxH), NAStuff.TopbarScrollHint ~= false)
		return cols * 44 + (cols - 1) * 8 + 12, h, cols, footer, shown * 52, openDown
	else
		const limit = math.clamp(math.floor((tonumber(NAStuff.TopbarVisibleButtons) or 4) + 0.5), 1, 10)
		const shown = math.max(1, math.min(limit, count, math.max(1, math.floor((maxW - 12 + 8) / 56))))
		const maxH = math.max(1, vp.Y - 16 / scale)
		const footer = NAStuff.TopbarScrollHint ~= false and count > shown and maxH >= 84 and 24 or 0
		return math.min(maxW, shown * 48 + (shown - 1) * 8 + 12), math.min(maxH, 60 + footer), shown, footer, shown * 56
	end
end

function Topbar_GetMaxOffset()
	if not (TopBarApp and TopBarApp.frame and TopBarApp.toggle) then
		return nil
	end
	const scale = math.max(0.01, NAmanage.GetUIScaleFactor(TopBarApp.toggle.Parent))
	const fw = TopBarApp.frame.AbsoluteSize.X / scale
	const bw = TopBarApp.toggle.AbsoluteSize.X / scale
	if fw <= 0 then
		return nil
	end
	local maxOffset = (fw - bw) * 0.5
	if maxOffset < 0 then
		maxOffset = 0
	end
	return maxOffset
end

NAmanage.Topbar_SavePositionPreference=function(opts)
	opts = opts or {}
	if not NATopbarKeepPosition and not opts.force then
		return
	end
	const maxOffset = Topbar_GetMaxOffset()
	if not maxOffset then
		return
	end
	local offset = opts.offset
	if type(offset) ~= "number" then
		if not (TopBarApp and TopBarApp.toggle) then
			return
		end
		offset = TopBarApp.toggle.Position.X.Offset
	end
	local ratio = 0
	if maxOffset > 0 then
		ratio = math.clamp(offset / maxOffset, -1, 1)
	end
	NATopbarPositionRatio = ratio
	NAmanage.NASettingsSet("topbarPositionRatio", ratio)
end

NAmanage.Topbar_ResetPositionPreference=function()
	NATopbarPositionRatio = 0
	NAmanage.NASettingsSet("topbarPositionRatio", 0)
	if TopBarApp and TopBarApp.toggle then
		const pos = TopBarApp.toggle.Position
		TopBarApp.toggle.Position = UDim2.new(0.5, 0, pos.Y.Scale, pos.Y.Offset)
		if TopBarApp.isOpen then
			NAmanage.Topbar_PositionPanel()
		end
	end
end

NAmanage.Topbar_ApplySavedPosition=function()
	if not NATopbarKeepPosition then
		return
	end
	const maxOffset = Topbar_GetMaxOffset()
	if not maxOffset then
		return
	end
	const ratio = math.clamp(NATopbarPositionRatio or 0, -1, 1)
	const offset = ratio * maxOffset
	if TopBarApp and TopBarApp.toggle then
		const pos = TopBarApp.toggle.Position
		const target = UDim2.new(0.5, offset, pos.Y.Scale, pos.Y.Offset)
		if TopBarApp.toggle.Position ~= target then TopBarApp.toggle.Position = target end
		if TopBarApp.isOpen then
			NAmanage.Topbar_PositionPanel()
		end
	end
end

NAmanage.Topbar_ApplyDock=function(dock, opts)
	opts = opts or {}
	dock = dock == "bottom" and "bottom" or "top"
	NATopbarDock = dock
	TopBarApp.dock = dock
	if opts.save ~= false then
		NAmanage.topbar_writeDock(dock)
	end
	if TopBarApp.frame then
		TopBarApp.frame.AnchorPoint = Vector2.new(0, dock == "bottom" and 1 or 0)
		TopBarApp.frame.Position = dock == "bottom" and UDim2.new(0,0,1,0) or UDim2.new(0,0,0,0)
	end
	if TopBarApp.toggle then
		const currentX = TopBarApp.toggle.Position.X.Offset
		const anchor = dock == "bottom" and Vector2.new(0.5,1) or Vector2.new(0.5,0)
		const yScale = dock == "bottom" and 1 or 0
		const yOffset = dock == "bottom" and -10 or 10
		TopBarApp.toggle.AnchorPoint = anchor
		TopBarApp.toggle.Position = UDim2.new(0.5, currentX, yScale, yOffset)
	end
	if NATopbarKeepPosition then
		NAmanage.Topbar_ApplySavedPosition()
	else
		NAmanage.Topbar_ClampToggle()
	end
	if TopBarApp.isOpen then
		NAmanage.Topbar_PositionPanel()
	end
end

NAmanage.Topbar_ChooseSide=function()
	const vp,scale,_,viewPos=NAmanage.Menu_GetView(TopBarApp.top)
	const ap=TopBarApp.toggle.AbsolutePosition / scale - viewPos
	const sz=TopBarApp.toggle.AbsoluteSize / scale
	const w=NAmanage.Topbar_ComputedSize()
	const canRight=(ap.X+sz.X+10+w)<= (vp.X-8 / scale)
	const canLeft=(ap.X-10-w)>=8 / scale
	if TopBarApp.sidePref=="right" and not canRight and canLeft then
		TopBarApp.sidePref="left"
	elseif TopBarApp.sidePref=="left" and not canLeft and canRight then
		TopBarApp.sidePref="right"
	elseif not canRight and canLeft then
		TopBarApp.sidePref="left"
	elseif canRight and not canLeft then
		TopBarApp.sidePref="right"
	end
end

NAmanage.Topbar_PositionPanel=function()
	if not (TopBarApp.top and TopBarApp.panel and TopBarApp.toggle) then return end
	const vp, scale, origin, viewPos = NAmanage.Menu_GetView(TopBarApp.top)
	const tap = TopBarApp.toggle.AbsolutePosition / scale - origin
	const tsz = TopBarApp.toggle.AbsoluteSize / scale
	const w, h, cols, footer, step, openDown = NAmanage.Topbar_ComputedSize()
	const panel = TopBarApp.panel
	if panel.Parent ~= TopBarApp.toggle then panel.Parent = TopBarApp.toggle end
	const gridMode = TopBarApp.mode == "bottom"
	const hintTop = not gridMode and (TopBarApp.dock or NATopbarDock or "top") == "bottom"
	TopBarApp.hintH = footer
	TopBarApp.scrollAxis = TopBarApp.mode == "bottom" and "Y" or "X"
	TopBarApp.scrollView = TopBarApp.mode == "bottom" and (h - footer) or w
	TopBarApp.scrollStep = step
	if TopBarApp.scroll then
		const size = UDim2.new(1, 0, 1, -footer)
		if TopBarApp.scroll.Size ~= size then TopBarApp.scroll.Size = size end
		const pos = UDim2.fromOffset(0, hintTop and footer or 0)
		if TopBarApp.scroll.Position ~= pos then TopBarApp.scroll.Position = pos end
	end
	if TopBarApp.hint then
		const anchor = Vector2.new(0.5, hintTop and 0 or 1)
		const pos = UDim2.new(0.5, 0, hintTop and 0 or 1, 0)
		if TopBarApp.hint.AnchorPoint ~= anchor then TopBarApp.hint.AnchorPoint = anchor end
		if TopBarApp.hint.Position ~= pos then TopBarApp.hint.Position = pos end
	end
	if TopBarApp.layout and TopBarApp.mode == "bottom" and TopBarApp.layout.FillDirectionMaxCells ~= cols then
		TopBarApp.layout.FillDirectionMaxCells = cols
	end
	const margin = 8 / scale
	const gap = 10
	const minX = viewPos.X + margin - origin.X
	const minY = viewPos.Y + (gridMode and margin or 0) - origin.Y
	const maxX = math.max(minX, viewPos.X + vp.X - margin - origin.X - w)
	const maxY = math.max(minY, viewPos.Y + vp.Y - (gridMode and margin or 0) - origin.Y - h)
	local x, y, anchor, pos
	if gridMode then
		x = math.clamp(tap.X + tsz.X * 0.5 - w * 0.5, minX, maxX)
		const wantedY = openDown and (tap.Y + tsz.Y + gap) or (tap.Y - gap - h)
		const topY = math.clamp(wantedY, minY, maxY)
		anchor = Vector2.new(0, openDown and 0 or 1)
		y = openDown and topY or (topY + h)
		pos = UDim2.new(0.5, x - tap.X - tsz.X * 0.5, openDown and 1 or 0, y - tap.Y - (openDown and tsz.Y or 0))
	else
		const right = viewPos.X + vp.X - margin - origin.X - (tap.X + tsz.X + gap)
		const left = tap.X - gap - minX
		if TopBarApp.sidePref == "right" and right < w and left >= w then
			TopBarApp.sidePref = "left"
		elseif TopBarApp.sidePref == "left" and left < w and right >= w then
			TopBarApp.sidePref = "right"
		elseif right < w and left < w then
			TopBarApp.sidePref = right >= left and "right" or "left"
		end
		const onRight = TopBarApp.sidePref ~= "left"
		const wantedX = onRight and (tap.X + tsz.X + gap) or (tap.X - gap - w)
		const leftX = math.clamp(wantedX, minX, maxX)
		x = onRight and leftX or (leftX + w)
		const rowH = h - footer
		const topY = tap.Y + tsz.Y * 0.5 - rowH * 0.5 - (hintTop and footer or 0)
		y = math.clamp(topY, minY, maxY) + h * 0.5
		anchor = Vector2.new(onRight and 0 or 1, 0.5)
		pos = UDim2.new(onRight and 1 or 0, x - tap.X - (onRight and tsz.X or 0), 0.5, y - tap.Y - tsz.Y * 0.5)
	end
	if panel.AnchorPoint ~= anchor then panel.AnchorPoint = anchor end
	if panel.Position ~= pos then panel.Position = pos end
	if not TopBarApp.animating then
		const size = UDim2.fromOffset(w, TopBarApp.isOpen and h or 0)
		if panel.Size ~= size then panel.Size = size end
	end
	NAmanage.MenuScroll_UpdateHint(TopBarApp)
end

NAmanage.Topbar_AnimateIcon=function(iconText)
	const ti=TweenInfo.new(0.1,Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
	const ti2=TweenInfo.new(0.1,Enum.EasingStyle.Sine,Enum.EasingDirection.InOut)
	NAmanage.Topbar_PlayTween("icon_shrink",TopBarApp.icon,ti,{TextSize=0}).Completed:Wait()
	NAmanage.SetIcon(TopBarApp.icon, iconText)
	TopBarApp.icon.TextSize=0
	NAmanage.Topbar_PlayTween("icon_grow",TopBarApp.icon,ti2,{TextSize=24})
end

NAmanage.Topbar_UpdateToggleVisual=function(open, opts)
	opts = opts or {}
	const ti=TweenInfo.new(0.1,Enum.EasingStyle.Sine,Enum.EasingDirection.InOut)
	const function clamp01(v, fallback)
		local n = tonumber(v)
		if n == nil then return fallback end
		if n < 0 then n = 0 elseif n > 1 then n = 1 end
		return n
	end
	const baseGlass = clamp01(NAStuff.TopbarGlassTransparency or 0.12, 0.12)
	const baseStroke = clamp01(NAStuff.TopbarStrokeTransparency or 0.15, 0.15)
	const bgTarget=open and math.max(0, baseGlass - 0.06) or baseGlass
	const strokeT=open and math.max(0, baseStroke - 0.1) or baseStroke
	if opts.instant == true then
		if TopBarApp.tGlass then
			TopBarApp.tGlass.BackgroundTransparency = bgTarget
		end
		if TopBarApp.tStroke then
			TopBarApp.tStroke.Transparency = strokeT
		end
	else
		if TopBarApp.tGlass then NAmanage.Topbar_PlayTween("tglass_bg",TopBarApp.tGlass,ti,{BackgroundTransparency=bgTarget}) end
		if TopBarApp.tStroke then NAmanage.Topbar_PlayTween("tglass_stroke",TopBarApp.tStroke,ti,{Transparency=strokeT}) end
	end
	const CLOSED_ICON="menu"
	const OPENED_ICON="x"
	if not opts.skipIcon then
		if opts.instant == true then
			if TopBarApp.icon then
				NAmanage.SetIcon(TopBarApp.icon, open and OPENED_ICON or CLOSED_ICON)
				TopBarApp.icon.TextSize = 24
			end
		elseif open then
			NAmanage.Topbar_AnimateIcon(OPENED_ICON)
		else
			NAmanage.Topbar_AnimateIcon(CLOSED_ICON)
		end
	end
end

NAmanage.Topbar_SetOpen=function(state, opts)
	opts = opts or {}
	if not TopBarApp.panel then return end
	if state == true and not TopBarApp.scroll and NAmanage.Topbar_Rebuild then
		NAmanage.Topbar_Rebuild(IsOnMobile == true and { skipWatch = true, skipVisual = true } or nil)
	end
	if state == true and not TopBarApp.scroll then
		NAmanage.MarkExternalLagProbe("topbar_open_missing_scroll")
		return false
	end
	NAlib.disconnect("tb_anim")
	if NAmanage._tweens and NAmanage._tweens.tb_panel then
		NAmanage._tweens.tb_panel:Cancel()
		NAmanage._tweens.tb_panel = nil
	end
	TopBarApp.isOpen=state
	local w,h=NAmanage.Topbar_ComputedSize()
	TopBarApp.panel.Visible=true
	TopBarApp.underlay.Visible = state
	if TopBarApp.scroll then
		TopBarApp.scroll.Visible = state
	end
	TopBarApp.underlay.ZIndex=201
	if TopBarApp.scroll then
		TopBarApp.scroll.ZIndex=202
	end
	NAlib.disconnect("tb_follow")
	TopBarApp.animating=true
	NAmanage.Topbar_PositionPanel()
	if opts.instant == true then
		TopBarApp.panel.Size = UDim2.new(0, w, 0, state and h or 0)
		TopBarApp.panel.Visible = state == true
		TopBarApp.animating = false
		NAmanage.Topbar_PositionPanel()
		NAmanage.Topbar_UpdateToggleVisual(state, { instant = true, skipIcon = opts.skipIcon == true })
		if NAmanage.Topbar_UpdateButtonVisuals and opts.skipVisual ~= true then
			NAmanage.Topbar_UpdateButtonVisuals()
		end
		return
	end
	const dur=0.18
	const ease=TweenInfo.new(dur,Enum.EasingStyle.Sine,Enum.EasingDirection.InOut)
	const panel=TopBarApp.panel
	if state then
		TopBarApp.panel.Size=UDim2.new(0,w,0,0)
		const tween=NAmanage.Topbar_PlayTween("tb_panel",panel,ease,{Size=UDim2.new(0,w,0,h)})
		NAlib.connect("tb_anim",tween.Completed:Connect(function()
			NAlib.disconnect("tb_anim")
			if TopBarApp.panel ~= panel then return end
			TopBarApp.animating=false
			NAmanage.Topbar_PositionPanel()
		end))
		NAlib.connect("tb_follow",Services.RunService.RenderStepped:Connect(function()
			NAmanage.Topbar_PositionPanel()
		end))
	else
		const tween=NAmanage.Topbar_PlayTween("tb_panel",panel,ease,{Size=UDim2.new(0,w,0,0)})
		NAlib.connect("tb_anim",tween.Completed:Connect(function()
			NAlib.disconnect("tb_anim")
			if TopBarApp.panel ~= panel then return end
			if not TopBarApp.isOpen then TopBarApp.panel.Visible=false end
			TopBarApp.animating=false
			NAmanage.Topbar_PositionPanel()
		end))
	end
	NAmanage.Topbar_UpdateToggleVisual(state)
	if NAmanage.Topbar_UpdateButtonVisuals then
		NAmanage.Topbar_UpdateButtonVisuals()
	end
end

NAmanage.Topbar_Toggle=function()
	NAmanage.Topbar_SetOpen(not TopBarApp.isOpen)
end

NAmanage.Topbar_DefFrame = function(def)
	if type(def) ~= "table" then
		return nil
	end
	const value = def.activeFrame
	if type(value) == "function" then
		local ok, frame = pcall(value, def)
		if ok then
			return frame
		end
		return nil
	end
	if type(value) == "string" and NAUIMANAGER then
		return NAUIMANAGER[value]
	end
	if typeof(value) == "Instance" then
		return value
	end
	return nil
end

NAmanage.Topbar_FrameOpen = function(frame)
	if typeof(frame) ~= "Instance" or not frame:IsA("GuiObject") then
		return false
	end
	if frame.Visible ~= true then
		return false
	end
	if NAmanage.GetAttr and NAmanage.GetAttr(frame, "NAMenuMinimized") == true then
		return false
	end
	return true
end

NAmanage.Topbar_ButtonActive = function(def)
	if type(def) ~= "table" then
		return false
	end
	if type(def.active) == "function" then
		local ok, active = pcall(def.active, def)
		if ok then
			return active == true
		end
	end
	const frame = NAmanage.Topbar_DefFrame(def)
	return NAmanage.Topbar_FrameOpen(frame)
end

NAmanage.Topbar_UpdateButtonVisuals = function(opts)
	opts = opts or {}
	if not TopBarApp or type(TopBarApp.childIcons) ~= "table" then
		return
	end
	const base = tonumber(NAStuff.TopbarButtonTransparency) or 0.18
	local i = 0
	for btn, icon in TopBarApp.childIcons do
		i += 1
		const def = TopBarApp.childDefs and TopBarApp.childDefs[btn]
		const active = NAmanage.Topbar_ButtonActive(def)
		if typeof(icon) == "Instance" then
			const alpha = active and 0 or 0.08
			if icon.TextTransparency ~= alpha then icon.TextTransparency = alpha end
			NAmanage.SetIconBold(icon, active)
		end
		const bg = TopBarApp.childBacks and TopBarApp.childBacks[btn]
		if typeof(bg) == "Instance" then
			pcall(function()
				bg.BackgroundTransparency = active and math.max(0, base - 0.08) or base
			end)
		end
		if opts.chunked == true and IsOnMobile == true and i % 2 == 0 then
			Wait()
		end
	end
end

NAmanage.Topbar_WatchButtonState = function(def)
	const frame = NAmanage.Topbar_DefFrame(def)
	if typeof(frame) ~= "Instance" or not frame:IsA("GuiObject") then
		return
	end
	NAlib.connect("tb_button_active", frame:GetPropertyChangedSignal("Visible"):Connect(function()
		Defer(function()
			if NAmanage.Topbar_UpdateButtonVisuals then
				NAmanage.Topbar_UpdateButtonVisuals()
			end
		end)
	end))
	pcall(function()
		NAlib.connect("tb_button_active", frame:GetAttributeChangedSignal(NAmanage.GetSessionAttrKey("NAMenuMinimized")):Connect(function()
			Defer(function()
				if NAmanage.Topbar_UpdateButtonVisuals then
					NAmanage.Topbar_UpdateButtonVisuals()
				end
			end)
		end))
	end)
end

NAmanage.SideSwipe_ButtonActive = function(def)
	if NAmanage.Topbar_ButtonActive then
		return NAmanage.Topbar_ButtonActive(def) == true
	end
	return false
end

NAmanage.SideSwipe_UpdateButtonVisuals = function(opts)
	opts = opts or {}
	if not SideSwipeApp or type(SideSwipeApp.childIcons) ~= "table" then
		return
	end
	const base = tonumber(NAStuff.SideSwipeButtonTransparency) or 0.16
	local i = 0
	for btn, icon in SideSwipeApp.childIcons do
		i += 1
		const def = SideSwipeApp.childDefs and SideSwipeApp.childDefs[btn]
		const active = NAmanage.SideSwipe_ButtonActive(def)
		if typeof(icon) == "Instance" then
			const alpha = active and 0 or 0.08
			if icon.TextTransparency ~= alpha then icon.TextTransparency = alpha end
			NAmanage.SetIconBold(icon, active)
		end
		const bg = SideSwipeApp.childBacks and SideSwipeApp.childBacks[btn]
		if typeof(bg) == "Instance" then
			pcall(function()
				bg.BackgroundTransparency = active and math.max(0, base - 0.08) or base
			end)
		end
		if opts.chunked == true and IsOnMobile == true and i % 2 == 0 then
			Wait()
		end
	end
end

NAmanage.SideSwipe_SyncButtonVisuals = function()
	Defer(function()
		if NAmanage.Topbar_UpdateButtonVisuals then
			NAmanage.Topbar_UpdateButtonVisuals()
		end
		if NAmanage.SideSwipe_UpdateButtonVisuals then
			NAmanage.SideSwipe_UpdateButtonVisuals()
		end
	end)
end

NAmanage.SideSwipe_WatchButtonState = function(def)
	const frame = NAmanage.Topbar_DefFrame and NAmanage.Topbar_DefFrame(def) or nil
	if typeof(frame) ~= "Instance" or not frame:IsA("GuiObject") then
		return
	end
	NAlib.connect("ss_button_active", frame:GetPropertyChangedSignal("Visible"):Connect(function()
		if NAmanage.SideSwipe_SyncButtonVisuals then
			NAmanage.SideSwipe_SyncButtonVisuals()
		end
	end))
	pcall(function()
		NAlib.connect("ss_button_active", frame:GetAttributeChangedSignal(NAmanage.GetSessionAttrKey("NAMenuMinimized")):Connect(function()
			if NAmanage.SideSwipe_SyncButtonVisuals then
				NAmanage.SideSwipe_SyncButtonVisuals()
			end
		end))
	end)
end

NAmanage.Topbar_Rebuild=function(opts)
	opts = opts or {}
	NAmanage.MarkExternalLagProbe("topbar_rebuild_start")
	TopBarApp.childIcons = NAmanage.ensureWeakTable(nil, "k")
	TopBarApp.childBacks = NAmanage.ensureWeakTable(nil, "k")
	TopBarApp.childDefs = NAmanage.ensureWeakTable(nil, "k")
	NAlib.disconnect("tb_button_active")
	NAlib.disconnect("tb_canvas")
	NAlib.disconnect("tb_hint")
	if TopBarApp.scroll then TopBarApp.scroll:Destroy() TopBarApp.scroll=nil end
	TopBarApp.scroll=InstanceNew("ScrollingFrame",TopBarApp.panel)
	TopBarApp.scroll:SetAttribute("NACustomScrollSkip", true)
	TopBarApp.scroll.BackgroundTransparency=1
	TopBarApp.scroll.BorderSizePixel=0
	TopBarApp.scroll.Size=UDim2.new(1,0,1,0)
	TopBarApp.scroll.ZIndex=202
	TopBarApp.scroll.ScrollBarThickness=4
	TopBarApp.scroll.VerticalScrollBarInset=Enum.ScrollBarInset.None
	TopBarApp.scroll.HorizontalScrollBarInset=Enum.ScrollBarInset.None
	TopBarApp.scroll.Active=true
	TopBarApp.scroll.ScrollingEnabled=true
	NAmanage.MenuScroll_BuildHint(TopBarApp, "tb_hint", TopBarApp.panel, 206)
	for _,c in TopBarApp.scroll:GetChildren() do c:Destroy() end
	for btn,_ in TopBarApp.childButtons do TopBarApp.childButtons[btn]=nil end
	const pad=InstanceNew("UIPadding",TopBarApp.scroll)
	pad.PaddingTop=UDim.new(0,6)
	pad.PaddingBottom=UDim.new(0,6)
	pad.PaddingLeft=UDim.new(0,6)
	pad.PaddingRight=UDim.new(0,6)
	if TopBarApp.layout then TopBarApp.layout:Destroy() TopBarApp.layout=nil end
	const tileBottom=44
	const tileSide=48
	if TopBarApp.mode=="bottom" then
		TopBarApp.scroll.ScrollingDirection=Enum.ScrollingDirection.Y
		const grid=InstanceNew("UIGridLayout",TopBarApp.scroll)
		grid.CellSize=UDim2.new(0,tileBottom,0,tileBottom)
		grid.CellPadding=UDim2.new(0,8,0,8)
		grid.FillDirection=Enum.FillDirection.Horizontal
		const _, _, cols=NAmanage.Topbar_ComputedSize()
		grid.FillDirectionMaxCells=cols
		grid.HorizontalAlignment=Enum.HorizontalAlignment.Center
		grid.VerticalAlignment=Enum.VerticalAlignment.Top
		grid.SortOrder=Enum.SortOrder.LayoutOrder
		TopBarApp.layout=grid
	else
		TopBarApp.scroll.ScrollingDirection = Enum.ScrollingDirection.X
		const list = InstanceNew("UIListLayout", TopBarApp.scroll)
		list.FillDirection = Enum.FillDirection.Horizontal
		list.HorizontalAlignment = Enum.HorizontalAlignment.Left
		list.VerticalAlignment = Enum.VerticalAlignment.Center
		list.Padding = UDim.new(0,8)
		list.SortOrder = Enum.SortOrder.LayoutOrder
		TopBarApp.layout = list
	end
	local i=0
	for _,def in TopBarApp.buttonDefs do
		i+=1
		NAmanage.MarkExternalLagProbe("topbar_rebuild_button:"..tostring(def.name or i))
		const btn=InstanceNew("TextButton",TopBarApp.scroll)
		btn.Name=def.name.."Btn"
		btn.Size=UDim2.new(0, TopBarApp.mode=="bottom" and tileBottom or tileSide, 0, TopBarApp.mode=="bottom" and tileBottom or tileSide)
		btn.BackgroundTransparency=1
		btn.BorderSizePixel=0
		btn.LayoutOrder=i
		btn.Text=''
		btn.TextTransparency=1
		btn.ZIndex=205
		const bg=InstanceNew("Frame",btn)
		bg.ZIndex=203
		bg.Size=UDim2.new(1,0,1,0)
		bg.BackgroundColor3=Color3.fromRGB(25,25,28)
		bg.BackgroundTransparency=NAStuff.TopbarButtonTransparency or 0.18
		bg.BorderSizePixel=0
		const cr=InstanceNew("UICorner",bg); cr.CornerRadius=UDim.new(0, 6)
		const stroke=InstanceNew("UIStroke",bg)
		stroke.Thickness=1
		stroke.Color=NAUISTROKER or Color3.fromRGB(148,93,255)
		stroke.Transparency=0.15
		NAgui.RegisterColoredStroke(stroke)
		const ic=InstanceNew("TextLabel",bg)
		ic.ZIndex=204
		ic.BackgroundTransparency=1
		ic.Size=UDim2.new(0.65,0,0.65,0)
		ic.Position=UDim2.new(0.5,0,0.5,0)
		ic.AnchorPoint=Vector2.new(0.5,0.5)
		NAmanage.SetIcon(ic, def.icon or def.name, {fallback = def.fallback})
		ic.TextColor3=Color3.new(1,1,1)
		ic.TextScaled=false
		ic.TextSize=24
		TopBarApp.childIcons[btn] = ic
		TopBarApp.childBacks[btn] = bg
		TopBarApp.childDefs[btn] = def
		if opts.skipWatch ~= true then
			NAmanage.Topbar_WatchButtonState(def)
		end
		const function fireTopbarButton()
			if type(def.func) == "function" then
				def.func()
			end
			Defer(function()
				if NAmanage.Topbar_UpdateButtonVisuals then
					NAmanage.Topbar_UpdateButtonVisuals()
				end
			end)
		end
		TopBarApp.childButtons[btn]=fireTopbarButton
		MouseButtonFix(btn,fireTopbarButton)
	end
	const function updateCanvas()
		const scale = math.max(0.01, NAmanage.GetUIScaleFactor(TopBarApp.scroll))
		if TopBarApp.mode == "bottom" then
			TopBarApp.scroll.CanvasSize = UDim2.new(0,0,0,TopBarApp.layout.AbsoluteContentSize.Y / scale + 12)
		else
			TopBarApp.scroll.CanvasSize = UDim2.new(0,TopBarApp.layout.AbsoluteContentSize.X / scale + 12,0,0)
		end
		if not TopBarApp.animating then
			NAmanage.Topbar_PositionPanel()
		end
	end
	NAlib.disconnect("tb_canvas")
	NAlib.connect("tb_canvas",TopBarApp.layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(updateCanvas))
	TopBarApp.updateCanvas = updateCanvas
	updateCanvas()
	if opts.skipVisual ~= true then
		NAmanage.Topbar_UpdateButtonVisuals()
	end
	NAmanage.MarkExternalLagProbe("topbar_rebuild_done")
end

NAmanage.Topbar_DeferActiveRefresh = NAmanage.Topbar_DeferActiveRefresh or function()
	if IsOnMobile == true then
		NAmanage.MarkExternalLagProbe("topbar_active_refresh_not_scheduled_mobile")
		return
	end
	Defer(function()
		Wait(0.5)
		if not (TopBarApp and TopBarApp.top and TopBarApp.top.Parent and type(TopBarApp.buttonDefs) == "table") then
			return
		end
		NAmanage.MarkExternalLagProbe("topbar_active_refresh_start")
		NAlib.disconnect("tb_button_active")
		for i, def in TopBarApp.buttonDefs do
			NAmanage.MarkExternalLagProbe("topbar_active_watch:"..tostring(def.name or i))
			NAmanage.Topbar_WatchButtonState(def)
		end
		if NAmanage.Topbar_UpdateButtonVisuals then
			NAmanage.MarkExternalLagProbe("topbar_active_visuals_start")
			NAmanage.Topbar_UpdateButtonVisuals({ chunked = true })
			NAmanage.MarkExternalLagProbe("topbar_active_visuals_done")
		end
		NAmanage.MarkExternalLagProbe("topbar_active_refresh_done")
	end)
end

NAmanage.Topbar_AddButton=function(def)
	TopBarApp.buttonDefs[#TopBarApp.buttonDefs+1]=def
	NAmanage.Topbar_Rebuild()
	NAmanage.SideSwipe_Rebuild()
	if TopBarApp.isOpen then NAmanage.Topbar_PositionPanel() end
end

NAmanage.Topbar_ClampToggle=function()
	if not (TopBarApp and TopBarApp.frame and TopBarApp.toggle) then
		return
	end
	if NATopbarKeepPosition then
		NAmanage.Topbar_ApplySavedPosition()
		return
	end
	const maxOffset=Topbar_GetMaxOffset() or 0
	const off=math.clamp(TopBarApp.toggle.Position.X.Offset,-maxOffset,maxOffset)
	const pos=TopBarApp.toggle.Position
	const target=UDim2.new(0.5,off,pos.Y.Scale,pos.Y.Offset)
	if TopBarApp.toggle.Position ~= target then TopBarApp.toggle.Position=target end
	if TopBarApp.isOpen then
		NAmanage.Topbar_PositionPanel()
	end
end

NAmanage.Topbar_MakeDraggableHorizontal=function(ui)
	const key = "tb_drag_ui"
	NAlib.disconnect(key)
	local dragging=false
	local dragInput,dragStart,startPos

	NAlib.connect(key, ui.InputBegan:Connect(function(input)
		if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
			dragging=true
			dragStart=input.Position
			startPos=ui.Position
			local endConn
			endConn=NAlib.connect(key, input.Changed:Connect(function()
				if input.UserInputState==Enum.UserInputState.End then
					dragging=false
					if NATopbarKeepPosition then
						NAmanage.Topbar_SavePositionPreference()
					end
					if endConn then
						endConn:Disconnect()
						endConn=nil
						if NAmanage and NAmanage.prnCon then
							NAmanage.prnCon(key)
						end
					end
				end
			end))
		end
	end))

	NAlib.connect(key, ui.InputChanged:Connect(function(input)
		if input.UserInputType==Enum.UserInputType.MouseMovement or input.UserInputType==Enum.UserInputType.Touch then
			dragInput=input
		end
	end))

	local lastStep=0
	NAlib.disconnect("tb_drag_input")
	NAlib.connect("tb_drag_input",Services.UserInputService.InputChanged:Connect(function(input)
		if input==dragInput and dragging then
			const now=os.clock()
			if now-lastStep<(1/60) then return end
			lastStep=now
			const delta=input.Position-dragStart
			const scale=math.max(0.01, NAmanage.GetUIScaleFactor(ui.Parent))
			const limit=Topbar_GetMaxOffset() or 0
			const base=startPos.X.Offset
			const newX=math.clamp(base+delta.X / scale,-limit,limit)
			ui.Position=UDim2.new(0.5,newX,startPos.Y.Scale,startPos.Y.Offset)
			if TopBarApp.isOpen then
				NAmanage.Topbar_PositionPanel()
			end
		end
	end))

	ui.Active=true
end

NAmanage.Topbar_SetMode=function(mode)
	if mode~="bottom" and mode~="side" then return end
	TopBarApp.mode=mode
	NAmanage.topbar_writeMode(mode)
	NAmanage.Topbar_Rebuild()
	if TopBarApp.isOpen then NAmanage.Topbar_PositionPanel() end
end

NAmanage.Topbar_SetDock=function(dock)
	dock = dock == "bottom" and "bottom" or "top"
	NATopbarDock = dock
	TopBarApp.dock = dock
	NAmanage.topbar_writeDock(dock)
	NAmanage.Topbar_ApplyDock(dock)
end

NAmanage.Topbar_SetVisible=function(visible, opts)
	opts = opts or {}
	NATOPBARVISIBLE = visible == true
	if TopBarApp and TopBarApp.top then
		TopBarApp.top.Visible = NATOPBARVISIBLE
		if not NATOPBARVISIBLE and TopBarApp.isOpen and NAmanage.Topbar_SetOpen then
			NAmanage.Topbar_SetOpen(false)
		end
	elseif NATOPBARVISIBLE and NAmanage.Topbar_Init then
		pcall(NAmanage.Topbar_Init)
	end
	NAmanage.NASettingsSet("topbarVisible", NATOPBARVISIBLE)
	if NAmanage.RunUIAutoSync then
		pcall(NAmanage.RunUIAutoSync)
	end
	if opts.notify ~= false then
		DebugNotif("Topbar "..(NATOPBARVISIBLE and "shown" or "hidden"), 2)
	end
	return NATOPBARVISIBLE
end

NAmanage.Commands_IsFrame = function(frame)
	return NAUIMANAGER and frame ~= nil and frame == NAUIMANAGER.commandsFrame
end

NAmanage.Commands_IsMinimized = function(frame)
	frame = frame or (NAUIMANAGER and NAUIMANAGER.commandsFrame)
	return frame ~= nil and NAmanage.GetAttr and NAmanage.GetAttr(frame, "NAMenuMinimized") == true
end

NAmanage.Commands_SyncHiddenState = function(opts)
	opts = opts or {}
	const frame = NAUIMANAGER and NAUIMANAGER.commandsFrame
	if not frame then
		return false
	end
	const shown = frame.Visible == true
	const minimized = NAmanage.Commands_IsMinimized(frame)
	const body = frame:FindFirstChild("Container")
	if body and body:IsA("GuiObject") then
		body.Visible = shown and not minimized
	end
	if NAUIMANAGER.description and (not shown or minimized) then
		NAUIMANAGER.description.Visible = false
		NAUIMANAGER.description.Text = ""
	end
	if shown and not minimized then
		if opts.center == true and NAmanage.centerFrame then
			NAmanage.centerFrame(frame)
		end
		if opts.responsive ~= false and type(NAmanage.cmdResp) == "function" then
			pcall(NAmanage.cmdResp, opts.center == true)
		end
		if opts.syncRows ~= false and type(NAmanage.syncVisibleCommandRows) == "function" then
			pcall(NAmanage.syncVisibleCommandRows)
		end
	end
	return shown and not minimized
end

NAmanage.Commands_SetVisible = function(visible, opts)
	opts = opts or {}
	const frame = NAUIMANAGER and NAUIMANAGER.commandsFrame
	if not frame then
		return false
	end
	visible = visible == true
	NAgui.setWindowVisible(frame, visible)
	if visible then
		if opts.resetCanvas ~= false and NAUIMANAGER.commandsList then
			NAUIMANAGER.commandsList.CanvasSize = UDim2.new(0, 0, 0, 0)
		end
		if type(NAgui) == "table" and type(NAgui.commands) == "function" and opts.refresh ~= false then
			pcall(NAgui.commands, {
				fromToggle = true;
				center = opts.center ~= false;
			})
		else
			NAmanage.Commands_SyncHiddenState({
				center = opts.center ~= false;
				syncRows = opts.syncRows ~= false;
			})
		end
	else
		NAmanage.Commands_SyncHiddenState({
			responsive = false;
			syncRows = false;
		})
	end
	return true
end

NAmanage.Commands_Toggle = function()
	const frame = NAUIMANAGER and NAUIMANAGER.commandsFrame
	if not frame then
		return false
	end
	if NAgui.isWindowOpen(frame) then
		return NAmanage.Commands_SetVisible(false, { refresh = false })
	end
	return NAmanage.Commands_SetVisible(true, { refresh = true; center = true; resetCanvas = true })
end

