	shell.filterScripts = function()
		const query = tostring(shell.searchBox.Text or ""):lower()
		for _, child in hubList:GetChildren() do
			if child:IsA("GuiObject") then
				if query == "" then
					child.Visible = true
				else
					local hay = ""
					if child:IsA("TextLabel") or child:IsA("TextButton") then
						hay = tostring(child.Text or "")
					end
					for _, descendant in child:GetDescendants() do
						if descendant:IsA("TextLabel") or descendant:IsA("TextButton") then
							hay ..= " " .. tostring(descendant.Text or "")
						end
					end
					child.Visible = hay:lower():find(query, 1, true) ~= nil
				end
			end
		end
	end
	shell.connect(shell.searchBox:GetPropertyChangedSignal("Text"), function()
		shell.filterScripts()
	end)
	shell.connect(hubList.ChildAdded, function()
		shell.filterScripts()
	end)

