	settingsPanel.Parent = body
	settingsTitle.Text = "Settings"
	do
		const title = topbar and topbar:FindFirstChild("Title")
		if title then title.Text = "Nameless / Executor" end
		for _, pane in { editorPane, hubPane, settingsPanel, shell.toolsPane } do pane.BackgroundTransparency = 0.22 end
		shell.rail.BackgroundTransparency = 0.35
		gutter.BackgroundTransparency = 1
		editorScroll.BackgroundTransparency = 1
		for _, scroll in container:GetDescendants() do
			if scroll:IsA("ScrollingFrame") then
				NAmanage.CreateCustomScrollbar(scroll, { style = "slim" })
			end
		end
		for _, pane in { gutter, editorScroll } do
			const stroke = pane:FindFirstChildOfClass("UIStroke")
			if stroke then stroke:Destroy() end
		end
		for _, card in settingsContent:GetChildren() do
			if card:IsA("Frame") then
				for _, row in card:GetChildren() do
					if row:IsA("Frame") then
						for _, item in row:GetChildren() do
							if item:IsA("TextLabel") and item.Size.X.Scale > 0.5 then
								item.TextWrapped = true
								item.TextSize = 11
								if item.Text == "Script Hub" then item.Text = "Saved Scripts" end
								if item.Size.X.Offset == -84 then item.Size = UDim2.new(1, -62, 1, 0) end
							elseif item:IsA("TextButton") and item.Size.X.Offset == 74 then
								item.Size = UDim2.fromOffset(52, 24)
							elseif item.Name == "Hitbox" then
								item.Size = UDim2.new(1, -60, 1, 0)
							end
						end
					end
				end
			end
		end
	end

	shell.show = function(page)
		if page ~= "editor" and page ~= "scripts" and page ~= "tools" and page ~= "settings" then
			page = "editor"
		end
		if page == "scripts" and cfg.showHub ~= true then
			page = "editor"
		end
		shell.page = page
		shell.apply()
	end

	shell.refreshNav = function()
		const item = shell.nav.scripts
		if item then
			const visible = cfg.showHub == true
			if item.button.Visible ~= visible then
				item.button.Visible = visible
			end
		end
		if shell.page == "scripts" and cfg.showHub ~= true then
			shell.page = "editor"
		end
		shell.apply()
	end

	shell.apply = function(w, h, compact, phone)
		const scale = shell.getScale()
		w = tonumber(w) or 0
		h = tonumber(h) or 0
		if w <= 0 then
			w = frame.AbsoluteSize.X / scale
		end
		if h <= 0 then
			h = frame.AbsoluteSize.Y / scale
		end
		if compact == nil then
			compact = w < 760 or h < 430
		end
		if phone == nil then
			phone = w < 560
		end
		const pad = compact and 6 or 8
		const gap = compact and 6 or 8
		const railW = phone and 36 or (compact and 42 or 48)
		const tabsH = compact and 30 or 34
		const dockH = compact and 40 or 44
		const statusH = 16
		const contentX = railW + gap
		const innerW = container.AbsoluteSize.X / scale
		const innerH = container.AbsoluteSize.Y / scale
		const bodyW = math.max(1, innerW - contentX - pad * 2)
		const pagePad = compact and 8 or 12

		rootPad.PaddingBottom = UDim.new(0, pad)
		rootPad.PaddingLeft = UDim.new(0, pad)
		rootPad.PaddingRight = UDim.new(0, pad)
		rootPad.PaddingTop = UDim.new(0, pad)

		shell.rail.Position = UDim2.new(0, 0, 0, 0)
		shell.rail.Size = UDim2.new(0, railW, 1, 0)
		const itemH = phone and 36 or (compact and 42 or 50)
		const showCaption = not compact
		for key, item in shell.nav do
			item.button.Size = UDim2.new(1, 0, 0, itemH)
			item.glyph.Position = UDim2.new(0, 0, 0, showCaption and 5 or 0)
			item.glyph.Size = UDim2.new(1, 0, 0, showCaption and (itemH - 18) or itemH)
			item.glyph.TextSize = phone and 16 or 18
			item.caption.Visible = showCaption
			const selected = key == shell.page
			if item.button.GetAttribute then
				if NAmanage.GetAttr(item.button, "NAExecutorSelected") ~= selected then
					item.button:SetAttribute("NAExecutorSelected", selected)
				end
			end
			const target = selected and colors.tabActive or colors.panel2
			if item.button.BackgroundColor3 ~= target then
				item.button.BackgroundColor3 = target
			end
		end

		const showEditor = shell.page == "editor"
		tabsBar.Visible = showEditor
		tabsBar.Position = UDim2.new(0, contentX, 0, 0)
		tabsBar.Size = UDim2.new(1, -contentX, 0, tabsH)
		addTabButton.Size = UDim2.new(0, 34, 0, tabsH - 6)

		const bodyTop = showEditor and (tabsH + gap) or 0
		const bodyBottom = showEditor and (dockH + statusH + gap * 2) or 0
		body.Position = UDim2.new(0, contentX, 0, bodyTop)
		body.Size = UDim2.new(1, -contentX, 1, -(bodyTop + bodyBottom))
		const bodyH = math.max(1, innerH - pad * 2 - bodyTop - bodyBottom)

		actions.Visible = showEditor
		actions.Position = UDim2.new(0, contentX, 1, -dockH)
		actions.Size = UDim2.new(1, -contentX, 0, dockH)
		const dockPad = compact and 4 or 6
		actionLayout.CellPadding = UDim2.new(0, dockPad, 0, 0)
		actionLayout.CellSize = UDim2.new(0, math.min(104, math.max(1, math.floor((bodyW - dockPad * 3) / 4))), 1, -(compact and 6 or 8))
		safeExecuteButton.Text = phone and "Safe Run" or "Safe Execute"
		executeButton.Text = "Run"
		actionLayout.FillDirectionMaxCells = 4
		for _, btn in { executeButton, safeExecuteButton, clearButton, copyButton } do
			btn.TextSize = compact and 11 or 13
		end

		statusLabel.Visible = showEditor
		statusLabel.Position = UDim2.new(0, contentX, 1, -(dockH + statusH + gap))
		statusLabel.Size = UDim2.new(1, -contentX, 0, statusH)

		editorPane.Visible = showEditor
		editorPane.Position = UDim2.new(0, 0, 0, 0)
		editorPane.Size = UDim2.new(1, 0, 1, 0)
		const gutterW = cfg.lineNumbers and (phone and 36 or (compact and 40 or 44)) or 0
		gutter.Size = UDim2.new(0, gutterW, 1, 0)
		const gutterGap = gutterW > 0 and 6 or 0
		editorScroll.Position = UDim2.new(0, gutterW + gutterGap, 0, 0)
		editorScroll.Size = UDim2.new(1, -(gutterW + gutterGap), 1, 0)
		editorLineScroll.Position = editorScroll.Position
		editorLineScroll.Size = editorScroll.Size
		pagePanel.Size = UDim2.new(0, phone and 168 or 210, 0, 26)
		pagePrev.Size = UDim2.new(0, 30, 0, 20)
		pageNext.Size = UDim2.new(0, 30, 0, 20)
		pageLabel.Size = UDim2.new(1, -70, 0, 20)

		const showScripts = shell.page == "scripts"
		hubPane.Visible = showScripts
		hubPane.Position = UDim2.new(0, 0, 0, 0)
		hubPane.Size = UDim2.new(1, 0, 1, 0)
		if showScripts then
			hubPad.PaddingBottom = UDim.new(0, pagePad)
			hubPad.PaddingLeft = UDim.new(0, pagePad)
			hubPad.PaddingRight = UDim.new(0, pagePad)
			hubPad.PaddingTop = UDim.new(0, pagePad)
			hubTitle.Position = UDim2.new(0, 0, 0, 0)
			hubTitle.Size = UDim2.new(1, 0, 0, 18)
			hubTitle.TextSize = compact and 14 or 15
			hubSubtitle.Position = UDim2.new(0, 0, 0, 20)
			hubSubtitle.Size = UDim2.new(1, 0, 0, 14)
			hubSubtitle.TextSize = compact and 10 or 11
			const searchTop = 38
			const wideSearch = bodyW >= 260
			shell.searchBox.Position = UDim2.new(0, 0, 0, searchTop)
			shell.searchBox.Size = wideSearch and UDim2.new(1, -110, 0, 28) or UDim2.new(1, 0, 0, 28)
			shell.searchBox.TextSize = compact and 11 or 12
			shell.publicHub.Position = wideSearch and UDim2.new(1, -102, 0, searchTop) or UDim2.new(0, 0, 0, searchTop + 34)
			shell.publicHub.Size = wideSearch and UDim2.new(0, 102, 0, 28) or UDim2.new(1, 0, 0, 26)
			shell.publicHub.TextSize = compact and 10 or 11
			const listTop = wideSearch and (searchTop + 36) or (searchTop + 68)
			if bodyW >= 620 then
				const actionsW = math.clamp(bodyW * 0.28, 176, 230)
				hubButtons.Position = UDim2.new(1, -actionsW, 0, listTop)
				hubButtons.Size = UDim2.new(0, actionsW, 1, -(listTop + pagePad))
				hubList.Position = UDim2.new(0, 0, 0, listTop)
				hubList.Size = UDim2.new(1, -(actionsW + 10), 1, -(listTop + pagePad))
			else
				const actionsH = math.clamp(bodyH * 0.34, 96, 180)
				hubButtons.Position = UDim2.new(0, 0, 1, -actionsH)
				hubButtons.Size = UDim2.new(1, 0, 0, actionsH)
				hubList.Position = UDim2.new(0, 0, 0, listTop)
				hubList.Size = UDim2.new(1, 0, 1, -(listTop + actionsH + 8))
			end
			const hubRowH = compact and 26 or 28
			for _, btn in { hubOpen, hubOpenNew, hubSave, hubClear, hubNew, hubDelete, hubRefresh, NAStuff.ExecutorTools.HubStopLast } do
				btn.Size = UDim2.new(1, -2, 0, hubRowH)
				btn.TextSize = compact and 11 or 12
			end
			hubButtons.ScrollBarThickness = compact and 3 or 4
		end

		const showTools = shell.page == "tools"
		shell.toolsPane.Visible = showTools
		shell.toolsPane.Position = UDim2.new(0, 0, 0, 0)
		shell.toolsPane.Size = UDim2.new(1, 0, 1, 0)
		if showTools then
			shell.toolsPad.PaddingTop = UDim.new(0, pagePad)
			shell.toolsPad.PaddingBottom = UDim.new(0, pagePad)
			shell.toolsPad.PaddingLeft = UDim.new(0, pagePad)
			shell.toolsPad.PaddingRight = UDim.new(0, pagePad)
			const toolsWidth = math.min(math.max(120, bodyW - pagePad * 2), 560)
			shell.toolsScroll.Size = UDim2.new(0, toolsWidth, 1, -52)
			const rowH = compact and 30 or 34
			for _, header in shell.toolHeaders do
				header.Size = UDim2.new(1, 0, 0, 16)
				header.TextSize = compact and 10 or 11
			end
			for _, button in shell.toolButtons do
