NAmanage.SubplaceViewer_GetPlaceThumbnail = function(placeId, width, height)
	const destinationId = tonumber(placeId) or tonumber(game.PlaceId) or 0
	return "rbxthumb://type=Asset&id="..tostring(destinationId)
		.."&w="..tostring(tonumber(width) or 150)
		.."&h="..tostring(tonumber(height) or 150)
end

NAmanage.SubplaceViewer_GetPlaceIcon = function(placeId, width, height, iconAssetId)
	const state = NAmanage.SubplaceViewer
	const destinationId = tonumber(placeId) or tonumber(game.PlaceId) or 0
	const cached = state.placeIconAssets[destinationId]
	const resolvedIconId = tonumber(iconAssetId) or (type(cached) == "number" and cached or nil)
	if resolvedIconId and resolvedIconId > 0 then
		return "rbxthumb://type=Asset&id="..tostring(resolvedIconId)
			.."&w="..tostring(tonumber(width) or 150)
			.."&h="..tostring(tonumber(height) or 150)
	end
	return NAmanage.SubplaceViewer_GetPlaceThumbnail(destinationId, width, height)
end

NAmanage.TeleportGui_GetBackdrop = function(placeId)
	const id = tonumber(placeId) or tonumber(game.PlaceId) or 0
	return "rbxthumb://type=GameThumbnail&id="..tostring(id).."&w=768&h=432"
end

NAmanage.TeleportGui_Protect = function(gui)
	if not gui then return false end
	const protector = __NAUIProtector
	if type(protector) == "table" and type(protector.protectUI) == "function" then
		local ok, result = pcall(protector.protectUI, gui, {
			keepName = true,
			watch = false,
			harden = false,
			deep = false,
			rename = false,
		})
		if ok and result and gui.Parent then
			return true
		end
	end
	local parent
	if NAlib and type(NAlib.huiGrabber) == "function" then
		pcall(function() parent = NAlib.huiGrabber() end)
	end
	parent = parent or Services.CoreGui
	if not parent then return false end
	return pcall(function() gui.Parent = parent end)
end

NAmanage.TeleportGui_GetIcon = function(placeId)
	const state = NAmanage.SubplaceViewer
	const id = tonumber(placeId) or tonumber(game.PlaceId) or 0
	local universeId = tonumber(state.teleportUniverseIds[id])
	if not universeId then
		if id == tonumber(game.PlaceId) then
			universeId = tonumber(game.GameId)
		else
			for _, place in state.places do
				if tonumber(place.PlaceId) == id then
					universeId = tonumber(game.GameId)
					break
				end
			end
		end
		if universeId and universeId > 0 then
			state.teleportUniverseIds[id] = universeId
		end
	end
	if universeId and universeId > 0 then
		return "rbxthumb://type=GameIcon&id="..tostring(universeId).."&w=512&h=512"
	end
	return NAmanage.SubplaceViewer_GetPlaceIcon(id, 420, 420)
end

NAmanage.TeleportGui_ResolveDestinationIcon = function(gui, placeId)
	if not gui then return false end
	const state = NAmanage.SubplaceViewer
	const id = tonumber(placeId) or tonumber(game.PlaceId) or 0
	const function apply(target)
		if typeof(target) ~= "Instance" then return end
		local ok, currentId = pcall(function()
			return target:GetAttribute("NADestinationPlaceId")
		end)
		if not ok or tonumber(currentId) ~= id then return end
		const root = target:FindFirstChild("Root")
		const fg = root and root:FindFirstChild("Foreground")
		const content = fg and fg:FindFirstChild("Content")
		const icon = content and content:FindFirstChild("DestinationIcon")
		if icon and icon:IsA("ImageLabel") then
			icon.Image = NAmanage.TeleportGui_GetIcon(id)
			icon.ImageTransparency = 0
			icon.ImageColor3 = Color3.new(1, 1, 1)
			icon.Visible = true
		end
	end
	apply(gui)
	if tonumber(state.teleportUniverseIds[id]) then return true end
	local pending = state.teleportUniverseRequests[id]
	if pending then
		pending[gui] = true
		return true
	end
	pending = setmetatable({}, { __mode = "k" })
	pending[gui] = true
	state.teleportUniverseRequests[id] = pending
	Spawn(function()
		local universeId
		local ok, raw = pcall(_na_boot.httpGet,
			"https://apis.roblox.com/universes/v1/places/"..tostring(id).."/universe",
			{ maxAttempts = 2; timeout = 6 }
		)
		if ok and type(raw) == "string" then
			local parsed, data = pcall(Services.HttpService.JSONDecode, Services.HttpService, raw)
			if parsed and type(data) == "table" then
				universeId = tonumber(data.universeId or data.UniverseId)
			end
		end
		if universeId and universeId > 0 then
			state.teleportUniverseIds[id] = universeId
		end
		if state.teleportUniverseRequests[id] == pending then
			state.teleportUniverseRequests[id] = nil
		end
		for target in pending do
			apply(target)
		end
	end)
	return true
end

NAmanage.SubplaceViewer_GetPlaceName = function(placeId)
	const state = NAmanage.SubplaceViewer
	for _, place in state.places do
		if tonumber(place.PlaceId) == tonumber(placeId) then
			return tostring(place.Name or ("Place "..tostring(placeId)))
		end
	end
	if tonumber(placeId) == tonumber(game.PlaceId) then
		return tostring(game.Name)
	end
	return "Place "..tostring(placeId)
end

NAmanage.SubplaceViewer_ClearTeleportGui = function(gui)
	const state = NAmanage.SubplaceViewer
	state.teleportGuiToken += 1
	const target = gui or state.teleportGui
	if target then
		pcall(function() target:Destroy() end)
	end
	if state.teleportHandoffGui then
		pcall(function() state.teleportHandoffGui:Destroy() end)
		state.teleportHandoffGui = nil
	end
	if state.teleportGui == target or gui == nil then
		state.teleportGui = nil
	end
	local gs = NAmanage.GameTeleportGui
	if type(gs) == "table" then
		if gs.lastGui == target then gs.lastGui = nil end
		if gs.prearmedGui and (gs.prearmedGui == target or not state.teleportHandoffGui) then
			gs.prearmedGui = nil
			gs.inFlight = false
		end
	end
	if Services.TeleportService then
		pcall(Services.TeleportService.SetTeleportGui, Services.TeleportService, nil)
	end
end

NAmanage.TeleportGui_GetViewportSize = function(gui)
	local viewport = Vector2.new(1280, 720)
	const camera = Services.Workspace and Services.Workspace.CurrentCamera
	if camera then
		local ok, size = pcall(function() return camera.ViewportSize end)
		if ok and typeof(size) == "Vector2" and size.X > 0 and size.Y > 0 then
			viewport = size
		end
	end
	const root = gui and gui:FindFirstChild("Root")
	if root and root.AbsoluteSize.X > 0 and root.AbsoluteSize.Y > 0 then
		viewport = root.AbsoluteSize
	end
	return viewport
end

NAmanage.TeleportGui_ApplyResponsiveLayout = function(gui)
	if not gui then return false end
	const root = gui:FindFirstChild("Root")
	const fg = root and root:FindFirstChild("Foreground")
	const brand = fg and fg:FindFirstChild("TopBrand")
	const content = fg and fg:FindFirstChild("Content")
	const image = root and root:FindFirstChild("Backdrop")
	if not (root and fg and brand and content and image) then return false end
	const viewport = NAmanage.TeleportGui_GetViewportSize(gui)
	const width = math.max(240, viewport.X)
	const height = math.max(240, viewport.Y)
	const compact = width < 700 or height < 500
	const tiny = width < 390 or height < 340
	local topInset, bottomInset, leftInset, rightInset = 0, 0, 0, 0
	if Services.GuiService then
		local ok, a, b = pcall(Services.GuiService.GetGuiInset, Services.GuiService)
		if ok and typeof(a) == "Vector2" and typeof(b) == "Vector2" then
			topInset, bottomInset = math.max(0, a.Y), math.max(0, b.Y)
			leftInset, rightInset = math.max(0, a.X), math.max(0, b.X)
		end
	end
	const side = math.max(tiny and 10 or 18, leftInset + 8, rightInset + 8)
	const top = math.max(topInset + 10, tiny and 14 or 24)
	const bottom = math.max(bottomInset + 20, tiny and 28 or 40)
	const cardHeight = tiny and 94 or (compact and 106 or 118)
	const contentWidth = math.min(710, math.max(180, width - side * 2))
	const iconSize = tiny and 54 or (compact and 64 or 78)
	const pad = tiny and 10 or 15
	const textX = pad + iconSize + (tiny and 10 or 15)
	const textWidth = math.max(60, contentWidth - textX - pad)
	const logoSize = tiny and 30 or 36
	local logo = brand:FindFirstChild("LogoHolder")
	local title = brand:FindFirstChild("Brand")
	local sub = brand:FindFirstChild("SubBrand")
	brand.Position = UDim2.fromOffset(side, top)
	brand.Size = UDim2.new(1, -(side * 2), 0, logoSize)
	brand:SetAttribute("FinalX", side)
	brand:SetAttribute("FinalY", top)
	if logo then logo.Size = UDim2.fromOffset(logoSize, logoSize) end
	if title then
		title.Position = UDim2.fromOffset(logoSize + 10, 0)
		title.Size = UDim2.new(1, -(logoSize + 10), 0, 20)
		title.TextSize = tiny and 12 or 14
	end
	if sub then
		sub.Position = UDim2.fromOffset(logoSize + 10, 21)
		sub.Size = UDim2.new(1, -(logoSize + 10), 0, 12)
		sub.TextSize = 9
	end
	image.AnchorPoint = Vector2.new(0.5, 0.5)
	image.Position = UDim2.fromScale(0.5, 0.5)
	image.Size = UDim2.fromScale(1, 1)
	image.ScaleType = Enum.ScaleType.Crop
	image.ZIndex = 2
	local imgCorner = image:FindFirstChild("HeroCorner")
	if imgCorner then imgCorner:Destroy() end
	local imgStroke = image:FindFirstChild("HeroStroke")
	if imgStroke then imgStroke:Destroy() end
	content.AnchorPoint = Vector2.new(0.5, 1)
	content.Position = UDim2.new(0.5, 0, 1, -bottom)
	content.Size = UDim2.fromOffset(contentWidth, cardHeight)
	content:SetAttribute("FinalY", -bottom)
	local limit = content:FindFirstChildOfClass("UISizeConstraint")
	if limit then
		limit.MinSize = Vector2.new(1, 1)
		limit.MaxSize = Vector2.new(710, 130)
	end
	local icon = content:FindFirstChild("DestinationIcon")
	local tag = content:FindFirstChild("StatusPill")
	local dest = content:FindFirstChild("Destination")
	local info = content:FindFirstChild("Info")
	local footer = content:FindFirstChild("Footer")
	local accent = content:FindFirstChild("Accent")
	if icon then
		icon.Visible = true
		icon.AnchorPoint = Vector2.new(0, 0.5)
		icon.Position = UDim2.new(0, pad, 0.5, 0)
		icon.Size = UDim2.fromOffset(iconSize, iconSize)
		icon.ImageTransparency = 0
		icon.ImageColor3 = Color3.new(1, 1, 1)
		icon.ScaleType = Enum.ScaleType.Crop
	end
	if accent then accent.Visible = false end
	if tag then
		tag.Position = UDim2.fromOffset(textX, tiny and 8 or 10)
		tag.Size = UDim2.fromOffset(math.min(textWidth, tiny and 145 or 165), 22)
	end
	if dest then
		dest.Position = UDim2.fromOffset(textX, tiny and 32 or 38)
		dest.Size = UDim2.fromOffset(textWidth, tiny and 28 or 38)
		dest.TextSize = tiny and 17 or (compact and 23 or 29)
	end
	if info then
		info.Position = UDim2.fromOffset(textX, tiny and 64 or 82)
		info.Size = UDim2.fromOffset(textWidth, 16)
		info.TextSize = tiny and 10 or 11
	end
	if footer then
		footer.Visible = not tiny and textWidth >= 240
		footer.Position = UDim2.new(1, -pad, 0, 12)
		footer.AnchorPoint = Vector2.new(1, 0)
		footer.Size = UDim2.fromOffset(80, 16)
		footer.TextSize = 10
		footer.TextXAlignment = Enum.TextXAlignment.Right
	end
	local track = fg:FindFirstChild("ProgressTrack")
	if track then
		track.AnchorPoint = Vector2.new(0.5, 1)
		track.Position = UDim2.new(0.5, 0, 1, -(bottom - 11))
		track.Size = UDim2.fromOffset(contentWidth, 2)
	end
	local caption = fg:FindFirstChild("ProgressCaption")
	if caption then caption.Visible = false end
	local placeTag = fg:FindFirstChild("PlaceTag")
	if placeTag then placeTag.Visible = false end
	local rightTag = fg:FindFirstChild("RightTag")
	if rightTag then rightTag.Visible = false end
	local edge = root:FindFirstChild("TopEdge")
	if edge then edge.Visible = false end
	local frame = root:FindFirstChild("InnerFrame")
	if frame then frame.Visible = false end
	return true
end

NAmanage._teleportGuiLayoutConns = NAmanage._teleportGuiLayoutConns or setmetatable({}, { __mode = "k" })
NAmanage.TeleportGui_BindResponsiveLayout = function(gui)
	if not gui then return false end
	const root = gui:FindFirstChild("Root")
	if not root then return false end
	local old = NAmanage._teleportGuiLayoutConns[gui]
	if type(old) == "table" then
		for _, connection in old do
			pcall(function() connection:Disconnect() end)
		end
	elseif old then
		pcall(function() old:Disconnect() end)
	end
	NAmanage.TeleportGui_ApplyResponsiveLayout(gui)
	local queued = false
	local sizeConn
	local destroyConn
	const function cleanup()
		if sizeConn then
			pcall(function() sizeConn:Disconnect() end)
			sizeConn = nil
		end
		if destroyConn then
			pcall(function() destroyConn:Disconnect() end)
			destroyConn = nil
		end
		NAmanage._teleportGuiLayoutConns[gui] = nil
	end
	sizeConn = root:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		if queued then return end
		queued = true
		Defer(function()
			queued = false
			if gui and gui.Parent then
				NAmanage.TeleportGui_ApplyResponsiveLayout(gui)
			else
				cleanup()
			end
		end)
	end)
	if gui.Destroying then
		destroyConn = gui.Destroying:Connect(cleanup)
	end
	NAmanage._teleportGuiLayoutConns[gui] = { sizeConn, destroyConn }
	return true
end

NAmanage.TeleportGui_ApplyStaticState = function(gui)
	if not gui then return false end
	const root = gui:FindFirstChild("Root")
	if not root then return false end
	pcall(NAmanage.TeleportGui_ApplyResponsiveLayout, gui)
	const backdrop = root:FindFirstChild("Backdrop")
	const innerFrame = root:FindFirstChild("InnerFrame")
	const innerFrameStroke = innerFrame and innerFrame:FindFirstChildOfClass("UIStroke")
	const foreground = root:FindFirstChild("Foreground")
	const topBrand = foreground and foreground:FindFirstChild("TopBrand")
	const content = foreground and foreground:FindFirstChild("Content")
	const logo = topBrand and topBrand:FindFirstChild("Logo", true)
	const fallback = topBrand and topBrand:FindFirstChild("Fallback", true)
	const brand = topBrand and topBrand:FindFirstChild("Brand", true)
	const subBrand = topBrand and topBrand:FindFirstChild("SubBrand", true)
	const rightTag = foreground and foreground:FindFirstChild("RightTag", true)
	const statusPill = content and content:FindFirstChild("StatusPill")
	const statusDot = statusPill and statusPill:FindFirstChild("StatusDot")
	const actionLabel = statusPill and statusPill:FindFirstChild("Action")
	const destination = content and content:FindFirstChild("Destination")
	const destinationIcon = content and content:FindFirstChild("DestinationIcon")
	const contentStroke = content and content:FindFirstChildOfClass("UIStroke")
	const accent = content and content:FindFirstChild("Accent")
	const info = content and content:FindFirstChild("Info")
	const footer = content and content:FindFirstChild("Footer")
	const progressTrack = foreground and foreground:FindFirstChild("ProgressTrack")
	const runner = progressTrack and progressTrack:FindFirstChild("Runner")
	const progressCaption = foreground and foreground:FindFirstChild("ProgressCaption")
	const placeTag = foreground and foreground:FindFirstChild("PlaceTag")
	const topEdge = root:FindFirstChild("TopEdge")
	if backdrop and backdrop:IsA("ImageLabel") then
		backdrop.ImageTransparency = 0
	end
	if innerFrameStroke then innerFrameStroke.Transparency = 0.78 end
	if topBrand and topBrand:IsA("Frame") then
		topBrand.Position = UDim2.new(0, tonumber(topBrand:GetAttribute("FinalX")) or 52, 0, tonumber(topBrand:GetAttribute("FinalY")) or 88)
	end
	if content and content:IsA("Frame") then
		content.Position = UDim2.new(0.5, 0, 1, tonumber(content:GetAttribute("FinalY")) or -42)
		content.BackgroundTransparency = 0.12
	end
	if contentStroke then contentStroke.Transparency = 0.56 end
	if accent and accent:IsA("Frame") then accent.Visible = false end
	if logo and logo:IsA("ImageLabel") then logo.ImageTransparency = 0 end
	if fallback and fallback:IsA("TextLabel") then fallback.TextTransparency = 0 end
	if brand and brand:IsA("TextLabel") then brand.TextTransparency = 0 end
	if subBrand and subBrand:IsA("TextLabel") then subBrand.TextTransparency = 0.18 end
	if rightTag and rightTag:IsA("TextLabel") then rightTag.TextTransparency = 0.32 end
	if statusPill and statusPill:IsA("Frame") then statusPill.BackgroundTransparency = 0.18 end
	if statusDot and statusDot:IsA("Frame") then statusDot.BackgroundTransparency = 0 end
	if actionLabel and actionLabel:IsA("TextLabel") then actionLabel.TextTransparency = 0 end
	if destination and destination:IsA("TextLabel") then destination.TextTransparency = 0 end
	if destinationIcon and destinationIcon:IsA("ImageLabel") then
		destinationIcon.Visible = true
		destinationIcon.ImageTransparency = 0
	end
	if info and info:IsA("TextLabel") then info.TextTransparency = 0.08 end
	if footer and footer:IsA("TextLabel") then footer.TextTransparency = 0.18 end
	if progressTrack and progressTrack:IsA("Frame") then progressTrack.BackgroundTransparency = 0.58 end
	if runner and runner:IsA("Frame") then
		runner.Position = UDim2.new(0.24, 0, 0, 0)
		runner.BackgroundTransparency = 0
	end
	if progressCaption and progressCaption:IsA("TextLabel") then progressCaption.TextTransparency = 0.16 end
	if placeTag and placeTag:IsA("TextLabel") then placeTag.TextTransparency = 0.28 end
	if topEdge and topEdge:IsA("Frame") then topEdge.BackgroundTransparency = 0.18 end
	return true
end

