	options = type(options) == "table" and options or {}
	const prearm = options.prearm == true
	if NAStuff.CustomTeleportGuiEnabled == false or NAStuff.AntiTeleportHooked == true then
		return nil
	end
	const state = NAmanage.SubplaceViewer
