SpawnCall(function()
	Wait(0.15)
	if not NAStuff.bindersList then
		return
	end
	local layoutOrder = 1
	for _, evName in events do
		const ev = evName
		const HEADER_H = 30

		const binderFrame = InstanceNew("Frame")
