const popular = {
	"DebugFRMQualityLevelOverride", "TextureQualityOverrideEnabled", "TextureQualityOverride",
	"DebugForceMSAASamples", "TaskSchedulerTargetFps", "DebugDynamicRenderKiloPixels",
	"CSGLevelOfDetailSwitchingDistance", "CSGLevelOfDetailSwitchingDistanceL12",
	"CSGLevelOfDetailSwitchingDistanceL23", "CSGLevelOfDetailSwitchingDistanceL34",
	"DisableDPIScale", "HandleAltEnterFullscreenManually", "DebugGraphicsPreferD3D11",
	"DebugGraphicsPreferVulkan", "DebugGraphicsPreferOpenGL",
}

NAFFlags.clientPrefixes = { "DFFlag", "DFInt", "DFString", "DFLog", "FFlag", "FInt", "FString", "FLog", "SFFlag", "SFInt", "SFString", "SFLog" }
NAFFlags.stripClientPrefix = function(name)
	for _, prefix in NAFFlags.clientPrefixes do
		if Sub(name, 1, #prefix) == prefix then
			return Sub(name, #prefix + 1)
		end
	end
	return name
end

const entries = {}
for _, entry in NAFFlags.whitelist do
	entries[entry.name] = entry
end
for _, group in groups do
	for _, row in group.flags do
		const key, label, default, hint, startup = table.unpack(row, 1, 5)
		const name = NAFFlags.stripClientPrefix(key)
		local entry = entries[name]
		if not entry then
			entry = { name = name, valueType = type(default) }
			entries[name] = entry
			Insert(NAFFlags.whitelist, entry)
		end
		entry.clientKey = key
		entry.label = label
		entry.default = default
		entry.hint = hint
		entry.startup = startup
	end
end

const backends = { "DebugGraphicsPreferD3D11", "DebugGraphicsPreferD3D11FL10", "DebugGraphicsPreferVulkan", "DebugGraphicsPreferOpenGL" }
entries.DebugGraphicsPreferD3D11FL10.startup = true
entries.DebugGraphicsDisableDirect3D11.startup = true

const ranges = {
	DebugFRMQualityLevelOverride = { 0, 21 },
	TextureQualityOverride = { 0, 3 },
	FRMMinGrassDistance = { 0, 10000 },
	FRMMaxGrassDistance = { 0, 10000 },
	TaskSchedulerTargetFps = { 1, 1000 },
	DebugDynamicRenderKiloPixels = { 0, 16000 },
	DebugTextureManagerSkipMips = { -1, 8 },
	CSGLevelOfDetailSwitchingDistance = { 0, 10000 },
	CSGLevelOfDetailSwitchingDistanceL12 = { 0, 10000 },
	CSGLevelOfDetailSwitchingDistanceL23 = { 0, 10000 },
	CSGLevelOfDetailSwitchingDistanceL34 = { 0, 10000 },
	RobloxGuiBlurIntensity = { 0, 56 },
	FontSizePadding = { -20, 20 },
	GrassMovementReducedMotionFactor = { 0, 100 },
	Network = { 0, 7 },
	WindowsWebViewTelemetryThrottleHundredthsPercent = { 0, 10000 },
	ClientLightingTechnologyChangedTelemetryHundredthsPercent = { 0, 10000 },
}

const function trim(raw)
	return (tostring(raw or ""):match("^%s*(.-)%s*$"))
end

NAFFlags.parseCustomValue = function(raw)
	if type(raw) ~= "string" then
		return raw
	end
	const text = trim(raw)
	const lower = Lower(text)
	if lower == "true" then
		return true
	elseif lower == "false" then
		return false
	end
	return tonumber(text) or text
end

const function norm(entry, raw)
	if entry and entry.valueType == "string" then
		return type(raw) == "string" and raw or nil
	end
	const value = NAFFlags.parseCustomValue(raw)
	if entry and entry.valueType == "boolean" then
		if type(value) == "boolean" then return value end
	elseif entry and entry.valueType == "number" then
		if type(value) == "number" and value % 1 == 0 and value >= -2147483648 and value <= 2147483647 then
			return value
		end
	elseif type(value) == "string" or type(value) == "boolean" or (type(value) == "number" and math.abs(value) < math.huge) then
		return value
	end
	return nil
end

const function isManagedName(name)
	return name:match("^[%a_][%w_]*$") ~= nil
		and name ~= NAgui.SCREEN_GUI_NO_RENDER_FLAG
		and name ~= "DebugPauseVoxelizer"
		and name ~= "DebugRenderingSetDeterministic"
end

const function addValue(cfg, rawName, rawValue)
	const key = trim(rawName)
	const name = NAFFlags.stripClientPrefix(key)
	if not isManagedName(name) then
		return false
	end
	const entry = entries[name]
	const value = norm(entry, rawValue)
	if value == nil then
		return false
	end
	if entry then
		cfg.flags[name] = value
		cfg.enabledFlags[name] = true
	else
		cfg.custom[name] = value
	end
	if key ~= name then
		cfg.clientKeyAliases[name] = key
	end
	return true
end

const function newValues()
	return { flags = {}, custom = {}, enabledFlags = {}, clientKeyAliases = {} }
end

const cfg = newValues()
cfg.useFFlags = false
cfg.autoApply = false
cfg.autoApplyLoop = false
cfg.autoApplyInterval = 3
cfg.applyWhitelistOnly = false
cfg.favorites = {}
NAFFlags.config = cfg
NAFFlags.filePath = NAfiles.NAFFLAGSPATH or (NAfiles.NAFILEPATH.."/NAFFlags.json")
NAFFlags.metaPath = NAfiles.NAFFLAGSCONFIGPATH or (NAfiles.NAFILEPATH.."/NAFFlagsConfig.json")

const function decode(raw)
	const ok, data = pcall(Services.HttpService.JSONDecode, Services.HttpService, raw)
	return ok and type(data) == "table" and data or nil
end

const function readJson(path)
	if not FileSupport then return nil end
	const ok, raw = pcall(readfile, path)
	return ok and type(raw) == "string" and decode(raw) or nil
end

const function readSaved()
	const saved = readJson(NAFFlags.filePath)
	const legacy = saved and (type(saved.flags) == "table" or type(saved.custom) == "table" or type(saved.enabledFlags) == "table"
		or type(saved.useFFlags) == "boolean" or type(saved.autoApply) == "boolean")
	local meta = readJson(NAFFlags.metaPath)
	if legacy then
		meta = meta or {}
		for key, value in saved do
			meta[key] = value
		end
	end
	if meta then
		for _, key in { "useFFlags", "autoApply", "autoApplyLoop", "applyWhitelistOnly" } do
			if type(meta[key]) == "boolean" then
				cfg[key] = meta[key]
			end
		end
		const interval = tonumber(meta.autoApplyInterval)
		cfg.autoApplyInterval = interval and interval == interval and math.clamp(interval, 0.1, 60) or 3
		if type(meta.flags) == "table" then
			for name, raw in meta.flags do
				const entry = entries[name]
				if entry and isManagedName(name) then
					cfg.flags[name] = norm(entry, raw)
				end
			end
		end
		if legacy and type(meta.enabledFlags) == "table" then
			for name, enabled in meta.enabledFlags do
				const entry = entries[name]
				if enabled == true and entry and isManagedName(name) then
					cfg.enabledFlags[name] = true
					if cfg.flags[name] == nil and entry.valueType == "boolean" then
						cfg.flags[name] = false
					end
				end
			end
		end
		if type(meta.clientKeyAliases) == "table" then
			for name, key in meta.clientKeyAliases do
				if type(name) == "string" and type(key) == "string" and NAFFlags.stripClientPrefix(key) == name then
					cfg.clientKeyAliases[name] = key
				end
			end
		end
		if type(meta.favorites) == "table" then
			for name, key in meta.favorites do
				if type(name) == "string" and type(key) == "string" and isManagedName(name)
					and NAFFlags.stripClientPrefix(key) == name then
					cfg.favorites[name] = key
				end
			end
		end
	end
	const values = legacy and saved.custom or (not legacy and saved)
	if type(values) == "table" then
		local any = false
		for key, value in values do
			if type(key) == "string" then
				any = addValue(cfg, key, value) or any
			end
		end
		if not meta and any then
			cfg.useFFlags = true
		end
	end
end

const function normalizeBackends(prefer)
	local active = nil
	if prefer and cfg.enabledFlags[prefer] and cfg.flags[prefer] == true then
		active = prefer
	end
	for _, name in backends do
		if cfg.enabledFlags[name] and cfg.flags[name] == true then
			if active and active ~= name then
				cfg.flags[name] = false
			else
				active = name
			end
		end
	end
end

readSaved()
normalizeBackends()

const function flagValue(entry)
	const saved = cfg.flags[entry.name]
	if saved ~= nil then
		return saved
	end
	return entry.default
end

const prefixes = { boolean = "FFlag", number = "FInt", string = "FString" }

const function makeJson(withCustom)
	const out = {}
	for _, entry in NAFFlags.whitelist do
		if cfg.enabledFlags[entry.name] then
			const prefix = prefixes[entry.valueType]
			const key = entry.clientKey or cfg.clientKeyAliases[entry.name] or prefix..entry.name
			const value = flagValue(entry)
			out[key] = type(value) == "boolean" and (value and "True" or "False") or tostring(value)
		end
	end
	if withCustom then
		for name, value in cfg.custom do
			const key = cfg.clientKeyAliases[name] or name
			out[key] = type(value) == "boolean" and (value and "True" or "False") or tostring(value)
		end
	end
	return Services.HttpService:JSONEncode(out)
end

const function saveMeta()
	if not FileSupport then return end
	const ok, json = pcall(Services.HttpService.JSONEncode, Services.HttpService, {
		useFFlags = cfg.useFFlags,
		autoApply = cfg.autoApply,
		autoApplyLoop = cfg.autoApplyLoop,
		autoApplyInterval = cfg.autoApplyInterval,
		applyWhitelistOnly = cfg.applyWhitelistOnly,
		clientKeyAliases = cfg.clientKeyAliases,
		flags = cfg.flags,
		favorites = cfg.favorites,
	})
	if not ok or not pcall(writefile, NAFFlags.metaPath, json) then
		DoNotif("Could not save FastFlag settings.", 4)
	end
end

NAFFlags.save = function()
	if not FileSupport then return end
	const ok, json = pcall(makeJson, true)
	if not ok or not pcall(writefile, NAFFlags.filePath, json) then
		DoNotif("Could not save FastFlag overrides.", 4)
		return
	end
	saveMeta()
end

const getter = type(getfflag) == "function" and getfflag or getfastflag
const setter = type(setfflag) == "function" and setfflag or setfastflag
const getType = type(getfflagtype) == "function" and getfflagtype or getfastflagtype
const avail = {}
const applied = {}
const original = {}

NAFFlags.hasSupport = function()
	return type(setter) == "function"
end

const function readFlag(name)
	if type(getter) ~= "function" then return nil end
	const ok, value = pcall(getter, name)
	if ok and value ~= nil then
		return tostring(value)
	end
	return nil
end

NAFFlags.isFlagAvailable = function(rawName)
	const name = NAFFlags.stripClientPrefix(rawName)
	if avail[name] == nil then
		if type(getter) == "function" then
			avail[name] = readFlag(name) ~= nil
		elseif type(getType) == "function" then
			const ok, kind = pcall(getType, name)
			avail[name] = ok and type(kind) == "string" and kind ~= "" and kind ~= "invalid" and kind ~= "unknown"
		end
	end
	return avail[name]
end

const function sameFlag(a, b)
	if a == b then return true end
	if a == nil or b == nil then return false end
	const low = Lower(b)
	return (low == "true" or low == "false") and Lower(a) == low
end

const function writeFlag(name, value)
	const ok, ret = pcall(setter, name, value)
	if not ok or ret == false then
		return false, ok and "Executor rejected the override" or tostring(ret)
	end
	if type(getter) == "function" and not sameFlag(readFlag(name), value) then
		return false, "Client did not accept the value"
	end
	return true
end

NAFFlags.apply = function(rawName, value, opts)
	opts = opts or {}
	if not cfg.useFFlags and not opts.allowDisabled then
		return false, "FastFlags are disabled"
	end
	if not NAFFlags.hasSupport() then
		return false, "setfflag is unavailable"
	end
	const name = NAFFlags.stripClientPrefix(trim(rawName))
	if not name:match("^[%a_][%w_]*$") or value == nil then
		return false, "Invalid flag name or value"
	end
	if NAFFlags.isFlagAvailable(name) == false then
		return false, "Flag unavailable on this client"
	end
	const text = tostring(value)
	const current = readFlag(name)
	if sameFlag(current, text) or (type(getter) ~= "function" and applied[name] == text) then
		return true
	end
	const ok, err = writeFlag(name, text)
	if ok then
		if applied[name] == nil or (current ~= nil and not sameFlag(current, applied[name])) then
			original[name] = current
		end
		applied[name] = text
	elseif current ~= nil then
		const after = readFlag(name)
		if after ~= nil and not sameFlag(after, current) then
			writeFlag(name, current)
		end
	end
	return ok, err
end

const function restore(name)
	const last = applied[name]
	if last == nil then return true end
	const current = readFlag(name)
	const old = original[name]
	if current == nil or old == nil then return false end
	if sameFlag(current, last) and not writeFlag(name, old) then
		return false
	end
	applied[name] = nil
	original[name] = nil
	return true
end

const function restoreAll()
	local failed = 0
	for name in applied do
		if not restore(name) then
			failed += 1
		end
	end
	return failed
end

const function getTargets()
	const names = {}
	for _, entry in NAFFlags.whitelist do
		if cfg.enabledFlags[entry.name] and not entry.startup then
			Insert(names, entry.name)
		end
	end
	if not cfg.applyWhitelistOnly then
		for name in cfg.custom do
			Insert(names, name)
		end
	end
	return names
end

const function targetValue(name)
	const entry = entries[name]
	if entry then
		if cfg.enabledFlags[name] and not entry.startup then
			return flagValue(entry)
		end
	elseif not cfg.applyWhitelistOnly then
		return cfg.custom[name]
	end
	return nil
end

NAFFlags.applyAll = function(opts)
	const notify = not opts or opts.notify ~= false
	if not cfg.useFFlags or not NAFFlags.hasSupport() then
		if notify then
			DoNotif(cfg.useFFlags and "setfflag is unavailable." or "Turn on Use FastFlags first.", 3)
		end
		return 0, false
	end
	local count, total = 0, 0
	const work = {}
	for _, name in getTargets() do
		if not cfg.useFFlags then break end
		const value = targetValue(name)
		if value ~= nil then
			total += 1
			if NAFFlags.apply(name, value) then count += 1 end
		end
		NAmanage.WorkBudgetStep(work, 4, 0.002)
	end
	if notify then
		DoNotif(Format("Applied %d of %d runtime overrides.", count, total), 3)
	end
	return count, true
end

local loop
const function stopLoop()
	if loop then
		task.cancel(loop)
		loop = nil
	end
end

const function queueLoop()
	if loop or NAStuff._unloading or not (cfg.useFFlags and cfg.autoApply and cfg.autoApplyLoop and NAFFlags.hasSupport()) then
		return
	end
	loop = task.delay(cfg.autoApplyInterval, function()
		loop = nil
		NAFFlags.applyAll({ notify = false })
		queueLoop()
	end)
end

NAmanage.RegisterUnloadCleanup("FastFlags", function()
	cfg.useFFlags = false
	stopLoop()
	restoreAll()
end)

const savedLabel = "Saved Advanced Overrides"
const nameLabel = "Custom Flag Name"
const valueLabel = "Custom Flag Value"
const listLabel = "FastFlag List"
const pickLabel = "Selected FastFlag"
const quickLabel = "Selected Flag Value"
const noFlag = "(None)"
local selected
local editName, editValue = "", ""
local view = "Popular"
local picked, flagInfo
local draft = ""

const function controlValue(entry)
	if not cfg.enabledFlags[entry.name] then return "Default" end
	const value = flagValue(entry)
	if entry.valueType == "boolean" then
		return value and "On" or "Off"
	end
	return tostring(value)
end

const function flagKey(name)
	const entry = entries[name]
	return (entry and entry.clientKey) or cfg.clientKeyAliases[name] or cfg.favorites[name] or name
end

const function syncPicked()
	const entry = picked and entries[picked]
	const value = picked and cfg.custom[picked]
	draft = entry and controlValue(entry) or (value == nil and "Default" or tostring(value))
	if not picked then draft = "" end
	NAgui.setInputValue(quickLabel, draft, { fire = false })
	if flagInfo then
		local text = picked and flagKey(picked) or "Select a flag from the list."
		if entry and entry.hint then text ..= "\n"..entry.hint end
		if flagInfo.Text ~= text then flagInfo.Text = text end
	end
end

const function syncPicker()
	const options = { { value = noFlag, display = "Select a flag" } }
	local found = false
	const function add(name)
		const entry = entries[name]
		const label = entry and entry.label or name
		Insert(options, { value = name, display = (cfg.favorites[name] and "★ " or "")..label })
		found = found or name == picked
	end
	if view == "Favorites" then
		const names = {}
		for name in cfg.favorites do Insert(names, name) end
		table.sort(names)
		for _, name in names do add(name) end
	elseif view == "Popular" then
		for _, name in popular do add(name) end
	else
		for _, group in groups do
			for _, row in group.flags do add(NAFFlags.stripClientPrefix(row[1])) end
		end
	end
	if not found then
		picked = nil
		syncPicked()
	end
	NAgui.setDropdownOptions(pickLabel, options)
	NAgui.setDropdownValue(pickLabel, picked or noFlag, { fire = false })
end

const function toggleFavorite(raw)
	const key = trim(raw)
	const name = NAFFlags.stripClientPrefix(key)
	if not isManagedName(name) then
		DoNotif("Select or enter a valid flag name first.", 3)
		return
	end
	local added = false
	if cfg.favorites[name] then
		cfg.favorites[name] = nil
	else
		cfg.favorites[name] = key ~= name and key or flagKey(name)
		added = true
	end
	saveMeta()
	syncPicker()
	DoNotif(added and "Added to FastFlag favorites." or "Removed from FastFlag favorites.", 2)
end

const function syncControls()
	NAgui.setToggleState("Use FastFlags", cfg.useFFlags, { fire = false })
	for _, group in groups do
		for _, row in group.flags do
			const entry = entries[NAFFlags.stripClientPrefix(row[1])]
			const value = controlValue(entry)
			if entry.valueType == "boolean" then
				NAgui.setDropdownValue(entry.label, value, { fire = false })
			else
				NAgui.setInputValue(entry.label, value, { fire = false })
			end
		end
	end
	const names = {}
	for name in cfg.custom do Insert(names, name) end
	for name, enabled in cfg.enabledFlags do
		if enabled and (not entries[name].label or avail[name] == false) then
			Insert(names, name)
		end
	end
	table.sort(names)
	if #names == 0 then Insert(names, "None") end
	if not table.find(names, selected) then selected = nil end
	NAgui.setDropdownOptions(savedLabel, names)
	NAgui.setDropdownValue(savedLabel, selected or names[1], { fire = false })
	syncPicked()
end

NAFFlags.setCustomFlag = function(rawName, value)
	const name = NAFFlags.stripClientPrefix(trim(rawName))
	if not addValue(cfg, rawName, value) then
		return false, "Invalid flag name or value"
	end
	if table.find(backends, name) then normalizeBackends(name) end
	NAFFlags.save()
	syncControls()
	return true
end

const function applyEntry(entry)
	if not cfg.useFFlags or not cfg.enabledFlags[entry.name] then return end
	if entry.startup then
		DoNotif("Saved for export. Set it in ClientAppSettings before launching Roblox.", 3)
		return
	end
	const ok, err = NAFFlags.apply(entry.name, flagValue(entry))
	if not ok then DoNotif((entry.label or entry.name).." — "..tostring(err), 3) end
end

const function saveControl(name, raw)
	if type(raw) == "table" then raw = raw[1] end
	const choice = Lower(trim(raw))
	if choice == "" or choice == "default" then
		cfg.enabledFlags[name] = nil
		cfg.custom[name] = nil
		if not restore(name) then DoNotif("Restart Roblox to clear this override.", 3) end
		NAFFlags.save()
		syncControls()
		return
	end

	const entry = entries[name]
	local value = norm(entry, raw)
	if entry and entry.valueType == "boolean" and (choice == "on" or choice == "off") then
		value = choice == "on"
	end
	const range = ranges[name]
	if value == nil or (range and (value < range[1] or value > range[2]))
		or (name == "DebugForceMSAASamples" and not table.find({ 1, 2, 4, 8 }, value)) then
		DoNotif("Enter "..((entry and entry.hint) or "On, Off, or Default")..".", 3)
		syncControls()
		return
	end
	addValue(cfg, flagKey(name), value)
	if table.find(backends, name) then normalizeBackends(name) end
	NAFFlags.save()
	if entry then
		applyEntry(entry)
	elseif cfg.useFFlags and not cfg.applyWhitelistOnly then
		const ok, err = NAFFlags.apply(name, value)
		if not ok then DoNotif(tostring(err), 3) end
	end
	syncControls()
end

const function preset(title, items)
	local saved, appliedCount = 0, 0
	for _, item in items do
		const name, value = item[1], item[2]
		if NAFFlags.isFlagAvailable(name) == true and addValue(cfg, name, value) then
			cfg.useFFlags = true
			saved += 1
			if NAFFlags.apply(name, value) then appliedCount += 1 end
		end
	end
	if saved == 0 then
		DoNotif("This client has no matching flags for "..title..".", 3)
		return
	end
	NAFFlags.save()
	syncControls()
	queueLoop()
	DoNotif(Format("%s applied %d of %d supported overrides.", title, appliedCount, saved), 3)
end

const function importText(raw)
	const decoded = type(raw) == "string" and decode(raw)
	const nextCfg = newValues()
	local count = 0
	for key, value in decoded or {} do
		if type(key) == "string" and addValue(nextCfg, key, value) then
			count += 1
		end
	end
	if count == 0 then
		DoNotif("No valid FastFlags found in the JSON.", 3)
		return
	end
	restoreAll()
	for key, value in nextCfg do
		cfg[key] = value
	end
	normalizeBackends()
	cfg.useFFlags = true
	NAFFlags.save()
	syncControls()
	if cfg.autoApply then
		NAFFlags.applyAll({ notify = false })
		queueLoop()
	end
	DoNotif(Format("Imported %d FastFlags.", count), 3)
end

const function restoreSession()
	cfg.useFFlags = false
	stopLoop()
	const failed = restoreAll()
	NAFFlags.save()
	if failed > 0 then
		DoNotif(Format("%d overrides could not be restored. Restart Roblox to clear them.", failed), 4)
	else
		DoNotif("Session overrides restored.", 2)
	end
end

