		local function queueUsersListRefresh()
			NAChat.usersViewCache.dirty = true
			NAChat.usersViewCache.pending = true
			NAChat.usersUpdateGeneration += 1
			if NAChat.queuedUsersRefresh or NAChat.usersViewportQueued or NAChat.usersViewCache.rendering then return end
			NAChat.queuedUsersRefresh = true
			Defer(function()
				NAChat.usersViewCache.pending = false
				if type(updateUsersList)=="function" and not isChatUiSuppressed() and NAChat.activeTab=="users" then updateUsersList(NAChat.users or {}) end
				NAChat.queuedUsersRefresh = false
				if NAChat.usersViewCache.pending then queueUsersListRefresh() end
			end)
		end

		local function queueUsersViewportRefresh()
			NAChat.usersViewCache.pending = true
			NAChat.usersUpdateGeneration += 1
			if NAChat.queuedUsersRefresh or NAChat.usersViewportQueued or NAChat.usersViewCache.rendering then return end
			NAChat.usersViewportQueued = true
			Defer(function()
				NAChat.usersViewCache.pending = false
				if type(updateUsersList)=="function" and not isChatUiSuppressed() and NAChat.activeTab=="users" then updateUsersList(NAChat.users or {}) end
				NAChat.usersViewportQueued = false
				if NAChat.usersViewCache.pending then queueUsersViewportRefresh() end
			end)
		end

		local function queueStatusLabelRefresh()
			if NAChat.queuedStatusRefresh then
				return
			end
			NAChat.queuedStatusRefresh = true
			Delay(0.1, function()
				NAChat.queuedStatusRefresh = false
				if type(updateStatusLabel) == "function" then
					updateStatusLabel()
				end
			end)
		end

		local function getVerifiedUsernameCached(userId)
			if type(userId) ~= "number" then
				return nil
			end
			local cached = NAChat.verifiedNameCache[userId]
			if type(cached) == "string" and cached ~= "" then
				return cached
			end
			return nil
		end

		local function fetchVerifiedUsernameAsync(userId)
			if type(userId) ~= "number" or userId <= 0 then
				return
			end
			if getVerifiedUsernameCached(userId) then
				return
			end
			if NAChat.verifiedNameFetchInFlight[userId] then
				return
			end
			NAChat.verifiedNameFetchInFlight[userId] = true
			Spawn(function()
				local ok, name = pcall(function()
					return Players:GetNameFromUserIdAsync(userId)
				end)
				if ok and type(name) == "string" and name ~= "" then
					NAChat.verifiedNameCache[userId] = name
				end
				NAChat.verifiedNameFetchInFlight[userId] = nil
				queueUsersListRefresh()
				queueStatusLabelRefresh()
			end)
		end

		local function getVerifiedUsername(userId, fallback)
			local cached = getVerifiedUsernameCached(userId)
			if cached then
				return cached
			end
			local fallbackText = tostring(fallback or "")
			if type(userId) == "number"
				and (fallbackText == "" or fallbackText == tostring(userId) or fallbackText == "Unknown") then
				fetchVerifiedUsernameAsync(userId)
			end
			return fallback
		end

		local function getVerifiedUsernameBlocking(userId, fallback)
			local cached = getVerifiedUsernameCached(userId)
			if cached then
				return cached
			end
			if type(userId) ~= "number" or userId <= 0 then
				return fallback
			end
			local ok, name = pcall(function()
				return Players:GetNameFromUserIdAsync(userId)
			end)
			if ok and type(name) == "string" and name ~= "" then
				NAChat.verifiedNameCache[userId] = name
				return name
			end
			return fallback
		end

		updateStatusLabel = function()
			if not statusLabel then
				return
			end

			local now = os.clock()
			local names = {}

			local seen = {}

			for name, expires in NAChat.typingUsersByName do
				if type(expires) ~= "number" or expires <= now then
					NAChat.typingUsersByName[name] = nil
				else
					local display = tostring(name)
					if display ~= "" and not seen[display] then
						seen[display] = true
						Insert(names, display)
					end
				end
			end

			for userId, expires in NAChat.typingUsersById do
				if type(expires) ~= "number" or expires <= now then
					NAChat.typingUsersById[userId] = nil
				else
					local display = getVerifiedUsername(userId, tostring(userId))
					if display ~= "" and not seen[display] then
						seen[display] = true
						Insert(names, display)
					end
				end
			end

			local text = baseStatusText or ""
			if #names > 0 then
				local who
				if #names == 1 then
					who = names[1]
				elseif #names == 2 then
					who = names[1].." and "..names[2]
				else
					who = names[1].." and others"
				end
				if text ~= "" then
					text = text.."  •  "
				end
				text = text..who.." is typing..."
			end

			statusLabel.Text = text
			statusLabel.TextColor3 = baseStatusColor or statusLabel.TextColor3
			const settingsStatus = NAStuff.NAChatRuntime and NAStuff.NAChatRuntime.SettingsStatus
			if settingsStatus then
				settingsStatus.Text = baseStatusText or ""
				settingsStatus.TextColor3 = statusLabel.TextColor3
			end
		end

		local function normalizeRichTextEntities(text)
			text = tostring(text or "")
			if text == "" then
				return text
			end
			text = text:gsub("&amp;lt;", "&lt;")
			text = text:gsub("&amp;gt;", "&gt;")
			text = text:gsub("&amp;quot;", "&quot;")
			text = text:gsub("&amp;apos;", "&apos;")
			text = text:gsub("&amp;amp;", "&amp;")
			return text
		end

		local function formatMessageWithMentions(rawText)
			local plain = tostring(rawText or "")
			if plain == "" then
				return "", false
			end

			local safe = originalIO.escapeRichTextText and originalIO.escapeRichTextText(plain) or plain
			safe = normalizeRichTextEntities(safe)

			local lp = Players.LocalPlayer
			if not lp then
				return safe, false
			end

			local lowerNames = {}
			lowerNames[Lower(lp.Name)] = true
			local disp = lp.DisplayName
			if disp and disp ~= "" then
				lowerNames[Lower(disp)] = true
			end

			local wasMentioned = false

			local function repl(token)
				local namePart = token:sub(2)
				if lowerNames[Lower(namePart)] then
					wasMentioned = true
					return '<font color="#FFD966">'..token..'</font>'
				end
				return token
			end

			local withMarkup = safe:gsub("(@[%w_]+)", repl)
			return withMarkup, wasMentioned
		end

