		updateUsersList = function(list)
			if NAChat.usersViewCache.rendering then
				NAChat.usersUpdateGeneration += 1
				NAChat.usersViewCache.pendingList = list
				return
			end
			NAChat.usersViewCache.rendering = true
			const ok,err = pcall(NAmanage.NAChat_RenderUsersList,list)
			NAChat.usersViewCache.rendering = false
			if not ok then warn("[NA Chat] User render failed:",tostring(err)) end
			const pending = NAChat.usersViewCache.pendingList
			NAChat.usersViewCache.pendingList = nil
			if pending then
				Defer(function() updateUsersList(pending) end)
			elseif NAChat.usersViewCache.pending and not NAChat.queuedUsersRefresh and not NAChat.usersViewportQueued then
				queueUsersViewportRefresh()
			end
		end

