			if NAUIMANAGER.NAchatMessageBar then NAUIMANAGER.NAchatMessageBar.Visible = tab == "chat" end
			if tab ~= "chat" and inputBox and inputBox:IsFocused() then inputBox:ReleaseFocus() end
