					if NAChat.activeGroupId and not NAChat.groupRecords[tostring(NAChat.activeGroupId)] then
						NAChat.switchConversation(nil)
					elseif NAChat.refreshGroupPicker then
						NAChat.refreshGroupPicker()
					end
				end)
			end

			if NAChat.service.OnGroupUpdated then
				NAChat.service.OnGroupUpdated.Event:Connect(function(group)
					if type(group) ~= "table" or not group.id then
