					local id = tostring(group.id)
					if not NAChat.pendingGroupInvites[id] then
						NAChat.pendingGroupInviteOrder[#NAChat.pendingGroupInviteOrder + 1] = id
					end
					NAChat.pendingGroupInvites[id] = group
					if NAChat.refreshGroupInvitePrompt then
						NAChat.refreshGroupInvitePrompt()
					end
