			NAChat.service.OnUserListUpdate.Event:Connect(function(list)
				if NAChat.serverIsAdmin and NAChat.service and NAChat.service.OnUserListUpdateAdmin then
					NAChat.usersFetchInFlight = false
					return
				end
				NAChat.users = list or {}
				for _, info in NAChat.users do NAmanage.StreamerTrackIdentity(info) end
				NAChat.usersFetchInFlight = false
				NAChat.lastUsersUpdateAt = os.clock()

				local newSig = makeUserSignature(NAChat.users)
				local changed = (newSig ~= NAChat.lastUserSig)
				NAChat.lastUserSig = newSig

				refreshStatus()

				local newSet, reliable = buildServerSet(NAChat.users)
				updateServerJoinState(newSet, reliable)

				if NAChat.currentDMTarget then
					local stillHere = false
					for _, info in NAChat.users or {} do
						if type(info) == "table" then
							local uid = tonumber(info.userId)
							local uname = getVerifiedUsername(uid, tostring(info.username or ""))
							if uname == NAChat.currentDMTarget then
								stillHere = true
								break
							end
						end
					end
					if not stillHere then
						local hadTarget = NAChat.currentDMTarget ~= nil
						NAChat.currentDMTarget = nil
						if inputBox then
							inputBox.PlaceholderText = "Send a message (/w name)..."
						end
						if hadTarget then
							originalIO.setStatus("NA Chat: DM target left", STATUS_COLORS.info)
						end
					end
				end

				if changed and not isChatUiSuppressed() and NAChat.activeTab == "users" then
					queueUsersListRefresh()
				end
			end)

			if NAChat.service.OnUserListUpdateAdmin then
				NAChat.service.OnUserListUpdateAdmin.Event:Connect(function(list)
					if not NAChat.serverIsAdmin then
						NAChat.usersFetchInFlight = false
						return
					end
					NAChat.users = list or {}
					for _, info in NAChat.users do NAmanage.StreamerTrackIdentity(info) end
					NAChat.usersFetchInFlight = false
					NAChat.lastUsersUpdateAt = os.clock()

					local newSig = makeUserSignature(NAChat.users)
					local changed = (newSig ~= NAChat.lastUserSig)
					NAChat.lastUserSig = newSig

					refreshStatus()

					local newSet, reliable = buildServerSet(NAChat.users)
					updateServerJoinState(newSet, reliable)

					if NAChat.currentDMTarget then
						local stillHere = false
						for _, info in NAChat.users or {} do
							if type(info) == "table" then
								local uid = tonumber(info.userId)
								local uname = getVerifiedUsername(uid, tostring(info.username or ""))
								if uname == NAChat.currentDMTarget then
									stillHere = true
									break
								end
							end
						end
						if not stillHere then
							local hadTarget = NAChat.currentDMTarget ~= nil
							NAChat.currentDMTarget = nil
							if inputBox then
								inputBox.PlaceholderText = "Send a message (/w name)..."
							end
							if hadTarget then
								originalIO.setStatus("NA Chat: DM target left", STATUS_COLORS.info)
							end
						end
					end

					if changed and not isChatUiSuppressed() and NAChat.activeTab == "users" then
						queueUsersListRefresh()
					end
				end)
			end

			if NAChat.service.OnRemoteCommand then
				NAChat.service.OnRemoteCommand.Event:Connect(function(fromId, fromName, argList, target)
					local lp = Players.LocalPlayer
					if not lp then
						return
					end
					local myId = lp.UserId

					local runForMe = false
					if target == nil or target == "" or target == "all" then
						runForMe = true
					else
						local tNum = tonumber(target)
						if tNum and tNum == myId then
							runForMe = true
						end
					end

					if not runForMe then
						return
					end

					if type(argList) ~= "table" or #argList == 0 then
						return
					end

					local args = {}
					for i, v in argList do
						args[i] = tostring(v)
					end

					SpawnCall(function()
						local ok = pcall(function()
							cmd.run(args)
						end)
					end)
				end)
			end

			NAChat.service.OnConnected.Event:Connect(function(name, _, hidden, _, isAdmin)
				resetReconnectBackoff()
				NAChat.connecting = false
				NAChat.serverIsAdmin = (isAdmin == true)
				if type(refreshAdminTabUI) == "function" then
					refreshAdminTabUI()
				end
				if refreshAdminAppearanceSettingsUI then
					pcall(refreshAdminAppearanceSettingsUI)
				end
				NAChat.isHidden = hidden or false
				originalIO.setHiddenState(NAChat.isHidden, true)
				local lp = Players.LocalPlayer
				local myName = (lp and lp.Name) or tostring(name or "?")
				appendConversationMessage("public", ("[NA Chat] Connected as %s"):format(myName), STATUS_COLORS.ok)
				local activityEnabled = true
				if type(_G.NAChatGameActivityEnabled) == "function" then
					local okActivity, savedActivity = pcall(_G.NAChatGameActivityEnabled)
					if okActivity and type(savedActivity) == "boolean" then
						activityEnabled = savedActivity
					end
				end
				if refreshGameActivityButton then
					refreshGameActivityButton(activityEnabled)
				end
				if NAChat.service and type(NAChat.service.SetActivityHidden) == "function" then
					pcall(NAChat.service.SetActivityHidden, not activityEnabled)
				end
				requestUsersList()
				if NAChat.service.RequestGroups then
					pcall(NAChat.service.RequestGroups)
				end
				refreshStatus()
			end)

			NAChat.service.OnDisconnected.Event:Connect(function()
				NAChat.connecting = false
				NAChat.serverIsAdmin = false
				if type(refreshAdminTabUI) == "function" then
					refreshAdminTabUI()
				end
				if NAChat.bannedFromChat then
					refreshStatus()
					return
				end
				if isChatDisconnectedPreference() then
					originalIO.setStatus("NA Chat: Disconnected (disabled)", STATUS_COLORS.info)
					return
				end
				appendConversationMessage("public", "[NA Chat] Disconnected", STATUS_COLORS.err)
				refreshStatus()
				queueReconnect("disconnected")
			end)

			NAChat.service.OnError.Event:Connect(function(err, _, data)
				local errText = tostring(err or "Unknown error")
				local isBan = isBanMessage(errText)
				local isMute = false
				if type(data) == "table" and (data.code == "muted" or data.error == "muted") then
					isMute = true
					local untilEpoch = tonumber(data["until"] or data.muted_until or data.mutedUntil)
					if untilEpoch and untilEpoch > 0 then
						NAChat.muteUntil = untilEpoch
						local r = tostring(data.reason or "")
						NAChat.muteReason = r ~= "" and r or nil
						ensureMuteCountdown()
					end
				elseif isMuteMessage(errText) then
					isMute = true
				end
				if isBan then
					markBannedState()
				elseif isMute then
					local left = getMuteRemainingSeconds()
					local text = "NA Chat: Muted"
					if left then
						text = text.." ("..formatDurationSeconds(left).." left)"
					end
					if type(NAChat.muteReason) == "string" and NAChat.muteReason ~= "" then
						text = text.." - "..NAChat.muteReason
					end
					originalIO.setStatus(text, STATUS_COLORS.err)
				else
					originalIO.setStatus("NA Chat error", STATUS_COLORS.err)
				end
				local msg = "[NA Chat] "..errText
				local now = os.clock()
				if lastErrText ~= msg or (now - (lastErrTime or 0)) > 15 then
					lastErrText, lastErrTime = msg, now
					appendConversationMessage("public", msg, STATUS_COLORS.err)
					if isBan then
						NAChat.banNoticeShown = true
					end
				end
				refreshStatus()
			end)
		end

		NAChat.resolveEndpoint = function()
			local override = type(__NAChatEnv) == "table" and rawget(__NAChatEnv, "NAChatServerUrl")
			if type(override) == "string" and override ~= "" then
				return override
			end
			local url = type(__NAChatEnv) == "table" and rawget(__NAChatEnv, "NAChatEndpointConfigUrl")
			if type(url) ~= "string" or url == "" then
				url = "https://gitlab.com/ltseverydayyou/Open-Cheating-Network/-/raw/main/Client/endpoint.txt"
			end
			local suffix = url:find("?", 1, true) and "&" or "?"
			local ok, body = NAAssetsLoading.httpGetNoSkipWithTimeout(url..suffix.."na_endpoint="..tostring(os.time()).."-"..tostring(os.clock()), 8)
			if not ok or type(body) ~= "string" then
				return nil
			end
			for line in body:gmatch("[^\r\n]+") do
				line = line:gsub("^%s+", ""):gsub("%s+$", "")
				if line ~= "" and line:sub(1, 1) ~= "#" then
					line = line:gsub("^https://", "wss://"):gsub("^http://", "ws://"):gsub("/healthz/?$", ""):gsub("/+$", "")
					if not line:match("^wss?://[%w%.%-]+:?%d*/?[%w%-]*$") then
						return nil
					end
					return line:match("/axxum$") and line or line.."/axxum"
				end
			end
			return nil
		end

		connect = function()
			if not NAChat.runtimeActive() then
				return
			end
			if isChatDisconnectedPreference() then
				NAChat.connecting = false
				resetReconnectBackoff()
				NAChat.setStatus("NA Chat: Disconnected (disabled)", STATUS_COLORS.info)
				return
			end
			if NAChat.permanentFailureReason then
				NAChat.permanentFailureReason = nil
			end
			if NAChat.connecting then
				return
			end
			NAChat.connecting = true
			Defer(function()
				if not NAChat.runtimeActive() then
					return
				end
				NAChat.setStatus("NA Chat: Connecting...", STATUS_COLORS.info)

				if not loadService() then
					if not NAChat.runtimeActive() then
						return
					end
					NAChat.connecting = false
					queueReconnect()
					return
				end
				if not NAChat.runtimeActive() then
					return
				end

				local wireOk, wireErr = pcall(wireEvents)
				if not NAChat.runtimeActive() then
					return
				end
				if not wireOk then
					NAChat.wired = false
					NAChat.connecting = false
					warn("[NA Chat] event wiring failed: "..tostring(wireErr))
					NAChat.setStatus("NA Chat: UI wiring failed", STATUS_COLORS.err)
					queueReconnect()
					return
				end

				local okInit, initErr = true, nil
				if NAChat.service and NAChat.service.Init then
					NAChat.resolvedEndpoint = NAChat.resolveEndpoint()
					if not NAChat.runtimeActive() then
						return
					end
					if not NAChat.resolvedEndpoint then
						NAChat.setStatus("NA Chat: endpoint unavailable", STATUS_COLORS.err)
						NAChat.connecting = false
						queueReconnect("endpoint_unavailable")
						return
					end
					local initCallOk, initResult, initMessage = pcall(NAChat.service.Init, {
						serverUrl = NAChat.resolvedEndpoint,
						endpointDiscovery = false,
						endpointRefreshInterval = 15,
						heartbeatInterval = 10,
						reconnectDelay = 6,
						autoReconnect = false,
						hidden = NAChat.isHidden,
						chatColor = getSavedChatColorHex(),
						chatColor2 = NAmanage.NAChat_GetSavedColor2Hex()
					})
					if initCallOk then
						okInit, initErr = initResult, initMessage
					else
						okInit, initErr = false, initResult
					end
				end
				if not NAChat.runtimeActive() then
					return
				end

				if not okInit then
					NAChat.setStatus("NA Chat: connect failed (Init)", STATUS_COLORS.err)

					local permanent = false
					NAChat.permanentFailureReason = nil

					local reason = tostring(initErr or "unknown IntegrationService error")
					local msg
					if reason == "websocket_not_available" then
						msg = "[NA Chat] Init failed: WebSocket not available in this executor"
					else
						msg = "[NA Chat] Init failed: "..reason
					end

					local now = os.clock()
					if lastErrText ~= msg or (now - (lastErrTime or 0)) > 15 then
						lastErrText, lastErrTime = msg, now
						appendConversationMessage("public", msg, STATUS_COLORS.err)
					end
					NAChat.connecting = false

					if not permanent then
						queueReconnect(reason)
					end
					return
				end

				NAChat.setStatus("NA Chat: Waiting for server...", STATUS_COLORS.info)
			end)
		end

		local myTyping = false
		local lastTypeTime = 0

		local function noteLocalTyping()
			lastTypeTime = os.clock()
			if myTyping then
				return
			end
			myTyping = true
			if NAChat.service and NAChat.service.SendTyping then
				pcall(NAChat.service.SendTyping, true)
			end
			Spawn(function()
				local stamp = lastTypeTime
				Wait(5)
				if stamp == lastTypeTime and myTyping then
					myTyping = false
					if NAChat.service and NAChat.service.SendTyping then
						pcall(NAChat.service.SendTyping, false)
					end
				end
			end)
		end

		local function clearTyping()
			if myTyping and NAChat.service and NAChat.service.SendTyping then
				myTyping = false
				pcall(NAChat.service.SendTyping, false)
			end
		end

		NAChat.clearDMTarget = function(reason)
			local hadTarget = NAChat.currentDMTarget ~= nil
			NAChat.currentDMTarget = nil
			if inputBox then
				if NAChat.activeGroupId and NAChat.groupRecords[tostring(NAChat.activeGroupId)] then
					inputBox.PlaceholderText = "Message #"..tostring(NAChat.groupRecords[tostring(NAChat.activeGroupId)].name or "group").."..."
				else
					inputBox.PlaceholderText = "Send a message (/w name)..."
				end
			end
			if reason and hadTarget then
				originalIO.setStatus(reason, STATUS_COLORS.info)
			end
		end

		local function findUserByPrefix(prefix)
			prefix = tostring(prefix or "")
			if prefix == "" then
				return nil
			end

			local lowerPrefix = prefix:lower()
			local bestMatch = nil

			for _, info in NAChat.users or {} do
				if type(info) == "table" then
					local uid = tonumber(info.userId)
					local uname = getVerifiedUsername(uid, tostring(info.username or ""))
					local display = tostring(info.displayName or "")
					if uname ~= "" then
						local lu = uname:lower()
						if lu == lowerPrefix then
							return uname
						elseif lu:sub(1, #lowerPrefix) == lowerPrefix and bestMatch == nil then
							bestMatch = uname
						end
					end
					if bestMatch == nil and display ~= "" then
						local ld = display:lower()
						if ld == lowerPrefix then
							return uname ~= "" and uname or display
						elseif ld:sub(1, #lowerPrefix) == lowerPrefix and bestMatch == nil then
							bestMatch = uname ~= "" and uname or display
						end
					end
				end
			end

			return bestMatch
		end

		NAmanage.NAChatSlurGuard:Prepare(opt and opt.extraSlurs)
		NAmanage._c29:_i(opt and opt._c29)

		local function sendMessage(t)
			if isChatUiSuppressed() then
				originalIO.setStatus("NA Chat: Hidden (message not sent)", STATUS_COLORS.info)
				return false
			end

			local muteLeft = getMuteRemainingSeconds()
			if muteLeft then
				local text = "NA Chat: Muted ("..formatDurationSeconds(muteLeft).." left)"
				if type(NAChat.muteReason) == "string" and NAChat.muteReason ~= "" then
					text = text.." - "..NAChat.muteReason
				end
				originalIO.setStatus(text, STATUS_COLORS.err)
				ensureMuteCountdown()
				clearTyping()
				return false
			end

			if not t then
				return true
			end

			t = tostring(t):gsub("^%s+", ""):gsub("%s+$", "")
			if t == "" then
				return true
			end

			if not NAChat.serverIsAdmin then
				if NAmanage.NAChatSlurGuard:IsAttempt(t) then
					NAmanage.NAChatSlurGuard:Warn(STATUS_COLORS.err)
					clearTyping()
					return true
				end

				if NAmanage._c29:_m(t) then
					clearTyping()
					return true
				end
			end

			local low = Lower(t)

			if low == "/cancel" then
				clearComposeMode()
				clearTyping()
				return true
			end

			if composeEditEntry then
				local svc = NAChat.service
				local ok = svc and type(svc.EditMessage) == "function" and svc.EditMessage(composeEditEntry.messageId, t) or false
				if ok then
					clearComposeMode()
				else
					originalIO.setStatus("NA Chat: failed to edit message", STATUS_COLORS.err)
				end
				clearTyping()
				return ok
			end

			if composeReplyEntry then
				local svc = NAChat.service
				local ok = svc and type(svc.SendMessage) == "function" and svc.SendMessage(t, composeReplyEntry.messageId) or false
				if ok then
					clearComposeMode()
				else
					originalIO.setStatus("NA Chat: failed to send reply", STATUS_COLORS.err)
				end
				clearTyping()
				return ok
			end

			if low == "/w" or low == "/whisper" or low == "/dm" or low == "/w off" or low == "/whisper off" or low == "/dm off" then
				NAChat.clearDMTarget("NA Chat: DM cleared")
				clearTyping()
				return true
			end

			local shortTarget = t:match("^/%a+%s+(%S+)$")
			if shortTarget then
				local cmdName = (t:match("^/(%a+)%s+") or ""):lower()
				if cmdName == "w" or cmdName == "whisper" or cmdName == "dm" then
					local resolved = findUserByPrefix(shortTarget)
					if resolved then
						clearComposeMode()
						NAChat.currentDMTarget = resolved
						if inputBox then
							inputBox.PlaceholderText = ("DM to %s..."):format(resolved)
						end
						originalIO.setStatus(("NA Chat: DM -> %s"):format(resolved), STATUS_COLORS.blue)
					else
						originalIO.setStatus(("NA Chat: user '%s' not found"):format(shortTarget), STATUS_COLORS.err)
					end
					clearTyping()
					return true
				end
			end

			local ok = false
			local dmTarget, dmMsg = t:match("^/%a+%s+(%S+)%s+(.+)$")
			if dmTarget and dmMsg then
				local cmdName = (t:match("^/(%a+)%s+") or ""):lower()
				if (cmdName == "w" or cmdName == "whisper" or cmdName == "dm") and NAChat.service and NAChat.service.SendPrivateMessage then
					local resolved = findUserByPrefix(dmTarget) or dmTarget
					ok = NAChat.service.SendPrivateMessage(resolved, dmMsg)
				elseif NAChat.currentDMTarget and NAChat.service and NAChat.service.SendPrivateMessage then
					ok = NAChat.service.SendPrivateMessage(NAChat.currentDMTarget, t)
				elseif NAChat.service and NAChat.service.SendMessage then
					ok = NAChat.service.SendMessage(t)
				end
			else
				if NAChat.activeGroupId and NAChat.service and NAChat.service.SendGroupMessage then
					ok = NAChat.service.SendGroupMessage(NAChat.activeGroupId, t)
				elseif NAChat.currentDMTarget and NAChat.service and NAChat.service.SendPrivateMessage then
					ok = NAChat.service.SendPrivateMessage(NAChat.currentDMTarget, t)
				elseif NAChat.service and NAChat.service.SendMessage then
					ok = NAChat.service.SendMessage(t)
				end
			end

			if not ok then
				originalIO.setStatus("NA Chat: failed to send", STATUS_COLORS.err)
			end

			clearTyping()
			return ok
		end

		if sendBtn then
			MouseButtonFix(sendBtn, function()
				local pendingText = inputBox and inputBox.Text or ""
				if inputBox then
					inputBox.Text = ""
				end
				Defer(function()
					local ok = sendMessage(pendingText)
					if ok == false and inputBox and inputBox.Text == "" then
						inputBox.Text = pendingText
					end
				end)
			end)
		end

		if inputBox then
			inputBox.ClearTextOnFocus = false
			inputBox:GetPropertyChangedSignal("Text"):Connect(function()
				local txt = inputBox.Text or ""
				txt = txt:match("^%s*(.-)%s*$") or ""
				if txt ~= "" then
					noteLocalTyping()
				end
			end)
			inputBox.FocusLost:Connect(function(enter)
				if enter then
					local pendingText = inputBox.Text
					inputBox.Text = ""
					Defer(function()
						local ok = sendMessage(pendingText)
						if ok == false and inputBox and inputBox.Text == "" then
							inputBox.Text = pendingText
						end
					end)
				end
			end)
		end

		if clearBtn and chatScroll then
			MouseButtonFix(clearBtn, function()
				clearComposeMode()
				conversationHistory[NAChat.activeConversation] = {}
				renderConversation(true)
			end)
		end

		if reconnectBtn and MouseButtonFix then
			MouseButtonFix(reconnectBtn, function()
				if NAmanage and type(NAmanage.NASettingsSet) == "function" then
					pcall(NAmanage.NASettingsSet, "naChatDisconnected", false)
				end
				refreshDisconnectButton()
				local svc = NAChat.service
				if svc and svc.Disconnect then
					pcall(svc.Disconnect)
				end
				NAChat.connecting = false
				NAChat.serverIsAdmin = false
				NAChat.permanentFailureReason = nil
				resetReconnectBackoff()
				connect()
			end)
		end

		if chatTab and MouseButtonFix then
			MouseButtonFix(chatTab, function()
				NAChat.switchTab("chat")
			end)
		end

		if usersTab and MouseButtonFix then
			MouseButtonFix(usersTab, function()
				NAChat.switchTab("users")
			end)
		end

		if settingsBtn and MouseButtonFix then
			styleChatTab(settingsBtn, false)
			MouseButtonFix(settingsBtn, function()
				NAChat.switchTab("settings")
			end)
		end

		if disconnectBtn then
			refreshDisconnectButton()
			MouseButtonFix(disconnectBtn, function()
				local disabled = not isChatDisconnectedPreference()
				if NAmanage and type(NAmanage.NASettingsSet) == "function" then
					pcall(NAmanage.NASettingsSet, "naChatDisconnected", disabled)
				end
				refreshDisconnectButton()
				resetReconnectBackoff()
				if disabled then
					local svc = NAChat.service
					if svc and svc.Disconnect then
						pcall(svc.Disconnect)
					end
					NAChat.users = {}
					NAChat.usersFetchInFlight = false
					if usersScroll then
						updateUsersList({})
					end
					originalIO.setStatus("NA Chat: Disconnected (disabled)", STATUS_COLORS.info)
				else
					NAChat.connecting = false
					connect()
				end
			end)
		end

		if visibilityBtn then
			MouseButtonFix(visibilityBtn, function()
				originalIO.setHiddenState(not NAChat.isHidden, false)
			end)
		end

		if gameActivityBtn then
			local gameActivityDebounce = false

			refreshGameActivityButton = function(enabledOverride)
				local enabled = enabledOverride
				if type(enabled) ~= "boolean" then
					enabled = _G.NAChatGameActivityEnabled()
				end
				styleChatToggle(gameActivityBtn, enabled == true, "Activity  •  On", "Activity  •  Off")
			end

			refreshGameActivityButton()

			MouseButtonFix(gameActivityBtn, function()
				if gameActivityDebounce then
					return
				end
				gameActivityDebounce = true

				local settings = NAmanage.NASettingsEnsure()
				local current = settings.naChatGameActivity
				if type(current) ~= "boolean" then
					current = true
				end
				local enabled = not current
				NAmanage.NASettingsSet("naChatGameActivity", enabled)
				refreshGameActivityButton()

				local okSvc, svc = pcall(function()
					return NAChat.service
				end)
				local targetHidden = not enabled
				local connected = okSvc and svc and type(svc.IsConnected) == "function" and svc.IsConnected() == true
				if connected and type(svc.SetActivityHidden) == "function" then
					local okSet, result = pcall(svc.SetActivityHidden, targetHidden)
					if not (okSet and result == true) then
						originalIO.setStatus("NA Chat: activity preference saved; server update pending", STATUS_COLORS.info)
					end
				elseif not connected then
					originalIO.setStatus("NA Chat: activity preference saved", STATUS_COLORS.info)
				end

				Defer(function()
					Wait(0.2)
					gameActivityDebounce = false
				end)
			end)
		end

		if dmNotifBtn then
			local function refreshDmNotifButton()
				local enabled = isDmNotifyEnabled()
				styleChatToggle(dmNotifBtn, enabled, "DM Notifications  •  On", "DM Notifications  •  Off")
			end

			refreshDmNotifButton()

			MouseButtonFix(dmNotifBtn, function()
				local settings = NAmanage.NASettingsEnsure()
				local current = settings.naChatDmNotify
				if type(current) ~= "boolean" then
					current = true
				end
				local enabled = not current
				NAmanage.NASettingsSet("naChatDmNotify", enabled)
				NAStuff.dmNotificationsEnabled = enabled
				refreshDmNotifButton()
			end)
		end

		Spawn(function()
			while true do
				Wait(15)

				refreshStatus()

				local svc = NAChat.service
				local staleUsers = NAChat.lastUsersUpdateAt <= 0 or (os.clock() - NAChat.lastUsersUpdateAt) >= 30
				if staleUsers and NAChat.activeTab == "users" and svc and svc.IsConnected and svc.IsConnected() and not isChatUiSuppressed() then
					requestUsersList()
				end
			end
		end)

		local initialHidden = false
		if NAmanage and type(NAmanage.NASettingsGet) == "function" then
			local ok, saved = pcall(NAmanage.NASettingsGet, "naChatHidden")
			if ok and saved ~= nil then
				initialHidden = saved == true
			end
		end

		local function isLocalAdmin()
			if NAChat.serverIsAdmin == true then
				return true
			end
			local lp = Players and Players.LocalPlayer
			if not lp then
				return false
			end
			local admins = _na_env and _na_env.NAadminsLol
			if type(admins) ~= "table" then
				return false
			end
			const userId = tonumber(lp.UserId)
			for _, id in admins do
				if userId and userId == tonumber(id) then
					return true
				end
			end
			return false
		end

		local function ensureAdminTabUI()
			if not chatFrame then
				return
			end

			if not adminTab and usersTab and usersTab.Parent then
				adminTab = usersTab.Parent:FindFirstChild("AdminTab")
			end

			if not adminFrame then
				const container = NAUIMANAGER and NAUIMANAGER.NAchatContent
				const page = container and container:FindFirstChild("AdminFrame")
				if page and usersScroll then
					adminFrame = page
					const userBox = page.AdminUserInput
					const durBox = page.AdminMuteDurationInput
					const reasonBox = page.AdminMuteReasonInput
					const muteBtn = page.AdminMuteButton
					const banBtn = page.AdminBanButton
					const unmuteBtn = page.AdminUnmuteButton
					const unbanBtn = page.AdminUnbanButton
					const hwidBanBtn = page.AdminHWIDBanButton
					const hwidUnbanBtn = page.AdminHWIDUnbanButton
					const purgeCountBox = page.AdminPurgeCountInput
					const purgeBtn = page.AdminPurgeButton
					const adminTagToggleBtn = page.AdminTagToggleButton
					const adminRainbowToggleBtn = page.AdminRainbowToggleButton

					refreshAdminAppearanceSettingsUI = function()
						local tagEnabled = NAmanage.NAChat_GetShowAdminTag()
						local rainbowEnabled = NAmanage.NAChat_GetAdminRainbowMessages()
						adminTagToggleBtn.Text = tagEnabled and "Admin tag: On" or "Admin tag: Off"
						adminTagToggleBtn.BackgroundColor3 = tagEnabled and CHAT_ON or CHAT_OFF
						adminRainbowToggleBtn.Text = rainbowEnabled and "Rainbow messages: On" or "Rainbow messages: Off"
						adminRainbowToggleBtn.BackgroundColor3 = rainbowEnabled and CHAT_ON or CHAT_OFF
					end
					refreshAdminAppearanceSettingsUI()

					const banScroll = page.AdminBanList

					local function normalizeName(name)
						return Lower(tostring(name or ""))
					end

					local function addBannedUser(name)
						local candidate = tostring(name or "")
						if candidate == "" then
							return
						end
						local normalized = normalizeName(candidate)
						local list = adminState.banned or {}
						for _, existing in list do
							if normalizeName(existing) == normalized then
								return
							end
						end
						Insert(list, candidate)
						adminState.banned = list
						if adminFrameUpdateBanList then
							adminFrameUpdateBanList()
						end
					end

					local function removeBannedUser(name)
						local candidate = tostring(name or "")
						if candidate == "" then
							return
						end
						local normalized = normalizeName(candidate)
						local list = adminState.banned or {}
						local removed = false
						for i = #list, 1, -1 do
							if normalizeName(list[i]) == normalized then
								table.remove(list, i)
								removed = true
							end
						end
						if removed then
							adminState.banned = list
							if adminFrameUpdateBanList then
								adminFrameUpdateBanList()
							end
						end
					end

					const muteRows = {}
					local function updateBanList()
						if not banScroll then
							return
						end
						for _, child in banScroll:GetChildren() do
							if child:IsA("Frame") then
								child:Destroy()
							end
						end

						table.clear(muteRows)
						local order = 0

						local function addHeader(text)
							order += 1
							local header = InstanceNew("Frame", banScroll)
							header.Size = UDim2.new(1, 0, 0, 20)
							header.BackgroundTransparency = 1
							header.LayoutOrder = order
							local lbl = InstanceNew("TextLabel", header)
							lbl.BackgroundTransparency = 1
							lbl.Size = UDim2.new(1, -6, 1, 0)
							lbl.Position = UDim2.new(0, 6, 0, 0)
							lbl.FontFace = NAmanage.uiBoldFont
							lbl.TextSize = 13
							lbl.TextXAlignment = Enum.TextXAlignment.Left
							lbl.TextColor3 = Color3.fromRGB(171, 176, 201)
							lbl.Text = text
						end

						local function addEmptyRow(text)
							order += 1
							local row = InstanceNew("Frame", banScroll)
							row.Size = UDim2.new(1, 0, 0, 30)
							row.BackgroundColor3 = Color3.fromRGB(31, 33, 45)
							row.BackgroundTransparency = 0.2
							row.LayoutOrder = order
							local emptyCorner = InstanceNew("UICorner", row)
							emptyCorner.CornerRadius = UDim.new(0, 7)
							ensureChatStroke(row, Color3.fromRGB(70, 73, 96), 0.76)
							local lbl = InstanceNew("TextLabel", row)
							lbl.BackgroundTransparency = 1
							lbl.Size = UDim2.new(1, -6, 1, 0)
							lbl.Position = UDim2.new(0, 10, 0, 0)
							lbl.FontFace = Font.new("rbxasset://fonts/families/Roboto.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal)
							lbl.TextSize = 13
							lbl.TextXAlignment = Enum.TextXAlignment.Left
							lbl.TextColor3 = Color3.fromRGB(180, 180, 194)
							lbl.Text = text
						end

						addHeader("Muted users")
						const nowEpoch = os.time()
						local muted = {}
						for _, entry in adminState.muted or {} do
							if type(entry) == "table" then
								local uname = tostring(entry.username or "")
								local untilEpoch = tonumber(entry.untilEpoch)
								local reason = tostring(entry.reason or "")
								if uname ~= "" then
									if not untilEpoch or untilEpoch > nowEpoch then
										Insert(muted, { username = uname, untilEpoch = untilEpoch, reason = reason })
									end
								end
							end
						end
						table.sort(muted, function(a, b)
							return (tonumber(a.untilEpoch) or math.huge) < (tonumber(b.untilEpoch) or math.huge)
						end)
						if #muted == 0 then
							addEmptyRow("None")
						else
							for _, entry in muted do
								order += 1
								local row = InstanceNew("Frame", banScroll)
								row.Size = UDim2.new(1, 0, 0, 38)
								row.BackgroundColor3 = CHAT_SURFACE_MUTED
								row.BackgroundTransparency = 0.04
								row.LayoutOrder = order
								local rowCorner = InstanceNew("UICorner", row)
								rowCorner.CornerRadius = UDim.new(0, 7)
								ensureChatStroke(row, Color3.fromRGB(73, 76, 101), 0.7)

								local uname = tostring(entry.username or "")
								local untilEpoch = tonumber(entry.untilEpoch)
								local reason = tostring(entry.reason or "")
								local remaining = untilEpoch and (untilEpoch - os.time()) or nil

								local labelText = uname
								if remaining then
									labelText = labelText.." - "..formatDurationSeconds(remaining).." left"
								end
								if reason ~= "" then
									labelText = labelText.." - "..reason
								end

								local lbl = InstanceNew("TextLabel", row)
								lbl.BackgroundTransparency = 1
								lbl.Size = UDim2.new(0.72, -6, 1, 0)
								lbl.Position = UDim2.new(0, 6, 0, 0)
								lbl.FontFace = Font.new("rbxasset://fonts/families/Roboto.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal)
								lbl.TextSize = 13
								lbl.TextXAlignment = Enum.TextXAlignment.Left
								lbl.TextColor3 = Color3.fromRGB(230, 230, 240)
								lbl.TextWrapped = true
								lbl.Text = labelText
								if untilEpoch then muteRows[lbl] = entry end

								local unmuteBtnRow = InstanceNew("TextButton", row)
								lbl.Size = UDim2.new(1, -76, 1, 0)
								unmuteBtnRow.Size = UDim2.fromOffset(62, 26)
								unmuteBtnRow.AnchorPoint = Vector2.new(1, 0.5)
								unmuteBtnRow.Position = UDim2.new(1, -6, 0.5, 0)
								unmuteBtnRow.BackgroundColor3 = Color3.fromRGB(57, 76, 113)
								unmuteBtnRow.BackgroundTransparency = 0.04
								unmuteBtnRow.AutoButtonColor = false
								unmuteBtnRow.TextColor3 = Color3.fromRGB(255, 255, 255)
								unmuteBtnRow.FontFace = NAmanage.uiBoldFont
								unmuteBtnRow.TextSize = 12
								unmuteBtnRow.Text = "Unmute"
								local ubCorner = InstanceNew("UICorner", unmuteBtnRow)
								ubCorner.CornerRadius = UDim.new(0, 7)
								ensureChatStroke(unmuteBtnRow, Color3.fromRGB(118, 153, 222), 0.35)

								if MouseButtonFix then
									MouseButtonFix(unmuteBtnRow, function()
										local svc = NAChat.service
										if svc and svc.SendAdminAction then
											svc.SendAdminAction("unmute", uname)
										end
									end)
								end
							end
						end

						addHeader("Banned users")
						local list = adminState.banned or {}
						if #list == 0 then
							addEmptyRow("None")
						else
							for _, name in list do
								order += 1
								local row = InstanceNew("Frame", banScroll)
								row.Size = UDim2.new(1, 0, 0, 34)
								row.BackgroundColor3 = CHAT_SURFACE_MUTED
								row.BackgroundTransparency = 0.04
								row.LayoutOrder = order
								local rowCorner = InstanceNew("UICorner", row)
								rowCorner.CornerRadius = UDim.new(0, 7)
								ensureChatStroke(row, Color3.fromRGB(73, 76, 101), 0.7)

								local lbl = InstanceNew("TextLabel", row)
								lbl.BackgroundTransparency = 1
								lbl.Size = UDim2.new(0.6, -6, 1, 0)
								lbl.Position = UDim2.new(0, 6, 0, 0)
								lbl.FontFace = Font.new("rbxasset://fonts/families/Roboto.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal)
								lbl.TextSize = 14
								lbl.TextXAlignment = Enum.TextXAlignment.Left
								lbl.TextColor3 = Color3.fromRGB(230, 230, 240)
								lbl.Text = tostring(name)

								local unbanBtn = InstanceNew("TextButton", row)
								unbanBtn.Size = UDim2.new(0.2, 0, 0, 22)
								unbanBtn.Position = UDim2.new(0.8, -6, 0.5, -11)
								unbanBtn.BackgroundColor3 = CHAT_DANGER
								unbanBtn.BackgroundTransparency = 0.04
								unbanBtn.AutoButtonColor = false
								unbanBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
								unbanBtn.FontFace = NAmanage.uiBoldFont
								unbanBtn.TextSize = 12
								unbanBtn.Text = "Unban"
								local ubCorner = InstanceNew("UICorner", unbanBtn)
								ubCorner.CornerRadius = UDim.new(0, 7)
								ensureChatStroke(unbanBtn, Color3.fromRGB(210, 104, 127), 0.35)

								if MouseButtonFix then
									MouseButtonFix(unbanBtn, function()
										local svc = NAChat.service
										if svc and svc.SendAdminAction then
											svc.SendAdminAction("unban", name)
											removeBannedUser(name)
										end
									end)
								end
							end
						end

						addHeader("HWID bans")
						local hwidList = adminState.hwidBanned or {}
						if #hwidList == 0 then
							addEmptyRow("None")
						else
							for _, entry in hwidList do
								if type(entry) == "table" then
									order += 1
									local row = InstanceNew("Frame", banScroll)
									row.Size = UDim2.new(1, 0, 0, 38)
									row.BackgroundColor3 = CHAT_SURFACE_MUTED
									row.BackgroundTransparency = 0.04
									row.LayoutOrder = order
									local rowCorner = InstanceNew("UICorner", row)
									rowCorner.CornerRadius = UDim.new(0, 7)
									ensureChatStroke(row, Color3.fromRGB(73, 76, 101), 0.7)

									local users = type(entry.users) == "table" and entry.users or {}
									local names = #users > 0 and table.concat(users, ", ") or "Unknown user"
									local fingerprint = tostring(entry.fingerprint or "")
									local labelText = names
									if fingerprint ~= "" then
										labelText = labelText.." - "..fingerprint
									end

									local lbl = InstanceNew("TextLabel", row)
									lbl.BackgroundTransparency = 1
									lbl.Size = UDim2.new(0.72, -6, 1, 0)
									lbl.Position = UDim2.new(0, 6, 0, 0)
									lbl.FontFace = Font.new("rbxasset://fonts/families/Roboto.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal)
									lbl.TextSize = 13
									lbl.TextXAlignment = Enum.TextXAlignment.Left
									lbl.TextColor3 = Color3.fromRGB(230, 230, 240)
									lbl.TextWrapped = true
									lbl.Text = labelText

									local removeBtn = InstanceNew("TextButton", row)
									removeBtn.Size = UDim2.new(0.22, 0, 0, 24)
									removeBtn.Position = UDim2.new(0.78, -6, 0.5, -12)
									removeBtn.BackgroundColor3 = CHAT_DANGER
									removeBtn.BackgroundTransparency = 0.04
									removeBtn.AutoButtonColor = false
									removeBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
									removeBtn.FontFace = NAmanage.uiBoldFont
									removeBtn.TextSize = 12
									removeBtn.Text = "Unban"
									local removeCorner = InstanceNew("UICorner", removeBtn)
									removeCorner.CornerRadius = UDim.new(0, 7)
									ensureChatStroke(removeBtn, Color3.fromRGB(210, 104, 127), 0.35)

									if MouseButtonFix then
										MouseButtonFix(removeBtn, function()
											local target = fingerprint
											if target == "" and #users > 0 then
												target = tostring(users[1])
											end
											local svc = NAChat.service
											if target ~= "" and svc and svc.SendAdminAction then
												svc.SendAdminAction("unhwid_ban", target)
											end
										end)
									end
								end
							end
						end

						addHeader("Recent DMs (admin audit)")
						local dmLog = adminState.dmLog or {}
						if #dmLog == 0 then
							addEmptyRow("None")
						else
							local first = math.max(1, #dmLog - 49)
							for index = #dmLog, first, -1 do
								local entry = dmLog[index]
								if type(entry) == "table" then
									order += 1
									local row = InstanceNew("Frame", banScroll)
									row.Size = UDim2.new(1, 0, 0, 46)
									row.BackgroundColor3 = Color3.fromRGB(31, 33, 45)
									row.BackgroundTransparency = 0.12
									row.LayoutOrder = order
									local rowCorner = InstanceNew("UICorner", row)
									rowCorner.CornerRadius = UDim.new(0, 7)
									ensureChatStroke(row, Color3.fromRGB(70, 73, 96), 0.76)

									local stamp = tonumber(entry.timestamp)
									local prefix = ""
									if stamp then
										local okDate, formatted = pcall(os.date, "%H:%M", stamp)
										if okDate and formatted then
											prefix = "["..tostring(formatted).."] "
										end
									end
									local text = prefix..tostring(entry.from or "?").." -> "..tostring(entry.to or "?")..": "..tostring(entry.message or "")

									local lbl = InstanceNew("TextLabel", row)
									lbl.BackgroundTransparency = 1
									lbl.Size = UDim2.new(1, -12, 1, -4)
									lbl.Position = UDim2.new(0, 6, 0, 2)
									lbl.FontFace = Font.new("rbxasset://fonts/families/Roboto.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal)
									lbl.TextSize = 12
									lbl.TextXAlignment = Enum.TextXAlignment.Left
									lbl.TextYAlignment = Enum.TextYAlignment.Center
									lbl.TextColor3 = Color3.fromRGB(218, 218, 231)
									lbl.TextWrapped = true
									lbl.Text = text
								end
							end
						end

					end

					adminFrameUpdateBanList = updateBanList

					if not adminListTickerActive then
						adminListTickerActive = true
						Spawn(function()
							while adminFrame and adminFrame.Parent do
								Wait(1)
								if adminFrame and adminFrame.Visible and chatFrame.Visible and NAmanage.GetAttr(chatFrame, "NAMenuMinimized") ~= true then
									const now = os.time()
									for label, entry in muteRows do
										const remaining = entry.untilEpoch - now
										if remaining <= 0 then
											updateBanList()
											break
										end
										const reason = entry.reason
										const text = entry.username.." - "..formatDurationSeconds(remaining).." left"..(reason ~= "" and (" - "..reason) or "")
										if label.Text ~= text then label.Text = text end
									end
								end
							end
							adminListTickerActive = false
						end)
					end

					if MouseButtonFix then
						MouseButtonFix(adminTagToggleBtn, function()
							local previous = NAmanage.NAChat_GetShowAdminTag()
							local desired = not previous
							NAmanage.NAChat_SetSetting("naChatShowAdminTag", desired)
							if refreshAdminAppearanceSettingsUI then refreshAdminAppearanceSettingsUI() end
							local sent, sendErr = pushAdminPresentation(desired, nil)
							if not sent then
								NAmanage.NAChat_SetSetting("naChatShowAdminTag", previous)
								if refreshAdminAppearanceSettingsUI then refreshAdminAppearanceSettingsUI() end
								appendConversationMessage("public", "[NA Chat] Failed to update admin tag: "..tostring(sendErr or "unknown error"), STATUS_COLORS.err)
							end
						end)

						MouseButtonFix(adminRainbowToggleBtn, function()
							local previous = NAmanage.NAChat_GetAdminRainbowMessages()
							local desired = not previous
							NAmanage.NAChat_SetSetting("naChatAdminRainbowMessages", desired)
							if refreshAdminAppearanceSettingsUI then refreshAdminAppearanceSettingsUI() end
							local sent, sendErr = pushAdminPresentation(nil, desired)
							if not sent then
								NAmanage.NAChat_SetSetting("naChatAdminRainbowMessages", previous)
								if refreshAdminAppearanceSettingsUI then refreshAdminAppearanceSettingsUI() end
								appendConversationMessage("public", "[NA Chat] Failed to update rainbow messages: "..tostring(sendErr or "unknown error"), STATUS_COLORS.err)
							end
						end)

						local function resolveTargetOrWarn(actionLabel)
							local targetName = userBox.Text or ""
							targetName = targetName:match("^%s*(.-)%s*$") or ""
							if targetName ~= "" then
								local resolved = findUserByPrefix(targetName)
								if resolved then
									targetName = resolved
									userBox.Text = resolved
								end
							end
							if targetName == "" then
								local auto = getAdminActionTarget()
								if auto then
									targetName = auto
									userBox.Text = auto
								end
							end
							if targetName == "" then
								if DoNotif then
									DoNotif("NA Chat admin: enter a username to "..actionLabel..".", 2)
								end
								return nil
							end
							return targetName
						end

						MouseButtonFix(muteBtn, function()
							local targetName = resolveTargetOrWarn("mute")
							if not targetName then
								return
							end

							local duration = tonumber(durBox.Text) or 300
							local reason = ""
							if reasonBox then
								reason = tostring(reasonBox.Text or ""):match("^%s*(.-)%s*$") or ""
							end
							local svc = NAChat.service
							if svc and svc.SendAdminAction then
								svc.SendAdminAction("mute", targetName, duration, reason ~= "" and reason or nil)
							end
						end)

						MouseButtonFix(banBtn, function()
							local targetName = resolveTargetOrWarn("ban")
							if not targetName then
								return
							end
							local svc = NAChat.service
							if svc and svc.SendAdminAction then
								svc.SendAdminAction("ban", targetName)
								addBannedUser(targetName)
							end
						end)

						MouseButtonFix(unbanBtn, function()
							local targetName = resolveTargetOrWarn("unban")
							if not targetName then
								return
							end

							local svc = NAChat.service
							if svc and svc.SendAdminAction then
								svc.SendAdminAction("unban", targetName)
								removeBannedUser(targetName)
							end
						end)

						MouseButtonFix(unmuteBtn, function()
							local targetName = resolveTargetOrWarn("unmute")
							if not targetName then
								return
							end

							local svc = NAChat.service
							if svc and svc.SendAdminAction then
								svc.SendAdminAction("unmute", targetName)
							end
						end)

						MouseButtonFix(hwidBanBtn, function()
							local targetName = resolveTargetOrWarn("HWID ban")
							if not targetName then
								return
							end
							local svc = NAChat.service
							if svc and svc.SendAdminAction then
								svc.SendAdminAction("hwid_ban", targetName)
							end
						end)

						MouseButtonFix(hwidUnbanBtn, function()
							local targetName = resolveTargetOrWarn("remove HWID ban")
							if not targetName then
								return
							end
							local svc = NAChat.service
							if svc and svc.SendAdminAction then
								svc.SendAdminAction("unhwid_ban", targetName)
							end
						end)

						MouseButtonFix(purgeBtn, function()
							local count = math.floor(tonumber(purgeCountBox.Text) or 1)
							count = math.clamp(count, 1, 1000)
							purgeCountBox.Text = tostring(count)
							local svc = NAChat.service
							if svc and svc.SendAdminAction then
								svc.SendAdminAction("purge", "", nil, nil, count)
							end
						end)
					end

					updateBanList()
					adminFrame.Visible = (NAChat.activeTab == "admin")
				end
			end
		end

		local function getAdminActionTarget()
			if NAChat.currentDMTarget and NAChat.currentDMTarget ~= "" then
				return NAChat.currentDMTarget
			end
			if usersSearchBox and usersSearchBox.Text and usersSearchBox.Text ~= "" then
				local resolved = findUserByPrefix(usersSearchBox.Text)
				if resolved then
					return resolved
				end
			end
			return nil
		end

		local function findTargets(spec)
			spec = Lower(tostring(spec or ""))
			if spec == "" then
				return nil
			end

			if spec == "all" or spec == "*" then
				return "all"
			end

			local matchId = nil
			local len = #spec

			for _, info in NAChat.users or {} do
				if type(info) == "table" then
					local uname = Lower(tostring(info.username or ""))
					local uid = tonumber(info.userId)
					if uid and Sub(uname, 1, len) == spec then
						matchId = uid
						break
					end
				end
			end

			return matchId
		end

		refreshAdminTabUI = function()
			if isLocalAdmin() then
				ensureAdminTabUI()
				if adminTab and adminFrame then
					adminTab.Visible = true
					if not adminTabBound and MouseButtonFix then
						adminTabBound = true
						MouseButtonFix(adminTab, function()
							NAChat.switchTab("admin")
						end)
					end
				end
			else
				if NAChat.activeTab == "admin" then
					NAChat.switchTab("chat")
				end
				local tabsContainer = chatFrame and chatFrame:FindFirstChild("Tabs")
				local tab = tabsContainer and tabsContainer:FindFirstChild("AdminTab")
				if tab then
					tab.Visible = false
				end
				if adminFrame then
					adminFrame.Visible = false
				end
			end
		end
		refreshAdminTabUI()

		if isLocalAdmin() then
		NAmanage.NAChatTakeAnonymousFlag = function(parts)
			local anonymous = false
			for i = #parts, 1, -1 do
				local value = Lower(tostring(parts[i] or ""))
				if value == "--anon" or value == "--anonymous" or value == "-a" then
					table.remove(parts, i)
					anonymous = true
				end
			end
			return anonymous
		end

		cmd.register({
			name = "nadisguise",
			aliases = { "nachatdisguise" },
			description = "Disguise your NA Chat appearance as another Roblox user",
			usage = "nadisguise <roblox username|off> (nachatdisguise)",
			requiresArguments = true,
			callback = function(username)
				local svc = NAChat.service
				if not (svc and svc.IsConnected and svc.IsConnected() and svc.SetAdminDisguise) then
					return
				end
				username = tostring(username or "")
				if username == "" then
					return
				end
				svc.SetAdminDisguise(username)
			end,
		})

		cmd.register({
			name = "nacmd",
			aliases = { "naremote" },
			description = "Send a command to NA Chat user(s)",
			usage = "nacmd <target> <command> (naremote)",
			requiresArguments = true,
			callback = function(targetSpec, ...)
				local svc = NAChat.service
				if not (svc and svc.IsConnected and svc.IsConnected()) then
					return
				end

				local args = { ... }
				if #args == 0 then
					return
				end

				local target = findTargets(targetSpec)
				if not target then
					return
				end

				if svc.SendRemoteCommand then
					svc.SendRemoteCommand(target, args)
				end
			end,
		})

		cmd.register({
			name = "naannouncement",
			aliases = { "naannc", "announcement" },
			description = "Send an announcement to all NA Chat users",
			usage = "naannouncement [--anon] <message> (naannc, announcement)",
			requiresArguments = true,
			callback = function(...)
				local svc = NAChat.service
				if not (svc and svc.IsConnected and svc.IsConnected() and svc.SendAnnouncement) then
					return
				end

				local parts = { ... }
				local anonymous = NAmanage.NAChatTakeAnonymousFlag(parts)
				if #parts == 0 then
					return
				end

				local msg = Concat(parts, " ")
				svc.SendAnnouncement(msg, anonymous)
			end,
		})

		cmd.register({
			name = "nanotify",
			description = "Send a notification to NA Chat user(s)",
			usage = "nanotify <target> [duration] [--anon] <message>",
			requiresArguments = true,
			callback = function(targetSpec, ...)
				local svc = NAChat.service
				if not (svc and svc.IsConnected and svc.IsConnected() and svc.SendNotify) then
					return
				end

				local parts = { ... }
				local anonymous = NAmanage.NAChatTakeAnonymousFlag(parts)
				if #parts == 0 then
					return
				end

				local target = findTargets(targetSpec)
				if not target then
					return
				end

				local duration = 5
				local msgStart = 1
				local maybeDur = tonumber(parts[1])
				if maybeDur and #parts >= 2 then
					duration = maybeDur
					msgStart = 2
				end

				local msgParts = {}
				for i = msgStart, #parts do
					msgParts[#msgParts + 1] = tostring(parts[i])
				end

				local msg = Concat(msgParts, " ")
				if msg == "" then
					return
				end

				svc.SendNotify(target, msg, duration, anonymous)
			end,
		})

		cmd.register({
			name = "nanotify2",
			description = "Send a window to NA Chat user(s)",
			usage = "nanotify2 <target> [--anon] <message>",
			requiresArguments = true,
			callback = function(targetSpec, ...)
				local svc = NAChat.service
				if not (svc and svc.IsConnected and svc.IsConnected() and svc.SendNotify2) then
					return
				end

				local parts = { ... }
				local anonymous = NAmanage.NAChatTakeAnonymousFlag(parts)
				if #parts == 0 then
					return
				end

				local target = findTargets(targetSpec)
				if not target then
					return
				end

				local msg = Concat(parts, " ")
				if msg == "" then
					return
				end

				svc.SendNotify2(target, msg, anonymous)
			end,
		})

		cmd.register({
			name = "nanotify3",
			description = "Send a popup to NA Chat user(s)",
			usage = "nanotify3 <target> [--anon] <message>",
			requiresArguments = true,
			callback = function(targetSpec, ...)
				local svc = NAChat.service
				if not (svc and svc.IsConnected and svc.IsConnected() and svc.SendNotify3) then
					return
				end

				local parts = { ... }
				local anonymous = NAmanage.NAChatTakeAnonymousFlag(parts)
				if #parts == 0 then
					return
				end

				local target = findTargets(targetSpec)
				if not target then
					return
				end

				local msg = Concat(parts, " ")
				if msg == "" then
					return
				end

				svc.SendNotify3(target, msg, anonymous)
			end,
		})
		end

		NAChat.switchTab("chat")
		originalIO.setHiddenState(initialHidden, true)
		resetReconnectBackoff()
		refreshDisconnectButton()
		connect()
	end
end
originalIO.runNACHAT()

-- PART 30
NAmanage.InitWindowTools = function()
	if NAStuff.WindowTools and not NAStuff.WindowTools.dead then return NAStuff.WindowTools end
	const function service(name)
		return SafeGetService(name)
	end
	const UIS = service("UserInputService")
	const Http = service("HttpService")
	const WS = service("Workspace")
	const PPS = service("ProximityPromptService")
	const player = service("Players").LocalPlayer
	local VIM
	pcall(function() VIM = service("VirtualInputManager") end)
	const T = {
		bags = {}, wins = {}, dead = false, runId = 0, scanId = {}, held = {}, wants = {}, holds = {},
		data = { version = 1, records = {}, profiles = {}, favorites = {}, auto = {} },
		rec = { steps = {}, name = "", mode = "actions", tab = "steps", all = false },
		inter = { items = {}, kind = "All", near = true, jobs = {}, signal = "Activated" },
		assets = { items = {}, lookups = {}, kind = "All", mode = "All loaded", angle = 0 },
		prof = { scope = "game", all = false, picks = { Controls = true, Keys = true, Buttons = true, Plugins = false, Startup = false } },
		regs = { "input", "keybind", "slider", "dropdown", "colorPicker", "toggle" },
		path = (NAfiles.NAFILEPATH or "Nameless-Admin").."/WindowTools.json",
	}
	NAStuff.WindowTools = T
	T.trim = function(v) return tostring(v or ""):match("^%s*(.-)%s*$") or "" end
	T.finite = function(n, fallback, lo, hi)
		n = tonumber(n)
		if not n or n ~= n or math.abs(n) == math.huge then n = fallback end
		return math.clamp(n, lo, hi)
	end
	T.clean = function(group)
		const bag = T.bags[group]
		T.bags[group] = nil
		for _, conn in bag or {} do pcall(function() conn:Disconnect() end) end
	end
	T.on = function(group, signal, fn)
		const conn = signal:Connect(fn)
		T.bags[group] = T.bags[group] or {}
		table.insert(T.bags[group], conn)
		return conn
	end
	T.status = function(name, value)
		const w = T.wins[name]
		if w and w.body.Parent then w.body.Status.Text = tostring(value) end
	end
	T.pack = function(value, depth, seen)
		depth = depth or 0
		if depth > 12 then return nil end
		const typ = typeof(value)
		if typ == "string" then return #value <= 200000 and value or string.sub(value, 1, 200000) end
		if typ == "boolean" then return value end
		if typ == "number" then return value == value and math.abs(value) < math.huge and value or nil end
		if typ == "Color3" then return { _type = "Color3", r = value.R, g = value.G, b = value.B } end
		if typ == "EnumItem" then return { _type = "Enum", enum = tostring(value.EnumType), name = value.Name } end
		if typ == "UDim2" then return { _type = "UDim2", xs = value.X.Scale, xo = value.X.Offset, ys = value.Y.Scale, yo = value.Y.Offset } end
		if typ == "Vector2" then return { _type = "Vector2", x = value.X, y = value.Y } end
		if typ ~= "table" then return nil end
		seen = seen or {}
		if seen[value] then return nil end
		seen[value] = true
		const out = {}
		local count = 0
		for key, item in value do
			if type(key) == "string" or type(key) == "number" then
				count += 1
				if count > 3000 then break end
				out[key] = T.pack(item, depth + 1, seen)
			end
		end
		seen[value] = nil
		return out
	end
	T.unpack = function(value, depth)
		depth = depth or 0
		if type(value) ~= "table" or depth > 12 then return value end
		if value._type == "Color3" then return Color3.new(T.finite(value.r, 0, 0, 1), T.finite(value.g, 0, 0, 1), T.finite(value.b, 0, 0, 1)) end
		if value._type == "UDim2" then return UDim2.new(tonumber(value.xs) or 0, tonumber(value.xo) or 0, tonumber(value.ys) or 0, tonumber(value.yo) or 0) end
		if value._type == "Vector2" then return Vector2.new(tonumber(value.x) or 0, tonumber(value.y) or 0) end
		if value._type == "Enum" then
			local result
			pcall(function() result = Enum[tostring(value.enum):gsub("^Enum%.", "")][value.name] end)
			return result
		end
		const out = {}
		for key, item in value do out[key] = T.unpack(item, depth + 1) end
		return out
	end
	T.clone = function(v) return T.unpack(T.pack(v)) end
	T.encode = function(value)
		const ok, result = pcall(Http.JSONEncode, Http, value)
		if ok then return result end
		return nil, tostring(result)
	end
	T.decode = function(text)
		if type(text) ~= "string" or #text > 4000000 then return nil, "Import is too large." end
		const ok, value = pcall(Http.JSONDecode, Http, text)
		if ok and type(value) == "table" then return value end
		return nil, ok and "Expected a JSON object." or tostring(value)
	end
	T.save = function()
		if type(writefile) ~= "function" or type(readfile) ~= "function" then return false, "Kept for this session; file saving is unavailable." end
		if type(makefolder) == "function" then pcall(makefolder, NAfiles.NAFILEPATH or "Nameless-Admin") end
		const json, err = T.encode(T.data)
		if not json or #json > 4000000 then return false, err or "Saved data is too large." end
		local old
		pcall(function() old = readfile(T.path) end)
		if old and T.decode(old) then pcall(writefile, T.path..".bak", old) end
		const ok, why = pcall(function()
			writefile(T.path, json)
			assert(readfile(T.path) == json, "Saved data could not be verified.")
		end)
		if not ok and old then pcall(writefile, T.path, old) end
		return ok, ok and "Saved." or tostring(why)
	end
	T.load = function()
		if type(readfile) ~= "function" then return end
		for _, path in { T.path, T.path..".bak" } do
			const ok, raw = pcall(readfile, path)
			const data = ok and T.decode(raw)
			if type(data) == "table" and data.version == 1 then
				for id, value in type(data.records) == "table" and data.records or {} do
					if type(id) == "string" then T.data.records[id] = T.validate(value) end
				end
				for id, value in type(data.profiles) == "table" and data.profiles or {} do
					if type(id) == "string" then T.data.profiles[id] = T.profile(value) end
				end
				for key, value in type(data.favorites) == "table" and data.favorites or {} do
					if type(key) == "string" and type(value) == "table" and type(value.id) == "string" and table.find({ "Sounds", "Animations", "Meshes", "Images", "Videos" }, value.kind) then
						const id = T.assetId(value.id)
						if id then
							T.data.favorites[T.assetKey(value.kind, id)] = { id = id, kind = value.kind, name = tostring(value.name or value.id), decal = value.decal == true or nil }
						end
					end
				end
				for key, id in type(data.auto) == "table" and data.auto or {} do
					const prof = T.data.profiles[id]
					if prof and key == T.scopeKey(prof) then T.data.auto[key] = id end
				end
				return
			end
		end
	end
	T.rootGui = function() return NAStuff.NASCREENGUI end
	T.own = function(obj)
		const gui = T.rootGui()
		return obj == gui or gui and obj:IsDescendantOf(gui) or false
	end
	T.pathOf = function(obj)
		if typeof(obj) ~= "Instance" then return nil end
		const pg = player:FindFirstChildOfClass("PlayerGui")
		const char = getChar()
		const segs = {}
		local cur = obj
		while cur and cur ~= game do
			if cur == pg or cur == char or cur.Parent == game then
				return { root = cur == pg and "PlayerGui" or cur == char and "Character" or cur.Name, segs = segs }
			end
			const par = cur.Parent
			if not par then return nil end
			local nth = 0
			for _, kid in par:GetChildren() do
				if kid.Name == cur.Name and kid.ClassName == cur.ClassName then nth += 1 end
				if kid == cur then break end
			end
			table.insert(segs, 1, { name = cur.Name, class = cur.ClassName, nth = nth })
			cur = par
			if #segs > 80 then return nil end
		end
	end
	T.pathText = function(path)
		if type(path) ~= "table" then return "Unavailable" end
		const parts = { path.root }
		for _, seg in path.segs or {} do table.insert(parts, seg.name) end
		return table.concat(parts, "/")
	end
	T.pathCode = function(path)
		if not path then return "" end
		const root = (path.root == "PlayerGui" or path.root == "Character") and "Players" or path.root
		const base = NAmanage.ServiceCode(root)
		local code = path.root == "PlayerGui" and base..'.LocalPlayer:FindFirstChildOfClass("PlayerGui")' or path.root == "Character" and base..'.LocalPlayer.Character' or base
		for _, seg in path.segs do code ..= ':FindFirstChild('..string.format("%q", seg.name)..')' end
		return code
	end
	T.parsePath = function(text)
		const decoded = T.decode(text)
		if decoded and type(decoded.root) == "string" and type(decoded.segs) == "table" then return decoded end
		const bits = {}
		for name in tostring(text):gmatch("[^/]+") do table.insert(bits, name) end
		if #bits == 0 then return nil end
		const path = { root = table.remove(bits, 1), segs = {} }
		if path.root == "workspace" then path.root = "Workspace" end
		for _, name in bits do table.insert(path.segs, { name = name, nth = 1 }) end
		return path
	end
	T.resolve = function(path)
		if type(path) ~= "table" or type(path.root) ~= "string" or type(path.segs) ~= "table" or #path.segs > 80 then return nil end
		local obj
		if path.root == "PlayerGui" then obj = player:FindFirstChildOfClass("PlayerGui")
		elseif path.root == "Character" then obj = getChar()
		else pcall(function() obj = service(path.root) end) end
		for _, seg in path.segs do
			if not obj or type(seg) ~= "table" then return nil end
			local found, nth = nil, 0
			for _, kid in obj:GetChildren() do
				if kid.Name == seg.name and (not seg.class or kid.ClassName == seg.class) then
					nth += 1
					if nth == (tonumber(seg.nth) or 1) then found = kid break end
				end
			end
			obj = found
		end
		return obj
	end
	T.visible = function(obj)
		if NAmanage.IsGuiActuallyVisible then return NAmanage.IsGuiActuallyVisible(obj) end
		while obj and obj ~= game do
			if obj:IsA("GuiObject") and not obj.Visible or obj:IsA("LayerCollector") and not obj.Enabled then return false end
			obj = obj.Parent
		end
		return true
	end
	T.part = function(obj)
		local cur = obj
		for _ = 1, 8 do
			if not cur then return nil end
			if cur:IsA("BasePart") then return cur end
			if cur:IsA("Model") then return cur.PrimaryPart or cur:FindFirstChildWhichIsA("BasePart", true) end
			cur = cur.Parent
		end
	end
	T.distance = function(obj)
		if obj:IsA("GuiButton") then return 0 end
		const part = T.part(obj)
		const char = getChar()
		const root = char and getRoot(char)
		return part and root and (root.Position - part.Position).Magnitude or math.huge
	end
	T.copy = function(text)
		if type(setclipboard) ~= "function" then return false end
		return pcall(setclipboard, tostring(text))
	end
	T.message = function(name, title, value, importing)
		const w = T.wins[name]
		if not w then return end
		const pane = w.body.Transfer
		pane.Title.Text = title
		pane.Content.Text.Text = value or ""
		pane.Content.CanvasPosition = Vector2.zero
		pane.Confirm.Visible = importing == true
		pane.Visible = true
		w.importing = importing == true
		if not importing then T.copy(value or "") end
	end
	T.measureTransfer = function(w)
		w.measureId = (w.measureId or 0) + 1
		const ticket = w.measureId
		task.delay(0.08, function()
			if T.dead or ticket ~= w.measureId or not w.body.Transfer.Visible then return end
			const content = w.body.Transfer.Content
			const box = content.Text
			const scale = NAmanage.GetUIScaleFactor and NAmanage.GetUIScaleFactor(content) or 1
			local params
			const ok, bounds = pcall(function()
				params = Instance.new("GetTextBoundsParams")
				params.Font = box.FontFace
				params.Size = box.TextSize
				params.Width = math.max(1, content.AbsoluteSize.X / math.max(scale, 0.01) - 18)
				params.Text = box.Text.."\n"
				return service("TextService"):GetTextBoundsAsync(params)
			end)
			if params then params:Destroy() end
			if T.dead or ticket ~= w.measureId or not box.Parent then return end
			local height = ok and bounds.Y or box.TextBounds.Y / math.max(scale, 0.01)
			box.Size = UDim2.new(1, 0, 0, math.max(200, math.ceil(height) + 20))
		end)
	end
	T.button = function(w, key, fn)
		const obj = w.detail:FindFirstChild(key, true)
		if obj then
			T.on(w.name, obj.Activated, function()
				const ok, err = pcall(fn)
				if not ok then T.status(w.name, tostring(err)) end
			end)
		end
	end
	T.rows = function(w, rows, onPick)
		w.page = math.clamp(w.page or 1, 1, math.max(1, math.ceil(#rows / 60)))
		w.rows = rows
		w.cols.Empty.Visible = #rows == 0
		w.cols.Empty.Text = w.empty or "No matches. Try refreshing or changing the filters."
		const first = (w.page - 1) * 60 + 1
		const drawn = {}
		for i = first, math.min(#rows, first + 59) do drawn[#drawn + 1] = rows[i] end
		local same = w.draw and #w.draw == #drawn and w.drawPage == w.page and w.drawSel == w.sel
		if same then
			for i, row in drawn do
				const old = w.draw[i]
				if old.key ~= row.key or old.title ~= row.title or old.meta ~= row.meta or old.item ~= row.item then same = false break end
			end
		end
		if w.name ~= "ActionRecorder" then T.status(w.name, #rows.." results  |  Page "..w.page.." / "..math.max(1, math.ceil(#rows / 60))) end
		if same then return end
		local pos = w.list.CanvasPosition
		if w.drawPage ~= w.page or w.drawQuery ~= w.bar.Search.Text then pos = Vector2.zero end
		w.draw = drawn w.drawPage = w.page w.drawQuery = w.bar.Search.Text w.drawSel = w.sel
		T.clean(w.name.."Rows")
		for _, row in w.list:GetChildren() do if row:IsA("GuiObject") then row:Destroy() end end
		for i = first, math.min(#rows, first + 59) do
			const item = rows[i]
			const row = w.frame.Templates.Row:Clone()
			row.Name = "Item"..i
			row.Title.Text = tostring(item.title or "Item")
			row.Meta.Text = tostring(item.meta or "")
			row.LayoutOrder = i
			row.BackgroundColor3 = item.key == w.sel and Color3.fromRGB(64, 47, 94) or Color3.fromRGB(27, 29, 38)
			row.Visible = true
			row.Parent = w.list
			T.on(w.name.."Rows", row.Activated, function()
				w.sel = item.key
				onPick(item)
			end)
		end
		w.list.CanvasPosition = pos
		if w.name ~= "ActionRecorder" then T.status(w.name, #rows.." results  |  Page "..w.page.." / "..math.max(1, math.ceil(#rows / 60))) end
	end
	T.layout = function(w)
		const narrow = w.frame.AbsoluteSize.X < 600 and (w.frame.AbsoluteSize.X < 480 or w.frame.AbsoluteSize.Y > 420)
		const short = w.frame.AbsoluteSize.Y < 300 and w.frame.AbsoluteSize.X >= 480
		w.frame.Topbar.Size = UDim2.new(1, 0, 0, short and 36 or 44)
		w.body.Size = UDim2.new(1, -20, 1, short and -56 or -66)
		w.bar.Size = UDim2.new(1, 0, 0, short and 34 or 72)
		w.cols.Position = UDim2.fromOffset(0, short and 40 or 78)
		w.cols.Size = UDim2.new(1, 0, 1, short and -64 or -102)
		if short then
			local x = 0
			for _, data in { { "Search", 0.28 }, { "Refresh", 0.16 }, { "Filter", 0.22 }, { "Mode", 0.20 }, { "Prev", 0.07 }, { "Next", 0.07 } } do
				const obj = w.bar[data[1]]
				obj.Position = UDim2.fromScale(x, 0)
				obj.Size = UDim2.new(data[2], -4, 0, 30)
				obj.TextSize = 12
				x += data[2]
			end
		else
			w.bar.Search.Position = UDim2.new()
			w.bar.Search.Size = UDim2.new(1, -92, 0, 30)
			w.bar.Refresh.Position = UDim2.new(1, -84, 0, 0)
			w.bar.Refresh.Size = UDim2.fromOffset(84, 30)
			for i, key in { "Filter", "Mode", "Prev", "Next" } do
				w.bar[key].Size = UDim2.new(i <= 2 and 0.38 or 0.12, -5, 0, 30)
				w.bar[key].Position = UDim2.new(i <= 2 and (i - 1) * 0.38 or 0.76 + (i - 3) * 0.12, 0, 0, 38)
			end
			for _, key in { "Search", "Refresh", "Filter", "Mode", "Prev", "Next" } do w.bar[key].TextSize = 13 end
		end
		const reserve = 0
		const list, detail, empty = w.list, w.detail, w.cols.Empty
		if narrow then
			list.Position = UDim2.new()
			list.Size = UDim2.new(1, -reserve, 0.38, -4)
			detail.Position = UDim2.new(0, 0, 0.38, 4)
			detail.Size = UDim2.new(1, -reserve, 0.62, -4)
			empty.Size = UDim2.new(1, -12, 0.38, -4)
		else
			list.Position = UDim2.new()
			list.Size = UDim2.new(0.45, -reserve - 6, 1, 0)
			detail.Position = UDim2.fromScale(0.45, 0)
			detail.Size = UDim2.new(0.55, -reserve, 1, 0)
			empty.Size = UDim2.new(0.45, -12, 1, 0)
		end
		if w.recTop then
			const height = short and 32 or 38
			const gap = 4
			const top = T.rec.tab == "saved" and height + gap or 2 * (height + gap)
			for _, row in { w.recTop, w.recAlt, w.recTools } do row.Size = UDim2.new(1, 0, 0, height) end
			w.recTop.Position = UDim2.new()
			w.recAlt.Position = UDim2.new()
			w.recTools.Position = UDim2.fromOffset(0, height + gap)
			w.bar.Size = UDim2.new(1, 0, 0, top + height)
			for _, key in { "Refresh", "Filter", "Mode" } do w.bar[key].Visible = false end
			w.bar.Search.Position = UDim2.fromOffset(0, top)
			w.bar.Search.Size = UDim2.new(1, -76, 0, height)
			w.bar.Prev.Position = UDim2.new(1, -72, 0, top)
			w.bar.Prev.Size = UDim2.fromOffset(34, height)
			w.bar.Next.Position = UDim2.new(1, -34, 0, top)
			w.bar.Next.Size = UDim2.fromOffset(34, height)
			const y = top + height + 6
			w.cols.Position = UDim2.fromOffset(0, y)
			w.cols.Size = UDim2.new(1, 0, 1, -y - 24)
			list.Position = UDim2.new()
			list.Size = UDim2.fromScale(1, 1)
			detail.Visible = false
			empty.Size = UDim2.new(1, -12, 1, 0)
		end
		const transfer = w.body.Transfer
		transfer.Title.Size = UDim2.new(1, -12, 0, short and 20 or 32)
		transfer.Content.Position = UDim2.fromOffset(0, short and 24 or 40)
		transfer.Content.Size = UDim2.new(1, -reserve, 1, short and -58 or -92)
		for _, key in { "Confirm", "Close" } do
			const btn = transfer[key]
			btn.Position = UDim2.new(btn.Position.X.Scale, btn.Position.X.Offset, 1, short and -30 or -40)
			btn.Size = UDim2.new(0.5, -5, 0, short and 26 or 36)
		end
		for _, ctrl in w.scrolls or {} do ctrl.scheduleRefresh() end
	end
	T.scroll = function(w, target)
		const ctrl = NAmanage.CreateCustomScrollbar(target)
		if not ctrl then return end
		w.scrolls = w.scrolls or {}
		table.insert(w.scrolls, ctrl)
	end
	T.refreshScroll = function(w)
		w.cols.Visible = not w.body.Transfer.Visible
		for _, ctrl in w.scrolls or {} do
			if not ctrl.isActive() then ctrl.stopArrowHold() ctrl.stopThumbDrag() end
			ctrl.scheduleRefresh()
		end
	end
	T.saveSize = function(w)
		const sizing = NAmanage.ExecutorWindowSizing
		if not sizing or not sizing.Save then return end
		if NAmanage.GetAttr and (NAmanage.GetAttr(w.frame, "NAMenuMinimized") == true or NAmanage.GetAttr(w.frame, "NAMenuMaximized") == true) then return end
		sizing.Save(w.frame, "NA"..w.name.."SavedSizeX", "NA"..w.name.."SavedSizeY")
	end
	T.bind = function(name)
		if T.wins[name] then return T.wins[name] end
		const frame = NAUIMANAGER and NAUIMANAGER[name.."Frame"] or T.rootGui() and T.rootGui():FindFirstChild(name)
		if not frame then return nil end
		const body = frame.Container
		const w = { name = name, frame = frame, body = body, bar = body.Toolbar, cols = body.Columns, list = body.Columns.List, detail = body.Columns.Detail, page = 1 }
		T.wins[name] = w
		T.scroll(w, w.list)
		if name ~= "ActionRecorder" then T.scroll(w, w.detail) end
		T.scroll(w, body.Transfer.Content)
		if NAgui and type(NAgui.menu) == "function" then NAgui.menu(frame) end
		T.fit(w)
		T.on(name, frame:GetPropertyChangedSignal("AbsoluteSize"), function() T.layout(w) end)
		T.on(name, frame:GetPropertyChangedSignal("Size"), function()
			if NAmanage.GetAttr and NAmanage.GetAttr(frame, "NAResizeActive") == true then T.saveSize(w) end
		end)
		T.on(name, frame:GetAttributeChangedSignal("NAResizeActive"), function() T.saveSize(w) end)
		T.on(name, w.bar.Search:GetPropertyChangedSignal("Text"), function()
			w.searchId = (w.searchId or 0) + 1
			const ticket = w.searchId
			task.delay(0.15, function() if not T.dead and ticket == w.searchId and w.render then w.page = 1 w.render() end end)
		end)
		for _, data in { { "Prev", -1 }, { "Next", 1 } } do
			T.on(name, w.bar[data[1]].Activated, function()
				w.page = math.clamp(w.page + data[2], 1, math.max(1, math.ceil(#(w.rows or {}) / 60)))
				if w.render then w.render() end
			end)
		end
		T.on(name, body.Transfer.Close.Activated, function() body.Transfer.Visible = false end)
		T.on(name, body.Transfer.Confirm.Activated, function()
			if w.importing and w.import then
				const ok, err = w.import(body.Transfer.Content.Text.Text)
				if ok then body.Transfer.Visible = false w.render() end
				T.status(name, err or (ok and "Imported." or "Import failed."))
			end
		end)
		T.on(name, frame:GetPropertyChangedSignal("Visible"), function()
			T.refreshScroll(w)
			if not frame.Visible then
				T.scanId[name] = (T.scanId[name] or 0) + 1
				w.watchId = (w.watchId or 0) + 1
				T.clean(name.."Watch")
				if name == "InteractionBrowser" then T.stopInter() T.highlight(nil) end
				if name == "AssetBrowser" then
					w.lookup = nil
					T.stopPreview()
				end
				if name == "InteractionBrowser" or name == "AssetBrowser" then
					T.clean(name.."Rows")
					for _, row in w.list:GetChildren() do if row:IsA("GuiObject") then row:Destroy() end end
					w.rows = {} w.draw = nil w.sel = nil
					if name == "InteractionBrowser" then T.inter.items = {} T.inter.sel = nil
					else T.assets.items = {} T.assets.index = {} T.assets.sel = nil end
				end
			end
		end)
		T.on(name, body:GetPropertyChangedSignal("Visible"), function()
			T.refreshScroll(w)
			if name == "AssetBrowser" and not body.Visible then T.stopPreview() end
		end)
		T.on(name, body.Transfer:GetPropertyChangedSignal("Visible"), function() T.refreshScroll(w) T.measureTransfer(w) end)
		T.on(name, body.Transfer.Content:GetPropertyChangedSignal("AbsoluteSize"), function() T.measureTransfer(w) end)
		for _, prop in { "Text", "TextSize", "FontFace" } do T.on(name, body.Transfer.Content.Text:GetPropertyChangedSignal(prop), function() T.measureTransfer(w) end) end
		T.layout(w)
		return w
	end
	T.fit = function(w)
		const sizing = NAmanage.ExecutorWindowSizing
		const config = { key = w.name, baseWidth = 820, baseHeight = 610, minWidth = 300, minHeight = 360, mobileMinWidth = 280, mobileMinHeight = 240, viewportRatio = 0.94 }
		if sizing then
			if NAmanage.GetAttr and NAmanage.GetAttr(w.frame, "NAMenuMaximized") == true then return end
			const _, metrics = sizing.Apply(w.frame, config)
			if metrics then
				const profile = tostring(metrics.mobile)..":"..tostring(metrics.viewport)..":"..tostring(metrics.scale)
				if metrics.mobile and w.fitProfile ~= profile and not (NAmanage.GetAttr and NAmanage.GetAttr(w.frame, "NAMenuMinimized") == true) then
					w.frame.Size = UDim2.fromOffset(metrics.capWidth, metrics.capHeight)
					T.saveSize(w)
				end
				w.fitProfile = profile
			end
			if metrics and NAgui and NAgui.resizeable then w.resize = NAgui.resizeable(w.frame, Vector2.new(metrics.minWidth, metrics.minHeight), Vector2.new(5000, 5000)) end
		elseif not w.resize and NAgui and NAgui.resizeable then
			w.resize = NAgui.resizeable(w.frame, Vector2.new(280, 240), Vector2.new(5000, 5000))
		end
	end
	T.matches = function(w, value)
		return string.find(string.lower(tostring(value)), string.lower(w.bar.Search.Text), 1, true) ~= nil
	end
	T.roots = function(assets)
		const roots = { WS, player:FindFirstChildOfClass("PlayerGui") }
		if assets then
			for _, name in { "ReplicatedStorage", "Lighting", "SoundService", "ReplicatedFirst" } do
				local obj
				pcall(function() obj = service(name) end)
				if obj then table.insert(roots, obj) end
			end
		end
		return roots
	end
	T.scan = function(name, roots, visit, done)
		T.scanId[name] = (T.scanId[name] or 0) + 1
		const ticket = T.scanId[name]
		task.spawn(function()
			const queue = {}
			for _, root in roots do if root then table.insert(queue, root) end end
			local index, total = 1, 0
			while index <= #queue and total < 30000 and not T.dead and T.scanId[name] == ticket do
				const start = os.clock()
				local batch = 0
				repeat
					const obj = queue[index]
					queue[index] = false
					index += 1
					batch += 1
					total += 1
					if obj and obj.Parent and not T.own(obj) then
						pcall(visit, obj)
						local ok, kids = pcall(obj.GetChildren, obj)
						if ok then
							for _, kid in kids do
								if #queue < 35000 then table.insert(queue, kid) end
							end
						end
					end
				until index > #queue or batch >= 180 or total >= 30000 or os.clock() - start > 0.003
				task.wait()
			end
			if not T.dead and T.scanId[name] == ticket then done(total >= 30000 or #queue >= 35000) end
		end)
	end
	T.busy = function()
		const gui = T.rootGui()
		const stop = gui and gui:FindFirstChild("ToolsStop")
		if not stop then return end
		stop.Visible = T.recording == true or T.playing == true or next(T.inter.jobs) ~= nil
		stop.Text = T.recording and "Stop Recording" or T.playing and "Stop Playback" or "Stop Repeats"
		if T.playing and not T.pauseBtn then
			const pause = stop:Clone()
			pause.Name = "ToolsPause"
			pause.Position = stop.Position + UDim2.fromOffset(0, stop.Size.Y.Offset + 5)
			pause.Parent = gui
			T.pauseBtn = pause
			T.on("Lifetime", pause.Activated, T.pauseRun)
		end
		if T.pauseBtn then
			T.pauseBtn.Visible = T.playing == true
			T.pauseBtn.Text = T.paused and "Resume Playback" or "Pause Playback"
		end
	end
	T.restoreUI = function()
		const hidden = T.hidden or {}
		T.hidden = nil
		for obj in hidden do
			if obj.Parent then
				obj.Visible = true
				if T.wins.InteractionBrowser and obj == T.wins.InteractionBrowser.frame then T.scanInter()
				elseif T.wins.AssetBrowser and obj == T.wins.AssetBrowser.frame then T.scanAssets() end
			end
		end
	end
	T.hideUI = function()
		T.restoreUI()
		T.hidden = {}
		for _, obj in T.rootGui():GetChildren() do
			if obj:IsA("GuiObject") and obj.Name ~= "ToolsStop" and obj.Visible then T.hidden[obj] = true obj.Visible = false end
		end
	end
	T.input = function(step)
		const kind = step.kind
		const down = step.down == true
		local ok, err = false, "Input playback is unavailable."
		if kind == "key" then
			local key
			pcall(function() key = Enum.KeyCode[step.value] end)
			if not key or key == Enum.KeyCode.Unknown then return false, "Unknown key: "..tostring(step.value) end
			if VIM then ok, err = pcall(VIM.SendKeyEvent, VIM, down, key, false, game) end
			if not ok then
				const fn = if down then keypress else keyrelease
				if type(fn) == "function" then ok, err = pcall(fn, key.Value) end
			end
		elseif kind == "pointer" or kind == "move" or kind == "touch" then
			const cam = WS.CurrentCamera
			const size = cam and cam.ViewportSize or Vector2.new(800, 600)
			const x = math.floor(T.finite(step.x, 0.5, 0, 1) * size.X)
			const y = math.floor(T.finite(step.y, 0.5, 0, 1) * size.Y)
			if VIM then
				if kind == "touch" then ok, err = pcall(VIM.SendTouchEvent, VIM, tonumber(step.finger) or 1, tonumber(step.state) or 0, x, y)
				elseif kind == "move" then ok, err = pcall(VIM.SendMouseMoveEvent, VIM, x, y, game)
				else ok, err = pcall(VIM.SendMouseButtonEvent, VIM, x, y, tonumber(step.button) or 0, down, game, 0) end
			end
			if not ok and kind ~= "touch" then
				if type(mousemoveabs) == "function" then
					ok, err = pcall(mousemoveabs, x, y)
					if ok and kind == "pointer" then
						const fn = if step.button == 1 then (if down then mouse2press else mouse2release) else (if down then mouse1press else mouse1release)
						if type(fn) == "function" then ok, err = pcall(fn) else ok, err = false, "Mouse button playback is unavailable." end
					end
				end
			end
		end
		if ok and kind ~= "move" then
			const id = kind == "key" and "key:"..step.value or kind == "touch" and "touch:"..tostring(step.finger) or "pointer:"..tostring(step.button)
			if down or kind == "touch" and step.state ~= 2 then T.held[id] = T.clone(step) else T.held[id] = nil end
		end
		if ok then return true end
		return false, tostring(err)
	end
	T.release = function()
		const held = T.held
		T.held = {}
		for _, step in held do
			step.down = false
			if step.kind == "touch" then step.state = 2 end
			pcall(T.input, step)
		end
		T.held = {}
	end
	T.pauseRun = function()
		if not T.playing then return end
		T.paused = not T.paused
		if T.paused then
			T.wants = T.clone(T.held)
			T.release()
		else
			for _, step in T.wants do
				const ok, err = T.input(step)
				if not ok then T.stopPlay(err) return end
			end
			T.wants = {}
		end
		T.busy()
		T.status("ActionRecorder", T.paused and "Paused." or "Resumed.")
	end
	T.wait = function(seconds, ticket)
		local left = seconds
		while left > 0 and not T.dead and T.runId == ticket do
			const start = os.clock()
			task.wait(math.min(0.04, left))
			if not T.paused then left -= os.clock() - start end
		end
		while T.paused and not T.dead and T.runId == ticket do task.wait(0.04) end
		return not T.dead and T.runId == ticket
	end
	T.endHold = function(obj, token)
		if T.holds[obj] ~= token then return false, "Prompt hold ended early." end
		T.holds[obj] = nil
		return pcall(obj.InputHoldEnd, obj)
	end
	T.action = function(obj, kind, signal)
		if not obj or not obj.Parent then return false, "The object is no longer loaded. Refresh the list." end
		if T.own(obj) then return false, "NA controls are excluded." end
		if kind == "gui" then
			if not obj:IsA("GuiButton") or not T.visible(obj) or not obj.Active or not obj.Interactable then return false, "This button is hidden or disabled." end
			const event = signal == "MouseButton1Click" and "MouseButton1Click" or "Activated"
			if type(firesignal) == "function" then
				const ok, err = pcall(firesignal, obj[event])
				if ok then return true end
		return false, tostring(err)
			end
			if not VIM then return false, "Button playback is unavailable on this executor." end
			const pos = obj.AbsolutePosition + obj.AbsoluteSize * 0.5
			local ok, err = pcall(VIM.SendMouseButtonEvent, VIM, pos.X, pos.Y, 0, true, game, 0)
			if ok then
				task.wait()
				ok, err = pcall(VIM.SendMouseButtonEvent, VIM, pos.X, pos.Y, 0, false, game, 0)
			end
			if ok then return true end
		return false, tostring(err)
		elseif kind == "prompt" then
			if not obj:IsA("ProximityPrompt") or not obj.Enabled then return false, "This prompt is disabled." end
			if T.distance(obj) > obj.MaxActivationDistance + 1 then return false, "Move within the prompt's activation range." end
			if type(fireproximityprompt) == "function" then
				const ok, err = pcall(fireproximityprompt, obj)
				if ok then return true end
		return false, tostring(err)
			end
			if T.holds[obj] then return false, "This prompt is already being held." end
			const token = {}
			T.holds[obj] = token
			const ok, err = pcall(obj.InputHoldBegin, obj)
			if not ok then
				T.holds[obj] = nil
				return false, tostring(err)
			end
			task.wait(math.min(obj.HoldDuration + 0.05, 30))
			const ended, why = T.endHold(obj, token)
			return ended, not ended and tostring(why) or nil
		elseif kind == "click" then
			if not obj:IsA("ClickDetector") then return false, "This object is not a click detector." end
			if T.distance(obj) > obj.MaxActivationDistance + 1 then return false, "Move within the click detector's activation range." end
			if type(fireclickdetector) ~= "function" then return false, "Click detector playback is unavailable." end
			const ok, err = pcall(fireclickdetector, obj)
			if ok then return true end
		return false, tostring(err)
		elseif kind == "touch" then
			const char = getChar()
			const root = char and getRoot(char)
			const part = T.part(obj)
			if not root or not part then return false, "The character or touch part is unavailable." end
			if type(firetouchinterest) ~= "function" then return false, "Touch playback is unavailable." end
			const ok, err = pcall(function()
				firetouchinterest(root, part, 0)
				task.wait()
				firetouchinterest(root, part, 1)
			end)
			if ok then return true end
		return false, tostring(err)
		end
		return false, "Unsupported interaction."
	end
	T.validate = function(data)
		if type(data) ~= "table" or data.kind ~= "NARecording" or data.version ~= 1 or type(data.steps) ~= "table" or #data.steps > 2000 then return nil, "This is not a supported recording (maximum 2000 steps)." end
		const kinds = { command = true, wait = true, key = true, keytap = true, gui = true, prompt = true, click = true, touch = true, pointer = true, move = true, waitfor = true }
		const out = { kind = "NARecording", version = 1, name = string.sub(T.trim(data.name), 1, 80), place = tostring(data.place or game.PlaceId), game = tostring(data.game or game.GameId), steps = {} }
		local total = 0
		for key, src in data.steps do
			total += 1
			if total > 2000 or type(key) ~= "number" or key < 1 or key % 1 ~= 0 or key > #data.steps then return nil, "Recording steps must be a list of at most 2000 items." end
			if type(src) ~= "table" or not kinds[src.kind] then return nil, "The recording contains an unsupported step." end
			const step = T.pack(src)
			step.delay = T.finite(step.delay, 0, 0, 3600)
			step.extra = T.finite(step.extra, step.kind == "keytap" and 0.1 or 5, 0, 300)
			step.value = string.sub(tostring(step.value or ""), 1, 16000)
			if step.path and (type(step.path) ~= "table" or type(step.path.root) ~= "string" or type(step.path.segs) ~= "table" or #step.path.segs > 80) then return nil, "A recorded object path is invalid." end
			if step.path then
				for _, seg in step.path.segs do
					if type(seg) ~= "table" or type(seg.name) ~= "string" or #seg.name > 1000 or seg.class and type(seg.class) ~= "string" then return nil, "An object path contains an invalid name." end
				end
			end
			table.insert(out.steps, step)
		end
		return out
	end
	T.snapshotRec = function()
		return { kind = "NARecording", version = 1, name = T.rec.name, place = T.rec.place or tostring(game.PlaceId), game = T.rec.game or tostring(game.GameId), steps = T.pack(T.rec.steps) }
	end
	T.addStep = function(step, timed)
		if not step then return false end
		if T.rec.place and T.rec.place ~= tostring(game.PlaceId) then
			T.status("ActionRecorder", "Start a new recording to add steps in this place.")
			return false
		end
		if #T.rec.steps >= 2000 then
			T.stopRecord()
			T.status("ActionRecorder", "Recording reached the 2000-step limit.")
			return false
		end
		T.rec.place = tostring(game.PlaceId)
		T.rec.game = tostring(game.GameId)
		if timed then
			const now = os.clock()
			step.delay = math.max(0, now - (T.rec.last or now))
			T.rec.last = now
		end
		step.delay = step.delay or 0
		table.insert(T.rec.steps, step)
		T.rec.dirty = true
		const w = T.wins.ActionRecorder
		if w and w.frame.Visible and not T.rec.pending then
			T.rec.pending = true
			task.delay(0.15, function()
				T.rec.pending = false
				if not T.dead and w.render then w.render() end
			end)
		end
		return true
	end
	T.objectStep = function(obj, kind, signal)
		const path = T.pathOf(obj)
		if not path then return nil end
		return { kind = kind, path = path, value = T.pathText(path), signal = signal }
	end
	T.stopRecord = function()
		const was = T.recording
		T.recording = false
		T.scanId.Recording = (T.scanId.Recording or 0) + 1
		T.clean("Recording")
		T.rec.pressed = {}
		T.rec.fingers = {}
		if T.rec.restore then
			T.rec.restore = false
			const w = T.wins.ActionRecorder
			if w and w.frame.Parent and not T.dead then
				w.frame.Visible = true
				if was then
					w.page = math.max(1, math.ceil(#T.rec.steps / 60))
					w.render()
					T.status(w.name, #T.rec.steps.." steps. Tap a step to edit it, or choose Play.")
				end
			end
		end
		T.busy()
	end
	T.stopPlay = function(reason)
		T.runId += 1
		T.playing = false
		T.paused = false
		T.release()
		T.wants = {}
		if not T.dead then T.restoreUI() else T.hidden = nil end
		T.busy()
		if reason then T.status("ActionRecorder", reason) end
	end
	T.record = function()
		if T.rec.place and T.rec.place ~= tostring(game.PlaceId) then T.status("ActionRecorder", "Choose More, then New Recording to record in this place.") return end
		if T.playing then T.stopPlay() end
		T.stopRecord()
		T.recording = true
		T.rec.place = tostring(game.PlaceId)
		T.rec.game = tostring(game.GameId)
		T.rec.last = os.clock()
		T.rec.pressed = {}
		T.rec.fingers = {}
		T.rec.finger = 0
		T.rec.moves = 0
		const recWin = T.wins.ActionRecorder
		if recWin and recWin.frame.Visible then
			T.recTab(recWin, "steps")
			T.rec.restore = true
			recWin.frame.Visible = false
		end
		const function coord(input)
			const cam = WS.CurrentCamera
			const size = cam and cam.ViewportSize or Vector2.new(800, 600)
			return math.clamp(input.Position.X / math.max(1, size.X), 0, 1), math.clamp(input.Position.Y / math.max(1, size.Y), 0, 1)
		end
		const function ownAt(input)
			const pos = input.Position
			const gui = T.rootGui()
			for _, kid in gui and gui:GetChildren() or {} do
				if kid:IsA("GuiObject") and kid.Visible and T.visible(kid) then
					const a, s = kid.AbsolutePosition, kid.AbsoluteSize
					if pos.X >= a.X and pos.X <= a.X + s.X and pos.Y >= a.Y and pos.Y <= a.Y + s.Y then return true end
				end
			end
			return false
		end
		const function buttonAt(input)
			const pg = player:FindFirstChildOfClass("PlayerGui")
			if not pg then return nil end
			local ok, list = pcall(pg.GetGuiObjectsAtPosition, pg, input.Position.X, input.Position.Y)
			if not ok then return nil end
			for _, obj in list do
				local cur = obj
				while cur and cur ~= pg do
					if cur:IsA("GuiButton") and cur.Active and cur.Interactable and T.visible(cur) and not T.own(cur) then return cur end
					cur = cur.Parent
				end
			end
		end
		T.on("Recording", UIS.InputBegan, function(input, processed)
			if not T.recording or UIS:GetFocusedTextBox() then return end
			const typ = input.UserInputType
			const mouse = typ == Enum.UserInputType.MouseButton1 or typ == Enum.UserInputType.MouseButton2
			const touch = typ == Enum.UserInputType.Touch
			if (mouse or touch) and ownAt(input) then return end
			if T.rec.mode == "actions" and (typ == Enum.UserInputType.MouseButton1 or touch) then
				const btn = buttonAt(input)
				if btn then
					T.rec.pressed[input] = { button = btn }
					return
				end
			end
			if T.rec.mode == "actions" or processed and not (touch or mouse) then return end
			if typ == Enum.UserInputType.Keyboard and input.KeyCode ~= Enum.KeyCode.Unknown then
				T.rec.pressed[input.KeyCode] = { kind = "key", value = input.KeyCode.Name, down = true }
				T.addStep(T.clone(T.rec.pressed[input.KeyCode]), true)
			elseif mouse then
				const x, y = coord(input)
				const step = { kind = "pointer", button = typ == Enum.UserInputType.MouseButton2 and 1 or 0, down = true, x = x, y = y }
				T.rec.pressed[typ] = step
				T.addStep(T.clone(step), true)
			elseif touch then
				T.rec.finger += 1
				const x, y = coord(input)
				const step = { kind = "touch", finger = T.rec.finger, state = 0, x = x, y = y }
				T.rec.fingers[input] = step
				T.addStep(T.clone(step), true)
			end
		end)
		T.on("Recording", UIS.InputEnded, function(input)
			if not T.recording then return end
			const hit = T.rec.pressed[input]
			if hit and hit.button then
				T.rec.pressed[input] = nil
				if hit.button.Parent and not ownAt(input) and buttonAt(input) == hit.button then
					T.addStep(T.objectStep(hit.button, "gui", "Activated"), true)
				end
				return
			end
			const key = input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode or input.UserInputType
			const step = T.rec.pressed[key]
			if step then
				const out = T.clone(step)
				out.down = false
				T.addStep(out, true)
				T.rec.pressed[key] = nil
			end
			const finger = T.rec.fingers[input]
			if finger then
				const out = T.clone(finger)
				out.state = 2
				out.x, out.y = coord(input)
				T.addStep(out, true)
				T.rec.fingers[input] = nil
			end
		end)
		T.on("Recording", UIS.InputChanged, function(input)
			if not T.recording or T.rec.mode == "actions" or os.clock() - T.rec.moves < 0.08 then return end
			const finger = T.rec.fingers[input]
			if finger then
				const out = T.clone(finger)
				out.state = 1
				out.x, out.y = coord(input)
				T.addStep(out, true)
				T.rec.moves = os.clock()
			elseif input.UserInputType == Enum.UserInputType.MouseMovement and (T.rec.pressed[Enum.UserInputType.MouseButton1] or T.rec.pressed[Enum.UserInputType.MouseButton2]) then
				const x, y = coord(input)
				T.addStep({ kind = "move", x = x, y = y }, true)
				T.rec.moves = os.clock()
			end
		end)
		if T.rec.mode == "actions" and PPS then
			T.on("Recording", PPS.PromptTriggered, function(prompt, who)
				if not who or who == player then T.addStep(T.objectStep(prompt, "prompt"), true) end
			end)
		end
		if T.rec.mode == "actions" then T.recordWatch() end
		T.busy()
		T.status("ActionRecorder", "Recording. Use Stop Recording when finished.")
	end
	T.commandEntry = function(name)
		name = tostring(name or ""):lower()
		const entry = cmds.Commands[name] or cmds.Aliases[name]
		if not entry then return nil, "Command not found: "..name end
		for _, blocked in { "actionrecorder", "recordactions", "stopactions", "playrecord", "gameprofiles", "applyprofile", "pluginmaker" } do
			const control = cmds.Commands[blocked]
			if name == blocked or control and control[1] == entry[1] then
				return nil, "Recorder, profile and plugin maker controls cannot be replayed as steps."
			end
		end
		return entry
	end
	T.execute = function(step, ticket, rate)
		rate = rate or 1
		if step.kind == "wait" then return T.wait(T.finite(step.value, step.extra or 1, 0, 3600) / rate, ticket) end
		if step.kind == "command" then
			const argv, why = NAmanage.MCPNormalizeArgs(step.args or step.value)
			if not argv then return false, why end
			const entry, err = T.commandEntry(argv[1])
			if not entry then return false, err end
			return cmd.run(argv, { prediction = false })
		end
		if step.kind == "keytap" then
			const press = { kind = "key", value = step.value, down = true }
			const ok, msg = T.input(press)
			if not ok then return false, msg end
			if not T.wait(T.finite(step.extra, 0.1, 0.01, 300) / rate, ticket) then return false, "Stopped." end
			press.down = false
			return T.input(press)
		end
		if step.kind == "key" or step.kind == "pointer" or step.kind == "move" or step.kind == "touch" and step.finger then return T.input(step) end
		const path = step.path or T.parsePath(step.value)
		if step.kind == "waitfor" then
			local elapsed = 0
			while not T.dead and T.runId == ticket and elapsed <= T.finite(step.extra, 5, 0.1, 300) do
				const obj = T.resolve(path)
				if obj and (not obj:IsA("GuiObject") or T.visible(obj)) then return true end
				if not T.wait(0.1, ticket) then return false, "Stopped." end
				elapsed += 0.1
			end
			return false, "Timed out waiting for "..T.pathText(path)
		end
		return T.action(T.resolve(path), step.kind, step.signal)
	end
	T.play = function(data, count, rate)
		const rec, why = T.validate(data)
		if not rec then return false, why end
		if #rec.steps == 0 then return false, "Add or record some steps first." end
		if rec.place ~= tostring(game.PlaceId) then return false, "This recording belongs to a different place." end
		T.stopRecord()
		T.stopPlay()
		T.playing = true
		T.paused = false
		T.hideUI()
		const ticket = T.runId
		count = math.floor(T.finite(count, 1, 1, 1000))
		rate = T.finite(rate, 1, 0.1, 10)
		T.busy()
		task.spawn(function()
			local reason = "Playback finished."
			local ok, err = pcall(function()
				for turn = 1, count do
					for i, step in rec.steps do
						if not T.wait(step.delay / rate, ticket) then return end
						T.status("ActionRecorder", "Playing "..i.." / "..#rec.steps.."  |  Repeat "..turn.." / "..count)
						const success, msg = T.execute(step, ticket, rate)
						if not success then reason = "Step "..i.." ("..T.recLabel(step):sub(1, 65)..") failed. "..tostring(msg or "Playback failed.") return end
					end
					T.release()
					if not T.wait(0.05, ticket) then return end
				end
			end)
			if T.runId == ticket then T.stopPlay(ok and reason or tostring(err)) end
		end)
		return true
	end
	T.recDefs = {
		{ key = "command", label = "Run a command", command = true, help = "Enter the command and arguments as you would in the NA command bar.",
			fields = { { "value", "Command and arguments", "Example: walkspeed 32" } } },
		{ key = "wait", label = "Wait", fields = { { "value", "Seconds to wait", "1", "1" } } },
		{ key = "keytap", label = "Press a key", fields = { { "value", "Roblox key name", "Example: Space or W" }, { "extra", "Hold for (seconds)", "0.1", "0.1" } } },
		{ key = "gui", label = "Click a game button", browse = true, advanced = true, fields = { { "value", "Object path", "PlayerGui/Menu/Button" } } },
		{ key = "prompt", label = "Use a proximity prompt", browse = true, advanced = true, fields = { { "value", "Object path", "Workspace/Door/Prompt" } } },
		{ key = "click", label = "Click a world object", browse = true, advanced = true, fields = { { "value", "Object path", "Workspace/Part/ClickDetector" } } },
		{ key = "touch", label = "Touch a world object", browse = true, advanced = true, fields = { { "value", "Object path", "Workspace/Part" } } },
		{ key = "waitfor", label = "Wait for an object", advanced = true, fields = {
			{ "value", "Object path", "PlayerGui/Menu/Button" }, { "extra", "Timeout (seconds)", "5", "5" },
		} },
		{ key = "key", label = "Recorded key input", editOnly = true, fields = { { "value", "Roblox key name", "Example: Space or W" } } },
		{ key = "pointer", label = "Recorded mouse click", editOnly = true },
		{ key = "move", label = "Recorded mouse movement", editOnly = true },
		{ key = "screen_touch", label = "Recorded screen touch", editOnly = true },
	}
	for _, def in T.recDefs do
		def.fields = def.fields or {}
		table.insert(def.fields, { "delay", "Pause before this step (seconds)", "0", "0" })
	end
	T.recLabel = function(step)
		if step.kind == "key" then return (step.down and "Hold " or "Release ")..step.value end
		if step.kind == "pointer" then
			return (step.down and "Press " or "Release ")..(step.button == 1 and "right click" or "left click")
		end
		if step.kind == "touch" and step.finger then
			return (step.state == 2 and "End touch " or step.state == 1 and "Move touch " or "Start touch ")..step.finger
		end
		for _, def in T.recDefs do
			if step.kind == def.key then
				local val = T.trim(step.value)
				if val == "" and step.path then val = T.pathText(step.path) end
				if step.kind == "wait" and val ~= "" then return "Wait "..val.."s" end
				return def.label..(val ~= "" and ("  ·  "..val:gsub("[%c]+", " ")) or "")
			end
		end
		return "Recorded step"
	end
	T.recCanEdit = function(w)
		if T.playing or T.recording then
			T.status(w.name, "Stop recording or playback before editing.")
			return false
		end
		return true
	end
	T.recTab = function(w, tab)
		T.rec.tab = tab
		w.sel = nil
		w.page = 1
		w.bar.Search.Text = ""
		w.bar.Search.PlaceholderText = tab == "saved" and "Search recordings" or "Search steps"
		w.recTop.Visible = tab == "steps"
		w.recAlt.Visible = tab == "saved"
		w.recTools.Visible = tab == "steps"
		T.layout(w)
		w.render()
	end
	T.confirmDiscard = function(w, run)
		if not T.rec.dirty then run() return end
		const F = NAmanage.BuilderUI
		const list, close = F.dialog(w.frame, "Discard Unsaved Changes")
		F.text(list, "Save your current recording first if you want to keep it.")
		F.buttons(list, { { "Discard Changes", function() close() run() end } })
	end
	T.recNew = function(w)
		if not T.recCanEdit(w) then return end
		T.confirmDiscard(w, function()
			T.rec.steps = {}
			T.rec.id = nil
			T.rec.name = ""
			T.rec.place = nil
			T.rec.game = nil
			T.rec.dirty = false
			T.recTab(w, "steps")
			T.status(w.name, "New recording. Choose Record or Add Step.")
		end)
	end
	T.recSaved = function(w, item)
		if not T.recCanEdit(w) then return end
		const F = NAmanage.BuilderUI
		const data = T.data.records[item.key]
		if not data then return end
		const list, close, status = F.dialog(w.frame, "Saved Recording")
		F.text(list, data.name ~= "" and data.name or "Unnamed recording", true)
		F.text(list, #data.steps.." steps  ·  Place "..data.place)
		F.buttons(list, { { "Open Recording", function()
			close()
			T.confirmDiscard(w, function()
				const rec, err = T.validate(data)
				if not rec then T.status(w.name, err) return end
				T.rec.steps = rec.steps
				T.rec.name = rec.name
				T.rec.id = item.key
				T.rec.place = rec.place
				T.rec.game = rec.game
				T.rec.dirty = false
				T.recTab(w, "steps")
				T.status(w.name, "Opened "..rec.name..".")
			end)
		end, true }, { "Play Recording", function()
			const ok, err = T.play(data, T.rec.repeats, T.rec.rate)
			if ok then close() else status.Text = err end
		end } })
		F.buttons(list, { { "Delete Recording", function()
			const confirm, done = F.dialog(w.frame, "Delete Saved Recording")
			F.text(confirm, "Delete "..(data.name ~= "" and data.name or "this recording").."?")
			F.buttons(confirm, { { "Delete", function()
				T.data.records[item.key] = nil
				if T.rec.id == item.key then
					T.rec.id = nil
					T.rec.dirty = #T.rec.steps > 0
				end
				const ok, err = T.save()
				done()
				w.render()
				T.status(w.name, ok and "Deleted recording." or err)
			end } })
		end } })
	end
	T.recStep = function(kind, fields, old)
		const same = old and (kind == old.kind or kind == "screen_touch" and old.kind == "touch" and old.finger)
		const step = same and T.clone(old) or {}
		step.kind = kind == "screen_touch" and "touch" or kind
		const delay = tonumber(T.trim(fields.delay) ~= "" and fields.delay or "0")
		if not delay or delay ~= delay or delay < 0 or delay > 3600 then return nil, "Enter a pause between 0 and 3600 seconds." end
		step.delay = delay
		if fields.value ~= nil then step.value = T.trim(fields.value) end
		if fields.extra ~= nil then
			const sec = tonumber(fields.extra)
			const min = kind == "keytap" and 0.01 or 0.1
			if not sec or sec ~= sec or sec < min or sec > 300 then return nil, "Enter a duration between "..min.." and 300 seconds." end
			step.extra = sec
		end
		if kind == "command" then
			local argv, why
			if same and old.value == step.value and type(old.args) == "table" then argv = old.args
			else argv, why = NAmanage.MCPNormalizeArgs(step.value) end
			if not argv then return nil, why end
			const entry, err = T.commandEntry(argv[1])
			if not entry then return nil, err end
			step.args = table.clone(argv)
		elseif kind == "wait" then
			const sec = tonumber(step.value)
			if not sec or sec ~= sec or sec < 0 or sec > 3600 then return nil, "Enter a wait between 0 and 3600 seconds." end
		elseif kind == "keytap" or kind == "key" then
			local key
			pcall(function() key = Enum.KeyCode[step.value] end)
			if not key then
				for _, item in Enum.KeyCode:GetEnumItems() do
					if item.Name:lower() == step.value:lower() then key = item break end
				end
			end
			if not key or key == Enum.KeyCode.Unknown then return nil, "Enter a key name such as Space or W." end
			step.value = key.Name
		elseif kind == "gui" or kind == "prompt" or kind == "click" or kind == "touch" or kind == "waitfor" then
			if step.value == "" then return nil, "Enter a path or choose the object in Game Interactions." end
			step.path = same and old.value == step.value and old.path or T.parsePath(step.value)
			if not step.path or #step.path.segs == 0 then return nil, "Enter an object path such as Workspace/Door/Prompt." end
		end
		return step
	end
	T.recBrowse = function(w)
		const ok, err = T.open("InteractionBrowser", true)
		if ok then NAgui.setWindowVisible(w.frame, false)
		else T.status(w.name, err) end
	end
	T.recEdit = function(w, index)
		if not T.recCanEdit(w) then return end
		const F = NAmanage.BuilderUI
		const old = index and T.rec.steps[index]
		const edit = {}
		local close
		const function changed()
			T.rec.dirty = true
			w.render()
			if close then close() end
		end
		if index then
			if index > 1 then table.insert(edit, { "Move Up", function()
				T.rec.steps[index], T.rec.steps[index - 1] = T.rec.steps[index - 1], old
				w.sel = index - 1
				changed()
			end }) end
			if index < #T.rec.steps then table.insert(edit, { "Move Down", function()
				T.rec.steps[index], T.rec.steps[index + 1] = T.rec.steps[index + 1], old
				w.sel = index + 1
				changed()
			end }) end
			table.insert(edit, { "Delete Step", function()
				table.remove(T.rec.steps, index)
				w.sel = nil
				changed()
			end })
		end
		const start = old and T.clone(old)
		if start and start.kind == "touch" and start.finger then start.kind = "screen_touch" end
		if start and T.trim(start.value) == "" and start.path then start.value = T.pathText(start.path) end
		close = F.step(w.frame, {
			defs = T.recDefs, step = start, edit = #edit > 0 and edit or nil, advanced = true,
			browse = function() T.recBrowse(w) end,
			save = function(kind, fields)
				const step, err = T.recStep(kind, fields, old)
				if not step then return false, err end
				if index then
					T.rec.steps[index] = step
				elseif not T.addStep(step) then
					return false, "Start a new recording in this place or remove some steps."
				else
					w.sel = #T.rec.steps
					w.page = math.ceil(#T.rec.steps / 60)
				end
				changed()
				return true
			end,
			test = function(kind, fields)
				const step, err = T.recStep(kind, fields, old)
				if not step then return false, err end
				step.delay = 0
				const data = T.snapshotRec()
				data.steps = { step }
				return T.play(data, 1, 1)
			end,
		})
	end
	T.recRender = function()
		const w = T.wins.ActionRecorder
		if not w then return end
		const rows = {}
		local pick
		if T.rec.tab == "saved" then
			w.empty = w.bar.Search.Text == "" and "No recordings saved here yet. Save a recording or import one." or "No saved recordings match your search."
			for id, data in T.data.records do
				if type(data) == "table" and (T.rec.all or tostring(data.game) == tostring(game.GameId)) and T.matches(w, data.name or id) then
					table.insert(rows, { key = id, title = data.name ~= "" and data.name or "Unnamed recording", meta = #data.steps.." steps  ·  Place "..data.place })
				end
			end
			table.sort(rows, function(a, b) if a.title == b.title then return a.key < b.key end return a.title < b.title end)
			pick = function(item) T.recSaved(w, item) end
		else
			w.empty = w.bar.Search.Text == "" and "Choose Record to capture what you do, or Add Step to build a recording by hand." or "No steps match your search."
			for i, step in T.rec.steps do
				const label = T.recLabel(step)
				if T.matches(w, label) then
					table.insert(rows, { key = i, title = i..". "..label,
						meta = step.delay and step.delay > 0 and string.format("%.2fs before this step", step.delay) or "Runs immediately" })
				end
			end
			pick = function(item) T.recEdit(w, item.key) end
		end
		T.rows(w, rows, pick)
		const title = T.rec.tab == "saved" and (#rows.." saved recordings") or
			((T.rec.name ~= "" and T.rec.name or "Untitled recording").."  ·  "..#T.rec.steps.." steps"..(T.rec.dirty and "  ·  Unsaved" or ""))
		const pages = math.ceil(#rows / 60)
		T.status(w.name, title..(pages > 1 and ("  ·  Page "..w.page.."/"..pages) or ""))
	end
	T.saveRec = function(name)
		name = string.sub(T.trim(name), 1, 80)
		if name == "" then return false, "Enter a recording name." end
		if #T.rec.steps == 0 then return false, "Add or record some steps first." end
		const raw = T.snapshotRec()
		raw.name = name
		const data, err = T.validate(raw)
		if not data then return false, err end
		const id = T.rec.id or Http:GenerateGUID(false)
		T.data.records[id] = data
		T.rec.id = id
		T.rec.name = name
		const ok, msg = T.save()
		T.rec.dirty = not ok
		T.recRender()
		return ok, ok and "Saved "..name.."." or msg
	end
	T.recSavePrompt = function(w)
		if not T.recCanEdit(w) then return end
		const F = NAmanage.BuilderUI
		const list, close, status = F.dialog(w.frame, "Save Recording")
		const name = F.field(list, "Recording name", "Example: Quick Setup", T.rec.name)
		F.buttons(list, { { "Save Recording", function()
			const ok, msg = T.saveRec(name.Text)
			if ok then close() T.status(w.name, msg) else status.Text = msg end
		end, true } })
	end
	T.recCapture = function(w)
		if not T.recCanEdit(w) then return end
		const F = NAmanage.BuilderUI
		const list, close = F.dialog(w.frame, "What Do You Want to Record?")
		for _, mode in {
			{ "actions", "Commands & Interactions", "Run NA commands or use game buttons, prompts and objects." },
			{ "inputs", "Controls", "Capture key presses, mouse clicks and screen touches." },
			{ "both", "Commands & Controls", "Capture NA commands together with game controls." },
		} do
			F.buttons(list, { { mode[2], function()
				close()
				T.rec.mode = mode[1]
				T.record()
			end, mode[1] == T.rec.mode } })
			F.text(list, mode[3])
		end
		F.text(list, "Use the Stop Recording button to return to your steps.")
	end
	T.recMore = function(w)
		const F = NAmanage.BuilderUI
		const list, close = F.dialog(w.frame, "Recording Options")
		F.buttons(list, { { "Playback Settings", function()
			const menu, done, status = F.dialog(w.frame, "Playback Settings")
			const times = F.field(menu, "Repeat count", "1", T.rec.repeats or 1)
			const speed = F.field(menu, "Playback speed", "1", T.rec.rate or 1)
			F.buttons(menu, { { "Apply", function()
				const count, rate = tonumber(times.Text), tonumber(speed.Text)
				if not count or count % 1 ~= 0 or count < 1 or count > 1000 or not rate or rate ~= rate or rate < 0.1 or rate > 10 then
					status.Text = "Use 1–1000 repeats and a speed from 0.1 to 10."
					return
				end
				T.rec.repeats, T.rec.rate = count, rate
				done()
				T.status(w.name, "Playback set to "..count.." repeats at "..rate.."x.")
			end, true } })
		end } })
		F.buttons(list, { { "Browse Game Interactions", function() close() T.recBrowse(w) end } })
		F.buttons(list, { { "Make Plugin", function()
			if #T.rec.steps == 0 then close() T.status(w.name, "Add or record some steps first.") return end
			const blob, err = T.encode(T.snapshotRec())
			if not blob then close() T.status(w.name, err) return end
			close()
			const ok, why = NAmanage.PluginMaker_FromRecording(blob, T.rec.name)
			if ok then NAgui.setWindowVisible(w.frame, false) else T.status(w.name, why) end
		end } })
		F.buttons(list, { { "Export Recording JSON", function()
			close()
			local raw, err = T.encode(T.snapshotRec())
			if raw then T.message(w.name, "Recording JSON", raw, false) else T.status(w.name, err) end
		end }, { "Import Recording JSON", function() close() T.message(w.name, "Paste Recording JSON", "", true) end } })
		F.buttons(list, { { "New Recording", function() close() T.recNew(w) end } })
	end
	T.initRec = function(w)
		const F = NAmanage.BuilderUI
		w.render = T.recRender
		w.import = function(raw)
			const data, err = T.validate(T.decode(raw))
			if not data then return false, err end
			const id = Http:GenerateGUID(false)
			T.data.records[id] = data
			if tostring(data.game) ~= tostring(game.GameId) then T.rec.all = true end
			if w.recScope then w.recScope.Text = T.rec.all and "All Games" or "This Game" end
			T.recTab(w, "saved")
			const ok, msg = T.save()
			return true, ok and "Imported "..data.name.."." or msg
		end
		w.recTop = F.buttons(w.bar, {
			{ "Record", function() T.recCapture(w) end, true },
			{ "Play", function()
				const ok, err = T.play(T.snapshotRec(), T.rec.repeats, T.rec.rate)
				if not ok then T.status(w.name, err) end
			end },
			{ "Add Step", function() T.recEdit(w) end },
		})
		w.recAlt = F.buttons(w.bar, {
			{ "Back to Steps", function() T.recTab(w, "steps") end, true },
			{ "Import", function() T.message(w.name, "Paste Recording JSON", "", true) end },
			{ "This Game", function()
				T.rec.all = not T.rec.all
				w.recScope.Text = T.rec.all and "All Games" or "This Game"
				w.page = 1
				w.render()
			end },
		})
		for _, child in w.recAlt:GetChildren() do
			if child:IsA("TextButton") and child.LayoutOrder == 3 then w.recScope = child break end
		end
		w.recTools = F.buttons(w.bar, {
			{ "Saved Recordings", function() T.recTab(w, "saved") end },
			{ "Save Recording", function() T.recSavePrompt(w) end },
			{ "More", function() T.recMore(w) end },
		})
		T.recTab(w, "steps")
		T.layout(w)
	end
	T.interKind = function(obj)
		if obj:IsA("ProximityPrompt") then return "prompt" end
		if obj:IsA("ClickDetector") then return "click" end
		if obj:IsA("TouchTransmitter") and obj.Parent and obj.Parent:IsA("BasePart") then return "touch" end
		if obj:IsA("GuiButton") then return "gui" end
	end
	T.highlight = function(obj)
		if T.mark then T.mark:Destroy() T.mark = nil end
		if not obj then return end
		const target = T.part(obj)
		if target then
			const mark = Instance.new("Highlight")
			mark.Name = "InteractionPreview"
			mark.Adornee = target
			mark.FillColor = Color3.fromRGB(143, 104, 242)
			mark.FillTransparency = 0.6
			mark.OutlineTransparency = 0
			mark.Parent = T.rootGui()
			T.mark = mark
		end
	end
	T.stopInter = function()
		for _, job in T.inter.jobs do job.stop = true end
		T.inter.jobs = {}
		T.busy()
	end
	T.interInfo = function()
		const w = T.wins.InteractionBrowser
		const entry = T.inter.sel
		if not w or not entry then return end
		const obj = entry.obj
		w.detail.Title.Text = obj.Parent and obj.Name or "No longer loaded"
		w.detail.Path.Text = T.pathText(entry.path)
		local info = entry.kind.."  |  "..obj.ClassName
		if obj.Parent then
			if entry.kind == "prompt" then
				info ..= "\n"..obj.ActionText.."  "..obj.ObjectText.."\nRange "..string.format("%.1f", obj.MaxActivationDistance).."  |  Hold "..obj.HoldDuration.."s  |  "..(obj.Enabled and "Enabled" or "Disabled")
			elseif entry.kind == "click" then info ..= "\nRange "..obj.MaxActivationDistance
			elseif entry.kind == "gui" then info ..= "\n"..(obj:IsA("TextButton") and obj.Text or "Image button").."\n"..(T.visible(obj) and "Visible" or "Hidden") end
			const dist = T.distance(obj)
			if dist < math.huge and entry.kind ~= "gui" then info ..= "\nDistance "..string.format("%.1f studs", dist) end
		end
		w.detail.Info.Text = info
		w.detail.Repeat.Text = T.inter.jobs[entry.obj] and "Stop repeating selected" or "Repeat selected"
	end
	T.interRender = function()
		const w = T.wins.InteractionBrowser
		if not w then return end
		const rows = {}
		const radius = T.finite(w.detail.Radius.Text, 100, 1, 100000)
		const labels = { prompt = "Prompts", click = "Clicks", touch = "Touches", gui = "Buttons" }
		const live = {}
		for _, item in T.inter.items do
			const obj = item.obj
			if obj.Parent then table.insert(live, item) elseif T.inter.seen then T.inter.seen[obj] = nil end
			if obj.Parent and (T.inter.kind == "All" or T.inter.kind == labels[item.kind]) then
				const dist = T.distance(obj)
				const near = item.kind == "gui" and T.visible(obj) or item.kind ~= "gui" and dist <= radius
				const title = obj.Name..(item.kind == "prompt" and "  "..obj.ActionText or item.kind == "gui" and obj:IsA("TextButton") and "  "..obj.Text or "")
				if (not T.inter.near or near) and (T.matches(w, title) or w.bar.Search.Text ~= "" and T.matches(w, T.pathText(item.path))) then
					table.insert(rows, { key = obj, title = title, meta = labels[item.kind].."  |  "..(item.kind == "gui" and (near and "visible" or "hidden") or dist == math.huge and "distance unavailable" or string.format("%.1f studs", dist))..(T.inter.jobs[obj] and "  |  repeating" or ""), item = item, dist = dist })
				end
			end
		end
		T.inter.items = live
		table.sort(rows, function(a, b) if a.dist == b.dist then return a.title < b.title end return a.dist < b.dist end)
		T.rows(w, rows, function(row) T.inter.sel = row.item T.interInfo() end)
		T.interInfo()
	end
	T.watch = function(w, roots, visit)
		const group = w.name.."Watch"
		T.clean(group)
		w.watchId = (w.watchId or 0) + 1
		const ticket = w.watchId
		for _, root in roots do
			if root then
				T.on(group, root.DescendantAdded, function(obj)
					if not T.own(obj) then
						const ok, added = pcall(visit, obj)
						if ok and added then w.changed = true end
					end
				end)
				T.on(group, root.DescendantRemoving, function(obj)
					if not T.own(obj) then w.changed = true end
				end)
			end
		end
		task.spawn(function()
			while not T.dead and w.frame.Parent and w.frame.Visible and w.watchId == ticket do
				task.wait(1)
				if not w.frame.Visible or w.watchId ~= ticket or T.dead then break end
				if w.changed or w.name == "InteractionBrowser" or w.name == "AssetBrowser" and T.assets.mode == "Playing" then
					w.changed = false
					if w.name == "AssetBrowser" and T.assets.mode == "Lookups" then
						T.assetInfo()
					else
						w.render()
					end
				end
			end
		end)
	end
	T.scanInter = function()
		const w = T.wins.InteractionBrowser
		if not w then return end
		T.clean(w.name.."Watch")
		w.watchId = (w.watchId or 0) + 1
		T.inter.items = {}
		const seen = setmetatable({}, { __mode = "k" })
		T.inter.seen = seen
		const function visit(obj)
			const kind = T.interKind(obj)
			if not kind or seen[obj] or T.own(obj) or #T.inter.items >= 10000 then return false end
			const path = T.pathOf(obj)
			if not path then return false end
			seen[obj] = true
			table.insert(T.inter.items, { obj = obj, kind = kind, path = path })
			return true
		end
		const roots = T.roots(false)
		T.status(w.name, "Looking for interactions...")
		T.watch(w, roots, visit)
		T.scan(w.name, roots, visit, function(capped)
			w.page = 1
			w.render()
			if capped then T.status(w.name, "Scan limit reached. Results cover the first 30000 loaded objects.") end
		end)
	end
	T.initInter = function(w)
		w.render = T.interRender
		w.empty = "No matching interactions are loaded. Move closer, switch to All loaded, or refresh."
		T.on(w.name, w.bar.Refresh.Activated, T.scanInter)
		const filters = { "All", "Prompts", "Clicks", "Touches", "Buttons" }
		T.on(w.name, w.bar.Filter.Activated, function() T.inter.kind = filters[(table.find(filters, T.inter.kind) or 1) % #filters + 1] w.bar.Filter.Text = T.inter.kind w.page = 1 w.render() end)
		T.on(w.name, w.bar.Mode.Activated, function() T.inter.near = not T.inter.near w.bar.Mode.Text = T.inter.near and "Nearby" or "All loaded" w.page = 1 w.render() end)
		T.on(w.name, w.detail.Radius.FocusLost, function() w.page = 1 w.render() end)
		T.button(w, "Signal", function() T.inter.signal = T.inter.signal == "Activated" and "MouseButton1Click" or "Activated" w.detail.Signal.Text = "Button event: "..T.inter.signal end)
		const function selected()
			const item = T.inter.sel
			if not item or not item.obj.Parent then T.status(w.name, "Select a loaded interaction first.") return nil end
			return item
		end
		T.button(w, "Once", function()
			const item = selected()
			if not item then return end
			const ok, err = T.action(item.obj, item.kind, T.inter.signal)
			T.status(w.name, ok and "Activated "..item.obj.Name or err)
		end)
		T.button(w, "Repeat", function()
			const item = selected()
			if not item then return end
			if T.inter.jobs[item.obj] then T.inter.jobs[item.obj].stop = true T.inter.jobs[item.obj] = nil T.busy() w.render() return end
			const job = { interval = T.finite(w.detail.Interval.Text, 1, 0.1, 3600), signal = T.inter.signal }
			T.inter.jobs[item.obj] = job
			T.busy()
			task.spawn(function()
				while not T.dead and not job.stop and item.obj.Parent and w.frame.Visible do
					const ok, err = T.action(item.obj, item.kind, job.signal)
					if not ok then T.status(w.name, "Repeat stopped: "..tostring(err)) break end
					local left = job.interval
					while left > 0 and not job.stop and not T.dead do left -= task.wait(math.min(left, 0.05)) end
				end
				if T.inter.jobs[item.obj] == job then T.inter.jobs[item.obj] = nil end
				T.busy()
				T.interInfo()
			end)
			w.render()
		end)
		T.button(w, "Stop", function() T.stopInter() w.render() T.status(w.name, "All repeats stopped.") end)
		T.button(w, "Highlight", function() const item = selected() if item then T.highlight(item.obj) end end)
		T.button(w, "Copy", function() const item = selected() if item then T.message(w.name, "Object path", T.pathCode(item.path), false) end end)
		w.detail.Record.Text = "Add Step to Recorder"
		T.button(w, "Record", function()
			const item = selected()
			if not item then return end
			if T.playing then T.status(w.name, "Stop playback before adding steps.") return end
			if not T.addStep(T.objectStep(item.obj, item.kind, T.inter.signal), T.recording) then
				T.status(w.name, "Could not add this step. Check the recording place and step limit.")
				return
			end
			if not T.recording then
				local ok = T.open("ActionRecorder", true)
				if ok then NAgui.setWindowVisible(w.frame, false) end
				const rec = T.wins.ActionRecorder
				if rec then
					T.recTab(rec, "steps")
					rec.page = math.ceil(#T.rec.steps / 60)
					rec.sel = #T.rec.steps
					rec.render()
					T.status(rec.name, "Added "..item.obj.Name..". Choose Play to test the recording.")
				end
			end
			T.status(w.name, "Added to the Action Recorder.")
		end)
	end
	T.assetNum = function(raw)
		local id = raw:match("^(%d+)$") or raw:match("^rbxassetid://(%d+)$")
		if not id then
			const host, path = raw:match("^https?://([%w.]+)(/[^%s]*)$")
			if host == "roblox.com" or host and host:match("%.roblox%.com$") then
				const route = path:match("^[^?#]+") or ""
				id = route:match("^/library/(%d+)/") or route:match("^/library/(%d+)$")
					or route:match("^/catalog/(%d+)/") or route:match("^/catalog/(%d+)$")
					or route:match("^/store/asset/(%d+)/") or route:match("^/store/asset/(%d+)$")
				if not id and (route == "/asset/" or route == "/asset" or route == "/v1/asset/" or route == "/v1/asset") then
					id = path:match("[?&]id=(%d+)[&#]") or path:match("[?&]id=(%d+)$")
				end
			end
		end
		if id then
			id = id:gsub("^0+", "")
			if #id > 0 and #id <= 16 and tonumber(id) <= 9007199254740991 then return id end
		end
	end
	T.assetId = function(value)
		const raw = T.trim(value)
		if raw == "" or raw:match("^0+$") or raw:match("^rbxassetid://0+$") then return nil end
		const id = T.assetNum(raw)
		return id and "rbxassetid://"..id or raw
	end
	T.stopPreview = function()
		T.previewId = (T.previewId or 0) + 1
		T.clean("AssetVideo")
		if T.video then T.video:Destroy() T.video = nil end
		if T.track then pcall(T.track.Stop, T.track, 0) pcall(T.track.Destroy, T.track) T.track = nil end
		if T.sound then T.sound:Destroy() T.sound = nil end
		const w = T.wins.AssetBrowser
		if w then
			w.detail.Image.Visible = false
			w.detail.Image.Image = ""
			w.detail.Viewport.Visible = false
			w.detail.Viewport.CurrentCamera = nil
			for _, obj in w.detail.Viewport:GetChildren() do if not obj:IsA("UICorner") then obj:Destroy() end end
		end
		T.previewCam = nil
		T.previewAt = nil
	end
	T.assetKey = function(kind, id) return kind..":"..id end
	T.addAsset = function(index, kind, raw, obj, property, playing)
		const id = T.assetId(raw)
		if not id then return false end
		const key = T.assetKey(kind, id)
		local item = index[key]
		local added = false
		if not item then
			if #T.assets.items >= 10000 then return false end
			item = { key = key, kind = kind, id = id, name = obj.Name, refs = {}, total = 0 }
			index[key] = item
			table.insert(T.assets.items, item)
			added = true
		end
		for _, ref in item.refs do if ref.obj == obj and ref.prop == property then ref.playing = playing return added end end
		item.total += 1
		if #item.refs < 32 then table.insert(item.refs, { obj = obj, prop = property, path = T.pathOf(obj), playing = playing }) end
		return added
	end
	T.assetUses = function(item)
		return T.assets.index and T.assets.index[item.key] or item
	end
	T.isPlaying = function(item)
		for _, ref in T.assetUses(item).refs or {} do
			const obj = ref.obj
			if obj and obj.Parent then
				local ok, playing
				if obj:IsA("Sound") or obj:IsA("AudioPlayer") then
					ok, playing = pcall(function() return obj.IsPlaying and T.assetId(obj[ref.prop]) == item.id end)
				elseif item.kind == "Videos" and obj:IsA("VideoFrame") then
					ok, playing = pcall(function() return obj.Playing and T.assetId(obj.Video) == item.id end)
				end
				if ok and playing then return true end
			end
			if ref.playing then
				const ok, yes = pcall(function() return ref.playing.IsPlaying end)
				if ok and yes then return true end
			end
		end
		return false
	end
	T.assetRefs = function(item)
		const paths = {}
		for _, ref in T.assetUses(item).refs or {} do
			if ref.path then table.insert(paths, T.pathText(ref.path).."  ["..tostring(ref.prop).."]") end
		end
		return table.concat(paths, "\n")
	end
	T.assetInfo = function()
		const w = T.wins.AssetBrowser
		const item = T.assets.sel
		if not w or not item then return end
		w.detail.Title.Text = item.name or item.id
		w.detail.ID.Text = item.id
		w.detail.Paths.Text = T.assetRefs(item)
		w.detail.Info.Text = item.kind.."\n"..tostring(T.assetUses(item).total or 0).." loaded uses"..(T.isPlaying(item) and "  |  Playing" or "")
		w.detail.Favorite.Text = T.data.favorites[item.key] and "Remove from favorites" or "Add to favorites"
	end
	T.assetRender = function()
		const w = T.wins.AssetBrowser
		if not w then return end
		local items = {}
		const seen = {}
		const live = {}
		for _, item in T.assets.items do
			local loaded = T.isPlaying(item)
			for _, ref in item.refs do
				if ref.obj and ref.obj.Parent then
					local ok, raw = pcall(function() return ref.obj[ref.prop] end)
					if ok and T.assetId(raw) == item.id then loaded = true break end
				end
			end
			if loaded then seen[item.key] = true table.insert(items, item) table.insert(live, item)
			elseif T.assets.index then T.assets.index[item.key] = nil end
		end
		T.assets.items = live
		if T.assets.mode == "Lookups" then
			items = T.assets.lookups
		elseif T.assets.mode == "Favorites" then
			for key, saved in T.data.favorites do
				if not seen[key] then table.insert(items, { key = key, kind = saved.kind, id = saved.id, name = saved.name, decal = saved.decal }) end
			end
		end
		const rows = {}
		for _, item in items do
			if (T.assets.kind == "All" or T.assets.kind == item.kind) and (T.assets.mode ~= "Favorites" or T.data.favorites[item.key]) and (T.assets.mode ~= "Playing" or T.isPlaying(item)) and (T.matches(w, (item.name or "").." "..item.id) or w.bar.Search.Text ~= "" and T.matches(w, T.assetRefs(item))) then
				table.insert(rows, { key = item.key, title = (T.data.favorites[item.key] and "* " or "")..(item.name or item.id), meta = item.kind.."  |  "..item.id, item = item })
			end
		end
		if T.assets.mode ~= "Lookups" then table.sort(rows, function(a, b) return a.title < b.title end) end
		T.rows(w, rows, function(row) T.stopPreview() T.assets.sel = row.item T.assetInfo() end)
		T.assetInfo()
	end
	T.scanAssets = function()
		const w = T.wins.AssetBrowser
		if not w then return end
		T.assets.items = {}
		T.assets.index = {}
		const index = T.assets.index
		const watched = setmetatable({}, { __mode = "k" })
		local propCount = 0
		const function visit(obj)
			if T.own(obj) then return false end
			local added = false
			const function add(kind, prop, playing)
				watched[obj] = watched[obj] or {}
				if not watched[obj][prop] and propCount < 1600 then
					watched[obj][prop] = true propCount += 1
					T.on(w.name.."Watch", obj:GetPropertyChangedSignal(prop), function()
						local value
						pcall(function() value = obj[prop] end)
						if value then T.addAsset(index, kind, value, obj, prop, playing) w.changed = true end
					end)
				end
				local value
				pcall(function() value = obj[prop] end)
				if value then added = T.addAsset(index, kind, value, obj, prop, playing) or added end
			end
			if obj:IsA("Sound") then add("Sounds", "SoundId")
			elseif obj:IsA("AudioPlayer") then add("Sounds", "Asset")
			elseif obj:IsA("Animation") then add("Animations", "AnimationId")
			elseif obj:IsA("VideoFrame") then add("Videos", "Video")
			elseif obj:IsA("ImageLabel") or obj:IsA("ImageButton") then add("Images", "Image")
			elseif obj:IsA("Decal") or obj:IsA("Texture") then add("Images", "Texture")
			elseif obj:IsA("MeshPart") then add("Meshes", "MeshId") add("Images", "TextureID")
			elseif obj:IsA("SpecialMesh") then add("Meshes", "MeshId") add("Images", "TextureId")
			elseif obj:IsA("SurfaceAppearance") then for _, prop in { "ColorMap", "NormalMap", "RoughnessMap", "MetalnessMap" } do add("Images", prop) end
			elseif obj:IsA("Animator") then
				if not watched[obj] and propCount < 1600 then
					watched[obj] = { played = true } propCount += 1
					T.on(w.name.."Watch", obj.AnimationPlayed, function(track)
						const anim = track.Animation
						if anim then T.addAsset(index, "Animations", anim.AnimationId, anim, "AnimationId", track) w.changed = true end
					end)
				end
				local ok, tracks = pcall(obj.GetPlayingAnimationTracks, obj)
				if ok then
					for i, track in tracks do
						if i > 100 then break end
						const anim = track.Animation
						if anim then added = T.addAsset(index, "Animations", anim.AnimationId, anim, "AnimationId", track) or added end
					end
				end
			end
			return added
		end
		const roots = T.roots(true)
		if T.assets.mode == "Lookups" then
			w.render()
		else
			T.status(w.name, "Looking for loaded assets...")
		end
		T.watch(w, roots, visit)
		T.scan(w.name, roots, visit, function(capped)
			if T.assets.mode == "Lookups" then
				T.assetInfo()
			else
				w.page = 1
				w.render()
				if capped then T.status(w.name, "Scan limit reached. Results cover the first 30000 loaded objects.") end
			end
		end)
	end
	T.lookupAsset = function(w, value)
		const num = T.assetNum(T.trim(value))
		if not num then T.status(w.name, "Enter a Roblox asset ID or asset URL.") return end
		if w.lookup then return end
		const id = "rbxassetid://"..num
		const list = T.assets.lookups
		local item
		for i, entry in list do
			if entry.id == id then
				item = table.remove(list, i)
				break
			end
		end
		if not item then
			const token = {}
			w.lookup = token
			T.status(w.name, "Looking up asset "..num.."...")
			local ok, info = pcall(__lt.cm, "MarketplaceService", "GetProductInfoAsync", tonumber(num), Enum.InfoType.Asset)
			if not ok and w.lookup == token and not T.dead and w.frame.Visible then
				ok, info = pcall(__lt.cm, "MarketplaceService", "GetProductInfo", tonumber(num), Enum.InfoType.Asset)
			end
			if w.lookup ~= token then return end
			w.lookup = nil
			if T.dead or not w.frame.Visible then return end
			if not ok or type(info) ~= "table" then T.status(w.name, "Asset "..num.." is unavailable.") return end
			const asset = Enum.AssetType
			const kinds = {
				[asset.Image.Value] = "Images",
				[asset.Decal.Value] = "Images",
				[asset.Audio.Value] = "Sounds",
				[asset.Animation.Value] = "Animations",
				[asset.Mesh.Value] = "Meshes",
				[asset.Video.Value] = "Videos",
			}
			const kind = kinds[info.AssetTypeId]
			if not kind then T.status(w.name, "This asset type has no preview.") return end
			item = { key = T.assetKey(kind, id), kind = kind, id = id, name = info.Name or id, decal = info.AssetTypeId == asset.Decal.Value or nil }
		end
		table.insert(list, 1, item)
		if #list > 100 then table.remove(list) end
		T.stopPreview()
		T.assets.sel, T.assets.kind, T.assets.mode = item, "All", "Lookups"
		w.page, w.sel = 1, item.key
		w.bar.Filter.Text, w.bar.Mode.Text = "All", "Lookups"
		w.bar.Search.Text = ""
		w.detail.CanvasPosition = Vector2.zero
		w.render()
	end
	T.aimPreview = function()
		if not T.previewCam or not T.previewAt then return end
		const center, span = T.previewAt.center, T.previewAt.span
		const angle = math.rad(T.assets.angle)
		const front = T.previewAt.front
		const offset = front and (front * math.cos(angle) + front:Cross(Vector3.yAxis) * math.sin(angle)) * span + Vector3.yAxis * (span * 0.25) or Vector3.new(math.sin(angle) * span, span * 0.25, math.cos(angle) * span)
		T.previewCam.CFrame = CFrame.lookAt(center + offset, center)
	end
	T.preview = function()
		const w = T.wins.AssetBrowser
		const item = T.assets.sel
		if not item then return false, "Select an asset first." end
		if item.kind == "Animations" then T.assets.angle = 0 end
		T.stopPreview()
		const ticket = T.previewId
		if item.kind == "Videos" then
			const video = Instance.new("VideoFrame")
			const style = w.detail.Image
			video.Name = "AssetVideo"
			video.Size = style.Size
			video.LayoutOrder = w.detail.Stop.LayoutOrder + 1
			video.ZIndex = style.ZIndex
			video.BackgroundColor3 = style.BackgroundColor3
			video.BorderSizePixel = 0
			video.Looped = true
			video.Volume = 0.4
			const corner = style:FindFirstChildOfClass("UICorner")
			if corner then corner:Clone().Parent = video end
			T.video = video
			video.Parent = w.detail
			const function play()
				if T.dead or T.previewId ~= ticket or not video.IsLoaded or video.Playing then return end
				T.clean("AssetVideo")
				const ok, err = pcall(video.Play, video)
				if not ok then
					T.stopPreview()
					T.status(w.name, "Video playback failed: "..tostring(err))
					return
				end
				T.status(w.name, "Video preview playing.")
			end
			T.status(w.name, "Loading video preview...")
			T.on("AssetVideo", video.Loaded, play)
			const ok = pcall(function() video.Video = item.id end)
			if not ok then T.stopPreview() return false, "This video source could not be opened." end
			play()
			task.delay(10, function()
				if not T.dead and T.previewId == ticket and T.video == video and not video.IsLoaded then
					T.stopPreview()
					T.status(w.name, "Video could not load. Check asset access and try again.")
				end
			end)
			return true
		end
		if item.kind == "Images" then
			const thumb = item.decal and T.assetNum(item.id)
			w.detail.Image.Image = thumb and ("rbxthumb://type=Asset&id="..thumb.."&w=420&h=420") or item.id
			w.detail.Image.Visible = true
			T.status(w.name, "Image preview requested. Restricted or unloaded images may remain blank.")
			return true
		end
		if item.kind == "Sounds" then
			const sound = Instance.new("Sound")
			sound.Name = "AssetPreview"
			sound.SoundId = item.id
			sound.Volume = 0.4
			sound.Parent = T.rootGui()
			T.sound = sound
			local ok, err = pcall(sound.Play, sound)
			if not ok then T.stopPreview() return false, tostring(err) end
			task.delay(8, function()
				if not T.dead and T.previewId == ticket and T.sound == sound then T.status(w.name, sound.IsLoaded and "Audio loaded. Preview volume: 40%." or "Audio could not load. It may be restricted or unavailable.") end
			end)
			return true
		end
		const view = w.detail.Viewport
		const world = Instance.new("WorldModel")
		world.Parent = view
		const cam = Instance.new("Camera")
		cam.FieldOfView = 45
		cam.Parent = view
		view.CurrentCamera = cam
		view.Visible = true
		T.previewCam = cam
		local model
		if item.kind == "Animations" then
			const char = getChar()
			if not char then T.stopPreview() return false, "Your character is unavailable for the animation preview." end
			const old = char.Archivable
			local ok, result = pcall(function() if not old then char.Archivable = true end return char:Clone() end)
			if char.Archivable ~= old then char.Archivable = old end
			if not ok or not result then T.stopPreview() return false, "Could not create a preview rig." end
			model = result
			for _, obj in model:GetDescendants() do
				if obj:IsA("LuaSourceContainer") or obj:IsA("Tool") or obj:IsA("Sound") or obj:IsA("Animator") then obj:Destroy()
				elseif obj:IsA("BasePart") then obj.CanCollide = false obj.CanTouch = false obj.CanQuery = false obj.Anchored = false end
			end
			model:PivotTo(CFrame.new())
			const root = model:FindFirstChild("HumanoidRootPart")
			if root then root.Anchored = true end
			model.Parent = world
			const hum = model:FindFirstChildOfClass("Humanoid")
			local owner = hum
			if not owner then owner = Instance.new("AnimationController") owner.Parent = model end
			const animator = Instance.new("Animator") animator.Parent = owner
			const anim = Instance.new("Animation") anim.AnimationId = item.id anim.Parent = world
			const loaded, track = pcall(animator.LoadAnimation, animator, anim)
			if not loaded or not track then T.stopPreview() return false, "Animation unavailable: "..tostring(track) end
			T.track = track
			track.Looped = true
			track:Play()
			task.delay(8, function()
				if not T.dead and T.previewId == ticket and T.track == track then T.status(w.name, track.Length > 0 and "Animation playing on the preview rig." or "Animation did not load. Check its permissions and rig type.") end
			end)
		else
			model = Instance.new("Model")
			local part
			for _, ref in T.assetUses(item).refs or {} do
				const obj = ref.obj
				if obj and obj.Parent and obj:IsA("MeshPart") then
					const old = obj.Archivable
					const ok, copy = pcall(function() if not old then obj.Archivable = true end return obj:Clone() end)
					if obj.Archivable ~= old then obj.Archivable = old end
					if ok and copy then part = copy part:ClearAllChildren() break end
				end
			end
			if not part then
				part = Instance.new("Part")
				part.Size = Vector3.new(1, 1, 1)
				const mesh = Instance.new("SpecialMesh")
				mesh.MeshType = Enum.MeshType.FileMesh mesh.MeshId = item.id mesh.Parent = part
			end
			part.Anchored = true part.CanCollide = false part.CanTouch = false part.CFrame = CFrame.new()
			part.Parent = model model.Parent = world
		end
		const cf, size = model:GetBoundingBox()
		const root = item.kind == "Animations" and (model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart)
		const look = root and root.CFrame.LookVector
		local front
		if look then
			const flat = Vector3.new(look.X, 0, look.Z)
			front = flat.Magnitude > 0.01 and flat.Unit or Vector3.new(0, 0, -1)
		end
		T.previewAt = { center = cf.Position, span = math.max(size.Magnitude * 0.9, 6), front = front }
		T.aimPreview()
		T.status(w.name, "Preview requested. Rotate to change the view.")
		return true
	end
	T.initAssets = function(w)
		w.render = T.assetRender
		w.empty = "No matching assets. Change the filters, refresh, or look up an asset ID."
		w.detail.Info.Text = "Browse sounds, animations, images, meshes, and videos."
		const box = w.detail.ID:Clone()
		box.Name = "LookupID"
		box.Text = ""
		box.PlaceholderText = "Asset ID or Roblox URL"
		box.Size = w.detail.Preview.Size
		box.LayoutOrder = 5
		box.MultiLine = false
		box.TextWrapped = false
		box.TextYAlignment = Enum.TextYAlignment.Center
		box.Parent = w.detail
		const lookup = w.detail.Preview:Clone()
		lookup.Name = "Lookup"
		lookup.Text = "Look up asset"
		lookup.LayoutOrder = 6
		lookup.Parent = w.detail
		T.on(w.name, box.FocusLost, function(enter)
			if enter then T.lookupAsset(w, box.Text) end
		end)
		T.button(w, "Lookup", function() T.lookupAsset(w, box.Text) end)
		T.on(w.name, w.bar.Refresh.Activated, T.scanAssets)
		const filters = { "All", "Sounds", "Animations", "Images", "Meshes", "Videos" }
		const modes = { "All loaded", "Playing", "Favorites", "Lookups" }
		T.on(w.name, w.bar.Filter.Activated, function() T.assets.kind = filters[(table.find(filters, T.assets.kind) or 1) % #filters + 1] w.bar.Filter.Text = T.assets.kind w.page = 1 w.render() end)
		T.on(w.name, w.bar.Mode.Activated, function() T.assets.mode = modes[(table.find(modes, T.assets.mode) or 1) % #modes + 1] w.bar.Mode.Text = T.assets.mode w.page = 1 w.render() end)
		T.button(w, "Preview", function() const ok, err = T.preview() if not ok then T.status(w.name, err) end end)
		T.button(w, "Stop", function() T.stopPreview() T.status(w.name, "Preview stopped.") end)
		T.button(w, "Rotate", function() T.assets.angle = (T.assets.angle + 45) % 360 T.aimPreview() end)
		T.button(w, "Favorite", function()
			const item = T.assets.sel
			if not item then T.status(w.name, "Select an asset first.") return end
			T.data.favorites[item.key] = not T.data.favorites[item.key] and { kind = item.kind, id = item.id, name = item.name, decal = item.decal } or nil
			T.save() w.render()
		end)
		T.button(w, "Copy", function() if T.assets.sel then T.message(w.name, "Asset ID", T.assets.sel.id, false) end end)
		T.button(w, "CopyPath", function()
			const item = T.assets.sel
			const uses = item and T.assetUses(item)
			const ref = uses and uses.refs and uses.refs[1]
			if ref and ref.path then T.message(w.name, "Instance path", T.pathCode(ref.path), false) else T.status(w.name, "This asset has no loaded instance in the current game.") end
		end)
		T.button(w, "Export", function()
			const out = {}
			for _, row in w.rows or {} do table.insert(out, { kind = row.item.kind, id = row.item.id, name = row.item.name, paths = T.assetRefs(row.item) }) end
			T.message(w.name, "Visible results JSON", T.encode({ kind = "NAAssets", version = 1, assets = out }), false)
		end)
	end
	T.sensitive = function(label)
		const name = string.lower(tostring(label))
		for _, word in { "password", "secret", "token", "webhook", "api key", "apikey", "credential" } do
			if name:find(word, 1, true) then return true end
		end
		return false
	end
	T.equal = function(a, b, depth)
		if type(a) ~= type(b) then return false end
		if type(a) ~= "table" then return a == b end
		depth = depth or 0
		if depth > 12 then return false end
		for k, v in a do if not T.equal(v, b[k], depth + 1) then return false end end
		for k in b do if a[k] == nil then return false end end
		return true
	end
	T.capture = function()
		const data = { controls = {}, settings = {}, keys = T.pack(CommandKeybinds or {}), keyOpts = T.pack(CommandKeybindOptions or {}), buttons = T.pack(NAUserButtons or {}), plugins = {}, commands = {} }
		for _, kind in T.regs do
			const vals = {}
			for label, entry in NAgui["_"..kind.."Registry"] or {} do
				if not T.sensitive(label) and type(entry.get) == "function" then
					const ok, value = pcall(entry.get)
					if ok then vals[label] = T.pack(value) end
				end
			end
			data.controls[kind] = vals
		end
		for key, value in NAStuff.NASettingsData or {} do
			if not T.sensitive(key) then data.settings[key] = T.pack(value) end
		end
		if type(NAmanage.PluginListFiles) == "function" then
			for _, entry in NAmanage.PluginListFiles(false) do data.plugins[entry.kind.."/"..entry.name] = entry.enabled == true end
		end
		if type(NAmanage.GetAExec) == "function" then
			for _, entry in NAmanage.GetAExec() do table.insert(data.commands, entry.display) end
		end
		return data
	end
	T.profile = function(data)
		if type(data) ~= "table" or data.kind ~= "NAProfile" or data.version ~= 1 or type(data.setup) ~= "table" then return nil, "This is not a supported NA profile." end
		if type(data.name) ~= "string" or T.trim(data.name) == "" then return nil, "The profile needs a name." end
		const out = { kind = "NAProfile", version = 1, name = data.name:sub(1, 80), scope = data.scope == "place" and "place" or data.scope == "global" and "global" or "game", game = tostring(data.game or game.GameId), place = tostring(data.place or game.PlaceId), setup = {}, picks = {} }
		for _, key in { "controls", "settings", "keys", "keyOpts", "buttons", "plugins", "commands" } do
			out.setup[key] = type(data.setup[key]) == "table" and T.pack(data.setup[key]) or {}
		end
		if #out.setup.commands > 100 then return nil, "Profiles can contain at most 100 startup commands." end
		for i, line in out.setup.commands do
			if type(line) ~= "string" or #line > 16000 then return nil, "A startup command is invalid." end
			out.setup.commands[i] = T.trim(line)
		end
		for _, key in { "Controls", "Keys", "Buttons", "Plugins", "Startup" } do out.picks[key] = type(data.picks) == "table" and data.picks[key] == true or false end
		return out
	end
	T.scopeKey = function(data)
		if data.scope == "global" then return "global" end
		return data.scope == "place" and "place:"..data.place or "game:"..data.game
	end
	T.allowed = function(data)
		return data.scope == "global" or data.scope == "place" and data.place == tostring(game.PlaceId) or data.scope == "game" and data.game == tostring(game.GameId)
	end
	T.changes = function(data, picks)
		const lines = { data.name.."  |  "..data.scope.." profile" }
		const setup = data.setup
		local count = 0
		if picks.Controls then
			for _, kind in T.regs do
				for label, value in setup.controls[kind] or {} do
					const entry = NAgui["_"..kind.."Registry"] and NAgui["_"..kind.."Registry"][label]
					if entry and not T.sensitive(label) then
						const ok, current = pcall(entry.get)
						if ok and not T.equal(T.pack(current), value) then count += 1 if #lines < 200 then table.insert(lines, kind..": "..label) end end
					end
				end
			end
			table.insert(lines, "Saved settings will also be restored; controls not open yet use them next load.")
		end
		if picks.Keys then table.insert(lines, "Replace command keybinds and keybind options.") end
		if picks.Buttons then table.insert(lines, "Replace mobile user buttons and their saved layout.") end
		if picks.Plugins then table.insert(lines, "Restore enabled/disabled states for matching installed plugins.") end
		if picks.Startup then
			table.insert(lines, "Run "..#setup.commands.." startup commands:")
			for _, line in setup.commands do if #lines < 300 then table.insert(lines, "  "..line) end end
		end
		table.insert(lines, 2, tostring(count).." visible control changes.")
		return table.concat(lines, "\n")
	end
	T.apply = function(data, picks)
		const valid, err = T.profile(data)
		if not valid then return false, err end
		if not T.allowed(valid) then return false, "This profile is assigned to a different game or place. Duplicate it for this game first." end
		if T.applying then return false, "A profile is already being applied." end
		T.applying = true
		picks = T.clone(picks or valid.picks)
		T.applyId = (T.applyId or 0) + 1
		const ticket = T.applyId
		task.spawn(function()
			const errors = {}
			local applied = 0
			const function attempt(label, fn)
				if T.dead or T.applyId ~= ticket then return end
				const ok, why = pcall(fn)
				if ok then applied += 1 else table.insert(errors, label..": "..tostring(why)) end
			end
			local ok, failure = pcall(function()
				const setup = valid.setup
				if picks.Controls then
					const schema = NAmanage.NASettingsGetSchema and NAmanage.NASettingsGetSchema() or {}
					for key, value in setup.settings do
						if schema[key] and not T.sensitive(key) then
							attempt(key, function() NAStuff.NASettingsData[key] = NAmanage.NASettingsCoerce(schema[key], T.unpack(value)) end)
						end
					end
					for _, kind in T.regs do
						for label, value in setup.controls[kind] or {} do
							const entry = NAgui["_"..kind.."Registry"] and NAgui["_"..kind.."Registry"][label]
							if entry and type(entry.get) == "function" and type(entry.set) == "function" and not T.sensitive(label) then
								local got, current = pcall(entry.get)
								if got and not T.equal(T.pack(current), value) then
									attempt(label, function() entry.set(T.unpack(value), { fire = true, force = true, animate = false }) end)
								end
							end
						end
						task.wait()
					end
					if NAmanage.NASettingsSave then attempt("settings save", NAmanage.NASettingsSave) end
				end
				if picks.Keys then
					attempt("keybinds", function()
						CommandKeybinds = T.unpack(setup.keys)
						CommandKeybindOptions = T.unpack(setup.keyOpts)
						NAmanage.SaveCommandKeybinds()
						NAmanage.ApplyCommandKeybinds()
					end)
				end
				if picks.Buttons then
					attempt("mobile buttons", function()
						NAUserButtons = NAmanage.ubNorm and NAmanage.ubNorm(T.unpack(setup.buttons)) or T.unpack(setup.buttons)
						NAmanage.UserButtonsSave("profile")
						NAmanage.RenderUserButtons()
					end)
				end
				if picks.Plugins and NAmanage.PluginListFiles and NAmanage.PluginSetEnabled then
					local changed = false
					for _, entry in NAmanage.PluginListFiles(false) do
						const want = setup.plugins[entry.kind.."/"..entry.name]
						if type(want) == "boolean" and want ~= entry.enabled then
							attempt(entry.name, function() NAmanage.PluginSetEnabled(entry.path, want) end)
							changed = true
						end
					end
					if changed then attempt("plugins reload", function() NAmanage.LoadPlugins({ silent = true }) end) end
				end
				if picks.Startup then
					for _, line in setup.commands do
						if T.dead or T.applyId ~= ticket then return end
						if T.trim(line) ~= "" then
							attempt(line, function()
								const argv = NAmanage.MCPNormalizeArgs(line)
								assert(argv, "Invalid command.")
								const name = string.lower(argv[1])
								assert(name ~= "applyprofile" and name ~= "loadprofile", "Profiles cannot apply another profile from startup commands.")
								assert(cmds.Commands[name] or cmds.Aliases[name], "Command unavailable: "..name)
								const success, why = cmd.run(argv)
								assert(success ~= false, why)
								T.wait(0.05, T.runId)
							end)
						end
					end
				end
			end)
			if not ok then table.insert(errors, tostring(failure)) end
			T.applying = false
			T.prof.result = { applied = applied, errors = errors }
			T.status("GameProfiles", "Applied "..valid.name.."  |  "..applied.." updates"..(#errors > 0 and "  |  "..#errors.." failed: "..errors[1] or ""))
		end)
		return true
	end
	T.profPick = function(id)
		const w = T.wins.GameProfiles
		const data = T.data.profiles[id]
		if not w or type(data) ~= "table" then return end
		T.prof.sel = id
		T.prof.scope = data.scope
		w.detail:FindFirstChild("Name").Text = data.name or ""
		w.detail.Scope.Text = "Assign: "..(data.scope == "game" and "this game" or data.scope == "place" and "this place" or "all games")
		w.detail.Commands.Text = table.concat(data.setup and data.setup.commands or {}, "\n")
		for _, key in { "Controls", "Keys", "Buttons", "Plugins", "Startup" } do
			T.prof.picks[key] = type(data.picks) == "table" and data.picks[key] == true
		end
		T.profLabels()
	end
	T.profLabels = function()
		const w = T.wins.GameProfiles
		if not w then return end
		const labels = { Controls = "Settings", Keys = "Keybinds", Buttons = "Mobile buttons", Plugins = "Plugins", Startup = "Run startup commands" }
		for key, label in labels do w.detail[key].Text = label..": "..(T.prof.picks[key] and "on" or "off") end
		const data = T.prof.sel and T.data.profiles[T.prof.sel]
		const active = data and T.data.auto[T.scopeKey(data)] == T.prof.sel
		w.detail.Auto.Text = "Use automatically: "..(active and "on" or "off")
	end
	T.profRender = function()
		const w = T.wins.GameProfiles
		if not w then return end
		const rows = {}
		for id, data in T.data.profiles do
			if type(data) == "table" and (T.prof.all or T.allowed(data)) and T.matches(w, data.name or id) then
				const auto = T.data.auto[T.scopeKey(data)] == id
				table.insert(rows, { key = id, title = data.name, meta = tostring(data.scope).."  |  "..(data.scope == "place" and tostring(data.place) or data.scope == "game" and tostring(data.game) or "all games")..(auto and "  |  auto" or "") })
			end
		end
		table.sort(rows, function(a, b) return tostring(a.title) < tostring(b.title) end)
		T.rows(w, rows, function(item) T.profPick(item.key) end)
		T.profLabels()
	end
	T.initProfiles = function(w)
		w.render = T.profRender
		w.empty = "No profiles yet. Name your current setup and choose Save."
		w.bar.Filter.Text = "Profiles"
		T.on(w.name, w.bar.Refresh.Activated, w.render)
		T.on(w.name, w.bar.Mode.Activated, function() T.prof.all = not T.prof.all w.bar.Mode.Text = T.prof.all and "All games" or "This game" w.page = 1 w.render() end)
		T.on(w.name, w.bar.Filter.Activated, function() T.prof.all = not T.prof.all w.bar.Mode.Text = T.prof.all and "All games" or "This game" w.render() end)
		w.import = function(raw)
			const data, err = T.profile(T.decode(raw))
			if not data then return false, err end
			const id = Http:GenerateGUID(false)
			T.data.profiles[id] = data
			T.prof.all = true w.bar.Mode.Text = "All games" T.prof.sel = id
			T.save() T.profPick(id)
			return true, "Profile imported. Automatic use stays off until you enable it."
		end
		for _, key in { "Controls", "Keys", "Buttons", "Plugins", "Startup" } do
			T.button(w, key, function() T.prof.picks[key] = not T.prof.picks[key] T.profLabels() end)
		end
		T.button(w, "Scope", function()
			T.prof.scope = T.prof.scope == "game" and "place" or T.prof.scope == "place" and "global" or "game"
			w.detail.Scope.Text = "Assign: "..(T.prof.scope == "game" and "this game" or T.prof.scope == "place" and "this place" or "all games")
		end)
		T.button(w, "Save", function()
			const name = string.sub(T.trim(w.detail:FindFirstChild("Name").Text), 1, 80)
			if name == "" then T.status(w.name, "Enter a profile name.") return end
			const setup = T.capture()
			setup.commands = {}
			for line in w.detail.Commands.Text:gmatch("[^\r\n]+") do if T.trim(line) ~= "" then table.insert(setup.commands, T.trim(line)) end end
			const data, err = T.profile({ kind = "NAProfile", version = 1, name = name, scope = T.prof.scope, game = tostring(game.GameId), place = tostring(game.PlaceId), setup = setup, picks = T.clone(T.prof.picks) })
			if not data then T.status(w.name, err) return end
			const id = T.prof.sel or Http:GenerateGUID(false)
			for key, value in T.data.auto do if value == id and key ~= T.scopeKey(data) then T.data.auto[key] = nil end end
			T.data.profiles[id] = data T.prof.sel = id
			const _, msg = T.save() w.render() T.status(w.name, msg)
		end)
		T.button(w, "New", function()
			T.prof.sel = nil w.sel = nil w.detail:FindFirstChild("Name").Text = ""
			w.detail.Commands.Text = table.concat(T.capture().commands, "\n")
			T.profLabels() w.render()
		end)
		T.button(w, "Preview", function()
			const data = T.prof.sel and T.data.profiles[T.prof.sel]
			if not data then T.status(w.name, "Select a saved profile.") return end
			T.message(w.name, "Changes when applying this profile", T.changes(data, T.prof.picks), false)
		end)
		T.button(w, "Apply", function()
			const data = T.prof.sel and T.data.profiles[T.prof.sel]
			const ok, err = T.apply(data, T.prof.picks)
			T.status(w.name, ok and "Applying profile..." or err)
		end)
		T.button(w, "Auto", function()
			const data = T.prof.sel and T.data.profiles[T.prof.sel]
			if not data then T.status(w.name, "Save a profile first.") return end
			const key = T.scopeKey(data)
			if T.data.auto[key] == T.prof.sel then T.data.auto[key] = nil else T.data.auto[key] = T.prof.sel end
			T.save() w.render()
		end)
		T.button(w, "Duplicate", function()
			const data = T.prof.sel and T.clone(T.data.profiles[T.prof.sel])
			if not data then T.status(w.name, "Select a saved profile.") return end
			data.name ..= " copy" data.game = tostring(game.GameId) data.place = tostring(game.PlaceId) data.scope = T.prof.scope
			const id = Http:GenerateGUID(false)
			T.data.profiles[id] = data T.prof.sel = id T.save() w.render() T.profPick(id)
		end)
		T.button(w, "Delete", function()
			if not T.prof.sel then return end
			for key, id in T.data.auto do if id == T.prof.sel then T.data.auto[key] = nil end end
			T.data.profiles[T.prof.sel] = nil T.prof.sel = nil T.save() w.render()
		end)
		T.button(w, "Export", function()
			const data = T.prof.sel and T.data.profiles[T.prof.sel]
			if data then T.message(w.name, "Profile JSON", T.encode(data), false) else T.status(w.name, "Select a saved profile.") end
		end)
		T.button(w, "Import", function() T.message(w.name, "Paste profile JSON", "", true) end)
		w.detail.Commands.Text = table.concat(T.capture().commands, "\n")
	end
	T.recordWatch = function()
		const seen = setmetatable({}, { __mode = "k" })
		local watched = 0
		const function visit(obj)
			if not T.recording or T.rec.mode ~= "actions" or seen[obj] or watched >= 1200 then return end
			if obj:IsA("ClickDetector") then
				seen[obj] = true watched += 1
				T.on("Recording", obj.MouseClick, function(who)
					if T.recording and (not who or who == player) then T.addStep(T.objectStep(obj, "click"), true) end
				end)
			elseif obj:IsA("TouchTransmitter") and obj.Parent and obj.Parent:IsA("BasePart") then
				seen[obj] = true watched += 1
				local last = -math.huge
				const part = obj.Parent
				T.on("Recording", part.Touched, function(hit)
					const char = getChar()
					if T.recording and char and hit:IsDescendantOf(char) and os.clock() - last > 0.5 then
						last = os.clock()
						T.addStep(T.objectStep(obj, "touch"), true)
					end
				end)
			end
		end
		T.on("Recording", WS.DescendantAdded, visit)
		T.scan("Recording", { WS }, visit, function() end)
	end
	T.open = function(name, force)
		const w = T.bind(name)
		if not w then return false, "Update NA's interface to open "..name.."." end
		if not w.ready then
			if name == "ActionRecorder" then T.initRec(w)
			elseif name == "InteractionBrowser" then T.initInter(w)
			elseif name == "GameProfiles" then T.initProfiles(w)
			elseif name == "AssetBrowser" then T.initAssets(w) end
			w.ready = true
		end
		local show = force
		if type(show) ~= "boolean" then show = not NAgui.isWindowOpen(w.frame) end
		NAgui.setWindowVisible(w.frame, show)
		T.refreshScroll(w)
		if show then
			T.fit(w)
			if NAmanage.centerFrame then NAmanage.centerFrame(w.frame) end
			if NAmanage.OnUIWindowShown then NAmanage.OnUIWindowShown(w.frame) end
			T.layout(w)
			if name == "InteractionBrowser" then T.scanInter()
			elseif name == "AssetBrowser" then T.scanAssets()
			else w.render() end
		end
		return true
	end
	T.stopAll = function()
		for obj, token in T.holds do T.endHold(obj, token) end
		const wasPlaying = T.playing
		T.stopRecord()
		T.stopPlay(wasPlaying and "Playback stopped." or nil)
		T.stopInter()
		T.highlight(nil)
	end
	T.destroy = function()
		if T.dead then return end
		T.dead = true
		T.applyId = (T.applyId or 0) + 1
		T.stopAll() T.stopPreview()
		const groups = {}
		for group in T.bags do table.insert(groups, group) end
		for _, group in groups do T.clean(group) end
		for _, w in T.wins do
			for _, ctrl in w.scrolls or {} do
				ctrl.stopArrowHold()
				ctrl.stopThumbDrag()
			end
			w.scrolls = nil
			if w.resize then pcall(w.resize) end
			if w.drag then pcall(w.drag) end
			if NAgui and NAgui.cleanupMenu then NAgui.cleanupMenu(w.frame) end
			if w.frame.Parent then w.frame.Visible = false end
			w.rows = nil w.draw = nil w.sel = nil
		end
		T.inter.items = {} T.inter.sel = nil T.assets.items = {} T.assets.index = {} T.assets.lookups = {} T.assets.sel = nil
		if T.pauseBtn then T.pauseBtn:Destroy() T.pauseBtn = nil end
		if T.life then T.life.Connected = false end
	end
	T.load()
	const gui = T.rootGui()
	if gui then
		T.on("Lifetime", gui.Destroying, T.destroy)
		const stop = gui:FindFirstChild("ToolsStop")
		if stop then T.on("Lifetime", stop.Activated, T.stopAll) end
	end
	T.on("Lifetime", player.CharacterRemoving, function() T.stopAll() end)
	const function watchCamera()
		T.clean("Camera")
		const cam = WS.CurrentCamera
		if cam then
			T.on("Camera", cam:GetPropertyChangedSignal("ViewportSize"), function()
				for _, w in T.wins do
					T.fit(w)
					if w.frame.Visible and NAmanage.centerFrame then NAmanage.centerFrame(w.frame) end
					T.layout(w)
				end
			end)
		end
	end
	T.on("Lifetime", WS:GetPropertyChangedSignal("CurrentCamera"), watchCamera)
	watchCamera()
	if NAlib and NAlib.connect then
		T.life = { Connected = true, Disconnect = function(self) self.Connected = false T.destroy() end }
		NAlib.connect("NAWindowTools", T.life)
	end
	return T
end

NAmanage.OpenWindowTool = function(name, force)
	const ok, err = NAmanage.InitWindowTools().open(name, force)
	if not ok and DoNotif then DoNotif(err, 4) end
	return ok, err
end

NAmanage.ToolsCommand = function(args)
	const T = NAStuff.WindowTools
	if not T or T.dead or not T.recording or T.rec.mode == "inputs" then return end
	if not T.commandEntry(args[1]) then return end
	const parts = {}
	for i, arg in args do
		local text = tostring(arg)
		if text == "" or text:find("[%s\"'\\]") then text = string.format("%q", text) end
		parts[i] = text
	end
	T.addStep({ kind = "command", value = table.concat(parts, " "), args = table.clone(args) }, true)
end

