cmd.register({
	name = "playrecord",
	description = "Play a recording saved for this place",
	usage = "playrecord <name|id|JSON> [repeats]",
	requiresArguments = true,
	category = "Utility",
	callback = function(name, count)
		const T = NAmanage.InitWindowTools()
		local data = T.decode(name)
		if not data then
			data = T.data.records[name]
			if not data then
				for _, rec in T.data.records do if type(rec) == "table" and rec.name == name and tostring(rec.place) == tostring(game.PlaceId) then data = rec break end end
			end
		end
		const ok, err = T.play(data, count, 1)
		if not ok then DoNotif(err, 4, "Action Recorder") end
	end,
})
