		const T = NAmanage.InitWindowTools()
		local data = T.data.profiles[name]
		if not data then for _, prof in T.data.profiles do if type(prof) == "table" and prof.name == name and T.allowed(prof) then data = prof break end end end
		const ok, err = T.apply(data)
		if not ok then DoNotif(err, 4, "Game Profiles") end
	end,
})

task.defer(function()
	if type(readfile) ~= "function" then return end
	const path = (NAfiles.NAFILEPATH or "Nameless-Admin").."/WindowTools.json"
	local found = false
	for _, file in { path, path..".bak" } do
		const read, raw = pcall(readfile, file)
		if read and type(raw) == "string" and #raw <= 4000000 then
			const ok, data = pcall(function() return Services.HttpService:JSONDecode(raw) end)
			if ok and type(data) == "table" and data.version == 1 then
				const map = type(data.auto) == "table" and data.auto or {}
				const id = map["place:"..game.PlaceId] or map["game:"..game.GameId] or map.global
				if not id then return end
				found = true break
			end
		end
	end
	if not found then return end
	const T = NAmanage.InitWindowTools()
	const id = T.data.auto["place:"..game.PlaceId] or T.data.auto["game:"..game.GameId] or T.data.auto.global
	if not id or not T.data.profiles[id] then return end
	const start = os.clock()
	while not T.dead and os.clock() - start < 45 do
		const perf = NAStuff.StartupPerformance
		if perf and perf.settingsBuildOk == true then T.apply(T.data.profiles[id]) return end
		task.wait(0.2)
	end
end)

-- PART 31
const function pickIcon(btn, name, fallback, label)
	if not btn then return end
	if not btn.TextScaled then
		const cap = InstanceNew("UITextSizeConstraint", btn)
		cap.MaxTextSize = btn.TextSize
		cap.MinTextSize = math.min(9, btn.TextSize)
		btn.TextScaled = true
	end
	NAmanage.SetIcon(btn, name, {text = label or NAmanage.GetIconText(btn) or btn.Text, fallback = fallback})
end

NAmanage.NewAvatarPreview = function(E, spec)
	const Players = SafeGetService("Players")
	const UIS = SafeGetService("UserInputService")
	const RS = SafeGetService("RunService")
	const player = Players.LocalPlayer
	const key = spec.key:gsub("Picker$", "Preview")
	const P = { bags = {}, req = 0, angle = 0, zoom = 1, paused = false, dead = false, clips = {}, records = {} }
	P.on = function(group, signal, fn)
		const conn = signal:Connect(fn)
		P.bags[group] = P.bags[group] or {}
		table.insert(P.bags[group], conn)
		return conn
	end
	P.clean = function(group)
		const bag = P.bags[group]
		P.bags[group] = nil
		for _, conn in bag or {} do pcall(function() conn:Disconnect() end) end
	end
	P.msg = function(text)
		if P.body and P.body.Parent then P.body.Status.Text = tostring(text) end
	end
	P.visible = function()
		return not P.dead and not E.dead and P.frame and P.frame.Parent and P.frame.Visible and P.body.Visible
			and E.frame and E.frame.Visible and E.body.Visible and NAStuff.NASCREENGUI.Enabled
	end
	P.stopTrack = function()
		if P.timer then pcall(task.cancel, P.timer) P.timer = nil end
		if P.track then pcall(function() P.track:Stop(0) P.track:Destroy() end) P.track = nil end
		if P.anim then P.anim:Destroy() P.anim = nil end
		P.clean("Load")
	end
	P.aim = function()
		if not P.cam or not P.center or not P.size then return end
		const dims = P.view.AbsoluteSize
		const aspect = math.max(0.25, dims.X / math.max(1, dims.Y))
		const slope = math.tan(math.rad(P.cam.FieldOfView * 0.5))
		const dist = (math.max(P.size.Y * 0.5 / slope, P.size.X * 0.5 / (slope * aspect)) + P.size.Z * 0.5) * 1.18 * P.zoom
		const angle = math.rad(P.angle)
		const front = P.front or Vector3.new(0, 0, -1)
		const offset = (front * math.cos(angle) + front:Cross(Vector3.yAxis) * math.sin(angle)) * dist + Vector3.yAxis * (dist * 0.06)
		const cf = CFrame.lookAt(P.center + offset, P.center)
		if P.cam.CFrame ~= cf then P.cam.CFrame = cf end
	end
	P.layout = function()
		if not P.body or not P.frame.Parent then return end
		const width = P.frame.Size.X.Offset
		const scale = width > 0 and P.frame.AbsoluteSize.X / width or 1
		const short = P.body.AbsoluteSize.Y / math.max(scale, 0.01) < 300
		P.body.ItemName.Size = UDim2.new(1, short and -92 or 0, 0, 20)
		P.body.Clip.Position = short and UDim2.new(1, -86, 0, 0) or UDim2.fromOffset(0, 24)
		P.body.Clip.Size = short and UDim2.fromOffset(86, 20) or UDim2.new(1, 0, 0, 22)
		P.view.Position = UDim2.fromOffset(0, short and 24 or 52)
		P.view.Size = UDim2.new(1, 0, 1, short and -104 or -154)
		P.body.Status.Position = UDim2.new(0, 0, 1, short and -76 or -98)
		P.body.Status.Size = UDim2.new(1, 0, 0, short and 18 or 30)
		P.body.Status.TextWrapped = not short
		P.body.Status.TextTruncate = short and Enum.TextTruncate.AtEnd or Enum.TextTruncate.None
		for i, name in { "Left", "Front", "Right", "Spin", "Speed", "Pause" } do
			const btn = P.body[name]
			btn.Position = UDim2.new(((i - 1) % 3) / 3, 0, 1, (short and -52 or -62) + math.floor((i - 1) / 3) * (short and 26 or 32))
			btn.Size = UDim2.new(1 / 3, -3, 0, short and 22 or 26)
		end
		P.aim()
	end
	P.sync = function()
		if not P.body then return end
		const live = P.visible()
		NAmanage.SetIconText(P.body.Spin, E.spin and "Spin: on" or "Spin: off")
		NAmanage.SetIconText(P.body.Speed, E.speed.."× speed")
		const saved = E.body and E.body:FindFirstChild("Saved")
		if saved and saved:FindFirstChild("Prefs") then NAmanage.SetIconText(saved.Prefs.Speed, "Preview speed: "..E.speed.."×") end
		pickIcon(P.body.Pause, P.paused and "play" or "pause", nil, P.paused and "Resume" or "Pause")
		P.body.Pause.Active = P.track ~= nil
		P.body.Pause.AutoButtonColor = P.track ~= nil
		if P.track then pcall(function() P.track:AdjustSpeed(live and not P.paused and E.speed or 0) end) end
		if live and E.spin and P.cam then
			if not P.bags.Tick then
				local elapsed = 0
				P.on("Tick", RS.RenderStepped, function(dt)
					elapsed += dt
					if elapsed < 1 / 30 then return end
					P.angle = (P.angle + math.min(elapsed, 0.1) * 28) % 360
					elapsed = 0
					P.aim()
				end)
			end
		else P.clean("Tick") end
	end
	P.setSpin = function(value)
		const changed = E.spin ~= (value == true)
		E.spin = value == true
		P.sync() if changed then E.save() end
	end
	P.stop = function()
		P.req += 1 P.want = nil
		P.stopTrack()
		P.paused = false
		if not P.dead and not E.dead and P.body and P.body.Parent then P.msg("Preview stopped.") P.sync() end
	end
	P.clear = function()
		P.stop()
		P.clean("Tick")
		P.touch = nil
		if P.view then P.view.CurrentCamera = nil end
		if P.world then P.world:Destroy() P.world = nil end
		if P.cam then P.cam:Destroy() P.cam = nil end
		P.model, P.hum, P.animator, P.char, P.center, P.size, P.dummy = nil, nil, nil, nil, nil, nil, nil
		P.records, P.clips = {}, {}
	end
	P.hide = function()
		P.clear()
		if P.frame and P.frame.Parent then P.frame.Visible = false end
	end
	P.fit = function()
		if not P.frame or not P.frame.Parent then return end
		if NAmanage.GetAttr(P.frame, "NAMenuMinimized") or NAmanage.GetAttr(P.frame, "NAMenuMaximized") then return end
		const sizing = NAmanage.ExecutorWindowSizing
		if not P.fitted then
			sizing.Apply(P.frame, { key = key, baseWidth = 320, baseHeight = 470, minWidth = 220, minHeight = 280, mobileMinWidth = 210, mobileMinHeight = 230, viewportRatio = 0.92 })
			P.fitted = true
			if NAgui.resizeable then P.resize = NAgui.resizeable(P.frame, Vector2.new(210, 230), Vector2.new(5000, 5000)) end
		else
			const vp = sizing.GetLogicalViewport()
			const x, y = sizing.GetSafePad()
			const old = P.frame.Size
			const w, h = math.min(old.X.Offset, math.max(1, vp.X - x * 2)), math.min(old.Y.Offset, math.max(1, vp.Y - y * 2))
			if old.X.Offset ~= w or old.Y.Offset ~= h then P.frame.Size = UDim2.fromOffset(w, h) end
		end
		if P.placed then
			const vp = sizing.GetLogicalViewport()
			const padX, padY = sizing.GetSafePad()
			const pos = (P.frame.AbsolutePosition - P.frame.Parent.AbsolutePosition) / sizing.GetScale()
			const w, h = P.frame.Size.X.Offset, P.frame.Size.Y.Offset
			const x = math.clamp(pos.X, padX, math.max(padX, vp.X - w - padX))
			const y = math.clamp(pos.Y, padY, math.max(padY, vp.Y - h - padY))
			if math.abs(pos.X - x) > 0.5 or math.abs(pos.Y - y) > 0.5 then P.frame.Position = UDim2.fromOffset(x, y) end
		end
		P.layout()
	end
	P.place = function()
		if P.placed then return end
		const sizing = NAmanage.ExecutorWindowSizing
		const scale = sizing.GetScale()
		const vp = sizing.GetLogicalViewport()
		const padX, padY = sizing.GetSafePad()
		const origin = P.frame.Parent.AbsolutePosition
		const pos, size = (E.frame.AbsolutePosition - origin) / scale, E.frame.AbsoluteSize / scale
		const w, h = P.frame.Size.X.Offset, P.frame.Size.Y.Offset
		local x = pos.X + size.X + 12
		if x + w > vp.X - padX then x = pos.X - w - 12 end
		if x < padX then x = pos.X + (size.X - w) * 0.5 end
		x = math.clamp(x, padX, math.max(padX, vp.X - w - padX))
		const y = math.clamp(pos.Y, padY, math.max(padY, vp.Y - h - padY))
		P.frame.Position = UDim2.fromOffset(x, y)
		P.placed = true
	end
	const function validRig(model)
		return model and model:FindFirstChildOfClass("Humanoid") and model:FindFirstChild("HumanoidRootPart")
			and model:FindFirstChild("UpperTorso") and model:FindFirstChild("LowerTorso")
	end
	const function buildRig(desc)
		const ok, model = pcall(Players.CreateHumanoidModelFromDescriptionAsync, Players, desc, Enum.HumanoidRigType.R15)
		desc:Destroy()
		return ok and model or nil
	end
	P.rig = function(active)
		const char = player.Character
		const hum = char and char:FindFirstChildOfClass("Humanoid")
		const canClone = hum and hum.RigType == Enum.HumanoidRigType.R15 and validRig(char)
		if P.model and P.model.Parent and P.char == char and (not P.dummy or not canClone) then return true end
		local model, dummy
		const ok, err = pcall(function()
			if canClone then
				const old = char.Archivable
				local good, copy = pcall(function() if not old then char.Archivable = true end return char:Clone() end)
				if char.Archivable ~= old then char.Archivable = old end
				if good then model = copy end
			end
			if not validRig(model) and hum and active() then
				if model then model:Destroy() model = nil end
				const got, desc = pcall(hum.GetAppliedDescription, hum)
				if got and desc then model = buildRig(desc) end
			end
			if not active() then return end
			if not validRig(model) then
				if model then model:Destroy() model = nil end
				const desc = Instance.new("HumanoidDescription")
				const shade = Color3.fromRGB(182, 188, 201)
				desc.HeadColor, desc.TorsoColor = shade, shade
				desc.LeftArmColor, desc.RightArmColor = shade, shade
				desc.LeftLegColor, desc.RightLegColor = shade, shade
				model = buildRig(desc)
				dummy = true
			end
			if not active() then return end
			if not validRig(model) then error("Roblox couldn't load the R15 preview dummy.", 0) end
			for i, obj in model:GetDescendants() do
				if obj:IsA("LuaSourceContainer") or obj:IsA("Tool") or obj:IsA("Sound") or obj:IsA("Animator") then obj:Destroy()
				elseif obj:IsA("BasePart") then obj.Anchored, obj.CanCollide, obj.CanTouch, obj.CanQuery = false, false, false, false end
				if i % 64 == 0 then task.wait() if not active() then return end end
			end
			const root = model:FindFirstChild("HumanoidRootPart")
			if root then model.PrimaryPart = root root.Anchored = true end
			model:PivotTo(CFrame.new())
			const hum = model:FindFirstChildOfClass("Humanoid")
			if not hum then error("The preview rig has no Humanoid.", 0) end
			hum.AutoRotate = false
			hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
			pcall(function() hum.EvaluateStateMachine = false end)
			P.stopTrack()
			if P.world then P.world:Destroy() end
			if P.cam then P.cam:Destroy() end
			P.world = Instance.new("WorldModel") P.world.Parent = P.view
			P.cam = Instance.new("Camera") P.cam.FieldOfView = 40 P.cam.Parent = P.view
			P.view.CurrentCamera = P.cam
			model.Parent = P.world
			P.model, P.hum, P.char, P.dummy = model, hum, char, dummy
			P.animator = Instance.new("Animator") P.animator.Parent = hum
			const cf, size = model:GetBoundingBox()
			P.center, P.size = cf.Position, size
			const look = root and root.CFrame.LookVector or Vector3.new(0, 0, -1)
			const front = Vector3.new(look.X, 0, look.Z)
			P.front = front.Magnitude > 0.01 and front.Unit or Vector3.new(0, 0, -1)
			P.aim()
		end)
		if model and (not ok or not active()) then
			if P.model == model then P.model = nil end
			model:Destroy()
		end
		if not ok then error(err, 0) end
		return active() and P.model ~= nil
	end
	P.play = function(clip)
		const record = P.records[clip]
		if not record or not P.animator or not P.visible() then return false end
		P.stopTrack()
		P.paused = false
		P.clip = clip
		NAmanage.SetIconText(P.body.Clip, spec.clipName and spec.clipName(clip) or "Emote")
		P.anim = Instance.new("Animation")
		P.anim.AnimationId = "rbxassetid://"..record.variants[1].id
		const ok, track = pcall(P.animator.LoadAnimation, P.animator, P.anim)
		if not ok then P.stopTrack() error(tostring(track), 0) end
		P.track = track
		track.Priority, track.Looped = Enum.AnimationPriority.Action, true
		track:Play(0.15, 1, E.speed)
		const hint = P.dummy and "R15 dummy · drag to rotate" or "Drag to rotate · scroll to zoom"
		P.msg(hint)
		P.sync()
		P.on("Load", track:GetPropertyChangedSignal("Length"), function() if track.Length > 0 and P.track == track then P.msg(hint) end end)
		P.timer = task.delay(7, function()
			P.timer = nil
			if not P.dead and P.track == track and track.Length <= 0 then P.msg("Roblox couldn't load this animation. It may be restricted.") end
		end)
		return true
	end
	P.pump = function()
		if P.busy or not P.want or not P.visible() then return end
		const want = P.want
		P.want = nil
		P.busy = true
		local thread
		thread = task.defer(function()
			const function active() return not P.dead and not E.dead and P.req == want.req and P.visible() end
			const ok, err = pcall(function()
				const records = spec.preview(want.item, active)
				if not active() or not records or not next(records) then return end
				if not P.rig(active) then return end
				P.records, P.clips = records, {}
				for _, clip in { "emote", "idle", "walk", "run", "jump", "fall", "climb", "swim", "swimidle", "mood", "sit" } do
					if records[clip] then table.insert(P.clips, clip) end
				end
				const clip = records[want.target] and want.target or P.clips[1]
				P.body.Clip.Active = #P.clips > 1
				P.body.Clip.AutoButtonColor = #P.clips > 1
				P.item = want.item
				P.body.ItemName.Text = want.item.name
				P.play(clip)
			end)
			P.busy = false
			if P.job == thread then P.job = nil end
			if not ok and active() then P.msg(tostring(err)) E.msg(tostring(err)) end
			if P.want and P.visible() then P.pump() end
		end)
		P.job = thread
	end
	P.ensure = function()
		if P.frame and P.frame.Parent then return end
		const frame = NAUIMANAGER[key.."Frame"]
		if not frame then error("Update NAUI/NAUITEST to show the rig preview window.", 0) end
		P.frame, P.body = frame, frame.Container
		P.view = P.body.RigViewport
		pickIcon(P.body.Left, "rotate-ccw", "arrow-medium-left", "Left")
		pickIcon(P.body.Right, "rotate-cw", "arrow-medium-right", "Right")
		pickIcon(P.body.Front, "focus", "crosshairs")
		pickIcon(P.body.Spin, "refresh-cw", "tilt")
		pickIcon(P.body.Speed, "gauge", "three-sliders-horizontal")
		pickIcon(P.body.Pause, "pause")
		pickIcon(P.body.Clip, "list-video", "list-bulleted")
		const function click(btn, fn)
			P.on("UI", btn.Activated, function() const ok, err = pcall(fn) if not ok then P.msg(tostring(err)) end end)
		end
		click(P.body.Left, function() P.setSpin(false) P.angle = (P.angle - 30) % 360 P.aim() end)
		click(P.body.Right, function() P.setSpin(false) P.angle = (P.angle + 30) % 360 P.aim() end)
		click(P.body.Front, function() P.setSpin(false) P.angle, P.zoom = 0, 1 P.aim() end)
		click(P.body.Spin, function() P.setSpin(not E.spin) end)
		click(P.body.Pause, function() P.paused = not P.paused P.sync() end)
		click(P.body.Speed, function()
			const values = { 0.5, 1, 1.5, 2 }
			E.speed = values[(table.find(values, E.speed) or 1) % #values + 1]
			P.sync() E.save()
		end)
		click(P.body.Clip, function()
			if #P.clips > 1 then P.play(P.clips[(table.find(P.clips, P.clip) or 1) % #P.clips + 1]) end
		end)
		P.on("UI", P.view.InputBegan, function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				P.touch = input
				P.lastX = input.UserInputType == Enum.UserInputType.MouseButton1 and UIS:GetMouseLocation().X or input.Position.X
				if E.spin then P.setSpin(false) end
			end
		end)
		P.on("UI", UIS.InputChanged, function(input)
			if not P.touch or not P.visible() then return end
			if input == P.touch or P.touch.UserInputType == Enum.UserInputType.MouseButton1 and input.UserInputType == Enum.UserInputType.MouseMovement then
				const x = input.UserInputType == Enum.UserInputType.MouseMovement and UIS:GetMouseLocation().X or input.Position.X
				P.angle = (P.angle + (x - P.lastX) * 0.6) % 360
				P.lastX = x P.aim()
			end
		end)
		P.on("UI", UIS.InputEnded, function(input)
			if input == P.touch or input.UserInputType == Enum.UserInputType.MouseButton1 then P.touch = nil end
		end)
		P.on("UI", P.view.InputChanged, function(input)
			if input.UserInputType == Enum.UserInputType.MouseWheel then P.zoom = math.clamp(P.zoom - input.Position.Z * 0.1, 0.55, 2) P.aim() end
		end)
		P.on("UI", P.view:GetPropertyChangedSignal("AbsoluteSize"), P.aim)
		P.on("UI", frame:GetPropertyChangedSignal("AbsoluteSize"), P.layout)
		P.on("UI", frame:GetPropertyChangedSignal("Visible"), function() if not frame.Visible then P.clear() else P.sync() end end)
		P.on("UI", P.body:GetPropertyChangedSignal("Visible"), P.sync)
		P.on("UI", E.body:GetPropertyChangedSignal("Visible"), function() if not E.body.Visible then P.hide() end end)
		P.on("UI", NAStuff.NASCREENGUI:GetPropertyChangedSignal("Enabled"), P.sync)
		P.on("UI", frame.Destroying, function() P.destroy() end)
		const exit = frame:FindFirstChild("Exit", true)
		if exit then click(exit, P.hide) end
		if NAgui.draggerV2 then P.drag = NAgui.draggerV2(frame, frame.Topbar) end
		if NAgui.RegisterStrokesFromAsync then NAgui.RegisterStrokesFromAsync(frame) end
		P.fit()
	end
	P.open = function(item, target)
		if not item then E.msg("Select an item first.") return false end
		const other = NAStuff[spec.key == "EmotePicker" and "AnimationPicker" or "EmotePicker"]
		if other and other.peek and other.peek ~= P then other.peek.hide() end
		P.ensure()
		const look = NAmanage.WindowAppearance
		if look and look.applyFrame then look.applyFrame(P.frame) end
		P.fit() P.place()
		P.frame.Visible = true
		P.angle, P.zoom, P.paused = 0, 1, false
		P.req += 1
		P.stopTrack()
		P.body.ItemName.Text = item.name
		P.msg("Loading preview...")
		P.want = { item = table.clone(item), target = target, req = P.req }
		P.aim() P.pump()
		return true
	end
	P.destroy = function()
		if P.dead then return end
		P.dead = true
		P.job = nil
		P.clear()
		const groups = {}
		for group in P.bags do table.insert(groups, group) end
		for _, group in groups do P.clean(group) end
		if P.resize then pcall(P.resize) P.resize = nil end
		if P.drag then pcall(P.drag) P.drag = nil end
		if P.frame and P.frame.Parent then P.frame.Visible = false if NAgui.cleanupMenu then pcall(NAgui.cleanupMenu, P.frame) end end
	end
	return P
end

NAmanage.WaitAvatarAppearance = function(player, char)
	const deadline = os.clock() + 6
	while player.Character == char and os.clock() < deadline do
		local loaded = true
		pcall(function() loaded = player:HasAppearanceLoaded() end)
		if loaded then break end
		task.wait(0.1)
	end
end

NAmanage.NewAvatarPicker = function()
	const E = { bags = {}, jobs = {}, cache = {}, cards = {}, scroll = {}, favs = {}, recent = {}, sets = {}, page = 1, req = 0, draw = 0, dead = false, view = "Catalog", sale = "All items", sort = "Relevant", cost = "Any price", compact = false, auto = true, speed = 1 }
	E.valid = function(id)
		id = tonumber(id)
		return id and id > 0 and id <= 9007199254740991 and id % 1 == 0 and id or nil
	end
	E.text = function(value, limit)
		const str = tostring(value or "")
		const ok, cut = pcall(utf8.offset, str, limit + 1)
		return ok and (cut and str:sub(1, cut - 1) or str) or str:sub(1, limit)
	end
	E.item = function(v)
		if type(v) ~= "table" then return nil end
		const prod = type(v.Product) == "table" and v.Product or nil
		if type(v.Item) == "table" then v = v.Item end
		const id = E.valid(v.Id or v.id or v.AssetId or v.BundleId)
		if not id then return nil end
		local price = tonumber(v.Price or v.price or v.LowestPrice)
		if price and (price ~= price or price < 0 or price == math.huge) then price = nil end
		local sale = v.sale
		if type(v.Price) == "number" then sale = true end
		if type(v.IsForSale) == "boolean" then sale = v.IsForSale end
		if prod and type(prod.IsForSale) == "boolean" then sale = prod.IsForSale end
		if type(v.ItemStatus) == "table" and table.find(v.ItemStatus, "OffSale") then sale = false end
		if type(v.PriceStatus) == "string" and v.PriceStatus:lower():find("off", 1, true) then sale = false end
		if type(sale) ~= "boolean" then sale = nil end
		return { id = id, name = E.text(v.Name or v.name or ("Item "..id), 100), price = price, sale = sale, bundle = v.bundle == true or v.ItemType == "Bundle" or v.BundleId ~= nil, assetType = type(v.assetType or v.AssetType) == "string" and (v.assetType or v.AssetType) or nil }
	end
	E.key = function(item) return (item.bundle and "b" or "a")..tostring(item.id) end
	E.on = function(group, signal, fn)
		const conn = signal:Connect(fn)
		E.bags[group] = E.bags[group] or {}
		table.insert(E.bags[group], conn)
		return conn
	end
	E.clean = function(group)
		const list = E.bags[group]
		E.bags[group] = nil
		for _, conn in list or {} do pcall(function() conn:Disconnect() end) end
	end
	E.cancel = function(key)
		const thread = E.jobs[key]
		E.jobs[key] = nil
		if type(thread) == "thread" and thread ~= coroutine.running() and coroutine.status(thread) ~= "dead" then pcall(task.cancel, thread) end
	end
	E.msg = function(value)
		value = tostring(value)
		if E.status and E.status.Parent and E.status.Text ~= value then E.status.Text = value end
		E.lastMsg = value
	end
	E.run = function(key, fn)
		if E.dead then return end
		E.cancel(key)
		if key == "Query" then E.net = (E.net or 0) + 1 end
		local thread
		thread = task.defer(function()
			local ok, err = true, nil
			if not E.dead then ok, err = pcall(fn) end
			if key == "Query" then E.net = math.max(0, (E.net or 1) - 1) end
			const own = E.jobs[key] == thread
			if own then E.jobs[key] = nil end
			if not ok and not E.dead and (key ~= "Query" or own) then
				if key == "Query" then E.busy = false E.cancel("Timeout") E.dropPages() end
				E.msg(tostring(err))
			end
		end)
		E.jobs[key] = thread
		return thread
	end
	E.dropPages = function()
		const pages = E.pages
		E.pages = nil
		if typeof(pages) == "Instance" then pcall(function() pages:Destroy() end) end
	end
	E.paint = function()
		for key, btn in E.cards do
			const color = E.selected and E.key(E.selected) == key and E.accent or E.panel
			if btn.Parent then
				if btn.BackgroundColor3 ~= color then btn.BackgroundColor3 = color end
				if btn:FindFirstChild("Favorite") then
					NAmanage.SetIcon(btn.Favorite, "star", {color = E.favs[key] and Color3.fromRGB(255, 214, 139) or nil, bold = E.favs[key] ~= nil})
				end
			end
		end
		if E.peekBtn then
			const ready = E.selected ~= nil
			E.peekBtn.Active, E.peekBtn.AutoButtonColor = ready, ready
			E.peekBtn.TextTransparency = ready and 0 or 0.5
		end
		if E.bottom and E.bottom:FindFirstChild("Favorite") then
			const saved = E.selected and E.favs[E.key(E.selected)] ~= nil
			NAmanage.SetIcon(E.bottom.Favorite, "star", {text = saved and "Favorited" or "Favorite", color = saved and Color3.fromRGB(255, 214, 139) or nil, bold = saved})
		end
	end
	E.loadExtra = function(data)
		E.favs, E.recent, E.sets = {}, {}, {}
		for i, v in type(data.favorites) == "table" and data.favorites or {} do
			if type(i) == "number" and i <= 256 then const item = E.item(v) if item then E.favs[E.key(item)] = item end end
		end
		for i, v in type(data.recent) == "table" and data.recent or {} do
			if type(i) == "number" and i <= 48 then const item = E.item(v) if item then table.insert(E.recent, item) end end
		end
		for i, row in type(data.sets) == "table" and data.sets or {} do
			if type(i) == "number" and i <= 32 and type(row) == "table" and type(row.name) == "string" then
				const set = E.cleanSet(row.data)
				if set then table.insert(E.sets, { name = E.text(row.name, 40), data = set }) end
			end
		end
		const prefs = type(data.prefs) == "table" and data.prefs or {}
		if table.find({ "All items", "On sale", "Offsale" }, prefs.sale) then E.sale = prefs.sale end
		if table.find({ "Relevant", "Low → high", "High → low", "Newest", "Popular" }, prefs.sort) then E.sort = prefs.sort end
		if table.find({ "Any price", "Free", "≤ 100 R$", "≤ 500 R$", "500+ R$" }, prefs.cost) then E.cost = prefs.cost end
		E.spin = prefs.spin == true
		E.compact = prefs.compact == true
		E.auto = prefs.auto ~= false
		if table.find({ 0.5, 1, 1.5, 2 }, prefs.speed) then E.speed = prefs.speed end
	end
	E.saveExtra = function(data)
		data.favorites, data.recent, data.sets = {}, E.recent, E.sets
		for _, item in E.favs do table.insert(data.favorites, item) end
		table.sort(data.favorites, function(a, b) return E.key(a) < E.key(b) end)
		data.prefs = { sale = E.sale, sort = E.sort, cost = E.cost, compact = E.compact, auto = E.auto, speed = E.speed, spin = E.spin == true }
		return data
	end
	E.remember = function(item)
		const key = E.key(item)
		for i = #E.recent, 1, -1 do if E.key(E.recent[i]) == key then table.remove(E.recent, i) end end
		table.insert(E.recent, 1, E.item(item))
		while #E.recent > 48 do table.remove(E.recent) end
		return E.save()
	end
	E.favorite = function(item)
		item = item or E.selected
		if not item then E.msg("Select an item first.") return false end
		const key = E.key(item)
		if E.favs[key] then E.favs[key] = nil
		else
			local count = 0
			for _ in E.favs do count += 1 end
			if count >= 256 then E.msg("Your favorites are full. Remove one first.") return false end
			E.favs[key] = E.item(item)
		end
		const saved = E.save()
		E.paint()
		if E.view == "Favorites" then E.fetch(false, true) end
		E.msg((E.favs[key] and "Added to favorites." or "Removed from favorites.")..(saved and "" or " File saving is unavailable."))
		return true
	end
	E.unbindUI = function()
		if E.peek then E.peek.destroy() E.peek = nil end
		E.req += 1 E.draw += 1 E.busy = false
		for _, key in { "Timeout", "SearchDelay", "Draw", "Scroll" } do E.cancel(key) end
		E.running, E.pending = nil, nil
		E.dropPages()
		E.clean("Rows") E.clean("UI") E.clean("Camera") E.clean("Theme") E.clean("Sets")
		E.stroke, E.fitted, E.placed = nil, nil, nil
		for _, btn in E.cards do pcall(function() btn:Destroy() end) end
		E.cards = {}
		if E.resize then pcall(E.resize) E.resize = nil end
		if E.drag then pcall(E.drag) E.drag = nil end
		if E.frame and E.frame.Parent then
			E.frame.Visible = false
			if NAgui.cleanupMenu then pcall(NAgui.cleanupMenu, E.frame) end
		end
	end
	return E
end

NAmanage.BindAvatarPickerUI = function(E, spec)
	const AES = SafeGetService("AvatarEditorService")
	const WS = SafeGetService("Workspace")
	E.cleanSet, E.capture, E.restoreSet = spec.cleanSet, spec.capture, spec.restoreSet
	E.costLabel = function(item)
		if item.sale == false then return "Offsale" end
		if item.price == nil then return "Price unavailable" end
		return item.price == 0 and "Free" or (tostring(item.price).." R$")
	end
	E.accept = function(item, query)
		if query ~= "" and not item.name:lower():find(query:lower(), 1, true) then return false end
		if spec.accept and not spec.accept(item) then return false end
		if E.sale == "Offsale" and item.sale ~= false then return false end
		if E.sale == "On sale" and item.sale ~= true then return false end
		if E.cost == "Free" then return item.sale ~= false and item.price == 0 end
		if E.cost == "≤ 100 R$" then return item.sale ~= false and item.price ~= nil and item.price <= 100 end
		if E.cost == "≤ 500 R$" then return item.sale ~= false and item.price ~= nil and item.price <= 500 end
		if E.cost == "500+ R$" then return item.sale ~= false and item.price ~= nil and item.price >= 500 end
		return true
	end
	E.sortRows = function(rows)
		if E.sort == "Low → high" or E.sort == "High → low" then
			table.sort(rows, function(a, b)
				if a.price == b.price then return E.key(a) < E.key(b) end
				if a.price == nil then return false end
				if b.price == nil then return true end
				return E.sort == "Low → high" and a.price < b.price or E.sort == "High → low" and a.price > b.price
			end)
		end
	end
	E.render = function()
		E.dirty = true
		if not E.frame or not E.frame.Visible then return end
		E.draw += 1
		const token = E.draw
		E.run("Draw", function()
			E.clean("Rows")
			for _, obj in E.list:GetChildren() do if obj:IsA("GuiObject") then obj:Destroy() end end
			E.cards = {}
			const rows = E.cache[E.page] or {}
			for i, item in rows do
				if E.dead or token ~= E.draw or not E.frame.Parent then return end
				const card = E.template:Clone()
				const key = E.key(item)
				card.Name, card.LayoutOrder, card.Visible = "Item"..key, i, true
				card.BackgroundColor3 = E.panel
				card.ItemName.Text = item.name
				card.Preview.Image = "rbxthumb://type="..(item.bundle and "BundleThumbnail" or "Asset").."&id="..item.id.."&w=150&h=150"
				if card:FindFirstChild("Price") then card.Price.Text = E.costLabel(item) end
				card.Parent = E.list
				const look = NAmanage.WindowAppearance
				if look and look.setElementSurface then look.setElementSurface(card, 0, E.frame) end
				E.cards[key] = card
				E.on("Rows", card.Activated, function() E.selected = item E.refresh() E.paint() end)
				if card:FindFirstChild("Favorite") then
					NAmanage.SetIcon(card.Favorite, "star", {color = E.favs[key] and Color3.fromRGB(255, 214, 139) or nil, bold = E.favs[key] ~= nil})
					E.on("Rows", card.Favorite.Activated, function() E.favorite(item) end)
				end
				if i % 6 == 0 then task.wait() end
			end
			if E.dead or token ~= E.draw then return end
			E.prev.Active = E.cache[E.page - 1] ~= nil
			E.prev.AutoButtonColor = E.prev.Active
			E.next.Active = E.cache[E.page + 1] ~= nil or not E.finished
			E.next.AutoButtonColor = E.next.Active
			E.refresh() E.paint()
			E.dirty = false
			E.run("Scroll", function()
				task.wait()
				if not E.dead and token == E.draw and E.list.Parent then E.list.CanvasPosition = E.scroll[E.page] or Vector2.zero end
			end)
			E.msg(#rows > 0 and (E.view.." · page "..E.page.." · "..#rows.." items") or (E.view == "Favorites" and "No favorites match. Tap a star to save an item." or "No matches on this page. Try Next or change the filters."))
		end)
	end
	E.tint = function()
		const color = typeof(NAUISTROKER) == "Color3" and NAUISTROKER or E.accent
		E.accent = color
		if E.list and E.list.ScrollBarImageColor3 ~= color then E.list.ScrollBarImageColor3 = color end
		E.refresh() E.paint()
	end
	E.style = function()
		if not E.frame or not E.frame.Parent then return end
		const look = NAmanage.WindowAppearance
		if look and look.applyFrame then look.applyFrame(E.frame) end
		const stroke = E.frame:FindFirstChildWhichIsA("UIStroke")
		if E.stroke ~= stroke then
			E.clean("Theme") E.stroke = stroke
			if stroke then E.on("Theme", stroke:GetPropertyChangedSignal("Color"), E.tint) end
		end
		E.tint()
	end
	E.setPage = function(page)
		E.scroll[E.page] = E.list.CanvasPosition
		E.page = page
		E.render()
	end
	E.fetch = function(nextPage, force)
		if E.dead or not E.frame or not E.frame.Visible then return end
		const query = E.search.Text:match("^%s*(.-)%s*$"):sub(1, 100)
		const filter = table.concat({ spec.filter(), E.view, E.sale, E.sort, E.cost }, ":")
		if nextPage and E.cache[E.page + 1] then E.setPage(E.page + 1) return end
		if not nextPage and not force and query == E.query and filter == E.filter and E.cache[E.page] then
			if E.dirty then E.render() end
			return
		end
		if E.busy then
			if nextPage or query == E.pendingQ and filter == E.pendingF and not force then return end
			E.req += 1
			E.pending = true
			return
		end
		if (E.net or 0) >= 2 then E.msg("Two catalog requests are still finishing. Try again in a moment.") return end
		if nextPage and E.finished then E.msg("You reached the last page.") return end
		if nextPage and not E.pages then E.msg("Search again to load more results.") return end
		E.req += 1
		const token = E.req
		E.busy, E.pendingQ, E.pendingF, E.running = true, query, filter, token
		E.msg(nextPage and "Loading more results..." or "Finding "..E.view:lower().." items...")
		E.run("Query", function()
			local pages = E.pages
			local index = nextPage and (E.lastPage or 1) + 1 or 1
			local raw, finished
			const function active() return not E.dead and E.req == token end
			const function finish()
				if E.running ~= token then return end
				E.busy = false
				E.running = nil
				E.cancel("Timeout")
				if E.pending and not E.dead then
					E.pending = nil E.dropPages()
					if E.frame.Visible then task.defer(function() E.fetch(false, true) end) else E.dirty = true E.filter = nil end
				end
			end
			if E.view == "Favorites" or E.view == "Recent" then
				raw = {}
				for _, item in E.view == "Favorites" and E.favs or E.recent do
					if E.accept(item, query) then table.insert(raw, item) end
				end
				if E.view == "Favorites" then table.sort(raw, function(a, b) return a.name:lower() < b.name:lower() end) end
				E.sortRows(raw)
				E.dropPages()
				E.cache, E.scroll, E.selected = {}, {}, nil
				for i = 1, math.max(1, math.ceil(#raw / 30)) do
					const rows = {}
					for j = (i - 1) * 30 + 1, math.min(i * 30, #raw) do table.insert(rows, raw[j]) end
					E.cache[i] = rows
				end
				E.page, E.lastPage, E.query, E.filter, E.finished = 1, #E.cache, query, filter, true
				finish() E.render()
				return
			end
			const delay = math.max(0, (E.lastQuery or 0) + 0.8 - os.clock())
			if delay > 0 then task.wait(delay) end
			if not active() then finish() return end
			E.lastQuery = os.clock()
			if E.view == "Suggested" then
				raw = spec.recommend(E.selected)
				finished = true
				E.dropPages() pages = nil
			elseif not nextPage then
				E.dropPages()
				const params = CatalogSearchParams.new()
				params.IncludeOffSale = E.sale ~= "On sale"
				params.SearchKeyword, params.Limit = query, 30
				params.SortType = E.sort == "Low → high" and Enum.CatalogSortType.PriceLowToHigh or E.sort == "High → low" and Enum.CatalogSortType.PriceHighToLow or E.sort == "Newest" and Enum.CatalogSortType.RecentlyCreated or E.sort == "Popular" and Enum.CatalogSortType.MostFavorited or Enum.CatalogSortType.Relevance
				if E.cost == "Free" then params.MaxPrice = 0
				elseif E.cost == "≤ 100 R$" then params.MaxPrice = 100
				elseif E.cost == "≤ 500 R$" then params.MaxPrice = 500
				elseif E.cost == "500+ R$" then params.MinPrice = 500 end
				spec.params(params)
				pages = AES:SearchCatalogAsync(params)
				raw, finished = pages:GetCurrentPage(), pages.IsFinished
			else
				E.pages = nil
				const ok, rows, done = pcall(function()
					pages:AdvanceToNextPageAsync()
					return pages:GetCurrentPage(), pages.IsFinished
				end)
				if not ok then
					pcall(pages.Destroy, pages)
					error(rows, 0)
				end
				raw, finished = rows, done
			end
			if not active() then
				if pages and pages ~= E.pages then pcall(function() pages:Destroy() end) end
				if pages and pages == E.pages and E.running == token then E.dropPages() end
				finish() return
			end
			const rows, seen = {}, {}
			for _, row in raw or {} do
				const item = spec.item(row)
				if item then
					const key = E.key(item)
					if not seen[key] and E.accept(item, E.view == "Suggested" and query or "") then seen[key] = true table.insert(rows, item) end
				end
			end
			if not nextPage then E.cache, E.scroll, E.selected = {}, {}, nil end
			E.pages, E.query, E.filter = pages, query, filter
			E.cache[index] = rows
			E.cache[index - 20], E.scroll[index - 20] = nil, nil
			E.page, E.lastPage, E.finished = index, index, finished
			finish() E.render()
		end)
		E.jobs.Timeout = task.delay(15, function()
			E.jobs.Timeout = nil
			if not E.dead and E.req == token and E.busy then
				E.req += 1 E.busy = false E.running = nil
				E.jobs.Query = nil
				E.pending = nil
				E.dropPages()
				E.msg("The catalog took too long. Your results are kept; press Search to retry.")
			end
		end)
	end
	E.drawSets = function()
		const pane = E.body:FindFirstChild("Saved")
		if not pane then return end
		E.clean("Sets")
		for _, obj in pane.List:GetChildren() do if obj:IsA("GuiObject") then obj:Destroy() end end
		if #E.sets == 0 then
			const hint = pane.Template:Clone()
			hint.Name, hint.Text, hint.Visible, hint.Parent = "Empty", "No saved setups yet. Name your current setup and press Save current.", true, pane.List
			hint.Size, hint.TextWrapped, hint.BackgroundTransparency, hint.Active = UDim2.new(1, -4, 0, 42), true, 1, false
		end
		for i, row in E.sets do
			const btn = pane.Template:Clone()
			btn.Name, btn.Text, btn.LayoutOrder, btn.Visible, btn.Parent = "Set"..i, row.name, i, true, pane.List
			btn.BackgroundColor3 = E.setIdx == i and E.accent or E.panel
			E.on("Sets", btn.Activated, function() E.setIdx = i pane.SetName.Text = row.name E.drawSets() end)
		end
	end
	E.showSets = function(show)
		const pane = E.body.Saved
		pane.Visible = show == true
		E.list.Visible, E.bottom.Visible = not pane.Visible, not pane.Visible
		if E.body:FindFirstChild("Filters") then E.body.Filters.Visible = not pane.Visible end
		if pane.Visible then E.drawSets() end
	end
	E.saveSet = function()
		const pane = E.body.Saved
		const name = E.text(pane.SetName.Text:match("^%s*(.-)%s*$"), 40)
		if name == "" then E.msg("Give your setup a name first.") return false end
		const data = E.capture()
		if not data then return false end
		local index
		for i, row in E.sets do if row.name:lower() == name:lower() then index = i break end end
		if not index and #E.sets >= 32 then E.msg("You can save 32 setups. Delete one first.") return false end
		index = index or #E.sets + 1
		E.sets[index], E.setIdx = { name = name, data = data }, index
		const saved = E.save()
		E.drawSets()
		E.msg(saved and ("Saved “"..name.."”.") or "Setup kept for this session. File saving is unavailable.")
		return true
	end
	E.layout = function()
		if not E.frame or not E.body then return end
		const size = E.frame.Size
		const scale = size.X.Scale == 0 and size.X.Offset > 0 and E.frame.AbsoluteSize.X / size.X.Offset or (NAmanage.GetUIScaleFactor and NAmanage.GetUIScaleFactor(E.body) or 1)
		const width = math.max(240, E.body.AbsoluteSize.X / math.max(scale, 0.01))
		const height = E.body.AbsoluteSize.Y / math.max(scale, 0.01)
		const side, short = width >= 500 and height < 380, height < 410
		const tiny = height < 220
		const top = tiny and 28 or 84
		E.search.Visible, E.body.SearchButton.Visible, E.status.Visible = not tiny, not tiny, not tiny
		const filters = E.body:FindFirstChild("Filters")
		if filters then
			filters.Position = UDim2.fromOffset(0, tiny and 0 or 56)
			filters.Size = UDim2.new(1, tiny and (spec.mode and -180 or -106) or 0, 0, 24)
		end
		E.prev.Position, E.next.Position = UDim2.new(1, -100, 0, tiny and 0 or 29), UDim2.new(1, -48, 0, tiny and 0 or 29)
		if spec.mode then E.body.Mode.Position = UDim2.new(1, -174, 0, tiny and 0 or 29) end
		const saved = E.body:FindFirstChild("Saved")
		if saved then saved.Position, saved.Size = UDim2.fromOffset(0, tiny and 28 or 54), UDim2.new(1, 0, 1, tiny and -28 or -54) end
		const rows = math.ceil(spec.choices / (spec.choices == 8 and 8 or 6))
		const selectH, actionH = short and 20 or 24, short and 22 or 26
		const infoY = 20 + rows * (selectH + 4)
		const actionY = infoY + 18
		const footer = actionY + 2 * (actionH + 4) + 28
		const room = math.max(1, height - top - 6)
		const footH = math.min(footer, math.max(48, room * 0.5), math.max(1, room - 32))
		E.list.Position = UDim2.fromOffset(0, top)
		E.list.Size = side and UDim2.new(0.6, -8, 1, -top) or UDim2.new(1, 0, 1, -top - 6 - footH)
		E.bottom.Position = side and UDim2.new(0.6, 0, 0, top) or UDim2.new(0, 0, 1, -footH)
		E.bottom.Size = side and UDim2.new(0.4, 0, 1, -top) or UDim2.new(1, 0, 0, footH)
		if E.bottom:IsA("ScrollingFrame") then E.bottom.CanvasSize = UDim2.fromOffset(0, footer) end
		E.selectors.Size = UDim2.new(1, 0, 0, rows * (selectH + 4))
		const count = spec.choices == 8 and 8 or 6
		for i, btn in E.slotBtns do
			btn.Position = UDim2.new(((i - 1) % count) / count, 0, 0, math.floor((i - 1) / count) * (selectH + 4))
			btn.Size = UDim2.new(1 / count, -3, 0, selectH)
			btn.TextSize = spec.choices == 8 and 11 or 10
		end
		E.slotInfo.Position, E.slotInfo.Size = UDim2.fromOffset(0, infoY), UDim2.new(1, 0, 0, 16)
		for i, btn in E.actions do
			btn.Position = UDim2.new(((i - 1) % 3) / 3, 0, 0, actionY + math.floor((i - 1) / 3) * (actionH + 4))
			btn.Size = UDim2.new(1 / 3, -3, 0, actionH)
		end
		for i, key in { "Favorite", "SavedSets", "Density" } do
			const btn = E.bottom:FindFirstChild(key)
			if btn then btn.Position, btn.Size = UDim2.new((i - 1) / 3, 0, 0, footer - 25), UDim2.new(1 / 3, -3, 0, 23) end
		end
		const listW = side and width * 0.6 - 8 or width
		const cols = math.clamp(math.floor((listW - 6) / (E.compact and 74 or 96)), 2, 12)
		E.grid.FillDirectionMaxCells = cols
		E.grid.CellSize = UDim2.new(1 / cols, -(6 * (cols - 1) + 6) / cols, 0, E.compact and 86 or 106)
	end
	E.fit = function()
		if not E.frame or not E.frame.Parent then return end
		const sizing = NAmanage.ExecutorWindowSizing
		if sizing and NAmanage.GetAttr(E.frame, "NAMenuMaximized") ~= true and NAmanage.GetAttr(E.frame, "NAMenuMinimized") ~= true then
			if not E.fitted then
				const _, metrics = sizing.Apply(E.frame, { key = spec.key, baseWidth = 680, baseHeight = 600, minWidth = 300, minHeight = 380, mobileMinWidth = 280, mobileMinHeight = 320, viewportRatio = 0.94 })
				if metrics then
					if metrics.mobile then E.frame.Size = UDim2.fromOffset(metrics.capWidth, metrics.capHeight) end
					E.fitted = true
					if not E.resize and NAgui.resizeable then E.resize = NAgui.resizeable(E.frame, Vector2.new(metrics.minWidth, metrics.minHeight), Vector2.new(5000, 5000)) end
				end
			else
				const vp = sizing.GetLogicalViewport()
				const x, y = sizing.GetSafePad()
				const size = E.frame.Size
				const w, h = math.min(size.X.Offset, math.max(1, vp.X - 2 * x)), math.min(size.Y.Offset, math.max(1, vp.Y - 2 * y))
				if size.X.Offset ~= w or size.Y.Offset ~= h then E.frame.Size = UDim2.fromOffset(w, h) end
			end
		end
		E.layout()
		if E.peek then E.peek.fit() end
	end
	E.peekPlay = function()
		if not E.selected then E.msg("Select an item first.") return false end
		E.create()
		return E.peek.open(E.selected, spec.target and spec.target() or "emote")
	end
	E.create = function()
		if E.frame and E.frame.Parent then return end
		const frame = NAUIMANAGER and NAUIMANAGER[spec.key.."Frame"]
		if not frame then error("Update NAUI/NAUITEST to load the "..spec.title.." window.") end
		E.accent = typeof(NAUISTROKER) == "Color3" and NAUISTROKER or Color3.fromRGB(155, 100, 255)
		E.panel = Color3.fromRGB(31, 32, 42)
		E.frame, E.body = frame, frame.Container
		const body = E.body
		E.search, E.status, E.prev, E.next = body.Search, body.Status, body.Previous, body.Next
		E.list, E.grid, E.bottom = body.Results, body.Results.Grid, body.Controls
		E.template = frame.Templates.Card
		E.pick, E.slotInfo, E.selectors = E.bottom.Selected, E.bottom.Current, E.bottom.Selectors
		E.slotBtns, E.actions = {}, {}
		const function click(btn, fn)
			if not btn then return end
			E.on("UI", btn.Activated, function()
				const ok, err = pcall(fn)
				if not ok then E.msg(tostring(err)) end
			end)
		end
		for i = 1, spec.choices do
			const btn = E.selectors["Choice"..i]
			E.slotBtns[i] = btn
			click(btn, function() spec.choose(i) end)
		end
		for i, action in spec.actions do
			const btn = E.bottom["Action"..i]
			E.actions[i] = btn
			pickIcon(btn, action[2], action[3])
			click(btn, action[1])
		end
		E.peek = NAmanage.NewAvatarPreview(E, spec)
		const preview = E.bottom:FindFirstChild("Preview")
		E.peekBtn = preview or E.actions[1]
		pickIcon(preview, "eye")
		click(preview, E.peekPlay)
		const filters = body:FindFirstChild("Filters")
		if filters then
			const icons = {
				Source = { "list-filter", "list-bulleted" },
				Sale = { "tag", "shopping-cart" },
				Sort = { "arrow-down-up", "three-sliders-horizontal" },
				Cost = { "coins", "shopping-cart" },
			}
			for key, values in { Source = { "Catalog", "Favorites", "Recent", "Suggested" }, Sale = { "All items", "On sale", "Offsale" }, Sort = { "Relevant", "Low → high", "High → low", "Newest", "Popular" }, Cost = { "Any price", "Free", "≤ 100 R$", "≤ 500 R$", "500+ R$" } } do
				const field = key == "Source" and "view" or key:lower()
				const btn, icon = filters[key], icons[key]
				pickIcon(btn, icon[1], icon[2], E[field])
				click(btn, function()
					E[field] = values[(table.find(values, E[field]) or 0) % #values + 1]
					NAmanage.SetIconText(btn, E[field])
					E.save() E.fetch(false, true)
				end)
			end
		end
		click(E.bottom:FindFirstChild("Favorite"), function() E.favorite() end)
		const density = E.bottom:FindFirstChild("Density")
		if density then
			const function showSize()
				pickIcon(density, E.compact and "grid-2x2" or "grid-3x3", "grid", E.compact and "Larger cards" or "Compact cards")
			end
			showSize()
			click(density, function()
				E.compact = not E.compact
				showSize()
				E.layout() E.save()
			end)
		end
		const pane = body:FindFirstChild("Saved")
		if pane then
			pickIcon(E.bottom.SavedSets, "folder-open", "bookmark")
			pickIcon(pane.Header.Close, "arrow-left", "arrow-medium-left")
			pickIcon(pane.Actions.Save, "save", "floppy-disk")
			pickIcon(pane.Actions.Apply, "check")
			pickIcon(pane.Actions.Delete, "trash-2", "x")
			click(E.bottom.SavedSets, function() E.showSets(not pane.Visible) end)
			click(pane.Header.Close, function() E.showSets(false) end)
			click(pane.Actions.Save, E.saveSet)
			click(pane.Actions.Apply, function()
				const row = E.sets[E.setIdx or 0]
				if not row then E.msg("Choose a saved setup first.") return end
				if E.restoreSet(row.data) then E.msg("Applied “"..row.name.."”.") end
			end)
			click(pane.Actions.Delete, function()
				if not E.sets[E.setIdx or 0] then E.msg("Choose a saved setup first.") return end
				table.remove(E.sets, E.setIdx) E.setIdx = nil E.save() E.drawSets() E.msg("Saved setup deleted.")
			end)
			const prefs = pane:FindFirstChild("Prefs")
			if prefs then
				pickIcon(prefs.Auto, "refresh-cw", "tilt", E.auto and "Apply on respawn: on" or "Apply on respawn: off")
				pickIcon(prefs.Speed, "gauge", "three-sliders-horizontal", "Preview speed: "..E.speed.."×")
				click(prefs.Auto, function()
					E.auto = not E.auto
					NAmanage.SetIconText(prefs.Auto, E.auto and "Apply on respawn: on" or "Apply on respawn: off")
					E.save()
				end)
				click(prefs.Speed, function()
					const values = { 0.5, 1, 1.5, 2 }
					E.speed = values[(table.find(values, E.speed) or 1) % #values + 1]
					NAmanage.SetIconText(prefs.Speed, "Preview speed: "..E.speed.."×")
					if E.track then pcall(function() E.track:AdjustSpeed(E.speed) end) end
					if E.peek then E.peek.sync() end
					E.save()
				end)
			end
			for i, row in spec.combos or {} do
				const btn = pane.Combos:FindFirstChild("Combo"..i)
				pickIcon(btn, row.icon, row.fallback, row.name)
				click(btn, function() spec.combo(row) end)
			end
		end
		pickIcon(body.SearchButton, "search")
		E.prev.TextSize, E.next.TextSize = 16, 16
		NAmanage.SetIcon(E.prev, "chevron-left")
		NAmanage.SetIcon(E.next, "chevron-right")
		click(body.SearchButton, function() E.fetch(false, true) end)
		click(E.prev, function() if E.cache[E.page - 1] then E.setPage(E.page - 1) end end)
		click(E.next, function() E.fetch(true) end)
		if spec.mode then
			pickIcon(body.Mode, "package", "cube-vertexes")
			click(body.Mode, spec.mode)
		end
		E.on("UI", E.search.FocusLost, function(enter) if enter then E.fetch(false, true) end end)
		E.on("UI", E.search:GetPropertyChangedSignal("Text"), function()
			E.run("SearchDelay", function() task.wait(0.45) if not E.dead then E.fetch(false) end end)
		end)
		E.on("UI", frame:GetPropertyChangedSignal("AbsoluteSize"), E.layout)
		const function stopPlayback()
			E.cancel("Play")
			E.stop()
		end
		E.on("UI", frame:GetAttributeChangedSignal(NAmanage.GetSessionAttrKey("NAMenuMinimized")), function()
			if not frame.Visible and not NAmanage.GetAttr(frame, "NAMenuMinimized") then stopPlayback() end
		end)
		E.on("UI", frame:GetPropertyChangedSignal("Visible"), function()
			if not frame.Visible then
				E.scroll[E.page] = E.list.CanvasPosition
				E.cancel("SearchDelay")
				if not NAmanage.GetAttr(frame, "NAMenuMinimized") then stopPlayback() end
				if E.peek then E.peek.hide() end
				if E.jobs.Draw then E.draw += 1 E.cancel("Draw") E.dirty = true end
			else
				E.refresh() E.paint()
				E.fetch(false)
			end
		end)
		const function camera()
			E.clean("Camera")
			const cam = WS.CurrentCamera
			if cam then E.on("Camera", cam:GetPropertyChangedSignal("ViewportSize"), E.fit) end
			E.fit()
		end
		E.on("UI", WS:GetPropertyChangedSignal("CurrentCamera"), camera)
		const cam = WS.CurrentCamera
		if cam then E.on("Camera", cam:GetPropertyChangedSignal("ViewportSize"), E.fit) end
		if NAgui.menu then NAgui.menu(frame) end
		if NAgui.draggerV2 then E.drag = NAgui.draggerV2(frame, frame.Topbar) end
		E.on("UI", frame.Destroying, function() if not E.dead then E.destroy() end end)
		E.style()
		if NAgui.RegisterStrokesFromAsync then NAgui.RegisterStrokesFromAsync(frame) end
	end
	E.open = function(force)
		E.create()
		local show = force
		if type(show) ~= "boolean" then show = not NAgui.isWindowOpen(E.frame) end
		if show then
			E.activated = true
			if spec.bind then spec.bind() end
			if not E.fitted then E.fit() end
			if NAmanage.centerFrame and not NAmanage.GetAttr(E.frame, "NAMenuMinimized") then NAmanage.centerFrame(E.frame) end
			E.style()
		end
		NAgui.setWindowVisible(E.frame, show)
		if show then
			if NAmanage.OnUIWindowShown then NAmanage.OnUIWindowShown(E.frame) end
			E.refresh() E.paint() E.fetch(false)
		end
		return true
	end
end

NAmanage.InitEmotePicker = function()
	if NAStuff.EmotePicker and not NAStuff.EmotePicker.dead then return NAStuff.EmotePicker end
	const Players = SafeGetService("Players")
	const Http = SafeGetService("HttpService")
	const Gui = SafeGetService("GuiService")
	const Starter = SafeGetService("StarterGui")
	const player = Players.LocalPlayer
	const E = NAmanage.NewAvatarPicker()
	E.over, E.slot = {}, 1
	NAStuff.EmotePicker = E
	E.path = (NAfiles.NAFILEPATH or "Nameless-Admin").."/EmotePicker.json"
	E.load = function()
		if type(readfile) ~= "function" then return end
		for _, path in { E.path, E.path..".bak" } do
			const ok, raw = pcall(readfile, path)
			if ok and type(raw) == "string" and #raw < 524288 then
				const good, data = pcall(Http.JSONDecode, Http, raw)
				if good and type(data) == "table" and data.version == 1 and type(data.slots) == "table" then
					for i = 1, 8 do
						local row = data.slots[tostring(i)]
						if row == nil then row = data.slots[i] end
						if row == false then E.over[i] = false
						else E.over[i] = E.item(row) end
					end
					E.loadExtra(data)
					return
				end
			end
		end
	end
	E.save = function()
		if type(writefile) ~= "function" then return false end
		const data = { version = 1, slots = {} }
		for i = 1, 8 do if E.over[i] ~= nil then data.slots[tostring(i)] = E.over[i] end end
		const ok, raw = pcall(Http.JSONEncode, Http, E.saveExtra(data))
		if not ok or #raw >= 524288 then return false end
		if type(makefolder) == "function" then pcall(makefolder, NAfiles.NAFILEPATH or "Nameless-Admin") end
		if type(readfile) == "function" then
			local old
			pcall(function() old = readfile(E.path) end)
			if type(old) == "string" and #old < 524288 then
				const valid, prior = pcall(Http.JSONDecode, Http, old)
				if valid and type(prior) == "table" and prior.version == 1 then pcall(writefile, E.path..".bak", old) end
			end
		end
		return pcall(writefile, E.path, raw)
	end
	E.rig = function()
		const h = E.hum
		if E.dead or not h or not h.Parent or not E.desc or not E.desc.Parent then return false, "Your character is still loading." end
		if h.RigType ~= Enum.HumanoidRigType.R15 then return false, "Emotes need an R15 character." end
		if h.Health <= 0 then return false, "Wait for your character to respawn." end
		return true
	end
	E.maps = function(a, b)
		for name, ids in a do
			const other = b[name]
			if type(other) ~= "table" or #ids ~= #other then return false end
			for i, id in ids do if id ~= other[i] then return false end end
		end
		for name in b do if a[name] == nil then return false end end
		return true
	end
	E.slots = function(rows)
		const out = {}
		for i, v in rows do
			if type(v) == "string" then out[i] = v
			elseif type(v) == "table" then
				const slot = tonumber(v.Slot or v.position or i)
				const name = v.Name or v.name
				if slot and slot >= 1 and slot <= 8 and slot % 1 == 0 and type(name) == "string" then out[slot] = name end
			end
		end
		return out
	end
	E.plan = function(extra)
		const map, wheel, names = {}, {}, {}
		for name, ids in E.baseMap or {} do map[name] = table.clone(ids) end
		for slot, name in E.baseSlot or {} do names[slot] = name end
		const function add(item)
			local key = item.name
			if map[key] and (#map[key] ~= 1 or map[key][1] ~= item.id) then key ..= " ("..item.id..")" end
			map[key] = { item.id }
			return key
		end
		for i = 1, 8 do
			const row = E.over[i]
			if row == false then names[i] = nil
			elseif row then names[i] = add(row) end
		end
		local playKey
		if extra then playKey = add(extra) end
		for i = 1, 8 do if names[i] then table.insert(wheel, { Slot = i, Name = names[i] }) end end
		return map, wheel, names, playKey
	end
	E.apply = function(extra)
		const ready, why = E.rig()
		if not ready then return false, why end
		const map, wheel, _, key = E.plan(extra)
		const ok, err = pcall(function()
			if not E.maps(map, E.desc:GetEmotes()) then
				E.desc:SetEmotes(map)
				E.descChanged = true
			end
			const before = E.slots(E.desc:GetEquippedEmotes())
			const after = E.slots(wheel)
			local same = true
			for i = 1, 8 do if before[i] ~= after[i] then same = false break end end
			if not same then
				E.desc:SetEquippedEmotes(wheel)
				E.descChanged = true
			end
		end)
		if not ok then return false, tostring(err) end
		return true, key
	end
	E.stop = function()
		if E.peek then E.peek.stop() end
		E.playing = false
		const track = E.track
		E.track = nil
		if track then pcall(function() track:Stop(0.15) end) end
	end
	E.restore = function(save)
		E.stop()
		E.over = {}
		const ok, err = E.apply()
		if save ~= false then E.save() end
		E.refresh()
		E.msg(ok and "Your original wheel is restored." or err)
		return ok
	end
	E.bindChar = function(char)
		if E.char == char and E.hum and E.hum.Parent and E.desc and E.desc.Parent then return end
		E.run("Char", function()
			NAmanage.WaitAvatarAppearance(player, char)
			const hum = char and (char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 8))
			const desc = hum and (hum:FindFirstChildOfClass("HumanoidDescription") or hum:WaitForChild("HumanoidDescription", 8))
			if E.dead or player.Character ~= char or not hum or not desc then return end
			if E.desc ~= desc then
				E.stop()
				E.clean("Hum")
				E.hum, E.desc, E.char = hum, desc, char
				E.descChanged = false
				E.baseMap = desc:GetEmotes()
				E.baseEq = desc:GetEquippedEmotes()
				E.baseSlot = E.slots(E.baseEq)
				pcall(function()
					E.on("Hum", hum.EmoteTriggered, function(ok, track)
						if E.playing and ok and typeof(track) == "Instance" and track:IsA("AnimationTrack") then E.track = track end
					end)
				end)
			end
			if E.auto and next(E.over) then E.apply() end
			E.refresh()
		end)
	end
	E.setSlot = function()
		if not E.selected then E.msg("Select an emote first.") return false end
		const ready, why = E.rig()
		if not ready then E.msg(why) return false end
		const old = E.over[E.slot]
		E.over[E.slot] = table.clone(E.selected)
		const ok, err = E.apply()
		if not ok then E.over[E.slot] = old E.msg(err) return false end
		const saved = E.remember(E.selected)
		E.refresh()
		E.msg(E.selected.name.." added to slot "..E.slot..(saved and ". Saved for startup and respawn." or ". File saving is unavailable."))
		return true
	end
	E.clearSlot = function()
		const ready, why = E.rig()
		if not ready then E.msg(why) return false end
		const old = E.over[E.slot]
		E.over[E.slot] = false
		const ok, err = E.apply()
		if not ok then E.over[E.slot] = old E.msg(err) return false end
		E.save()
		E.refresh()
		E.msg("Slot "..E.slot.." cleared.")
		return true
	end
	E.play = function()
		if E.jobs.Play then E.msg("Wait for the current emote to start.") return false end
		if not E.selected then E.msg("Select an emote first.") return false end
		const ready, why = E.rig()
		if not ready then E.msg(why) return false end
		const item = table.clone(E.selected)
		E.stop()
		E.playing = true
		E.run("Play", function()
			if not E.playing then return end
			const ok, key = E.apply(item)
			if not ok then E.playing = false E.msg(key) return end
			const hum = E.hum
			const anim = hum:FindFirstChildOfClass("Animator")
			const before = {}
			if anim then for _, track in anim:GetPlayingAnimationTracks() do before[track] = true end end
			local good, played = pcall(function() return hum:PlayEmoteAsync(key) end)
			if E.dead or not E.playing or E.hum ~= hum then return end
			if not good then good, played = pcall(function() return hum:PlayEmote(key) end) end
			task.wait(0.08)
			if E.dead or not E.playing or E.hum ~= hum then return end
			if not E.track and good and played and anim then
				for _, track in anim:GetPlayingAnimationTracks() do
					if not before[track] and track.Priority.Value >= Enum.AnimationPriority.Action.Value then E.track = track break end
				end
			end
			E.playing = false
			if E.track then pcall(function() E.track:AdjustSpeed(E.speed) end) end
			if good and played then E.remember(item) end
			E.msg(good and played and ("Playing "..item.name..".") or "This emote could not play on your character.")
		end)
		return true
	end
	E.wheel = function()
		const ready, why = E.rig()
		if not ready then E.msg(why) return false end
		const ok, err = E.apply()
		if not ok then E.msg(err) return false end
		local good, enabled = pcall(Starter.GetCoreGuiEnabled, Starter, Enum.CoreGuiType.EmotesMenu)
		if good and not enabled then
			if E.coreWas == nil then E.coreWas = enabled end
			pcall(Starter.SetCoreGuiEnabled, Starter, Enum.CoreGuiType.EmotesMenu, true)
		end
		local opened, result = pcall(Gui.SetEmotesMenuOpen, Gui, true)
		E.msg(opened and "Emote wheel opened." or tostring(result))
		return opened
	end
	E.refresh = function()
		if not E.frame or not E.frame.Parent then return end
		const _, _, names = E.plan()
		E.pick.Text = E.selected and E.selected.name or "Select an emote"
		E.slotInfo.Text = "Slot "..E.slot..": "..(names[E.slot] or "Empty")
		for i, btn in E.slotBtns do
			const color = i == E.slot and E.accent or E.panel
			if btn.BackgroundColor3 ~= color then btn.BackgroundColor3 = color end
			btn.Text = tostring(i)..(names[i] and " •" or "")
		end
		E.paint()
	end
	E.copySet = function(raw)
		if type(raw) ~= "table" then return nil end
		const out = {}
		for i = 1, 8 do
			local item = raw[tostring(i)]
			if item == nil then item = raw[i] end
			if item == false then out[tostring(i)] = false
			else out[tostring(i)] = E.item(item) end
		end
		return next(out) and out or nil
	end
	E.capture = function()
		const ready, why = E.rig()
		if not ready then E.msg(why) return nil end
		const map, _, names = E.plan()
		const out = {}
		for i = 1, 8 do
			const name = names[i]
			out[tostring(i)] = name and map[name] and E.item({ id = map[name][1], name = name }) or false
		end
		return out
	end
	E.useSet = function(raw)
		const set = E.copySet(raw)
		if not set then E.msg("This wheel has no valid slots.") return false end
		const old = E.over
		E.over = {}
		for i = 1, 8 do E.over[i] = set[tostring(i)] end
		const ok, why = E.apply()
		if not ok then E.over = old E.msg(why) return false end
		E.save() E.refresh()
		return true
	end
	E.combo = function(row)
		if E.mixing then E.msg("Wait for the current wheel to load.") return end
		const ready, why = E.rig()
		if not ready then E.msg(why) return end
		E.mixing = true
		E.msg("Building "..row.name.."...")
		E.run("Combo", function()
			const ok, err = pcall(function()
				const items = {}
				if row.favorites then
					for _, item in E.favs do table.insert(items, item) end
					table.sort(items, function(a, b) return a.name:lower() < b.name:lower() end)
				else
					const params = CatalogSearchParams.new()
					params.AssetTypes = { Enum.AvatarAssetType.EmoteAnimation }
					params.SearchKeyword, params.Limit = row.query, 10
					params.SortType = Enum.CatalogSortType.MostFavorited
					const pages = SafeGetService("AvatarEditorService"):SearchCatalogAsync(params)
					for _, item in pages:GetCurrentPage() do const value = E.item(item) if value then table.insert(items, value) end end
					pages:Destroy()
				end
				if E.dead then return end
				if #items == 0 then E.msg("No emotes found. Try adding some favorites first.") return end
				const set = {}
				for i = 1, 8 do set[tostring(i)] = items[i] or false end
				if E.useSet(set) then E.msg(row.name.." applied. Give it a name to save another copy.") end
			end)
			E.mixing = false
			if not ok and not E.dead then E.msg(tostring(err)) end
		end)
	end
	E.clips = {}
	E.clipOrder = {}
	E.previewClip = function(item, active)
		local id = E.clips[item.id]
		if not id then
			local ok, rows = pcall(function() return game:GetObjects("rbxassetid://"..item.id) end)
			if not ok and type(getobjects) == "function" then ok, rows = pcall(getobjects, "rbxassetid://"..item.id) end
			if not ok or type(rows) ~= "table" then error("Roblox couldn't open this emote for preview.", 0) end
			const good, err = pcall(function()
				for _, obj in rows do
					if obj:IsA("Animation") then id = E.valid(obj.AnimationId:match("%d+")) end
					if not id then
						const anim = obj:FindFirstChildWhichIsA("Animation", true)
						if anim then id = E.valid(anim.AnimationId:match("%d+")) end
					end
					if id then break end
				end
			end)
			for _, obj in rows do pcall(function() obj:Destroy() end) end
			if not good then error(err, 0) end
			if not id then error("This emote has no playable animation.", 0) end
			if not active() then return {} end
			E.clips[item.id] = id table.insert(E.clipOrder, item.id)
			if #E.clipOrder > 64 then E.clips[table.remove(E.clipOrder, 1)] = nil end
		end
		return { emote = { name = item.name, variants = { { id = id } } } }
	end
	NAmanage.BindAvatarPickerUI(E, {
		key = "EmotePicker", title = "Emote Picker", choices = 8,
		preview = E.previewClip,
		cleanSet = E.copySet, capture = E.capture, restoreSet = E.useSet,
		bind = function() if player.Character then E.bindChar(player.Character) end end,
		recommend = function(item) return SafeGetService("AvatarEditorService"):GetRecommendedAssetsAsync(Enum.AvatarAssetType.EmoteAnimation, item and item.id or 0) end,
		combos = {
			{ name = "Dance wheel", icon = "music", fallback = "music-note", query = "dance" },
			{ name = "Greetings", icon = "hand", fallback = "square-face-waving-hand", query = "wave" },
			{ name = "My favorites", icon = "star", favorites = true },
		},
		combo = E.combo,
		filter = function() return "Emotes" end,
		params = function(params) params.AssetTypes = { Enum.AvatarAssetType.EmoteAnimation } end,
		item = E.item,
		choose = function(i) E.slot = i E.refresh() end,
		actions = {
			{ E.play, "play" },
			{ E.setSlot, "list-plus", "circle-plus" },
			{ E.wheel, "chart-pie", "grid" },
			{ function() E.stop() E.apply() E.msg("Stopped.") end, "square", "square-corner-line" },
			{ E.clearSlot, "list-minus", "minus" },
			{ E.restore, "rotate-ccw", "tilt" },
		},
	})
	E.destroy = function()
		if E.dead then return end
		E.dead = true
		E.req += 1
		E.draw += 1
		E.jobs.Query, E.jobs.Combo, E.jobs.Play, E.jobs.Char = nil, nil, nil, nil
		for key in E.jobs do E.cancel(key) end
		E.stop()
		if E.descChanged and E.desc and E.desc.Parent and E.baseMap then
			pcall(E.desc.SetEmotes, E.desc, E.baseMap)
			pcall(E.desc.SetEquippedEmotes, E.desc, E.baseEq)
		end
		if E.coreWas ~= nil then pcall(Starter.SetCoreGuiEnabled, Starter, Enum.CoreGuiType.EmotesMenu, E.coreWas) end
		E.unbindUI()
		local groups = {}
		for key in E.bags do table.insert(groups, key) end
		for _, key in groups do E.clean(key) end
		E.cache = {} E.cards = {} E.clips = {} E.clipOrder = {}
		E.hum, E.desc, E.char = nil, nil, nil
		if E.life then E.life.Connected = false end
	end
	E.load()
	E.on("Life", player.CharacterAdded, function(char) if E.activated or E.auto and next(E.over) then E.bindChar(char) end end)
	E.on("Life", player.CharacterAppearanceLoaded, function(char) if E.activated or E.auto and next(E.over) then E.bindChar(char) end end)
	E.on("Life", player.CharacterRemoving, function(char)
		if E.char == char then E.cancel("Char") E.stop() E.clean("Hum") E.hum, E.desc, E.char = nil, nil, nil end
	end)
	E.on("Life", NAStuff.NASCREENGUI.Destroying, E.destroy)
	E.life = { Connected = true, Disconnect = function(self) self.Connected = false E.destroy() end }
	NAlib.connect("NAEmotePicker", E.life)
	if player.Character and E.auto and next(E.over) then E.bindChar(player.Character) end
	return E
end

NAmanage.OpenEmotePicker = function(force)
	const ok, result = pcall(function() return NAmanage.InitEmotePicker().open(force) end)
	if not ok then DoNotif("Couldn't open the emote picker: "..tostring(result), 5) end
	return ok and result or false
end

cmd.register({
	name = "emotes",
	aliases = { "emotepicker", "emotewheel" },
	description = "Browse catalog emotes, play them, and choose your eight wheel slots",
	requiresArguments = false,
	category = "Avatar",
	callback = function() NAmanage.OpenEmotePicker() end,
})
cmd.register({
	name = "restoreemotes",
	description = "Restore the emote wheel you had before using the picker",
	requiresArguments = false,
	category = "Avatar",
	callback = function()
		const picker = NAStuff.EmotePicker
		if picker and not picker.dead then picker.restore()
		else DoNotif("Your emote wheel hasn't been changed by the picker.", 3) end
	end,
})

-- PART 32
NAmanage.InitAnimationPicker = function()
	if NAStuff.AnimationPicker and not NAStuff.AnimationPicker.dead then return NAStuff.AnimationPicker end
	const A = NAmanage.NewAvatarPicker()
	const Players = SafeGetService("Players")
	const AES = SafeGetService("AvatarEditorService")
	const Assets = SafeGetService("AssetService")
	const Http = SafeGetService("HttpService")
	const player = Players.LocalPlayer
	const keys = { "all", "idle", "walk", "run", "jump", "fall", "climb", "swim", "swimidle", "mood", "sit" }
	const names = { idle = "Idle", walk = "Walk", run = "Run", jump = "Jump", fall = "Fall", climb = "Climb", swim = "Swim", swimidle = "Swim idle", mood = "Mood", sit = "Sit" }
	const types = { idle = "IdleAnimation", walk = "WalkAnimation", run = "RunAnimation", jump = "JumpAnimation", fall = "FallAnimation", climb = "ClimbAnimation", swim = "SwimAnimation", swimidle = "SwimAnimation", mood = "MoodAnimation" }
	A.over, A.owned, A.resolved, A.order = {}, {}, {}, {}
	A.target, A.mode = "all", "Packs"
	A.path = (NAfiles.NAFILEPATH or "Nameless-Admin").."/AnimationPicker.json"
	NAStuff.AnimationPicker = A
	A.id = function(value)
		if type(value) == "string" then value = value:match("%d+") end
		return A.valid(value)
	end
	A.record = function(v)
		if type(v) ~= "table" or type(v.variants) ~= "table" then return nil end
		const out = { name = A.text(v.name or "Custom animation", 100), source = A.valid(v.source), variants = {} }
		for i, row in v.variants do
			if type(i) == "number" and i >= 1 and i <= 8 and type(row) == "table" then
				const id = A.id(row.id)
				if id then
					local weight = tonumber(row.weight) or 1
					if weight ~= weight or weight == math.huge or weight == -math.huge then weight = 1 end
					table.insert(out.variants, { id = id, name = A.text(row.name or ("Animation"..i), 60), weight = math.clamp(weight, 0.001, 100) })
				end
			end
		end
		return #out.variants > 0 and out or nil
	end
	A.load = function()
		if type(readfile) ~= "function" then return end
		for _, path in { A.path, A.path..".bak" } do
			const ok, raw = pcall(readfile, path)
			if ok and type(raw) == "string" and #raw < 524288 then
				const good, data = pcall(Http.JSONDecode, Http, raw)
				if good and type(data) == "table" and data.version == 1 and type(data.types) == "table" then
					for key in names do A.over[key] = A.record(data.types[key]) end
					A.loadExtra(data)
					return
				end
			end
		end
	end
	A.save = function()
		if type(writefile) ~= "function" then return false end
		const ok, raw = pcall(Http.JSONEncode, Http, A.saveExtra({ version = 1, types = A.over }))
		if not ok or #raw >= 524288 then return false end
		if type(makefolder) == "function" then pcall(makefolder, NAfiles.NAFILEPATH or "Nameless-Admin") end
		if type(readfile) == "function" then
			const good, old = pcall(readfile, A.path)
			if good and type(old) == "string" and #old < 524288 then
				const valid, prior = pcall(Http.JSONDecode, Http, old)
				if valid and type(prior) == "table" and prior.version == 1 then pcall(writefile, A.path..".bak", old) end
			end
		end
		return pcall(writefile, A.path, raw)
	end
	A.stop = function()
		if A.peek then A.peek.stop() end
		A.actionTok = (A.actionTok or 0) + 1
		if A.track then pcall(function() A.track:Stop(0.15) A.track:Destroy() end) A.track = nil end
		if A.preview then pcall(function() A.preview:Destroy() end) A.preview = nil end
	end
	A.resume = function()
		const animate = A.paused
		A.paused = nil
		if animate and animate.Parent and animate.Disabled then pcall(function() animate.Disabled = false end) end
	end
	A.restart = function(immediate)
		if A.paused then
			if immediate then A.cancel("Restart") A.resume() end
			return
		end
		const animate = A.animate
		if not animate or not animate.Parent or not animate:IsA("LocalScript") or animate.Disabled then return end
		A.paused = animate
		animate.Disabled = true
		if immediate then
			A.resume()
		else
			A.jobs.Restart = task.delay(0.04, function() A.jobs.Restart = nil A.resume() end)
		end
	end
	A.release = function(key)
		const entry = A.owned[key]
		if not entry then return end
		A.owned[key] = nil
		pcall(function() entry.node:Destroy() end)
		if entry.old and A.animate and A.animate.Parent and not A.animate:FindFirstChild(key) then pcall(function() entry.old.Parent = A.animate end) end
	end
	A.releaseAll = function()
		local changed = false
		for key in A.owned do A.release(key) changed = true end
		return changed
	end
	A.rig = function()
		if A.dead or not A.hum or not A.hum.Parent or not A.animate or not A.animate.Parent then return false, "Your character's Animate script is still loading." end
		if A.hum.RigType ~= Enum.HumanoidRigType.R15 then return false, "Catalog animation packs need an R15 character." end
		if A.hum.Health <= 0 then return false, "Wait for your character to respawn." end
		return true
	end
	A.apply = function()
		const ready, why = A.rig()
		if not ready then return false, why end
		local changed = false
		for key in names do
			const record = A.over[key]
			const prior = A.owned[key]
			const sig = record and Http:JSONEncode(record.variants)
			if prior and (not record or prior.sig ~= sig or prior.node.Parent ~= A.animate) then A.release(key) changed = true end
			if record and not A.owned[key] then
				const old = A.animate:FindFirstChild(key)
				const node = Instance.new("StringValue")
				node.Name = key
				for i, row in record.variants do
					const anim = Instance.new("Animation")
					anim.Name = row.name ~= "" and row.name or ("Animation"..i)
					anim.AnimationId = "rbxassetid://"..row.id
					const weight = Instance.new("NumberValue")
					weight.Name, weight.Value, weight.Parent = "Weight", row.weight, anim
					anim.Parent = node
				end
				A.owned[key] = { old = old or false, node = node, sig = sig }
				if old then old.Parent = nil end
				node.Parent = A.animate
				changed = true
			end
		end
		if changed then A.restart() end
		return true
	end
	A.bindChar = function(char)
		if A.char == char and A.hum and A.hum.Parent and A.animate and A.animate.Parent then return end
		A.run("Char", function()
			NAmanage.WaitAvatarAppearance(player, char)
			const hum = char and (char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 8))
			const animate = char and (char:FindFirstChild("Animate") or char:WaitForChild("Animate", 8))
			if animate and not animate:FindFirstChild("idle") then animate:WaitForChild("idle", 4) end
			if A.dead or player.Character ~= char or not hum or not animate then return end
			if A.animate ~= animate then
				A.stop() A.cancel("Restart") A.resume() A.releaseAll()
				A.hum, A.animate, A.char = hum, animate, char
			end
			if A.auto and next(A.over) then
				const ok, why = A.apply()
				if not ok then A.msg(why) end
			end
			A.refresh()
		end)
	end
	A.kind = function(value)
		for key, name in types do
			if key ~= "swimidle" then
				if tostring(value) == name then return key end
				if type(value) == "number" then
					local enum
					pcall(function() enum = Enum.AvatarAssetType[name] end)
					if enum and enum.Value == value then return key end
				end
			end
		end
	end
	A.resolve = function(item, target, token, check)
		const out, pending, seen = {}, {}, {}
		const function active()
			return not A.dead and (token == nil or A.actionTok == token) and (check == nil or check())
		end
		const function wanted(key)
			return target == nil or target == "all" or key == target
		end
		const function take(data)
			for key, variants in data do
				if wanted(key) then out[key] = A.record({ name = item.name, source = item.id, variants = variants }) end
			end
		end
		if not active() then return out end
		local items = item.items
		if item.bundle and type(items) ~= "table" then items = Assets:GetBundleDetailsAsync(item.id).Items end
		if not item.bundle then items = { { Id = item.id, Type = "Asset", AssetType = item.assetType } } end
		local count = 0
		for _, row in items or {} do
			if not active() then return {} end
			if row.Type == "Asset" and A.valid(row.Id) then
				count += 1
				if count > 16 then break end
				local kind = row.AssetType
				if kind == nil then
					const ok, info = pcall(AES.GetItemDetailsAsync, AES, row.Id, Enum.AvatarItemType.Asset)
					if ok and type(info) == "table" then kind = info.AssetType end
				end
				const key = A.kind(kind)
				if key and not seen[key] and (wanted(key) or (key == "swim" and wanted("swimidle"))) then
					seen[key] = true
					const cacheKey = tostring(row.Id)..":"..key
					if A.resolved[cacheKey] then take(A.resolved[cacheKey])
					else table.insert(pending, { id = row.Id, key = key, cacheKey = cacheKey }) end
				end
			end
		end
		if #pending > 0 and active() then
			const desc = Instance.new("HumanoidDescription")
			local model
			const ok, err = pcall(function()
				for _, row in pending do desc[types[row.key]] = row.id end
				model = Players:CreateHumanoidModelFromDescriptionAsync(desc, Enum.HumanoidRigType.R15)
				if not active() then return end
				task.wait()
				if not active() then return end
				const animate = model:FindFirstChild("Animate")
				if not animate then error("Roblox didn't return the selected animations.") end
				const function read(key)
					const node = animate:FindFirstChild(key)
					const variants, ids = {}, {}
					for _, obj in node and node:GetChildren() or {} do
						if obj:IsA("Animation") and #variants < 8 then
							const id = A.id(obj.AnimationId)
							if id and not ids[id] then
								ids[id] = true
								const weight = obj:FindFirstChild("Weight")
								table.insert(variants, { id = id, name = obj.Name, weight = weight and weight:IsA("NumberValue") and weight.Value or 1 })
							end
						end
					end
					return #variants > 0 and variants or nil
				end
				for _, row in pending do
					const data = {}
					data[row.key] = read(row.key)
					if row.key == "swim" then data.swimidle = read("swimidle") end
					if not next(data) then error("Roblox couldn't load the selected "..(names[row.key] or row.key).." animation.") end
					A.resolved[row.cacheKey] = data
					table.insert(A.order, row.cacheKey)
					if #A.order > 64 then A.resolved[table.remove(A.order, 1)] = nil end
					take(data)
				end
			end)
			if model then pcall(function() model:Destroy() end) end
			desc:Destroy()
			if not ok then error(err, 0) end
		end
		if not active() then return {} end
		if not next(out) then
			if target and target ~= "all" then error("This selection has no "..(names[target] or target).." animation.", 0) end
			error("Roblox couldn't load the animations in this selection.", 0)
		end
		return out
	end
	A.readAsset = function(id, key)
		const out = {}
		const configs = A.resolve({ id = id, name = "Animation "..id, assetType = types[key] })
		for state, row in configs do out[state] = row.variants end
		return out
	end
	A.work = function(fn, all)
		if A.resolving then A.msg("Wait for the current animation to load.") return false end
		const ready, why = A.rig()
		if not ready then A.msg(why) return false end
		if not A.selected then A.msg("Select an animation pack or animation first.") return false end
		const item = A.selected
		const target = A.target
		A.actionTok = (A.actionTok or 0) + 1
		const token = A.actionTok
		A.resolving = true
		A.msg("Loading "..item.name.."...")
		A.run("Resolve", function()
			const ok, err = pcall(function()
				const configs = A.resolve(item, all == true and "all" or target, token)
				if not A.dead and A.actionTok == token then fn(configs, target, item) end
			end)
			A.resolving = false
			if not ok and not A.dead then A.msg(tostring(err)) end
		end)
		return true
	end
	A.use = function(all)
		return A.work(function(configs, target, item)
			local count = 0
			const old = table.clone(A.over)
			for key, record in configs do
				if all or target == "all" or target == key then A.over[key] = record count += 1 end
			end
			if count == 0 then A.msg("This selection has no "..(names[target] or target).." animation.") return end
			const ok, why = A.apply()
			if not ok then A.over = old A.msg(why) return end
			const saved = A.remember(item)
			A.refresh()
			A.msg("Applied "..count.." animation type"..(count == 1 and "" or "s")..(saved and ". Saved for startup and respawn." or ". File saving is unavailable."))
		end, all)
	end
	A.play = function()
		return A.peekPlay()
	end
	A.reset = function(all)
		A.stop()
		if all or A.target == "all" then A.over = {} else A.over[A.target] = nil end
		if A.animate and A.animate.Parent then A.apply() end
		const saved = A.save()
		A.refresh()
		A.msg(saved and "Original animations restored and saved." or "Original animations restored. File saving is unavailable.")
	end
	A.refresh = function()
		if not A.frame or not A.frame.Parent then return end
		A.pick.Text = A.selected and A.selected.name or "Select an animation pack or animation"
		local count = 0
		for _ in A.over do count += 1 end
		const current = A.over[A.target]
		A.slotInfo.Text = A.target == "all" and (count.." customized types · choose a type to mix packs") or ((names[A.target] or A.target)..": "..(current and current.name or "Original"))
		for i, btn in A.slotBtns do
			const key = keys[i]
			const color = key == A.target and A.accent or A.panel
			if btn.BackgroundColor3 ~= color then btn.BackgroundColor3 = color end
			btn.Text = (names[key] or "All")..(A.over[key] and " •" or "")
		end
		const packs = A.mode == "Packs"
		NAmanage.SetIcon(A.body.Mode, packs and "package" or "clapperboard", {text = A.mode, fallback = packs and "cube-vertexes" or "person-walking"})
		NAmanage.SetIconText(A.actions[2], A.target == "all" and "Apply all" or "Apply type")
		A.paint()
	end
	A.copySet = function(raw)
		if type(raw) ~= "table" then return nil end
		const out = {}
		for key in names do out[key] = A.record(raw[key]) end
		return out
	end
	A.useSet = function(raw)
		const set = A.copySet(raw)
		if not set then A.msg("This setup has no valid animations.") return false end
		const old = A.over
		A.over = set
		const ok, why = A.apply()
		if not ok then A.over = old A.msg(why) return false end
		A.save() A.refresh()
		return true
	end
	A.packCache = {}
	A.findPack = function(name)
		if A.packCache[name] then return A.packCache[name] end
		const params = CatalogSearchParams.new()
		params.BundleTypes = { Enum.BundleType.Animations }
		params.SearchKeyword, params.Limit, params.CreatorName = name, 10, "Roblox"
		const pages = AES:SearchCatalogAsync(params)
		local found
		for _, row in pages:GetCurrentPage() do
			if tostring(row.Name):lower():find(name:lower(), 1, true) then
				found = A.item(row)
				if found then found.bundle = true found.items = row.BundledItems break end
			end
		end
		pages:Destroy()
		if not found then error("Couldn't find the "..name.." animation pack. Try again later.", 0) end
		A.packCache[name] = found
		return found
	end
	A.combo = function(row)
		if A.resolving then A.msg("Wait for the current animation to load.") return end
		const ready, why = A.rig()
		if not ready then A.msg(why) return end
		A.actionTok = (A.actionTok or 0) + 1
		const token = A.actionTok
		A.resolving = true
		A.msg("Building "..row.name.."...")
		A.run("Resolve", function()
			const ok, err = pcall(function()
				const packs, set = {}, {}
				for key, pack in row.types do
					if A.dead or A.actionTok ~= token then return end
					if not packs[pack] then packs[pack] = A.resolve(A.findPack(pack), "all", token) end
					if A.dead or A.actionTok ~= token then return end
					const record = packs[pack][key]
					if not record then error(pack.." has no "..(names[key] or key).." animation.", 0) end
					set[key] = record
					task.wait()
				end
				if not A.dead and A.actionTok == token and A.useSet(set) then A.msg(row.name.." applied. Save it with your own name to keep a copy.") end
			end)
			A.resolving = false
			if not ok and not A.dead then A.msg(tostring(err)) end
		end)
	end
	NAmanage.BindAvatarPickerUI(A, {
		key = "AnimationPicker", title = "Animation Picker", choices = #keys,
		target = function() return A.target end,
		preview = function(item, active) return A.resolve(item, "all", nil, active) end,
		clipName = function(key) return names[key] or key end,
		cleanSet = A.copySet, capture = function() return A.copySet(A.over) end, restoreSet = A.useSet,
		bind = function() if player.Character then A.bindChar(player.Character) end end,
		accept = function(item) return A.mode == "Packs" and item.bundle or A.mode ~= "Packs" and not item.bundle and (A.target == "all" or item.assetType == types[A.target]) end,
		recommend = function(item)
			if A.mode == "Packs" and item and item.bundle then return AES:GetRecommendedBundlesAsync(item.id) end
			if A.mode ~= "Packs" then return AES:GetRecommendedAssetsAsync(Enum.AvatarAssetType[types[A.target] or "IdleAnimation"], item and not item.bundle and item.id or 0) end
			const params = CatalogSearchParams.new()
			params.BundleTypes, params.SortType, params.Limit = { Enum.BundleType.Animations }, Enum.CatalogSortType.MostFavorited, 30
			const pages = AES:SearchCatalogAsync(params)
			const rows = pages:GetCurrentPage()
			pages:Destroy()
			return rows
		end,
		combos = {
			{ name = "Agile", icon = "zap", fallback = "person-walking", types = { idle = "Stylish", walk = "Ninja", run = "Ninja", jump = "Ninja", fall = "Ninja", climb = "Ninja", swim = "Ninja", swimidle = "Ninja" } },
			{ name = "Relaxed", icon = "leaf", fallback = "cloud", types = { idle = "Stylish", walk = "Stylish", run = "Bubbly", jump = "Bubbly", fall = "Stylish", climb = "Stylish", swim = "Stylish", swimidle = "Stylish" } },
			{ name = "Mechanical", icon = "bot", fallback = "circle-person", types = { idle = "Robot", walk = "Robot", run = "Robot", climb = "Robot", jump = "Levitation", fall = "Levitation", swim = "Levitation", swimidle = "Levitation" } },
		},
		combo = A.combo,
		filter = function() return A.mode..":"..(A.mode == "Packs" and "all" or A.target) end,
		params = function(params)
			if A.mode == "Packs" then params.BundleTypes = { Enum.BundleType.Animations }
			else
				const list, seen = {}, {}
				for key, name in types do
					if (A.target == "all" or A.target == key) and not seen[name] then
						local value
						pcall(function() value = Enum.AvatarAssetType[name] end)
						if value then table.insert(list, value) seen[name] = true end
					end
				end
				if #list == 0 then error("There is no separate catalog category for "..(names[A.target] or A.target)..". Choose Packs.") end
				params.AssetTypes = list
			end
		end,
		item = function(row)
			const item = A.item(row)
			if item then item.bundle = A.mode == "Packs" item.items = row.BundledItems item.assetType = row.AssetType or item.assetType or (A.mode ~= "Packs" and types[A.target] or nil) end
			return item
		end,
		choose = function(i)
			A.target = keys[i] A.refresh()
			if A.mode ~= "Packs" then A.fetch(false, true) end
		end,
		mode = function()
			A.mode = A.mode == "Packs" and "Animations" or "Packs"
			A.search.PlaceholderText = A.mode == "Packs" and "Search animation packs" or "Search individual animations"
			A.refresh() A.fetch(false, true)
		end,
		actions = {
			{ A.play, "eye" },
			{ function() A.use(false) end, "check" },
			{ function() A.use(true) end, "package-check", "cube-vertexes" },
			{ function() A.stop() A.msg("Preview stopped.") end, "square", "square-corner-line" },
			{ function() A.reset(false) end, "rotate-ccw", "tilt" },
			{ function() A.reset(true) end, "list-restart", "tilt" },
		},
	})
	A.destroy = function()
		if A.dead then return end
		A.dead = true
		A.cancel("Restart")
		const changed = A.releaseAll()
		if changed then A.restart(true) else A.resume() end
		A.jobs.Resolve, A.jobs.Query, A.jobs.Char = nil, nil, nil
		for key in A.jobs do A.cancel(key) end
		A.stop()
		A.unbindUI()
		local groups = {}
		for key in A.bags do table.insert(groups, key) end
		for _, key in groups do A.clean(key) end
		A.cache, A.resolved, A.order = {}, {}, {}
		A.hum, A.animate, A.char = nil, nil, nil
		if A.life then A.life.Connected = false end
	end
	A.load()
	A.on("Life", player.CharacterAdded, function(char) if A.activated or A.auto and next(A.over) then A.bindChar(char) end end)
	A.on("Life", player.CharacterAppearanceLoaded, function(char) if A.activated or A.auto and next(A.over) then A.bindChar(char) end end)
	A.on("Life", player.CharacterRemoving, function(char)
		if A.char == char then
			A.stop() A.cancel("Char") A.cancel("Restart") A.resume() A.releaseAll()
			A.hum, A.animate, A.char = nil, nil, nil
		end
	end)
	A.on("Life", NAStuff.NASCREENGUI.Destroying, A.destroy)
	A.life = { Connected = true, Disconnect = function(self) self.Connected = false A.destroy() end }
	NAlib.connect("NAAnimationPicker", A.life)
	if player.Character and A.auto and next(A.over) then A.bindChar(player.Character) end
	return A
end

NAmanage.HasAnimationPickerSettings = function()
	const picker = NAStuff.AnimationPicker
	return picker and not picker.dead and ((picker.auto and next(picker.over) ~= nil) or next(picker.owned) ~= nil) or false
end

NAmanage.OpenAnimationPicker = function(force)
	const ok, result = pcall(function() return NAmanage.InitAnimationPicker().open(force) end)
	if not ok then DoNotif("Couldn't open the animation picker: "..tostring(result), 5) end
	return ok and result or false
end

cmd.register({
	name = "animationpicker",
	aliases = { "animpicker", "animpackpicker" },
	description = "Browse animation packs and save a full pack or mix individual movement types",
	requiresArguments = false,
	category = "Avatar",
	callback = function() NAmanage.OpenAnimationPicker() end,
})

NAmanage.spawnStartupLoader("AvatarPickerSettings", function()
	NAmanage.InitEmotePicker()
	NAmanage.InitAnimationPicker()
end)

